String _nativeChatFontFamily(TargetPlatform platform) {
  switch (platform) {
    case TargetPlatform.iOS:
    case TargetPlatform.macOS:
      return '.SF Pro Text';
    case TargetPlatform.android:
    case TargetPlatform.fuchsia:
      return 'Roboto';
    case TargetPlatform.windows:
      return 'Segoe UI';
    case TargetPlatform.linux:
      return 'Noto Sans';
  }
}

TextStyle _nativeChatTextStyle(BuildContext context, Color color) {
  final platform = Theme.of(context).platform;
  final typography = Typography.material2021(platform: platform);
  final base = Theme.of(context).brightness == Brightness.dark
      ? typography.white.bodyLarge
      : typography.black.bodyLarge;
  return (base ?? const TextStyle(fontSize: 16)).copyWith(
    color: color,
    fontFamily: base?.fontFamily ?? _nativeChatFontFamily(platform),
    // Emoji not in the animated catalog stay as plain text in the span; route
    // any glyph the UI font lacks to the platform colour-emoji font so it never
    // renders as a tofu box (.notdef cross).
    fontFamilyFallback: kEmojiFontFallback,
    fontSize: 16,
    fontWeight: FontWeight.w400,
    letterSpacing: 0,
    height: 1.2,
  );
}

@visibleForTesting
/// Меняет ли это событие плеера РАЗМЕТКУ экрана переписки.
///
/// Плеер тикает пять раз в секунду, и почти всегда меняется только позиция —
/// цифры внутри уже существующих виджетов. Но три поля двигают вёрстку:
/// наличие трека решает, есть ли у AppBar `bottom` вообще, сколько занимает
/// `_headerBottomHeight()` и сливается ли панель «сейчас играет» с
/// закреплённым сообщением в один остров; смена трека переносит активное
/// состояние на другой пузырь; пауза меняет иконку и в панели, и в пузыре.
///
/// Только для таких событий нужен полноценный setState. Остальные едут
/// точечным тиком, не трогая делегат сливера и остальные строки ленты.
bool sharedAudioChangeNeedsLayout({
  required String? previousTrackId,
  required bool previousPlaying,
  required bool previousHasTrack,
  required String? trackId,
  required bool playing,
  required bool hasTrack,
}) =>
    trackId != previousTrackId ||
    playing != previousPlaying ||
    hasTrack != previousHasTrack;

@visibleForTesting
/// Whether an inbound 1:1 chat should be auto-marked read RIGHT NOW.
///
/// READ-RECEIPT SCOPE (2026-07-18): a read receipt claims the peer actually
/// SAW the message, so it must fire ONLY while this specific chat is the
/// on-screen, foreground, at-the-bottom view — never merely because the
/// ChatScreen widget is still mounted. It can stay mounted while invisible in
/// several ways: covered by a pushed sub-screen (peer profile, media viewer),
/// mid-close during the OpenContainer transition back to the chat list, or
/// built off-stage for that transition. In all of those the user is NOT
/// looking at the conversation, yet the old gate (foreground + near-latest)
/// passed and leaked a "read" the peer never earned ("read even on the main
/// page"). [isChatVisible] closes that — it is the route-is-current signal.
bool shouldAutoMarkChatRead({
  required bool appInForeground,
  required bool isChatVisible,
  required bool isNearLatestMessages,
  required bool isRequestConvo,
  required String? peerProfileId,
}) {
  if (!appInForeground) return false;
  if (!isChatVisible) return false;
  if (isRequestConvo) return false;
  final peer = peerProfileId?.trim();
  if (peer == null || peer.isEmpty) return false;
  return isNearLatestMessages;
}

// ─── GIPHY GIF API ──────────────────────────────────────────────────────────
// We used Tenor, but Google SHUT DOWN the Tenor API — v1 returns 403 and, as of
// Jan 2026, Google no longer issues new Tenor keys (the API can't even be
// enabled in Cloud). GIPHY is the actively-onboarding free replacement: a free
// beta key is issued instantly at developers.giphy.com (Create an App → API
// key). Provide it at build time:  --dart-define=GIPHY_API_KEY=YOUR_KEY
// With no key the GIF grid simply stays empty instead of erroring.
// NOTE: GIPHY's ToS requires visible "Powered by GIPHY" attribution — shown in
// the GIF picker.
const String _giphyKey = String.fromEnvironment(
  'GIPHY_API_KEY',
  defaultValue: '',
);

class _GifItem {
  const _GifItem({required this.previewUrl, required this.fullUrl});

  /// Small animated preview shown in the picker grid.
  final String previewUrl;

  /// Full-quality GIF downloaded and sent as a message.
  final String fullUrl;
}

/// Tagged-union result from the emoji / GIF picker bottom sheet.
class _PickerResult {
  const _PickerResult.emoji(String e)
    : emoji = e,
      gifUrl = null,
      sticker = null,
      createSticker = false;
  const _PickerResult.gif(String u)
    : emoji = null,
      gifUrl = u,
      sticker = null,
      createSticker = false;

  const _PickerResult.sticker(SecretlyStickerDescriptor value)
    : emoji = null,
      gifUrl = null,
      sticker = value,
      createSticker = false;

  /// "Создать стикер" was tapped — the caller runs the photo→sticker flow.
  const _PickerResult.createSticker()
    : emoji = null,
      gifUrl = null,
      sticker = null,
      createSticker = true;

  final String? emoji;
  final String? gifUrl;
  final SecretlyStickerDescriptor? sticker;
  final bool createSticker;
}

/// Одна страница результатов GIPHY.
class _GifPage {
  const _GifPage({
    required this.items,
    required this.hasMore,
    required this.returned,
  }) : failed = false;

  const _GifPage.failed()
    : items = const <_GifItem>[],
      hasMore = false,
      returned = 0,
      failed = true;

  static const _GifPage empty = _GifPage(
    items: <_GifItem>[],
    hasMore: false,
    returned: 0,
  );

  final List<_GifItem> items;

  /// Сколько записей отдал GIPHY — включая те, что мы отбросили.
  ///
  /// 🔴 КУРСОР СЧИТАЕТСЯ ПО ЭТОМУ ЧИСЛУ, А НЕ ПО ДЛИНЕ [items]. Часть записей
  /// приходит без пригодных ссылок, и мы их выбрасываем. Если сдвигать курсор по
  /// оставшимся, следующая страница начнётся раньше, чем кончилась предыдущая, и
  /// вернёт то же самое — а список перестанет расти, продолжая слать запросы.
  final int returned;

  /// Есть ли что грузить дальше.
  final bool hasMore;

  /// 🔴 ОТЛИЧАЕТСЯ ОТ ПУСТОГО РЕЗУЛЬТАТА НАМЕРЕННО. «Нет связи» и «ничего не
  /// нашлось» — разные причины и разные действия человека: в первом случае надо
  /// повторить, во втором — спросить иначе. Раньше оба случая давали одно и то
  /// же «GIF не найдены», и это врало ровно так же, как «копия недействительна»
  /// при севшем интернете.
  final bool failed;
}

/// Сколько просим за один раз.
const int _gifPageSize = 30;

/// Потолок накопленного списка.
///
/// 🔴 ЭТО И ЕСТЬ «НЕ НАГРУЖАТЬ ТЕЛЕФОН» В ЦИФРЕ. Каждая гифка в сетке — это
/// анимированная картинка, то есть кадры в памяти. Без потолка человек,
/// пролиставший подборщик минуту, набрал бы их сотнями. Шесть страниц — это
/// заметно больше, чем было (одна), и всё ещё ограниченно.
const int _gifMaxItems = 180;

/// За сколько до конца начинаем подгружать следующую страницу.
///
/// Расстоянием, а не «доскроллил до дна»: страница должна успеть приехать до
/// того, как человек увидит пустоту.
const double _gifPrefetchExtent = 700;

/// Fetches trending or search GIFs from the GIPHY API. Response is
/// `{ data: [ { images: { <rendition>: { url } } } ] }` — we pick a small
/// animated rendition for the grid and a size-capped one for sending.
Future<_GifPage> _fetchGifPage({
  String? query,
  String lang = 'en',
  int offset = 0,
  int limit = _gifPageSize,
}) async {
  // no key → empty grid, no dead request
  if (_giphyKey.isEmpty) return _GifPage.empty;
  final q = (query ?? '').trim();
  final base = q.isEmpty
      ? 'https://api.giphy.com/v1/gifs/trending'
      : 'https://api.giphy.com/v1/gifs/search';
  final uri = Uri.parse(base).replace(
    queryParameters: {
      'api_key': _giphyKey,
      'limit': '$limit',
      if (offset > 0) 'offset': '$offset',
      'rating': 'pg-13',
      // Язык запроса. Без него русское слово уходило в английский индекс и
      // возвращало пустоту — тот самый «поиск только на английском».
      'lang': lang,
      if (q.isNotEmpty) 'q': q,
    },
  );
  try {
    final resp = await http_pkg.get(uri).timeout(const Duration(seconds: 8));
    if (resp.statusCode != 200) return const _GifPage.failed();
    final body = jsonDecode(resp.body) as Map<String, dynamic>;
    final results = (body['data'] as List?) ?? [];
    final out = <_GifItem>[];
    String? urlOf(Map images, String key) {
      final r = images[key];
      if (r is Map) {
        final u = r['url'];
        if (u is String && u.isNotEmpty) return u;
      }
      return null;
    }

    for (final item in results) {
      try {
        final images = (item as Map)['images'] as Map?;
        if (images == null) continue;
        // Small, low-bandwidth animated preview for the grid.
        final preview =
            urlOf(images, 'fixed_width_downsampled') ??
            urlOf(images, 'fixed_width_small') ??
            urlOf(images, 'preview_gif') ??
            urlOf(images, 'fixed_width');
        // Size-capped full GIF for sending (downsized_medium ≤ ~5MB).
        final full =
            urlOf(images, 'downsized_medium') ??
            urlOf(images, 'downsized') ??
            urlOf(images, 'original') ??
            urlOf(images, 'fixed_width');
        if (preview == null || full == null) continue;
        out.add(_GifItem(previewUrl: preview, fullUrl: full));
      } catch (_) {
        continue;
      }
    }
    // Есть ли следующая страница. GIPHY отдаёт счётчики в `pagination`; когда их
    // нет, судим по полноте страницы — неполная страница значит конец.
    int? total;
    int? count;
    final pagination = body['pagination'];
    if (pagination is Map) {
      total = (pagination['total_count'] as num?)?.toInt();
      count = (pagination['count'] as num?)?.toInt();
    }
    final returned = count ?? results.length;
    final hasMore = (total != null && total > 0)
        ? (offset + returned) < total
        : results.length >= limit;
    return _GifPage(items: out, hasMore: hasMore, returned: returned);
  } catch (_) {
    return const _GifPage.failed();
  }
}

/// Noto Emoji Animation codepoints.
/// CDN: https://fonts.gstatic.com/s/e/notoemoji/latest/{codepoint}/lottie.json
// Full 881-entry Noto Emoji Animation catalog (generated by
// tools/regen_noto_codepoints.py). Was ~100 hand-listed entries; now the
// complete animatable set shared with the desktop + inline rendering.
const Map<String, String> _notoCodepoints = kNotoCodepoints;

final Map<String, Future<File?>> _notoLoadFutures = <String, Future<File?>>{};

Future<File?> _loadNotoLottieFile(String emoji) {
  final codepoint = _notoCodepoints[emoji];
  if (codepoint == null) return Future<File?>.value(null);
  return _notoLoadFutures[codepoint] ??= _doLoadNotoLottie(codepoint);
}

bool _isSoloNotoEmoji(String text) {
  final t = text.trim();
  return t.isNotEmpty && _notoCodepoints.containsKey(t);
}

/// Shows a small floating skin-tone chooser just ABOVE [anchor] with [base] +
/// its tone [variants]. Resolves to the chosen emoji, or null if dismissed by
/// tapping outside. Lets toneable gestures occupy one grid swatch instead of six.
Future<String?> _showSkinTonePopover(
  BuildContext context,
  String base,
  List<String> variants,
  Offset anchor,
) {
  final overlayState = Overlay.of(context);
  final completer = Completer<String?>();
  final options = <String>[base, ...variants];
  final media = MediaQuery.of(context).size;
  const itemW = 46.0;
  const padH = 8.0;
  final totalW = options.length * itemW + padH * 2;
  final left = (anchor.dx - totalW / 2).clamp(8.0, media.width - totalW - 8.0);
  final top = (anchor.dy - 70.0).clamp(48.0, media.height - 80.0);
  late OverlayEntry entry;
  void close(String? value) {
    if (completer.isCompleted) return;
    completer.complete(value);
    entry.remove();
  }

  entry = OverlayEntry(
    builder: (ctx) => Stack(
      children: [
        Positioned.fill(
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => close(null),
          ),
        ),
        Positioned(
          left: left,
          top: top,
          child: Material(
            color: Colors.transparent,
            child: Container(
              padding: const EdgeInsets.symmetric(
                horizontal: padH,
                vertical: 6,
              ),
              decoration: BoxDecoration(
                color: const Color(0xFF20232C),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: Colors.white.withValues(alpha: 0.10)),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0x66000000),
                    blurRadius: 18,
                    offset: Offset(0, 6),
                  ),
                ],
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  for (final e in options)
                    SizedBox(
                      width: itemW,
                      height: itemW,
                      child: Material(
                        color: Colors.transparent,
                        child: InkWell(
                          borderRadius: BorderRadius.circular(12),
                          onTap: () => close(e),
                          child: Center(
                            child: Text(
                              e,
                              style: const TextStyle(fontSize: 28, height: 1),
                            ),
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
      ],
    ),
  );
  overlayState.insert(entry);
  return completer.future;
}

/// Shared reaction emoji picker body: a search field above a categorized
/// (or filtered) Noto emoji grid. Extracted so the standalone bottom-sheet
/// ([_ChatScreenState._pickReactionEmoji]) and the in-place expanded reaction
/// popup render the exact same UI — categories, search and skin-tone chooser —
/// with no duplication. It only reads the catalog and reports a pick via
/// [onPick]; it never touches the message send/receive path.
class _ReactionEmojiPicker extends StatefulWidget {
  const _ReactionEmojiPicker({
    required this.categories,
    required this.onPick,
    this.bottomInset = 16.0,
  });

  /// Localized category sections (label + emoji list) to show when not searching.
  final List<({String label, List<String> emoji})> categories;

  /// Called with the chosen emoji (after the skin-tone chooser resolves, if any).
  final void Function(String chosen) onPick;

  /// Extra space appended below the grid (e.g. for the bottom safe-area inset).
  final double bottomInset;

  @override
  State<_ReactionEmojiPicker> createState() => _ReactionEmojiPickerState();
}

class _ReactionEmojiPickerState extends State<_ReactionEmojiPicker> {
  int _selectedCategory = 0;
  final ScrollController _gridController = ScrollController();

  @override
  void dispose() {
    _gridController.dispose();
    super.dispose();
  }

  void _selectCategory(int i) {
    setState(() => _selectedCategory = i);
    if (_gridController.hasClients) _gridController.jumpTo(0);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final cs = theme.colorScheme;
    final categories = widget.categories;
    final safeIndex =
        (_selectedCategory >= 0 && _selectedCategory < categories.length)
        ? _selectedCategory
        : 0;
    final current = categories.isEmpty
        ? const <String>[]
        : categories[safeIndex].emoji;

    Widget buildEmojiTile(String emoji) =>
        _buildEmojiPickerTile(context, emoji, widget.onPick);

    const gridDelegate = SliverGridDelegateWithFixedCrossAxisCount(
      crossAxisCount: 8,
      crossAxisSpacing: 6,
      mainAxisSpacing: 6,
      childAspectRatio: 1,
    );

    return Column(
      children: <Widget>[
        // Horizontal category strip (replaced the old search field): tap a
        // category to show it; the grid scrolls back to the top on switch.
        SizedBox(
          height: 46,
          child: ListView.separated(
            scrollDirection: Axis.horizontal,
            padding: const EdgeInsets.fromLTRB(12, 10, 12, 4),
            itemCount: categories.length,
            separatorBuilder: (_, __) => const SizedBox(width: 4),
            itemBuilder: (ctx, i) {
              final selected = i == safeIndex;
              final rep = categories[i].emoji.isNotEmpty
                  ? categories[i].emoji.first
                  : '⭐';
              return GestureDetector(
                onTap: () => _selectCategory(i),
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 120),
                  width: 38,
                  height: 38,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: selected
                        ? cs.primary.withValues(alpha: 0.18)
                        : Colors.transparent,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Text(
                    rep,
                    style: const TextStyle(
                      fontSize: 22,
                      height: 1,
                      fontFamilyFallback: kEmojiFontFallback,
                    ),
                  ),
                ),
              );
            },
          ),
        ),
        Expanded(
          child: RepaintBoundary(
            child: CustomScrollView(
              controller: _gridController,
              physics: secretlyListPhysics(),
              slivers: <Widget>[
                SliverPadding(
                  padding: const EdgeInsets.fromLTRB(16, 4, 16, 0),
                  sliver: SliverGrid(
                    delegate: SliverChildBuilderDelegate(
                      (_, i) => buildEmojiTile(current[i]),
                      childCount: current.length,
                    ),
                    gridDelegate: gridDelegate,
                  ),
                ),
                SliverToBoxAdapter(child: SizedBox(height: widget.bottomInset)),
              ],
            ),
          ),
        ),
      ],
    );
  }
}

/// Shared emoji-picker grid tile. Toneable bases show a small dot and open the
/// skin-tone chooser on tap; everything else calls [onPick] directly. [onPick]
/// lets each picker pop its own result type (raw emoji vs _PickerResult).
Widget _buildEmojiPickerTile(
  BuildContext sheetCtx,
  String emoji,
  void Function(String chosen) onPick,
) {
  final toneVariants = kNotoSkinToneVariants[emoji];
  final glyph = Stack(
    children: [
      Center(
        child: Text(
          emoji,
          style: const TextStyle(
            fontSize: 30,
            height: 1,
            // Route a codepoint the UI font lacks to the platform colour-emoji
            // font so picker-preview tiles never render as a tofu cross.
            fontFamilyFallback: kEmojiFontFallback,
          ),
          textAlign: TextAlign.center,
        ),
      ),
      if (toneVariants != null)
        Positioned(
          right: 5,
          bottom: 5,
          child: Container(
            width: 6,
            height: 6,
            decoration: BoxDecoration(
              color: Colors.white.withValues(alpha: 0.45),
              shape: BoxShape.circle,
            ),
          ),
        ),
    ],
  );
  if (toneVariants == null) {
    return RepaintBoundary(
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          borderRadius: BorderRadius.circular(18),
          onTap: () => onPick(emoji),
          child: glyph,
        ),
      ),
    );
  }
  return RepaintBoundary(
    child: GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTapUp: (d) async {
        final picked = await _showSkinTonePopover(
          sheetCtx,
          emoji,
          toneVariants,
          d.globalPosition,
        );
        if (picked != null) onPick(picked);
      },
      child: glyph,
    ),
  );
}

/// Replaces standard emoji (typed via the iOS/system keyboard or pasted) inside
/// already-built message [spans] with looping Noto Lottie animations — the
/// Telegram-style "typed emoji animate" behaviour. Only simple plain-text spans
/// are split; links/mentions/formatted (tappable or nested) spans are left
/// intact. Copy/selection is unaffected because the context-menu copy uses the
/// original message text, not these display spans.
List<InlineSpan> _animateEmojiInSpans(List<InlineSpan> spans, double fontSize) {
  final out = <InlineSpan>[];
  for (final span in spans) {
    if (span is TextSpan &&
        span.text != null &&
        span.text!.isNotEmpty &&
        (span.children == null || span.children!.isEmpty) &&
        span.recognizer == null) {
      out.addAll(_splitEmojiSpans(span.text!, span.style, fontSize));
    } else {
      out.add(span);
    }
  }
  return out;
}

List<InlineSpan> _splitEmojiSpans(
  String text,
  TextStyle? style,
  double fontSize,
) {
  // Fast path: nothing animatable in this run.
  var hasEmoji = false;
  for (final ch in text.characters) {
    if (_notoCodepoints.containsKey(ch)) {
      hasEmoji = true;
      break;
    }
  }
  if (!hasEmoji) return <InlineSpan>[TextSpan(text: text, style: style)];

  final out = <InlineSpan>[];
  final buf = StringBuffer();
  void flush() {
    if (buf.isNotEmpty) {
      out.add(TextSpan(text: buf.toString(), style: style));
      buf.clear();
    }
  }

  for (final ch in text.characters) {
    if (_notoCodepoints.containsKey(ch)) {
      flush();
      out.add(
        WidgetSpan(
          alignment: PlaceholderAlignment.middle,
          child: _NotoEmojiLottie(
            emoji: ch,
            size: fontSize * 1.35,
            mode: _NotoLottieMode.looping,
          ),
        ),
      );
    } else {
      buf.write(ch);
    }
  }
  flush();
  return out;
}

Future<File?> _doLoadNotoLottie(String codepoint) async {
  if (_notoFileCache.containsKey(codepoint)) return _notoFileCache[codepoint];
  final dir = await getTemporaryDirectory();
  final file = File(p.join(dir.path, 'noto_emoji_$codepoint.json'));
  if (await file.exists()) {
    // Heal a file cached BEFORE the `tm` + `sr` fix. Without this the emoji
    // that prompted the fix keeps vanishing forever on every install that had
    // already downloaded it — the cache never expires.
    await _healCachedNotoLottie(file);
    _notoFileCache[codepoint] = file;
    return file;
  }
  try {
    final uri = Uri.parse(
      'https://fonts.gstatic.com/s/e/notoemoji/latest/$codepoint/lottie.json',
    );
    final response = await http_pkg
        .get(uri)
        .timeout(const Duration(seconds: 15));
    if (response.statusCode == 200) {
      final normalized = normalizeNotoLottieBytes(response.bodyBytes);
      await file.writeAsBytes(normalized ?? response.bodyBytes);
      _notoFileCache[codepoint] = file;
      return file;
    }
  } catch (_) {}
  return null;
}

/// Rewrites an already-cached animation in place if it carries the `tm` + `sr`
/// conflict. Silent and fail-soft: any problem leaves the file untouched, which
/// is exactly the behaviour that shipped before.
Future<void> _healCachedNotoLottie(File file) async {
  try {
    final normalized = normalizeNotoLottieBytes(await file.readAsBytes());
    if (normalized != null) await file.writeAsBytes(normalized);
  } catch (_) {}
}

class ChatScreen extends StatefulWidget {
  const ChatScreen({
    super.key,
    required this.controller,
    required this.convoId,
    required this.title,
    this.peerProfileIdForSend,
    this.requestProfileId,
    this.initialForwardDraft,
  });

  final AppController controller;
  final String convoId;
  final String title;
  final String? peerProfileIdForSend;

  /// If set, this screen shows a pending request chat (read-only) with Accept/Block actions.
  final String? requestProfileId;
  final ForwardDraft? initialForwardDraft;

  @override
  State<ChatScreen> createState() => _ChatScreenState();
}

/// READ-RECEIPT SCOPE (2026-07-18): observes chat-route pushes/pops so a
/// ChatScreen can re-evaluate "mark read" the moment it becomes visible again
/// (a pushed sub-screen — peer profile, media viewer — was popped off it).
/// Registered on the app's root Navigator (see main.dart navigatorObservers).
final RouteObserver<ModalRoute<void>> chatRouteObserver =
    RouteObserver<ModalRoute<void>>();

class _ChatScreenState extends State<ChatScreen>
    with TickerProviderStateMixin, RouteAware {
  static const String _favoritesNoteAssetPath =
      AppAssetPaths.favoritesNotebookSvg;
  static const String _smileIconAssetPath = AppAssetPaths.smileLottie;
  static const String _prefsChatScrollOffsetPrefix = 'chat_scroll_offset_v2_';
  static const String _prefsSeenReactionAnimationsPrefix =
      'chat_seen_reaction_animation_v1_';
  static const String _prefsPinnedMessagesPrefix = 'chat_pinned_messages_v1_';
  static const String _prefsDraftPrefix = 'chat_draft_v1_';
  // Mirror of the keys persisted by SettingsScreen (Language → Translation).
  static const String _prefsLanguageShowTranslateButtonKey =
      'settings_language_show_translate_btn_v1';
  static const String _prefsLanguageTranslateWholeChatKey =
      'settings_language_translate_whole_chat_v1';
  // Translator language direction (Settings → Language → Translation).
  // Source 'auto' (default) = auto-detect the message language; otherwise a
  // pinned BCP-47 code. Target '' (default) = the app/device language.
  static const String _prefsLanguageTranslateSourceKey =
      'settings_language_translate_source_v1';
  static const String _prefsLanguageTranslateTargetKey =
      'settings_language_translate_target_v1';
  final _text = TextEditingController();

  /// Превью первой ссылки в поле ввода — уходит вместе с сообщением.
  final _linkPreviewDraft = OutgoingLinkPreviewDraft();
  final _messageInputFocusNode = FocusNode();
  final _sendButtonFocusNode = FocusNode(
    canRequestFocus: false,
    skipTraversal: true,
  );
  final _chatSearchController = TextEditingController();
  final _chatSearchFocusNode = FocusNode();
  final _scroll = ScrollController();

  /// Current keyboard inset, republished for the bubble gradient ONLY.
  ///
  /// 🔴 WHY (2026-08-01, field: "our bubbles have a dynamic colour — one at the
  /// bottom, another at the top. Raising the keyboard moves the bubbles up but
  /// their colour does not change; only a message I send WHILE typing gets the
  /// right, in-between colour, so it no longer matches the ones around it").
  ///
  /// The gradient is one continuous ramp across the VIEWPORT, and each bubble
  /// samples the slice its screen position falls on. Repainting was driven by
  /// [_scroll] alone — but opening the keyboard does not scroll anything. The
  /// list is lifted by [_KeyboardInsetAnchor]'s padding, so `pixels` never
  /// moves, no listener fires, and every already-painted bubble keeps the
  /// colour of the position it used to occupy. A freshly built bubble resolves
  /// against the CURRENT layout, which is exactly why the new message looked
  /// right while its neighbours did not.
  ///
  /// A plain `MediaQuery.viewInsetsOf` in the body would fix it and undo the
  /// 2026-07-05 work that deliberately keeps the chat body off the keyboard's
  /// rebuild path. So the inset is published from the anchor leaf instead and
  /// merged into the repaint signal: the body still does not rebuild, only the
  /// gradient repaints.
  final ValueNotifier<double> _keyboardInsetForGradient =
      ValueNotifier<double>(0);

  /// What a gradient bubble repaints on: scrolling OR the keyboard moving.
  late final Listenable _bubbleGradientRepaint = Listenable.merge(
    <Listenable>[_scroll, _keyboardInsetForGradient],
  );
  final AudioRecorder _voiceRecorder = AudioRecorder();
  late final AnimationController _smileIconController;

  /// Whether the smile has already played its one-off greeting for this
  /// appearance — see _syncComposerTickers for why it must not loop.
  bool _smileIconGreeted = false;
  late final AnimationController _voicePulseController;
  late final AnimationController _voiceLockBounceController;
  bool _sendingAttachment = false;
  // In-progress uploads now live in the CONTROLLER (survive chat navigation);
  // these read the per-convo lists so the bubble stays visible with live
  // progress when the user leaves and returns mid-upload. See M1.
  List<PendingPhotoAlbumUpload> get _pendingPhotoAlbums =>
      widget.controller.pendingPhotoAlbumUploadsFor(widget.convoId);
  List<PendingPhotoUpload> get _pendingPhotos =>
      widget.controller.pendingPhotoUploadsFor(widget.convoId);
  List<PendingAudioUpload> get _pendingAudio =>
      widget.controller.pendingAudioUploadsFor(widget.convoId);
  StreamSubscription<String>? _pendingUploadsSub;
  // Progress-only ticks ride this instead of setState — see the subscription in
  // initState. The upload bubbles rebuild themselves off it; the timeline rows
  // and the sliver delegate never see it.
  final ValueNotifier<int> _pendingUploadsTick = ValueNotifier<int>(0);
  String _lastPendingUploadsSignature = '';

  // Позиция воспроизведения ездит здесь, а не через setState — ровно тем же
  // приёмом, что и прогресс загрузок выше.
  //
  // Плеер тикает пять раз в секунду (positionStream just_audio), а setState в
  // этом State пересоздаёт делегат сливера, то есть инвалидирует ВСЕ
  // материализованные строки. Позиция при этом нужна двоим: аудио-пузырю в
  // ленте и панели «сейчас играет» в шапке — они и подписаны.
  final ValueNotifier<int> _audioTick = ValueNotifier<int>(0);

  // Снимок «структурной» части состояния плеера. Смена трека, паузы или самого
  // факта наличия трека меняет ВЁРСТКУ: от `_activeNowPlayingItem != null`
  // зависит, есть ли у AppBar `bottom`, какова `_headerBottomHeight()` и
  // сливается ли панель с закреплённым сообщением в один остров. Такое тиком
  // не обойтись — нужен полноценный setState. Позиция и длительность на
  // вёрстку не влияют и едут тиком.
  String? _audioStructuralTrackId;
  bool _audioStructuralPlaying = false;
  bool _audioStructuralHasTrack = false;

  /// Identity of the pending-upload SET (not its progress). Only a change here
  /// alters the list's itemCount / row identities and needs a real rebuild.
  String _pendingUploadsSignature() {
    final b = StringBuffer();
    for (final a in _pendingPhotoAlbums) {
      b..write(a.id)..write(',');
    }
    b.write('|');
    for (final p in _pendingPhotos) {
      b..write(p.id)..write(',');
    }
    b.write('|');
    for (final a in _pendingAudio) {
      b..write(a.id)..write(',');
    }
    return b.toString();
  }
  StreamSubscription<AttachmentUploadErrorEvent>? _attachmentUploadErrorSub;
  List<ChatEvent>? _cachedEvents;
  // PERF(db): loadEvents future reused across rebuilds that don't come from a
  // `changed` tick (keyboard, overlays, voice UI) — see
  // _eventsFutureForCurrentVersion().
  Future<List<ChatEvent>>? _eventsFuture;
  int _eventsFutureVersion = -1;
  String _eventsFutureConvoId = '';
  final Set<String> _imagePreviewLoadingBlobIds = <String>{};
  final Set<String> _imagePreviewFailedBlobIds = <String>{};
  final Set<String> _selectedEventIds = <String>{};
  final Set<String> _seenEventIds = <String>{};
  // payloadEventIds that were hidden last build because a pending-upload
  // placeholder was covering them. When one leaves this set (the placeholder
  // settled into its real event row) we let that row appear WITHOUT the
  // slide-up entrance, so a sent photo/voice/music swaps in seamlessly instead
  // of the placeholder vanishing while a "second copy" animates in.
  Set<String> _prevSuppressedPayloadIds = <String>{};
  // Persistent "suppress the entrance for this row" intent, held until the row
  // is actually rendered once — so the swap stays seamless even if the real
  // row lands a frame after the placeholder was dropped.
  final Set<String> _suppressEntranceForPayloadIds = <String>{};
  // PERF memo for the timeline filter → dedup → reactionIds chain. That chain is
  // a pure function of (timeline, suppressedPayloadIds), and the timeline list
  // identity is stable while the events are unchanged (_timelineEntriesFutureFor
  // caches its future by signature). A media upload ticks progress at frame rate
  // and rebuilds the timeline subtree on EVERY tick — recomputing three O(n)
  // passes (list + set allocations) per tick on the UI thread made the chat
  // stutter while scrolling during a send. Cache the results and recompute only
  // when the inputs actually change.
  List<_TimelineEntry>? _memoTimelineInput;
  Set<String> _memoSuppressedPayloadIds = <String>{};
  List<_TimelineEntry>? _memoVisibleTimeline;
  List<String>? _memoReactionIds;
  /// Last reactions we actually rendered, kept synchronously.
  ///
  /// The query is async, so the timeline used to paint its bubbles first and
  /// drop the reactions in a frame or two later — a visible "pop-in" every time
  /// the chat was opened or rebuilt, on reactions that were already known. This
  /// map is handed to the builder as `initialData`, so anything we have shown
  /// before appears WITH its bubble in the same frame; only genuinely new
  /// reactions wait for the query.
  ///
  /// 🔴 SCOPE (2026-08-01, field: "old reactions get placed again on every
  /// entry, the bubbles jump"): this map is on the SCREEN's State, so it dies
  /// with the screen and starts empty on the next open — "what we have shown
  /// before" was only ever true within a single visit. The cross-visit half
  /// lives on the controller (`cachedReactionsFor`) and is used as the
  /// fallback seed; this field still wins while the screen is alive because it
  /// is the freshest of the two.
  Map<String, List<MessageReaction>> _reactionsShown =
      const <String, List<MessageReaction>>{};

  // Memo for the reactions query — see _reactionsFutureFor.
  List<String>? _reactionsFutureIds;
  int _reactionsFutureVersion = -1;
  Future<Map<String, List<MessageReaction>>>? _reactionsFuture;
  // Voice-to-text state, per message. It lives HERE because the trigger renders
  // outside the bubble and the transcript inside it — two different subtrees
  // that must agree, so neither can own the state.
  final Map<String, VoiceTranscriptionController> _voiceTx =
      <String, VoiceTranscriptionController>{};

  VoiceTranscriptionController _voiceTxFor(
    String eventId,
    AttachmentEventV1 attachment,
  ) => _voiceTx.putIfAbsent(
    eventId,
    () => VoiceTranscriptionController(
      eventId: eventId,
      appController: widget.controller,
      resolveAudioFile: () => _ensureAttachmentFile(attachment),
    ),
  );
  // Telegram-style floating day chip: while the timeline scrolls, a small date
  // pill under the header islands names the day of the messages currently at
  // the TOP of the viewport, and fades away once scrolling settles.
  //
  // A ValueNotifier, NOT setState: this flips exactly while the user is
  // scrolling (chip appears on the first scroll tick, changes on every day
  // boundary crossed, hides shortly after the fling settles), and a setState
  // there rebuilds the ENTIRE chat subtree mid-gesture — every glass bubble on
  // screen — which dropped frames and read as scroll stutter. Only the chip's
  // own overlay listens to this.
  final ValueNotifier<({int dayMs, bool visible})?> _floatingDay =
      ValueNotifier<({int dayMs, bool visible})?>(null);
  Timer? _floatingDayHideTimer;
  int _lastFloatingDayScanMs = 0;
  // Global-Y of the timeline's top edge (under the islands), published by build
  // so the scroll-time scan knows what "at the top" means without depending on
  // MediaQuery from a callback.
  double _timelineTopEdgePx = 0;
  _ReplyTarget? _replyTo;
  _EditingTarget? _editingTarget;
  ForwardDraft? _forwardDraft;
  _NowPlayingItem? _nowPlaying;
  String? _audioLoadingBlobId;
  // Generic (non-media) files currently downloading on tap — drives the
  // circular spinner shown on the file bubble until the blob is cached.
  final Set<String> _downloadingFileBlobIds = <String>{};
  final Map<String, Duration> _audioAttachmentDurations = <String, Duration>{};
