  bool get _selectionMode => _selectedEventIds.isNotEmpty;

  /// PERF(idle): keeps the two composer animation loops honest — the voice
  /// pulse ticks ONLY while recording, and the smile Lottie pauses while its
  /// icon is not on screen (voice recording / in-chat search). A repeating
  /// AnimationController schedules frames even when nothing visible listens,
  /// so an idle open chat used to never reach a zero-frame steady state.
  /// (Selection mode is deliberately not tracked — it is rare, short-lived and
  /// toggled from many sites.)
  void _syncComposerTickers() {
    if (!mounted) return;
    final smileVisible = !_voiceRecording && !_chatSearchOpen;
    if (smileVisible) {
      // 🔴 NOT `repeat()` (2026-07-31, iOS heat).
      //
      // A controller that repeats forever schedules a frame every vsync — 60
      // or 120 a second — for as long as a chat is open. Nothing else has to
      // be moving: the engine still builds, rasterises and presents, so the
      // device never reaches idle. On iOS that also re-composites the frosted
      // bubble glass on every one of those frames, which is what turned a
      // decorative icon into a measurable heat source.
      //
      // It now plays ONCE when it appears and then holds still; tapping it
      // plays it again (see _openEmojiPanel). The delight survives, the
      // permanent frame loop does not.
      if (!_smileIconGreeted && !_smileIconController.isAnimating) {
        _smileIconGreeted = true;
        _smileIconController.forward(from: 0);
      }
    } else {
      _smileIconController.stop();
      // Re-arm so it greets again next time it comes back into view.
      _smileIconGreeted = false;
    }
    if (_voiceRecording) {
      if (!_voicePulseController.isAnimating) {
        _voicePulseController.repeat(reverse: true);
      }
    } else {
      _voicePulseController.stop();
    }
  }
  bool get _isGroupChat => widget.convoId.startsWith('group:');
  bool get _isFavoritesChat =>
      widget.controller.isSavedMessagesConvo(widget.convoId);

  void _scheduleComposerOverlayMeasurement() {
    if (_composerOverlayMeasureScheduled) return;
    _composerOverlayMeasureScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _composerOverlayMeasureScheduled = false;
      if (!mounted) return;
      final measureContext = _composerOverlayKey.currentContext;
      final renderObject = measureContext?.findRenderObject();
      if (measureContext == null ||
          renderObject is! RenderBox ||
          !renderObject.hasSize) {
        return;
      }
      final mediaPaddingBottom =
          MediaQuery.maybeOf(measureContext)?.padding.bottom ?? 0.0;
      final safeAreaBottomGap = mediaPaddingBottom > 10.0
          ? mediaPaddingBottom
          : 10.0;
      final nextHeight = (renderObject.size.height - safeAreaBottomGap).clamp(
        0.0,
        double.infinity,
      );
      final currentHeight = _composerOverlayHeight;
      if (currentHeight != null && (currentHeight - nextHeight).abs() < 0.5) {
        return;
      }
      setState(() {
        _composerOverlayHeight = nextHeight;
      });
    });
  }

  void _scheduleReactionTokenCleanup(String key, int token) {
    Timer(const Duration(milliseconds: 2200), () {
      if (!mounted) return;
      if (_reactionPlayTokens[key] != token) {
        return;
      }
      setState(() {
        _reactionPlayTokens.remove(key);
      });
    });
  }

  void _assignReactionPlayToken(String key) {
    final token = ++_reactionPlaySeq;
    _reactionPlayTokens[key] = token;
    _scheduleReactionTokenCleanup(key, token);
  }

  String get _seenReactionAnimationsPrefKey =>
      '$_prefsSeenReactionAnimationsPrefix${widget.convoId.trim()}';

  String _reactionSeenAnimationKey(MessageReaction reaction) =>
      '${reaction.eventId}|${reaction.profileId}|${reaction.emoji}|${reaction.createdAtMs}';

  Future<void> _ensureReactionSeenStateReady() {
    if (_reactionSeenStateReady) {
      return Future.value();
    }
    return _reactionSeenStateLoadFuture ??= _loadReactionSeenState();
  }

  Future<void> _loadReactionSeenState() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final stored =
          prefs.getStringList(_seenReactionAnimationsPrefKey) ??
          const <String>[];
      final normalized = stored
          .where((value) => value.trim().isNotEmpty)
          .toList(growable: false);
      if (!mounted) {
        _seenReactionAnimationKeys
          ..clear()
          ..addAll(normalized);
        _reactionSeenStateReady = true;
        return;
      }
      setState(() {
        _seenReactionAnimationKeys
          ..clear()
          ..addAll(normalized);
        _reactionSeenStateReady = true;
      });
    } catch (_) {
      _reactionSeenStateReady = true;
    } finally {
      _reactionSeenStateLoadFuture = null;
    }
  }

  Future<void> _markReactionAnimationsSeen(Iterable<String> seenKeys) async {
    final normalized = seenKeys
        .map((value) => value.trim())
        .where((value) => value.isNotEmpty)
        .toList(growable: false);
    if (normalized.isEmpty) {
      return;
    }
    await _ensureReactionSeenStateReady();
    for (final seenKey in normalized) {
      _seenReactionAnimationKeys.add(seenKey);
    }
    // ALWAYS write through to prefs. Callers add keys to the in-memory set
    // BEFORE calling this (so the UI suppresses instantly) — the old
    // "skip when set unchanged" gate therefore never fired a write, the seen
    // state was lost on every chat close, and every pop replayed on re-entry.
    const maxStoredReactionAnimations = 1200;
    while (_seenReactionAnimationKeys.length > maxStoredReactionAnimations) {
      _seenReactionAnimationKeys.remove(_seenReactionAnimationKeys.first);
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setStringList(
        _seenReactionAnimationsPrefKey,
        _seenReactionAnimationKeys.toList(growable: false),
      );
    } catch (_) {}
  }

  void _syncReactionPresentation({
    required List<String> reactionIds,
    required Map<String, List<MessageReaction>> reactionMap,
    required bool reactionsLoaded,
  }) {
    if (reactionIds.isEmpty || !_reactionSeenStateReady) {
      return;
    }

    var shouldHaptic = false;
    var registeredAny = false;
    final selfProfileId = widget.controller.profileId;

    for (final eventId in reactionIds) {
      final reactions = reactionMap[eventId] ?? const <MessageReaction>[];
      for (final reaction in reactions) {
        final key = '$eventId|${reaction.profileId}|${reaction.emoji}';
        final seenKey = _reactionSeenAnimationKey(reaction);
        final previousUpdatedAt = _reactionUpdatedAtByKey[key];
        _reactionUpdatedAtByKey[key] = reaction.updatedAtMs;
        if (_seenReactionAnimationKeys.contains(seenKey)) {
          continue;
        }
        if (previousUpdatedAt == null ||
            reaction.updatedAtMs > previousUpdatedAt) {
          // Do NOT consume the animation here — the message may be far
          // off-screen (e.g. a reaction that arrived while the app was
          // closed). Register it as PENDING; the row's itemBuilder claims it
          // when the message is actually built/visible, which is when the
          // one-shot pop plays and only then is it persisted as seen.
          _pendingReactionAnimsByEvent.putIfAbsent(
            eventId,
            () => <String, String>{},
          )[key] = seenKey;
          registeredAny = true;
          if (reaction.profileId != selfProfileId && _reactionBacklogSynced) {
            // Haptic only for a LIVE arrival, not for the initial backlog
            // sweep on chat open.
            shouldHaptic = true;
          }
        }
      }
    }
    // Only declare the backlog "synced" once the reaction map has ACTUALLY
    // loaded. The map loads async (FutureBuilder), so an early empty sweep used
    // to flip this flag before any reaction was seen — then the real reactions
    // arrived a sweep later and were mis-classified as LIVE arrivals, firing a
    // haptic on every chat (re)open. Gate it on the real load.
    if (reactionsLoaded) {
      _reactionBacklogSynced = true;
    }

    if (shouldHaptic) {
      unawaited(widget.controller.triggerUiHaptic());
    }
    if (registeredAny) {
      // A pending pop may belong to an already-visible row — poke one rebuild
      // so its itemBuilder runs and claims it.
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() {});
      });
    }
  }

  /// Claims the pending one-shot reaction pops for a message whose row is being
  /// BUILT (≈ visible): assigns play tokens on the next frame and persists the
  /// seen keys, so each reaction animates exactly once — and only on-screen.
  void _claimPendingReactionAnimations(String reactionEventId) {
    final pending = _pendingReactionAnimsByEvent.remove(reactionEventId);
    if (pending == null || pending.isEmpty) {
      return;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) {
        return;
      }
      setState(() {
        _seenReactionAnimationKeys.addAll(pending.values);
        for (final key in pending.keys) {
          _assignReactionPlayToken(key);
        }
      });
      unawaited(_markReactionAnimationsSeen(pending.values));
    });
  }

  @override
  void initState() {
    super.initState();
    widget.controller.setActiveConversation(widget.convoId);
    widget.controller.chatFocusRequest.addListener(_onChatFocusRequest);
    unawaited(_ensureReactionSeenStateReady());
    unawaited(_acknowledgeMissedCallsForConversation());
    // Immediately pull the peer's latest profile (name / avatar / frame / cover
    // / emoji-status / badge) on chat open. Background refresh only covered
    // saved contacts + pending requests, so a chat peer's profile could stay
    // blank — fetch it right away for the conversation we're entering.
    if (!_isGroupChat) {
      unawaited(
        widget.controller
            .refreshProfileMeta(widget.convoId.trim())
            .catchError((_) {}),
      );
    }
    if (_isGroupChat) {
      unawaited(_refreshRoomPolicyState());
      unawaited(_refreshRoomPinnedMessageState());
      unawaited(_refreshRoomMentionCandidates(force: true));
      unawaited(_refreshActiveRoomCall());
      // 🔴 Темы берём ИЗ БАЗЫ, а не только из видимой ленты (15.09.2026).
      //
      // Список рассылается скрытым сообщением, и до сих пор экран собирал его
      // заново из загруженного окна — последних двухсот событий. Стоило
      // накопиться двум сотням новых сообщений, и темы пропадали, а их
      // сообщения уезжали в «Общий». На устройстве, где комната не была
      // открыта в нужный момент, тем не появлялось вовсе.
      unawaited(_loadStoredRoomTopics());
    }
    // 🔴 БЕЗ `..repeat()` — это ровно тот вечный цикл кадров, который убирал
    // фикс от 31.07.2026 (нагрев iOS), см. развёрнутый комментарий в
    // _syncComposerTickers. Он остался здесь и переживал фикс: ветка
    // `smileVisible` проигрывает приветствие только при
    // `!_smileIconController.isAnimating`, а контроллер уже крутился с
    // initState — то есть приветствие не запускалось, а цикл жил весь сеанс
    // чата. Останавливал его лишь `Lottie.onLoaded`, и только если реальная
    // длительность ассета отличалась от 1800 мс.
    //
    // Приветствие теперь заводит `_syncComposerTickers()` — из onLoaded и на
    // каждом переходе состояний композера.
    _smileIconController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1800),
    );
    // PERF(idle): the voice pulse is only visible while recording, so it must
    // not tick from initState — a repeating controller keeps scheduling frames
    // for the whole life of the screen. Started/stopped by
    // _syncComposerTickers() on the _voiceRecording transitions.
    _voicePulseController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 920),
    );
    _voiceLockBounceController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 520),
    );
    // Same duration chats_screen uses for its search-bubble morph (260 ms).
    // No addListener(setState) here on purpose — that used to rebuild the
    // ENTIRE chat screen (message list included) on every animation tick.
    // The two header islands that read _chatSearchReveal are each wrapped in
    // their own narrow AnimatedBuilder instead.
    _chatSearchRevealController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 260),
    );
    _forwardDraft = widget.initialForwardDraft;
    _text.addListener(_onComposerTextChanged);
    unawaited(_loadBundledWallpapers());
    unawaited(_restoreChatWallpaperSelection());
    unawaited(_restorePinnedMessages());
    unawaited(_restoreDraft());
    unawaited(_restoreComposerCaptureMode());
    unawaited(_loadTranslationSettings());
    if (Platform.isAndroid) {
      // Pre-fetch the on-device voice model in the background so the first
      // dictation isn't blocked by the ~140 MB download. Idempotent + best-effort.
      unawaited(VoiceTranscriptionService.instance.warmUp());
    }
    _changedSub = widget.controller.changed.listen((_) {
      _scheduleMarkRead();
      unawaited(_refreshJumpUnreadCount());
      if (_isGroupChat) {
        unawaited(_refreshRoomPolicyState());
        unawaited(_refreshRoomPinnedMessageState());
        unawaited(_refreshActiveRoomCall());
      }
    });
    // M1: repaint the in-flight upload bubbles (progress ring + list changes)
    // on the DEDICATED stream — it does NOT bump the controller's changeVersion,
    // so a 12fps progress tick reuses the memoized timeline (no sqlite re-query).
    // A progress tick must NOT setState the screen. This build() is the whole
    // chat — wallpaper, islands, composer AND the ListView — and rebuilding it
    // hands the sliver a fresh delegate, which invalidates EVERY materialized
    // row (not just the uploading bubble): each one re-runs its bubble surface,
    // theme lookups, gradient controller and painter churn. At ~12 ticks/second
    // (far more for an album, whose items tick independently) that is what made
    // scrolling stutter during an upload — not the work inside a single build,
    // which is why memoizing the timeline chain changed nothing.
    //
    // So: only the SET of uploads (add / finish / cancel) changes the list and
    // needs a rebuild. A pure progress tick just bumps a notifier that the
    // upload bubbles listen to on their own, and the timeline never hears it.
    _pendingUploadsSub = widget.controller.pendingUploadsChanged.listen((
      convoId,
    ) {
      if (!mounted || convoId != widget.convoId) return;
      final sig = _pendingUploadsSignature();
      if (sig != _lastPendingUploadsSignature) {
        _lastPendingUploadsSignature = sig;
        setState(() {});
        return;
      }
      _pendingUploadsTick.value++;
    });
    // Surface a failed background upload exactly like the old in-screen path
    // (too-large upsell / snackbar) — only for THIS conversation.
    _attachmentUploadErrorSub = widget.controller.attachmentUploadErrors.listen((
      event,
    ) {
      if (mounted && event.convoId == widget.convoId) {
        unawaited(_reportAttachmentError(event.error));
      }
    });
    _scroll.addListener(_handleScrollChanged);
    widget.controller.sharedAudioPlayback.addListener(
      _handleSharedAudioPlaybackChanged,
    );
    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_restoreScrollOffset());
      unawaited(_refreshJumpUnreadCount());
      _handleScrollChanged();
    });
    _scheduleMarkRead();
    // INVISIBLE perf: run retention on open, then periodically — decoupled from
    // the per-render `loadEvents` (which now passes `applyRetention: false`).
    _runRetentionSweep();
    _retentionTimer = Timer.periodic(
      const Duration(seconds: 30),
      (_) => _runRetentionSweep(),
    );
    // Pre-fetch Noto emoji for the reaction bar so they animate immediately.
    for (final e in _quickReactions) {
      unawaited(_loadNotoLottieFile(e));
    }
  }

  // ---------------------------------------------------------------------------
  // On-the-fly message translation (incoming text). Fail-soft everywhere.
  // ---------------------------------------------------------------------------

  Future<void> _loadTranslationSettings() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final showBtn =
          prefs.getBool(_prefsLanguageShowTranslateButtonKey) ?? false;
      final auto = prefs.getBool(_prefsLanguageTranslateWholeChatKey) ?? false;
      final source =
          prefs.getString(_prefsLanguageTranslateSourceKey) ?? 'auto';
      final target = prefs.getString(_prefsLanguageTranslateTargetKey) ?? '';
      if (!mounted) return;
      setState(() {
        _translateButtonEnabled = showBtn;
        _autoTranslate = auto;
        _translateSourceLang = source.trim().isEmpty ? 'auto' : source.trim();
        _translateTargetLang = target.trim();
      });
    } catch (_) {
      // Settings unavailable → leave translation off (safe default).
    }
  }

  /// Target language for translations: the user's pinned choice (Settings →
  /// Language), else the app/device language.
  String _effectiveTranslateTarget() {
    final pinned = _translateTargetLang.trim();
    if (pinned.isNotEmpty) return pinned;
    return Localizations.localeOf(context).languageCode;
  }

  /// Source language to translate FROM, or null to auto-detect per message.
  String? _effectiveTranslateSource() {
    final s = _translateSourceLang.trim().toLowerCase();
    return (s.isEmpty || s == 'auto') ? null : _translateSourceLang.trim();
  }

  /// Toggles the inline translation for an incoming text message. If a
  /// translation is already shown, hides it; if cached, shows it; otherwise
  /// translates on-device into the current app locale and shows the result.
  Future<void> _toggleTranslate(String eventId, String text) async {
    if (eventId.isEmpty) return;
    // Currently shown → hide.
    if (_translationShown.contains(eventId)) {
      setState(() => _translationShown.remove(eventId));
      return;
    }
    // Already translated (or known-failed) → just reveal.
    if (_translations.containsKey(eventId)) {
      setState(() => _translationShown.add(eventId));
      return;
    }
    // Avoid double work.
    if (_translateInFlight.contains(eventId)) return;
    setState(() => _translateInFlight.add(eventId));
    String? result;
    try {
      final target = _effectiveTranslateTarget();
      result = await MessageTranslationService.instance.translate(
        text: text,
        targetBcp: target,
        sourceBcp: _effectiveTranslateSource(),
        cacheKey: eventId,
      );
    } catch (_) {
      result = null;
    }
    if (!mounted) return;
    setState(() {
      _translateInFlight.remove(eventId);
      _translations[eventId] = result; // null = failed / nothing to translate
      _translationShown.add(eventId);
    });
  }

  /// AUTO mode: translate an incoming text message exactly once (lazy, cached)
  /// and reveal it without a tap. Safe to call from build — guarded by the
  /// in-flight / seen sets and deferred to a post-frame callback so it never
  /// causes jank or a setState-during-build.
  void _maybeAutoTranslate(String eventId, String text) {
    if (!_autoTranslate || eventId.isEmpty) return;
    if (_translations.containsKey(eventId) ||
        _translateInFlight.contains(eventId)) {
      return;
    }
    _translateInFlight.add(eventId);
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;
      String? result;
      try {
        final target = _effectiveTranslateTarget();
        result = await MessageTranslationService.instance.translate(
          text: text,
          targetBcp: target,
          sourceBcp: _effectiveTranslateSource(),
          cacheKey: eventId,
        );
      } catch (_) {
        result = null;
      }
      if (!mounted) return;
      setState(() {
        _translateInFlight.remove(eventId);
        _translations[eventId] = result;
        if (result != null) _translationShown.add(eventId);
      });
    });
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // Re-subscribe RouteAware to whatever route now hosts this chat (a
    // ModalRoute is only available here, not in initState).
    final route = ModalRoute.of(context);
    if (route is ModalRoute<void>) {
      chatRouteObserver.subscribe(this, route);
    }
  }

  @override
  void didPopNext() {
    // A sub-screen pushed over this chat (peer profile, media viewer) was just
    // popped → the chat is visible again. Mark read for anything that arrived
    // while it was covered (the live-tick gate had suppressed it as invisible).
    _scheduleMarkRead();
  }

  @override
  void didUpdateWidget(covariant ChatScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.convoId != widget.convoId) {
      widget.controller.clearActiveConversation(oldWidget.convoId);
      widget.controller.setActiveConversation(widget.convoId);
      // Drop the timeline memo so the new conversation never reuses the old
      // one's resolved entries, and run retention for the conversation we just
      // switched to.
      _timelineEntriesSignature = null;
      _timelineEntriesFuture = null;
      _runRetentionSweep();
      _reactionPlayTokens.clear();
      _reactionUpdatedAtByKey.clear();
      _seenReactionAnimationKeys.clear();
      _pinnedMessages = const <_PinnedMessage>[];
      _visiblePinnedMessageIndex = 0;
      _reactionSeenStateReady = false;
      _reactionSeenStateLoadFuture = null;
      unawaited(_ensureReactionSeenStateReady());
      unawaited(_acknowledgeMissedCallsForConversation());
      unawaited(_restorePinnedMessages());
      if (_isGroupChat) {
        _groupPinnedMessageEventId = null;
        _roomMentionCandidates = const [];
        _composerMentionDraft = null;
        unawaited(_refreshRoomPolicyState());
        unawaited(_refreshRoomPinnedMessageState());
        unawaited(_refreshRoomMentionCandidates(force: true));
      } else {
        _roomPolicyRefreshTimer?.cancel();
        _roomPolicyRefreshTimer = null;
        _roomPolicyState = null;
        _groupPinnedMessageEventId = null;
        _roomMentionCandidates = const [];
        _composerMentionDraft = null;
      }
    }
  }

  Future<void> _refreshRoomPinnedMessageState() async {
    if (!_isGroupChat) return;
    final settings = await widget.controller.getRoomSettings(widget.convoId);
    final nextPinnedMessageEventId = (settings.pinnedMessageEventId ?? '')
        .trim();
    final normalized = nextPinnedMessageEventId.isEmpty
        ? null
        : nextPinnedMessageEventId;
    if (!mounted || _groupPinnedMessageEventId == normalized) {
      return;
    }
    var shouldPersistPins = false;
    setState(() {
      _groupPinnedMessageEventId = normalized;
      if (normalized != null) {
        _pinnedMessages = _withPinnedMessage(
          _pinnedMessages,
          _pinnedMessageForEventId(normalized),
        );
        _visiblePinnedMessageIndex = 0;
        shouldPersistPins = true;
      }
    });
    if (shouldPersistPins) {
      await _savePinnedMessages();
    }
  }

  /// Scans resolved timeline items for the newest pin-sync control message and,
  /// when it supersedes what we last applied, adopts that pin list for this
  /// device too. Applied off-frame to avoid mutating state during a build, and
  /// guarded by [_appliedPinSyncAtMs] so it converges (no rebuild loop).
  void _maybeAdoptSharedPins(List<_ResolvedTimelineItem> resolved) {
    if (_pinSyncApplyScheduled) return;
    PinSyncCommand? newest;
    var newestAtMs = 0;
    for (final item in resolved) {
      final payload = item.payload;
      if (payload is! MsgEventV1) continue;
      final command = parsePinSyncCommand(payload.text);
      if (command == null) continue;
      final atMs = item.event.createdAtMs;
      if (atMs >= newestAtMs) {
        newestAtMs = atMs;
        newest = command;
      }
    }
    if (newest == null || newestAtMs <= _appliedPinSyncAtMs) return;

    final adopted = newest;
    final adoptedAtMs = newestAtMs;
    _pinSyncApplyScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      _pinSyncApplyScheduled = false;
      if (!mounted) return;
      final nextPins = adopted.pins
          .map(
            (ref) => _PinnedMessage(
              eventId: ref.eventId,
              previewText: ref.previewText,
              pinnedAtMs: ref.pinnedAtMs,
            ),
          )
          .toList(growable: false);
      setState(() {
        _appliedPinSyncAtMs = adoptedAtMs;
        _pinnedMessages = nextPins;
        _groupPinnedMessageEventId = nextPins.isEmpty
            ? null
            : nextPins.first.eventId;
        _visiblePinnedMessageIndex = _normalizedPinnedIndex(
          _visiblePinnedMessageIndex,
          _effectivePinnedMessages().length,
        );
      });
      await _savePinnedMessages();
    });
  }

  /// Topic id an event belongs to (null/empty = General). Only message-bearing
  /// events carry a topic; everything else lives in General.
  String? _eventTopicId(E2eEventV1? payload) {
    if (payload is MsgEventV1) return payload.topicId;
    if (payload is AttachmentEventV1) return payload.topicId;
    if (payload is StickerEventV1) return payload.topicId;
    return null;
  }

  /// Adopts the newest room-topic set broadcast by any member (latest-wins).
  /// Mirrors [_maybeAdoptSharedPins]: applied off-frame, guarded so it
  /// converges without a rebuild loop. If the currently-selected topic was
  /// deleted, falls back to General.
  void _maybeAdoptRoomTopics(List<_ResolvedTimelineItem> resolved) {
    if (_topicSyncApplyScheduled) return;
    TopicsSyncCommand? newest;
    var newestAtMs = 0;
    for (final item in resolved) {
      final payload = item.payload;
      if (payload is! MsgEventV1) continue;
      final command = parseTopicsSyncCommand(payload.text);
      if (command == null) continue;
      final atMs = item.event.createdAtMs;
      if (atMs >= newestAtMs) {
        newestAtMs = atMs;
        newest = command;
      }
    }
    if (newest == null || newestAtMs <= _appliedTopicSyncAtMs) return;

    final adopted = newest;
    final adoptedBaseMark = newest.baseMark;
    final adoptedAtMs = newestAtMs;
    _topicSyncApplyScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _topicSyncApplyScheduled = false;
      if (!mounted) return;
      final nextTopics = List<RoomTopicRef>.from(adopted.topics)
        ..sort((a, b) => a.createdAtMs.compareTo(b.createdAtMs));
      final stillExists =
          _currentTopicId == null ||
          nextTopics.any((topic) => topic.id == _currentTopicId);
      setState(() {
        _appliedTopicSyncAtMs = adoptedAtMs;
        _roomTopics = nextTopics;
        _baseMark = adoptedBaseMark;
        if (!stillExists) _currentTopicId = null;
      });
      // Принятое кладём в базу: иначе через двести сообщений список снова
      // выпадет из окна ленты и темы исчезнут.
      unawaited(
        widget.controller.rememberRoomTopics(
          groupId: widget.convoId,
          topics: nextTopics,
          syncedAtMs: adoptedAtMs,
          baseMark: adoptedBaseMark,
        ),
      );
    });
  }

  /// Читает сохранённый список тем при открытии комнаты.
  ///
  /// Лента остаётся каналом доставки: если в ней найдётся СВЕЖЕЕ сообщение со
  /// списком, [_maybeAdoptRoomTopics] его примет — сравнение идёт по той же
  /// отметке времени.
  Future<void> _loadStoredRoomTopics() async {
    final stored = await widget.controller.loadRoomTopics(widget.convoId);
    final atMs = await widget.controller.roomTopicsSyncedAtMs(widget.convoId);
    if (!mounted) return;
    if (stored.topics.isEmpty &&
        stored.baseMark.isEmpty &&
        _roomTopics.isEmpty) {
      return;
    }
    if (atMs <= _appliedTopicSyncAtMs) return;
    setState(() {
      _appliedTopicSyncAtMs = atMs;
      _roomTopics = stored.topics;
      _baseMark = stored.baseMark;
      if (_currentTopicId != null &&
          !stored.topics.any((topic) => topic.id == _currentTopicId)) {
        _currentTopicId = null;
      }
    });
  }

  // ── Topic switcher bar ───────────────────────────────────────────────────

  /// Whether to show the topic switcher. By default nothing sits under the top
  /// bar — the switcher only appears once the room actually has topics. The
  /// first topic is created via the «Тема» chip in the attachment sheet.
  bool get _shouldShowTopicBar => _isGroupChat && _roomTopics.isNotEmpty;

  Widget _buildTopicBar() {
    final canManage = _roomPolicyState?.canChangeGroupInfo ?? false;
    return SizedBox(
      height: 44,
      child: ListView(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.fromLTRB(10, 4, 10, 6),
        children: <Widget>[
          // ◆ «ОСНОВА», А НЕ «ОБЩИЙ» (указание владельца). «Общий» звучит
          // как «остальное, что никуда не подошло»; на деле это главный поток
          // комнаты, от которого ветки и отходят. И раз это такая же ветка —
          // у неё такой же значок, и он так же меняется.
          _buildTopicChip(
            id: null,
            label: chatText(
              context,
              ru: kRoomBaseTopicTitleRu,
              en: kRoomBaseTopicTitleEn,
            ),
            markIcon: roomTopicIconFor(_baseMark),
            markColor: roomTopicIconColorFor(_baseMark),
            selected: _currentTopicId == null,
            unread: _topicUnreadFor(null),
            onLongPress: canManage ? _manageBaseTopic : null,
          ),
          for (final topic in _roomTopics) ...<Widget>[
            const SizedBox(width: 6),
            _buildTopicChip(
              id: topic.id,
              // Имя БЕЗ решётки: её рисует сама фишка приглушённым цветом —
              // «#» говорит «это ветка комнаты», а не входит в название. Так
              // же и на компьютере.
              label: topic.emoji.trim().isEmpty
                  ? normalizeRoomTopicTitle(topic.title)
                  : '${topic.emoji.trim()} ${normalizeRoomTopicTitle(topic.title)}',
              // Формат темы: ЗНАЧОК, потом название. По умолчанию значок —
              // решётка; выбранный знак её ЗАМЕНЯЕТ, а не приписывается рядом.
              markIcon: roomTopicIcon(topic),
              markColor: roomTopicIconColor(topic),
              selected: _currentTopicId == topic.id,
              unread: _topicUnreadFor(topic.id),
              onLongPress: canManage ? () => _manageTopic(topic) : null,
            ),
          ],
        ],
      ),
    );
  }

  int _topicUnreadFor(String? id) {
    final key = id ?? '';
    if ((_currentTopicId ?? '') == key) return 0; // viewing it → read
    return _topicUnread[key] ?? 0;
  }

  /// A topic chip styled like the app's glass islands: matte backdrop blur,
  /// soft top→bottom fill (primary-tinted when selected) and a specular
  /// top-edge highlight. Optional unread count pill on the right.
  Widget _buildTopicChip({
    required String? id,
    required String label,
    required bool selected,
    int unread = 0,
    VoidCallback? onLongPress,
    /// Значок перед названием: решётка или заменивший её знак. `null` — у
    /// «Общего»: общий поток не ветка, значка у него нет.
    IconData? markIcon,

    /// Цвет значка. `null` — серый: знак помогает узнать ветку, а не спорит
    /// с именем.
    Color? markColor,
  }) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final cs = Theme.of(context).colorScheme;
    const radius = 16.0;
    final fillTop = selected
        ? cs.primary.withValues(alpha: isDark ? 0.36 : 0.26)
        : (isDark
              ? Colors.white.withValues(alpha: 0.07)
              : Colors.white.withValues(alpha: 0.30));
    final fillBottom = selected
        ? cs.primary.withValues(alpha: isDark ? 0.22 : 0.16)
        : (isDark
              ? Colors.white.withValues(alpha: 0.03)
              : Colors.white.withValues(alpha: 0.16));
    final br = BorderRadius.circular(radius);
    final textColor = selected
        ? (isDark ? Colors.white : cs.onSurface)
        : cs.onSurface.withValues(alpha: 0.8);
    return CustomPaint(
      foregroundPainter: GlassHighlightBorderPainter(
        radius: radius,
        strokeWidth: 1.1,
        color: isDark
            ? Colors.white.withValues(alpha: 0.22)
            : Colors.white.withValues(alpha: 0.42),
      ),
      child: ClipRRect(
        borderRadius: br,
        child: BackdropFilter(
          filter: ImageFilter.blur(sigmaX: 20, sigmaY: 20),
          child: DecoratedBox(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: <Color>[fillTop, fillBottom],
              ),
              borderRadius: br,
            ),
            child: Material(
              color: Colors.transparent,
              child: InkWell(
                onTap: () {
                  if (_currentTopicId != id) {
                    setState(() => _currentTopicId = id);
                  }
                },
                onLongPress: onLongPress,
                child: Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 8,
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: <Widget>[
                      if (markIcon != null) ...<Widget>[
                        Icon(
                          markIcon,
                          size: 15,
                          color:
                              markColor ??
                              textColor.withValues(alpha: 0.62),
                        ),
                        const SizedBox(width: 5),
                      ],
                      Text(
                        label,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: Theme.of(context).textTheme.labelLarge?.copyWith(
                          fontWeight: FontWeight.w700,
                          color: textColor,
                        ),
                      ),
                      if (unread > 0) ...<Widget>[
                        const SizedBox(width: 7),
                        _TopicUnreadPill(count: unread),
                      ],
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Future<String?> _promptTopicTitle({String? initial}) async {
    final controller = TextEditingController(text: initial ?? '');
    final result = await showDialog<String>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: Text(
            initial == null
                ? chatText(context, ru: 'Новая тема', en: 'New topic')
                : chatText(
                    context,
                    ru: 'Переименовать тему',
                    en: 'Rename topic',
                  ),
          ),
          content: TextField(
            controller: controller,
            autofocus: true,
            maxLength: 48,
            textCapitalization: TextCapitalization.sentences,
            decoration: InputDecoration(
              hintText: chatText(
                context,
                ru: 'Название темы',
                en: 'Topic name',
              ),
              counterText: '',
            ),
          ),
          actions: <Widget>[
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: Text(chatText(context, ru: 'Отмена', en: 'Cancel')),
            ),
            FilledButton(
              onPressed: () =>
                  Navigator.of(dialogContext).pop(controller.text.trim()),
              child: Text(chatText(context, ru: 'Готово', en: 'Done')),
            ),
          ],
        );
      },
    );
    controller.dispose();
    return (result == null || result.trim().isEmpty) ? null : result.trim();
  }

  /// ◆ ВЫБОР ЗНАКА ТЕМЫ. Возвращает идентификатор, `'-'` — снять знак,
  /// `null` — человек передумал.
  ///
  /// Сетка, а не список: знаки узнают глазами, и тридцать строк с подписями
  /// читались бы дольше, чем разглядывается вся сетка целиком.
  Future<String?> _pickTopicMark({required String current}) async {
    final cs = Theme.of(context).colorScheme;
    return showModalBottomSheet<String>(
      context: context,
      isScrollControlled: true,
      builder: (sheetContext) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Text(
                chatText(context, ru: 'Значок темы', en: 'Topic mark'),
                style: Theme.of(context).textTheme.titleMedium?.copyWith(
                  fontWeight: FontWeight.w700,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                chatText(
                  context,
                  ru: 'Значок заменяет решётку перед названием. Цветные '
                      'обещают, что внутри: зелёный — созвон, красный — '
                      'срочное.',
                  en: 'The mark replaces the hash before the name. Tinted '
                      'ones promise what is inside: green is a call, red is '
                      'urgent.',
                ),
                style: Theme.of(context).textTheme.bodySmall?.copyWith(
                  color: cs.onSurfaceVariant,
                ),
              ),
              const SizedBox(height: 12),
              Flexible(
                child: SingleChildScrollView(
                  child: Wrap(
                    spacing: 10,
                    runSpacing: 10,
                    children: <Widget>[
                      _topicMarkCell(
                        sheetContext,
                        icon: kRoomTopicHashIcon,
                        color: null,
                        selected: current.trim().isEmpty,
                        value: '-',
                        tooltip: chatText(
                          context,
                          ru: 'Без значка',
                          en: 'No mark',
                        ),
                      ),
                      for (final mark in kRoomTopicMarks)
                        _topicMarkCell(
                          sheetContext,
                          icon: mark.icon,
                          color: mark.color,
                          selected: current.trim() == mark.id,
                          value: mark.id,
                          tooltip: mark.labelRu,
                        ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _topicMarkCell(
    BuildContext sheetContext, {
    required IconData icon,
    required Color? color,
    required bool selected,
    required String value,
    required String tooltip,
  }) {
    final cs = Theme.of(context).colorScheme;
