  String _groupComposerTextHint(BuildContext context, AppLocalizations l10n) {
    if (_isFavoritesChat) {
      return chatText(
        context,
        ru: 'Новая заметка',
        en: 'New note',
        uk: 'Нова нотатка',
        es: 'Nueva nota',
        pt: 'Nova nota',
        fr: 'Nouvelle note',
        de: 'Neue Notiz',
      );
    }
    final policy = _roomPolicyState;
    if (!_isGroupChat || policy == null) {
      return l10n.messageHint;
    }
    if (!policy.isMember) {
      return l10n.roomPolicyNotMember;
    }
    if (!policy.canSendText && !policy.canSendMedia) {
      return policy.settings.allowTextMessages
          ? _groupPostingDisabledText(context)
          : _groupAdminsOnlyTextMessageDisabledText(context);
    }
    if (!policy.canSendText) {
      return policy.settings.allowTextMessages
          ? l10n.roomPolicyTextMessagesDisabled
          : _groupAdminsOnlyTextMessageDisabledText(context);
    }
    return l10n.messageHint;
  }

  String? _groupComposerPolicyBannerText(AppLocalizations l10n) {
    final policy = _roomPolicyState;
    if (!_isGroupChat || policy == null) {
      return null;
    }
    if (!policy.isMember) {
      return l10n.roomPolicyNotMember;
    }
    if (policy.isSlowModeActive) {
      return l10n.roomPolicySlowMode(policy.slowModeRemainingSeconds);
    }
    if (!policy.canSendText && !policy.canSendMedia) {
      return policy.settings.allowTextMessages
          ? _groupPostingDisabledText(context)
          : _groupAdminsOnlyTextMessageDisabledText(context);
    }
    if (!policy.canSendText) {
      return policy.settings.allowTextMessages
          ? l10n.roomPolicyTextMessagesDisabled
          : _groupAdminsOnlyTextMessageDisabledText(context);
    }
    if (!policy.canSendMedia) {
      return policy.settings.allowMedia
          ? l10n.roomPolicyMediaDisabled
          : _groupAdminsOnlyMediaDisabledText(context);
    }
    return null;
  }

  IconData _groupComposerPolicyBannerIcon() {
    final policy = _roomPolicyState;
    if (!_isGroupChat || policy == null) {
      return Icons.info_outline_rounded;
    }
    if (!policy.isMember) {
      return Icons.group_off_rounded;
    }
    if (policy.isSlowModeActive) {
      return Icons.timer_outlined;
    }
    if (!policy.canSendText && !policy.canSendMedia) {
      return Icons.lock_outline_rounded;
    }
    if (!policy.canSendText) {
      return Icons.edit_off_outlined;
    }
    if (!policy.canSendMedia) {
      return Icons.photo_outlined;
    }
    return Icons.info_outline_rounded;
  }

