  bool _canUseBroadcastRoomMentions() {
    final policy = _roomPolicyState;
    if (!_isGroupChat || policy == null) {
      return false;
    }
    return policy.canUseBroadcastMentions;
  }

  Future<void> _refreshRoomMentionCandidates({bool force = false}) async {
    if (!_isGroupChat) return;
    if (_roomMentionCandidatesLoading) return;
    if (!force && _roomMentionCandidates.isNotEmpty) return;
    final convoId = widget.convoId;
    _roomMentionCandidatesLoading = true;
    try {
      final members = await widget.controller.listRoomMembersDetailed(
        convoId,
        statuses: <RoomMembershipStatus>{RoomMembershipStatus.active},
      );
      if (!mounted || widget.convoId != convoId) {
        return;
      }
      setState(() {
        _roomMentionCandidates = _buildRoomMentionCandidates(members);
      });
    } finally {
      _roomMentionCandidatesLoading = false;
    }
  }

  List<_RoomMentionCandidate> _buildRoomMentionCandidates(
    List<RoomMember> members,
  ) {
    final out = <_RoomMentionCandidate>[];
    final usedHandles = <String>{};

    void addCandidate(_RoomMentionCandidate candidate) {
      usedHandles.add(candidate.handle.toLowerCase());
      out.add(candidate);
    }

    if (_canUseBroadcastRoomMentions()) {
      addCandidate(
        const _RoomMentionCandidate.broadcast(
          kind: _RoomMentionCandidateKind.all,
          handle: 'all',
          title: '@all',
        ),
      );
      addCandidate(
        const _RoomMentionCandidate.broadcast(
          kind: _RoomMentionCandidateKind.here,
          handle: 'here',
          title: '@here',
        ),
      );
      addCandidate(
        const _RoomMentionCandidate.broadcast(
          kind: _RoomMentionCandidateKind.admins,
          handle: 'admins',
          title: '@admins',
        ),
      );
    }

    for (final member in members) {
      final baseHandle = _sanitizeMentionHandle(member.displayName).isNotEmpty
          ? _sanitizeMentionHandle(member.displayName)
          : _sanitizeMentionHandle(member.profileId);
      var handle = baseHandle.isEmpty ? 'member' : baseHandle;
      var suffix = 2;
      while (usedHandles.contains(handle.toLowerCase())) {
        handle = '${baseHandle.isEmpty ? 'member' : baseHandle}_$suffix';
        suffix++;
      }
      addCandidate(
        _RoomMentionCandidate.member(
          profileId: member.profileId,
          displayName: member.displayName,
          avatarPath: member.avatarPath,
          handle: handle,
          role: member.role,
        ),
      );
    }
    return out;
  }

  ChatMentionCandidate _toChatMentionCandidate(
    _RoomMentionCandidate candidate,
  ) {
    switch (candidate.kind) {
      case _RoomMentionCandidateKind.member:
        return ChatMentionCandidate(
          token: candidate.token,
          type: MsgMentionV1.profileType,
          profileId: candidate.profileId,
        );
      case _RoomMentionCandidateKind.all:
      case _RoomMentionCandidateKind.here:
        // @here behaves like @all (everyone) — the app has no reliable
        // per-member presence to scope it to "online only".
        return ChatMentionCandidate(
          token: candidate.token,
          type: MsgMentionV1.allType,
        );
      case _RoomMentionCandidateKind.admins:
        return ChatMentionCandidate(
          token: candidate.token,
          type: MsgMentionV1.adminsType,
        );
    }
  }

  _RoomMentionCandidate? _roomMentionCandidateForProfile(String profileId) {
    final target = profileId.trim();
    if (target.isEmpty) {
      return null;
    }
    for (final candidate in _roomMentionCandidates) {
      if (candidate.profileId == target) {
        return candidate;
      }
    }
    return null;
  }

  String _sanitizeMentionHandle(String raw) {
    final compact = raw.trim().replaceAll(RegExp(r'\s+'), '_');
    final stripped = compact.replaceAll(RegExp(r'[@.,!?;:()\[\]{}<>/]+'), '');
    final collapsed = stripped.replaceAll(RegExp(r'_+'), '_');
    return collapsed.replaceAll(RegExp(r'^_+|_+$'), '');
  }

  _ComposerMentionDraft? _resolveComposerMentionDraft(TextEditingValue value) {
    if (!_isGroupChat) return null;
    final selection = value.selection;
    if (!selection.isValid || !selection.isCollapsed) {
      return null;
    }
    final text = value.text;
    final caret = selection.baseOffset;
    if (caret <= 0 || caret > text.length) {
      return null;
    }

    var scan = caret - 1;
    while (scan >= 0) {
      final char = String.fromCharCode(text.codeUnitAt(scan));
      if (char == '@') {
        final start = scan;
        if (!_isMentionBoundaryBefore(text, start)) {
          return null;
        }
        final query = text.substring(start + 1, caret);
        if (query.contains(RegExp(r'[\r\n]'))) {
          return null;
        }
        return _ComposerMentionDraft(start: start, end: caret, query: query);
      }
      if (_isMentionBoundaryCharacter(char)) {
        break;
      }
      scan--;
    }
    return null;
  }

  void _syncComposerMentionDraft() {
    final nextDraft = _resolveComposerMentionDraft(_text.value);
    final currentDraft = _composerMentionDraft;
    final changed =
        nextDraft?.start != currentDraft?.start ||
        nextDraft?.end != currentDraft?.end ||
        nextDraft?.query != currentDraft?.query;
    if (changed && mounted) {
      setState(() {
        _composerMentionDraft = nextDraft;
      });
    }
    if (nextDraft != null &&
        _roomMentionCandidates.isEmpty &&
        !_roomMentionCandidatesLoading) {
      unawaited(_refreshRoomMentionCandidates(force: true));
    }
  }

  List<_RoomMentionCandidate> _visibleRoomMentionCandidates() {
    final draft = _composerMentionDraft;
    if (draft == null) {
      return const <_RoomMentionCandidate>[];
    }
    final query = draft.query.trim().toLowerCase();
    final source = _roomMentionCandidates;
    if (source.isEmpty) {
      return const <_RoomMentionCandidate>[];
    }
    if (query.isEmpty) {
      return source.take(6).toList(growable: false);
    }
    return source
        .where((candidate) => candidate.matchesQuery(query))
        .take(6)
        .toList(growable: false);
  }

  bool _isMentionBoundaryCharacter(String char) {
    return char.trim().isEmpty || '.,!?;:()[]{}<>/\\|'.contains(char);
  }

  void _replaceComposerTextRange(int start, int end, String value) {
    final textValue = _text.value;
    final full = textValue.text;
    final safeStart = start.clamp(0, full.length).toInt();
    final safeEnd = end.clamp(safeStart, full.length).toInt();
    final left = full.substring(0, safeStart);
    final right = full.substring(safeEnd);
    final next = '$left$value$right';
    final caret = left.length + value.length;
    _text.value = TextEditingValue(
      text: next,
      selection: TextSelection.collapsed(offset: caret),
      composing: TextRange.empty,
    );
    _messageInputFocusNode.requestFocus();
  }

  void _applyRoomMentionCandidate(_RoomMentionCandidate candidate) {
    final draft =
        _composerMentionDraft ?? _resolveComposerMentionDraft(_text.value);
    if (draft == null) return;
    _replaceComposerTextRange(draft.start, draft.end, '${candidate.token} ');
    if (mounted) {
      setState(() {
        _composerMentionDraft = null;
      });
    }
  }

  bool _isMentionBoundaryBefore(String text, int index) {
    if (index <= 0) return true;
    return _isMentionBoundaryCharacter(
      String.fromCharCode(text.codeUnitAt(index - 1)),
    );
  }

  Future<List<MsgMentionV1>> _resolveOutgoingGroupMentions(String text) async {
    if (!_isGroupChat || !text.contains('@')) {
      return const <MsgMentionV1>[];
    }
    await _refreshRoomMentionCandidates(force: _roomMentionCandidates.isEmpty);
    final candidates = _roomMentionCandidates;
    if (candidates.isEmpty) {
      return const <MsgMentionV1>[];
    }

    return resolveChatMessageMentions(
      text: text,
      candidates: candidates
          .map(_toChatMentionCandidate)
          .toList(growable: false),
    );
  }

  Widget _buildRoomMentionSuggestionsCard(
    List<_RoomMentionCandidate> candidates,
  ) {
    final cs = Theme.of(context).colorScheme;
    return Container(
      width: double.infinity,
      margin: const EdgeInsets.fromLTRB(8, 2, 8, 6),
      constraints: const BoxConstraints(maxHeight: 220),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16),
        color: cs.surfaceContainerHighest.withValues(alpha: 0.78),
        border: Border.all(color: cs.outlineVariant.withValues(alpha: 0.28)),
      ),
      child: ListView.separated(
        shrinkWrap: true,
        padding: const EdgeInsets.symmetric(vertical: 6),
        itemCount: candidates.length,
        separatorBuilder: (_, __) => Divider(
          height: 1,
          indent: 56,
          endIndent: 12,
          color: cs.outlineVariant.withValues(alpha: 0.2),
        ),
        itemBuilder: (context, index) {
          final candidate = candidates[index];
          return ListTile(
            dense: true,
            visualDensity: const VisualDensity(vertical: -2),
            leading: _buildRoomMentionCandidateAvatar(candidate),
            title: Text(
              candidate.title,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: Theme.of(
                context,
              ).textTheme.bodyMedium?.copyWith(fontWeight: FontWeight.w700),
            ),
            subtitle: Text(
              candidate.subtitle(context),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: Theme.of(
                context,
              ).textTheme.bodySmall?.copyWith(color: cs.onSurfaceVariant),
            ),
            onTap: () => _applyRoomMentionCandidate(candidate),
          );
        },
      ),
    );
  }

  Widget _buildRoomMentionCandidateAvatar(_RoomMentionCandidate candidate) {
    final avatarPath = (candidate.avatarPath ?? '').trim();
    final seed = candidate.profileId ?? candidate.handle;
    if (candidate.kind != _RoomMentionCandidateKind.member) {
      // Non-member entries (e.g. "@everyone", "@here") get a flat tinted
      // disc with the at-sign icon — the same colours as an initials
      // fallback, the icon standing in for the letters.
      return CircleAvatar(
        radius: 18,
        backgroundColor: AvatarInitials.backgroundColor(context, seed: seed),
        foregroundColor: AvatarInitials.foregroundColor(context, seed: seed),
        child: const Icon(Icons.alternate_email_rounded, size: 18),
      );
    }
    if (avatarPath.isNotEmpty) {
      final file = File(avatarPath);
      if (file.existsSync()) {
        return CircleAvatar(radius: 18, backgroundImage: FileImage(file));
      }
    }
    return AvatarInitials.fallbackBubble(
      context: context,
      radius: 18,
      seed: seed,
      displayName: candidate.displayName,
      fallbackId: candidate.profileId,
      labelStyle: Theme.of(context).textTheme.labelSmall,
    );
  }

  Future<void> _scrollToLatest() async {
    if (!_scroll.hasClients) return;
    await _scroll.animateTo(
      0,
      duration: const Duration(milliseconds: 240),
      curve: Curves.easeOutCubic,
    );
    _scheduleMarkRead();
  }

  /// Receipt counter under an outgoing ROOM bubble.
  ///
  /// A count is shown ONLY while it says something the ticks do not — i.e.
  /// while delivery is PARTIAL. Once every other member has the message the
  /// counter is dropped and the tick state speaks for itself.
  ///
  /// Why (2026-07-31, user report): in a two-person room this slot rendered a
  /// permanent "Доставлено: 1" next to a tick that already meant exactly that —
  /// two widgets describing one state, and briefly contradicting each other
  /// while the tick lagged the receipt. The counter was built for the case it
  /// is actually useful in ("3 of 9 got it"), so keep it there and only there.
  ///
  /// [otherMemberCount] is the room size excluding me. 0 means "unknown"
  /// (roster not loaded yet) — then behave exactly as before and show it,
  /// rather than hide a receipt we cannot reason about.
  String? _roomReceiptStatusText(
    ({int deliveredCount, int readCount})? counts, {
    required int otherMemberCount,
  }) {
    if (counts == null) return null;
    final everyoneHasIt =
        otherMemberCount > 0 && counts.readCount >= otherMemberCount;
    final everyoneGotIt =
        otherMemberCount > 0 && counts.deliveredCount >= otherMemberCount;
    if (counts.readCount > 0) {
      if (everyoneHasIt) return null;
      // Read receipts render as a small eye + the count (no word). The count
      // travels through the SHARED statusText slot, tagged with an internal
      // marker the meta footer strips — see _kReadReceiptMarker. The slot is
      // used by 8 bubble types and also carries the "Delivered: N" case below,
      // which must stay plain text, so the footer has to be able to tell them
      // apart. Marking the string keeps that to two places instead of threading
      // a new parameter through every bubble.
      return '$_kReadReceiptMarker${counts.readCount}';
    }
    if (counts.deliveredCount > 0) {
      if (everyoneGotIt) return null;
      return chatText(
        context,
        ru: 'Доставлено: ${counts.deliveredCount}',
        en: 'Delivered to ${counts.deliveredCount}',
        uk: 'Доставлено: ${counts.deliveredCount}',
        es: 'Entregado a ${counts.deliveredCount}',
        pt: 'Entregue a ${counts.deliveredCount}',
        ptBr: 'Entregue a ${counts.deliveredCount}',
        fr: 'Remis a ${counts.deliveredCount}',
        de: 'Zugestellt an ${counts.deliveredCount}',
      );
    }
    return null;
  }

  String _authorFallbackFromDevice(String deviceId) {
    final trimmed = deviceId.trim();
    if (trimmed.length <= 10) return trimmed;
    return '${trimmed.substring(0, 6)}…${trimmed.substring(trimmed.length - 4)}';
  }

  String? _normalizedRoomMemberTag(String? tag) {
    final normalized = tag?.trim();
    if (normalized == null || normalized.isEmpty) {
      return null;
    }
    return normalized;
  }

  String? get _typingPeerProfileId {
    if (_isGroupChat || _isFavoritesChat) return null;
    final isRequest =
        widget.requestProfileId != null && widget.requestProfileId!.isNotEmpty;
    if (isRequest) return null;
    final peer = widget.peerProfileIdForSend;
    if (peer == null || peer.trim().isEmpty) return null;
    return peer.trim();
  }

  String? get _markReadPeerProfileId {
    return resolveChatMarkReadPeerProfileId(
      convoId: widget.convoId,
      peerProfileIdForSend: widget.peerProfileIdForSend,
    );
  }

  /// Emits a typing signal for whichever kind of chat this is.
  ///
  /// Rooms used to emit NOTHING — the peer getter below is null for a group —
  /// so the room header could never say who was typing, however well the
  /// receiving side handled it. Both kinds share the same debounce above; only
  /// the addressing differs (one peer vs every member).
  void _emitTypingState(bool typing) {
    final roomId = (_isGroupChat && !_isFavoritesChat)
        ? widget.convoId.trim()
        : '';
    if (roomId.isNotEmpty) {
      unawaited(
        widget.controller.sendRoomTypingState(groupId: roomId, typing: typing),
      );
      return;
    }
    final peer = _typingPeerProfileId;
    if (peer == null) return;
    unawaited(
      widget.controller.sendTypingState(
        peerProfileId: peer,
        convoId: peer,
        typing: typing,
      ),
    );
  }

  /// True when this chat can announce typing at all (a peer, or a room).
  bool get _canEmitTyping =>
      _typingPeerProfileId != null ||
      (_isGroupChat && !_isFavoritesChat && widget.convoId.trim().isNotEmpty);

  void _onComposerTextChanged() {
    _syncComposerMentionDraft();
    _linkPreviewDraft.update(_text.text);
    if (!_canEmitTyping) return;

    final hasText = _text.text.trim().isNotEmpty;
    if (!hasText) {
      _typingStopDebounce?.cancel();
      if (_typingActiveSent) {
        _typingStopDebounce = Timer(const Duration(milliseconds: 120), () {
          if (!mounted) return;
          _typingActiveSent = false;
          _emitTypingState(false);
        });
      }
      return;
    }

    _typingStopDebounce?.cancel();
    final now = DateTime.now().millisecondsSinceEpoch;
    final shouldSendStart =
        !_typingActiveSent || (now - _lastTypingSentAtMs) >= 2600;
    if (!shouldSendStart) return;

    _typingActiveSent = true;
    _lastTypingSentAtMs = now;
    _emitTypingState(true);
  }

  /// Premium on-device dictation entry, shown as the composer field's suffix.
  /// Distinct from the round voice-message record button — this turns speech
  /// into editable text in both 1:1 chats and group rooms.
  Widget _buildDictationSuffix(Color iconColor) {
    return IconButton(
      padding: EdgeInsets.zero,
      visualDensity: VisualDensity.compact,
      iconSize: 22,
      constraints: const BoxConstraints(minWidth: 34, minHeight: 34),
      tooltip: chatText(
        context,
        ru: 'Голосовой ввод',
        en: 'Voice input',
        uk: 'Голосове введення',
        es: 'Entrada de voz',
        pt: 'Entrada de voz',
        ptBr: 'Entrada de voz',
        fr: 'Saisie vocale',
        de: 'Spracheingabe',
      ),
      icon: Icon(Icons.mic_none_rounded, color: iconColor),
      onPressed: _onDictationPressed,
    );
  }

  Future<void> _onDictationPressed() async {
    bool unlocked() => FeatureGate.isUnlocked(
      widget.controller.entitlementStateNow,
      GatedFeature.voiceToText,
    );
    if (!unlocked()) {
      await showPaywall(context, PaywallTrigger.general);
      if (!mounted || !unlocked()) return;
    }
    final text = await showVoiceDictationSheet(context);
    if (!mounted || text == null || text.trim().isEmpty) return;
    _insertDictatedText(text.trim());
  }

  void _insertDictatedText(String dictated) {
    final existing = _text.text;
    final needsSpace =
        existing.isNotEmpty &&
        !existing.endsWith(' ') &&
        !existing.endsWith('\n');
    final merged = needsSpace ? '$existing $dictated' : '$existing$dictated';
    _text.value = TextEditingValue(
      text: merged,
      selection: TextSelection.collapsed(offset: merged.length),
    );
    setState(() {});
    _messageInputFocusNode.requestFocus();
  }

  void _stopTypingNow() {
    _typingStopDebounce?.cancel();
    // Rooms stop typing too — leaving the indicator up after a send would keep
    // "<name> печатает" on everyone's header until it timed out.
    if (!_typingActiveSent || !_canEmitTyping) return;
    _typingActiveSent = false;
    _emitTypingState(false);
  }

  Future<Conversation?> _loadHeaderConversation(String convoId) async {
    final conversations = await widget.controller.listConversations();
    for (final conversation in conversations) {
      if (conversation.convoId == convoId) {
        return conversation;
      }
    }
    return null;
  }

  // Memoized header load. See [_headerConversationFuture].
  Future<Conversation?>? _headerFuture;
  int _headerFutureVersion = -1;
  String? _headerFutureConvoId;

  /// The header's conversation, loaded ONCE per (convo, changeVersion).
  ///
  /// 🔴 WHY (2026-08-01, field: "the avatar flashes in a moment after opening
  /// the chat — it feels like a separate web page reloading, not one app").
  ///
  /// This future used to be built inline in `build()`, inside a StreamBuilder on
  /// `controller.changed`. Every unrelated controller tick therefore handed
  /// `FutureBuilder` a BRAND-NEW future, and a new future resets the builder to
  /// `waiting` with `data == null` — so the header blanked and re-populated over
  /// and over during normal use, not just on open.
  ///
  /// Memoizing by `changeVersion` is the same treatment the timeline already
  /// gets from `_eventsFutureForCurrentVersion` (2026-07-05), and for the same
  /// reason: a layout-driven rebuild must not re-query the database.
  ///
  /// The remaining first-open gap is closed separately, by seeding the builder
  /// with `controller.cachedConversation` as `initialData` — the chats list has
  /// already put this very row in memory, so frame ONE can paint the real
  /// avatar instead of a hole.
  Future<Conversation?> _headerConversationFuture() {
    final version = widget.controller.changeVersion;
    final existing = _headerFuture;
    if (existing != null &&
        version == _headerFutureVersion &&
        _headerFutureConvoId == widget.convoId) {
      return existing;
    }
    final fut = _loadHeaderConversation(widget.convoId);
    _headerFuture = fut;
    _headerFutureVersion = version;
    _headerFutureConvoId = widget.convoId;
    return fut;
  }

  void _openPeerDetails({
    required String profileId,
    String? avatarPath,
    String? initialTitle,
    String? convoId,
    bool openChatByPush = false,
  }) {
    Navigator.of(context).push(
      SecretlyPageRoute(
        builder: (_) => ContactDetailsScreen(
          controller: widget.controller,
          peerProfileId: profileId,
          // For a group-member tap [convoId] is the member's OWN direct convo
          // (their profile id), never the room — otherwise the details screen
          // would resolve the room's title/avatar and "Chat" would reopen the
          // room. Fall back to the current chat's convo only for a 1:1 peer.
          convoId: convoId ?? widget.convoId,
          initialTitle: initialTitle ?? (openChatByPush ? null : widget.title),
          initialAvatarPath: avatarPath,
          openChatByPush: openChatByPush,
        ),
      ),
    );
  }

  /// Tap-to-profile for a group message's sender name/avatar. Resolves the
  /// device id to a profile id (same pattern used to build the author-meta
  /// cache above) and opens the same peer-details screen used elsewhere.
  Future<void> _handleGroupAuthorTap(
    String senderDeviceId, {
    String? avatarPath,
    String? initialTitle,
  }) async {
    final deviceId = senderDeviceId.trim();
    if (deviceId.isEmpty || widget.controller.isOwnDeviceId(deviceId)) return;
    final contact = await widget.controller.contactByDeviceId(deviceId);
    var profileId =
        await widget.controller.cachedProfileIdByDeviceId(deviceId) ??
        contact?.profileId ??
        '';
    if (profileId.isEmpty) {
      // Unknown member (never messaged us 1:1, so the device→profile cache is
      // empty) — resolve it from the keys server on demand so the tap still
      // opens their profile instead of silently doing nothing.
      profileId =
          (await widget.controller.resolveProfileIdForDevice(deviceId)) ?? '';
    }
    if (profileId.isEmpty || !mounted) return;
    _openPeerDetails(
      profileId: profileId,
      avatarPath: avatarPath ?? contact?.avatarPath,
      initialTitle: initialTitle,
      // Always resolve the member's own profile (their avatar/name) and let
      // "Chat" open a real 1:1 with them — never the room we tapped from.
      convoId: profileId,
      openChatByPush: true,
    );
  }

  /// Builds the tap handler for a forwarded-message header. Returns a non-null
  /// callback whenever the entry is a forward so the tap is always absorbed
  /// (otherwise it would fall through to the bubble's reactions/context menu).
  ///
  /// Target resolution:
  ///  • own forward («Переслано от вы» / any forward I sent) → jump to the
  ///    source chat that holds the original (`forwardedFromSourceConvoId`);
  ///  • incoming forward from someone else → open the 1:1 chat with the
  ///    original author (`forwardedFromProfileId`).
  VoidCallback? _forwardedHeaderTapFor(_TimelineEntry entry) {
    if (entry.forwardedFrom == null) return null;
    final ownSource = entry.isMe
        ? (entry.forwardedFromSourceConvoId?.trim() ?? '')
        : '';
    final authorPid = entry.forwardedFromProfileId?.trim() ?? '';
    final target = ownSource.isNotEmpty ? ownSource : authorPid;
    return () => _openForwardedSource(target, entry.forwardedFrom);
  }

  /// Tapping a «Переслано от …» header opens the source conversation so the
  /// reader can jump to the original message (Telegram parity). [target] is
  /// either a conversation id (`group:…`) or a peer profile id. No-ops when the
  /// target is empty or already the current chat (still absorbs the tap).
  void _openForwardedSource(String target, String? authorName) {
    final id = target.trim();
    if (id.isEmpty) return;
    if (id == widget.convoId || id == widget.peerProfileIdForSend) {
      // Already in that chat — nothing to navigate to.
      return;
    }
    final isGroup = id.startsWith('group:');
    final fallbackTitle = (authorName != null && authorName.trim().isNotEmpty)
        ? authorName.trim()
        : id;
    unawaited(() async {
      String title = fallbackTitle;
      try {
        final resolved = await widget.controller.resolveConvoTitle(id);
        if (resolved.trim().isNotEmpty) title = resolved.trim();
      } catch (_) {}
      if (!mounted) return;
      Navigator.of(context).push(
        SecretlyPageRoute(
          builder: (_) => isGroup
              ? ChatScreen(
                  controller: widget.controller,
                  convoId: id,
                  title: title,
                )
              : ChatScreen(
                  controller: widget.controller,
                  convoId: id,
                  title: title,
                  peerProfileIdForSend: id,
                ),
        ),
      );
    }());
  }

  void _openRoomDetails() {
    Navigator.of(context).push(
      SecretlyPageRoute(
        builder: (_) => RoomDetailsScreen(
          controller: widget.controller,
          groupId: widget.convoId,
          initialTitle: widget.title,
        ),
      ),
    );
  }

  /// "Share room" from the in-chat menu: reuse a still-valid invite link if one
  /// exists (never mints a duplicate per tap), else create one, then hand the
  /// https link to the NATIVE share sheet. Permission errors (only owners /
  /// admins manage invite links) surface as the room-policy snackbar.
  Future<void> _shareRoomExternally() async {
    try {
      final links = await widget.controller.listRoomInviteLinks(widget.convoId);
      final now = DateTime.now().millisecondsSinceEpoch;
      RoomInviteLink? link;
      for (final candidate in links) {
        final expired =
            candidate.expiresAtMs != null && candidate.expiresAtMs! <= now;
        final exhausted = candidate.maxUses != null &&
            candidate.useCount >= candidate.maxUses!;
        if (!candidate.revoked && !expired && !exhausted) {
          link = candidate;
          break;
        }
      }
      link ??= await widget.controller.createRoomInviteLink(widget.convoId);
      await shareTextExternally(text: link.shareUrl);
    } catch (e) {
      if (!mounted) return;
      final l10n = context.l10n;
      final roomPolicyText = tryRoomPolicyErrorText(l10n, e);
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(roomPolicyText ?? l10n.sendFailed(e.toString())),
        ),
      );
    }
  }

  void _openRoomCallScreen() {
    Navigator.of(context).push(
      SecretlyPageRoute(
        builder: (_) => RoomCallScreen(
          controller: widget.controller,
          groupId: widget.convoId,
          initialTitle: widget.title,
        ),
      ),
    );
  }

  SharedAudioPlaybackState get _sharedAudioPlayback =>
      widget.controller.sharedAudioPlayback.value;

  _NowPlayingItem? get _activeNowPlayingItem {
    final sharedTrack = _sharedAudioPlayback.currentTrack;
    if (sharedTrack != null) {
      return _NowPlayingItem(
        kind: _NowPlayingKind.audio,
        title: sharedTrack.title,
        subtitle: sharedTrack.artist,
        file: File(sharedTrack.sourcePath ?? ''),
        sourceBlobId: sharedTrack.sourceBlobId ?? sharedTrack.trackId,
      );
    }
    final item = _nowPlaying;
    if (item != null && item.kind == _NowPlayingKind.video) {
      return item;
    }
    return null;
  }

  void _handleSharedAudioPlaybackChanged() {
    if (!mounted) return;
    final playback = _sharedAudioPlayback;
    final currentTrack = playback.currentTrack;
    final blobId = currentTrack?.sourceBlobId;
    if (blobId != null && playback.duration > Duration.zero) {
      _audioAttachmentDurations[blobId] = playback.duration;
    }

    // Развилка: вёрстка или только цифры.
    //
    // Смена трека, пауза и появление/исчезновение трека меняют РАЗМЕТКУ —
    // высоту шапки, наличие `AppBar.bottom`, слияние панели с закреплённым
    // сообщением. Это полноценный setState, но случается он раз в несколько
    // минут. Позиция тикает пять раз в секунду и не двигает ни одного пикселя
    // разметки — её забирают подписчики `_audioTick`.
    final trackId = currentTrack?.trackId;
    final playing = playback.playing;
    final hasTrack = currentTrack != null;
    final structuralChanged = sharedAudioChangeNeedsLayout(
      previousTrackId: _audioStructuralTrackId,
      previousPlaying: _audioStructuralPlaying,
      previousHasTrack: _audioStructuralHasTrack,
      trackId: trackId,
      playing: playing,
      hasTrack: hasTrack,
    );

    if (structuralChanged) {
      _audioStructuralTrackId = trackId;
      _audioStructuralPlaying = playing;
      _audioStructuralHasTrack = hasTrack;
      // 🔴 Тик здесь НЕ поднимается намеренно. Подписчики сидят внутри дерева
      // и перестроятся вместе с ним от setState — а отдельный тик до setState
      // дал бы кадр, в котором панель «сейчас играет» ещё смонтирована, но
      // `_activeNowPlayingItem` уже null: там стоит `!`, и это падение при
      // остановке трека.
      setState(() {});
      return;
    }

    _audioTick.value++;
  }

