  bool _isAttachmentAudioActive(AttachmentEventV1 attachment) {
    final currentTrack = _sharedAudioPlayback.currentTrack;
    return currentTrack?.kind == SharedAudioTrackKind.attachment &&
        currentTrack?.sourceBlobId == attachment.blobId;
  }

  /// Подписывает аудио-пузырь на `_audioTick`, оставляя всё остальное как было.
  ///
  /// 🔴 Подписываются ВСЕ аудио-вложения, а не только играющее сейчас. Иначе
  /// при переходе к следующему треку предыдущий пузырь перестаёт быть активным
  /// и — лишившись общего setState — навсегда остаётся с наполовину залитой
  /// полосой и иконкой «пауза». Неактивный пузырь перестраивается дёшево: его
  /// аудио-поля — `Duration.zero` и `false`.
  ///
  /// Обёртка ставится ВНУТРЬ строки, вокруг самого пузыря: `GlobalKey` строки
  /// живёт выше, на `_HighlightWrapper`, и по нему работают плавающая дата дня
  /// (`_updateFloatingDay`), скролл к процитированному сообщению и
  /// `findChildIndexCallback` списка.
  Widget _audioAwareBubble({
    required bool isAudioAttachment,
    required Widget Function() build,
  }) {
    if (!isAudioAttachment) return build();
    return ListenableBuilder(
      listenable: _audioTick,
      builder: (context, _) => build(),
    );
  }

  Duration _audioBubbleDurationFor(AttachmentEventV1 attachment) {
    final blobId = attachment.blobId;
    final cached = _audioAttachmentDurations[blobId];
    if (cached != null && cached > Duration.zero) {
      return cached;
    }
    unawaited(_probeCachedAudioAttachmentDuration(attachment));
    return Duration.zero;
  }

  Future<void> _probeCachedAudioAttachmentDuration(
    AttachmentEventV1 attachment,
  ) async {
    if (!mounted) return;
    final blobId = attachment.blobId;
    if (_audioAttachmentDurations.containsKey(blobId) ||
        _audioAttachmentDurationPending.contains(blobId)) {
      return;
    }
    _audioAttachmentDurationPending.add(blobId);
    try {
      final cached = await widget.controller.cachedAttachmentFile(attachment);
      if (cached == null || !await cached.exists()) return;
      await _probeAudioAttachmentDurationFromFile(attachment, cached);
      await _probeMusicAttachmentMetadataFromFile(attachment, cached);
    } finally {
      _audioAttachmentDurationPending.remove(blobId);
    }
  }

  Future<void> _probeAudioAttachmentDurationFromFile(
    AttachmentEventV1 attachment,
    File file,
  ) async {
    final mime = (attachment.mime ?? '').toLowerCase();
    if (!mime.startsWith('audio/')) return;
    final blobId = attachment.blobId;
    if (_audioAttachmentDurations[blobId] != null || !await file.exists()) {
      return;
    }

    final probe = AudioPlayer();
    try {
      final duration = await probe.setFilePath(file.path);
      if (!mounted || duration == null || duration <= Duration.zero) return;
      setState(() {
        _audioAttachmentDurations[blobId] = duration;
      });
    } catch (_) {
      // Ignore metadata probe failures. The bubble still shows exact size.
    } finally {
      await probe.dispose();
    }
  }

  Future<void> _probeMusicAttachmentMetadataFromFile(
    AttachmentEventV1 attachment,
    File file,
  ) async {
    final mime = (attachment.mime ?? '').toLowerCase();
    // Skip voice notes robustly — an AAC/m4a recording is `audio/mp4` like real
    // music, so only the waveform tells them apart (else we'd read music tags
    // off a voice note).
    if (!mime.startsWith('audio/') || _isVoiceMessageAttachment(attachment)) {
      return;
    }
    final blobId = attachment.blobId;
    if (_musicMetadataByBlobId.containsKey(blobId) ||
        _musicMetadataPendingBlobIds.contains(blobId) ||
        _musicMetadataMissBlobIds.contains(blobId) ||
        !await file.exists()) {
      return;
    }

    _musicMetadataPendingBlobIds.add(blobId);
    try {
      final metadata = await _readResolvedMusicMetadata(file.path);
      if (metadata == null) {
        // Тегов нет — второй раз не читаем: запасной путь через систему
        // (Android, Mac) заметно дороже библиотеки.
        _musicMetadataMissBlobIds.add(blobId);
        return;
      }
      if (!mounted) return;
      setState(() {
        _musicMetadataByBlobId[blobId] = metadata;
      });
    } catch (_) {
      // Best-effort metadata read.
    } finally {
      _musicMetadataPendingBlobIds.remove(blobId);
    }
  }

  /// Теги песни из файла — только настоящие, без подстановки имени файла.
  Future<_ResolvedMusicMetadata?> _readResolvedMusicMetadata(
    String filePath,
  ) async {
    // Общий чтец: на iPhone теги читает система — библиотека там отключена.
    // Он не бросает: не прочлось — пусто.
    final tag = await MusicTagReader.read(filePath);
    if (tag == null) return null;
    return _ResolvedMusicMetadata(title: tag.title, artist: tag.artist);
  }

  String? _normalizeMusicMetadataLabel(String? value) {
    if (value == null) return null;
    final compact = value.replaceAll(RegExp(r'\s+'), ' ').trim();
    if (compact.isEmpty) return null;
    return compact;
  }

  String _unknownMusicArtistLabel(BuildContext context) {
    return chatText(
      context,
      ru: 'Неизвестен',
      en: 'Unknown artist',
      uk: 'Невідомий',
      es: 'Desconocido',
      pt: 'Desconhecido',
      fr: 'Inconnu',
      de: 'Unbekannt',
    );
  }

  String _voiceMessageLabel(BuildContext context) {
    return chatText(
      context,
      ru: 'Голосовое сообщение',
      en: 'Voice message',
      uk: 'Голосове повідомлення',
      es: 'Mensaje de voz',
      pt: 'Mensagem de voz',
      fr: 'Message vocal',
