    );
  }

  _ResolvedMusicMetadata _resolvedMusicMetadataForAttachment(
    BuildContext context,
    AttachmentEventV1 attachment, {
    String? payloadEventId,
  }) {
    final cached = _musicMetadataByBlobId[attachment.blobId];
    if (cached == null &&
        !_musicMetadataPendingBlobIds.contains(attachment.blobId)) {
      unawaited(_probeCachedAudioAttachmentDuration(attachment));
    }
    // Source order, strongest first:
    //   1. what the SENDER read and put in the payload — authoritative, present
    //      the instant the event exists, and the ONLY source a recipient has;
    //   2. tags probed from the local file — covers messages sent before the
    //      payload carried tags, and is all an old event will ever have;
    //   3. the file name — still tells you what the track is;
    //   4. the generic label.
    // Payload-first is what stops a sent track flipping from its real title to
    // "Music / Unknown artist" the moment the upload settles: the settled bubble
    // no longer depends on re-reading tags off the blob cache (on iOS that
    // became possible only with the system reader, `MusicTagReader`).
    //
    // 🔴 Название, совпадающее с именем файла, — не тег (17.09.2026): так
    // телефон подписывал песню, когда не успевал или не мог прочесть теги, и
    // такое «название» заслоняло настоящие теги из самого файла.
    final payloadTitle = taggedMusicTitle(attachment);
    final payloadArtist = attachment.musicArtist?.trim();
    final filename = attachment.filename?.trim();
    return _ResolvedMusicMetadata(
      title: (payloadTitle != null && payloadTitle.isNotEmpty)
          ? payloadTitle
          : (cached?.title ??
                ((filename != null && filename.isNotEmpty)
                    ? filename
                    : context.l10n.music)),
      artist: (payloadArtist != null && payloadArtist.isNotEmpty)
          ? payloadArtist
          : (cached?.artist ?? _unknownMusicArtistLabel(context)),
    );
  }

  Future<File> _ensureAttachmentFile(AttachmentEventV1 attachment) async {
    final cached = await widget.controller.cachedAttachmentFile(attachment);
    if (cached != null && await cached.exists()) {
      unawaited(_probeAudioAttachmentDurationFromFile(attachment, cached));
      unawaited(_probeMusicAttachmentMetadataFromFile(attachment, cached));
      return cached;
    }

    final existingLoad = _attachmentFileLoadFutures[attachment.blobId];
    if (existingLoad != null) {
      return existingLoad;
    }

    final loadFuture = () async {
      final file = await widget.controller.ensureCachedAttachmentFile(
        attachment,
      );
      unawaited(_probeAudioAttachmentDurationFromFile(attachment, file));
      unawaited(_probeMusicAttachmentMetadataFromFile(attachment, file));
      return file;
    }();

    _attachmentFileLoadFutures[attachment.blobId] = loadFuture;
    try {
      return await loadFuture;
    } finally {
      final currentLoad = _attachmentFileLoadFutures[attachment.blobId];
      if (identical(currentLoad, loadFuture)) {
        _attachmentFileLoadFutures.remove(attachment.blobId);
      }
    }
  }

  void _scheduleAudioAttachmentPrefetch(AttachmentEventV1 attachment) {
    final mime = (attachment.mime ?? '').toLowerCase();
    if (!mime.startsWith('audio/')) return;
    if (!_audioAttachmentPrefetchStartedBlobIds.add(attachment.blobId)) {
      return;
    }
    unawaited(() async {
      try {
        await _ensureAttachmentFile(attachment);
      } catch (_) {}
    }());
  }

  Future<void> _toggleAudioAttachment(
    AttachmentEventV1 attachment, {
    String? payloadEventId,
  }) async {
    if (_isAttachmentAudioActive(attachment)) {
      await widget.controller.toggleSharedAudioPlayback();
      return;
    }
    if (_audioLoadingBlobId == attachment.blobId) return;
    setState(() {
      _audioLoadingBlobId = attachment.blobId;
    });
    try {
      await _openAttachment(attachment, payloadEventId: payloadEventId);
    } finally {
      if (mounted) {
        setState(() {
          if (_audioLoadingBlobId == attachment.blobId) {
            _audioLoadingBlobId = null;
          }
        });
      }
    }
  }

  void _toggleSelection(String eventId) {
    setState(() {
      if (_selectedEventIds.contains(eventId)) {
        _selectedEventIds.remove(eventId);
      } else {
        _selectedEventIds.add(eventId);
      }
    });
  }

  void _startSelection(String eventId) {
    setState(() {
      _selectedEventIds.add(eventId);
    });
  }

  void _clearSelection() {
    if (_selectedEventIds.isEmpty) return;
    setState(_selectedEventIds.clear);
  }

  Iterable<ChatEvent> _eventsForTimelineEntry(_TimelineEntry entry) sync* {
    final imageItems = entry.imageItems;
    if (imageItems != null && imageItems.isNotEmpty) {
      final seenEventIds = <String>{};
      for (final imageItem in imageItems) {
        if (seenEventIds.add(imageItem.event.eventId)) {
          yield imageItem.event;
        }
      }
      return;
    }
    yield entry.event;
  }

  Future<List<ChatEvent>> _loadSelectedEvents() async {
    final selectedById = <String, ChatEvent>{};
    for (final entry in _selectedTimelineEntries()) {
      for (final event in _eventsForTimelineEntry(entry)) {
        selectedById[event.eventId] = event;
      }
    }
    if (selectedById.isEmpty && _selectedEventIds.isNotEmpty) {
      final events = await widget.controller.loadEvents(widget.convoId);
      for (final event in events) {
        if (_selectedEventIds.contains(event.eventId)) {
          selectedById[event.eventId] = event;
        }
      }
    }
    final selected = selectedById.values.toList(growable: false)
      ..sort((a, b) => a.createdAtMs.compareTo(b.createdAtMs));
    return selected;
  }

  Iterable<_TimelineEntry> _selectedTimelineEntries() sync* {
    for (final entry in _lastTimeline) {
      if (_selectedEventIds.contains(entry.event.eventId)) {
        yield entry;
      }
    }
  }

  bool _isDownloadableMediaAttachment(AttachmentEventV1 attachment) {
    final mime = (attachment.mime ?? '').toLowerCase();
    return mime.startsWith('image/') ||
        mime.startsWith('video/') ||
        mime.startsWith('audio/');
  }

  List<_AttachmentDownloadTarget> _selectedDownloadableAttachments() {
    final targets = <_AttachmentDownloadTarget>[];
    final seenBlobIds = <String>{};
    for (final entry in _selectedTimelineEntries()) {
      final attachments =
          entry.imageAttachments ??
          (entry.attachment != null
              ? <AttachmentEventV1>[entry.attachment!]
              : const <AttachmentEventV1>[]);
      for (final attachment in attachments) {
        if (!_isDownloadableMediaAttachment(attachment)) continue;
        if (!seenBlobIds.add(attachment.blobId)) continue;
        targets.add(
          _AttachmentDownloadTarget(
            attachment: attachment,
            createdAtMs: entry.event.createdAtMs,
          ),
        );
      }
    }
    targets.sort((a, b) => a.createdAtMs.compareTo(b.createdAtMs));
    return targets;
  }

  int get _selectedDownloadableAttachmentCount =>
      _selectedDownloadableAttachments().length;

  Future<Directory> _resolveMediaDownloadDirectory() =>
      resolveMediaDownloadDirectory();

  String _attachmentDownloadSuggestedName(
    AttachmentEventV1 attachment,
    int createdAtMs,
    File source,
  ) => attachmentDownloadSuggestedName(attachment, createdAtMs, source);

  Future<File> _uniqueDownloadTarget(Directory dir, String suggestedName) =>
      uniqueDownloadTarget(dir, suggestedName);

  Future<void> _saveSelectedMediaAttachments() async {
    final items = _selectedDownloadableAttachments();
    if (items.isEmpty || !mounted) return;

    final messenger = ScaffoldMessenger.of(context);

    try {
      if (items.length == 1) {
        final item = items.single;
        final source = await _ensureAttachmentFile(item.attachment);
        // GALLERY SAVE FIX (2026-07-17): a downloaded photo/video must land in
        // the SYSTEM gallery (like Telegram), not in an app-private folder the
        // Gallery app never scans. Non-media keeps the save-as flow below.
        final inGallery = await saveMediaToSystemGallery(
          attachment: item.attachment,
          createdAtMs: item.createdAtMs,
          source: source,
        );
        if (inGallery) {
          if (!mounted) return;
          _clearSelection();
          messenger.showSnackBar(
            SecretlySnackBar(content: Text(_savedToGalleryLabel(context))),
          );
          return;
        }
        final suggestedName = _attachmentDownloadSuggestedName(
          item.attachment,
          item.createdAtMs,
          source,
        );

        String? savePath;
        var pickerSupported = true;
        try {
          savePath = await FilePicker.platform.saveFile(
            fileName: suggestedName,
          );
        } catch (_) {
          pickerSupported = false;
        }

        if (pickerSupported && (savePath == null || savePath.isEmpty)) {
          return;
        }

        if (!pickerSupported) {
          final savedPathLabel = await saveAttachmentToUserVisibleLocation(
            fileName: suggestedName,
            source: source,
            mime: item.attachment.mime,
          );
          if (!mounted) return;
          _clearSelection();
          messenger.showSnackBar(
            SecretlySnackBar(content: Text(context.l10n.savedTo(savedPathLabel))),
          );
          return;
        }

        var resolvedPath = savePath!;
        final ext = p.extension(suggestedName);
        if (ext.isNotEmpty && p.extension(resolvedPath).isEmpty) {
          resolvedPath = '$resolvedPath$ext';
        }
        final target = File(resolvedPath);
        await target.parent.create(recursive: true);
        await source.copy(target.path);
        if (!mounted) return;
        _clearSelection();
        messenger.showSnackBar(
          SecretlySnackBar(content: Text(context.l10n.savedTo(target.path))),
        );
        return;
      }

      final dir = await _resolveMediaDownloadDirectory();
      var savedCount = 0;
      var galleryCount = 0;
      Object? firstError;
      for (final item in items) {
        try {
          final source = await _ensureAttachmentFile(item.attachment);
          // Media → system gallery; anything else → the Secretly folder.
          final inGallery = await saveMediaToSystemGallery(
            attachment: item.attachment,
            createdAtMs: item.createdAtMs,
            source: source,
          );
          if (inGallery) {
            galleryCount++;
            savedCount++;
            continue;
          }
          final suggestedName = _attachmentDownloadSuggestedName(
            item.attachment,
            item.createdAtMs,
            source,
          );
          await saveAttachmentToUserVisibleLocation(
            fileName: suggestedName,
            source: source,
            mime: item.attachment.mime,
          );
          savedCount++;
        } catch (error) {
          firstError ??= error;
        }
      }

      if (!mounted) return;
      if (savedCount > 0) {
        _clearSelection();
        final label = galleryCount == savedCount
            ? chatText(
                context,
                ru: 'Сохранено в галерею: $galleryCount',
                en: 'Saved to gallery: $galleryCount',
                uk: 'Збережено в галерею: $galleryCount',
                es: 'Guardado en la galeria: $galleryCount',
                pt: 'Guardado na galeria: $galleryCount',
                ptBr: 'Salvo na galeria: $galleryCount',
                fr: 'Enregistres dans la galerie : $galleryCount',
                de: 'In der Galerie gespeichert: $galleryCount',
              )
            : galleryCount > 0
            ? chatText(
                context,
                ru: 'В галерею: $galleryCount, в файлы: ${savedCount - galleryCount}',
                en: 'To gallery: $galleryCount, to files: ${savedCount - galleryCount}',
                uk: 'У галерею: $galleryCount, у файли: ${savedCount - galleryCount}',
                es: 'A la galeria: $galleryCount, a archivos: ${savedCount - galleryCount}',
                pt: 'Para a galeria: $galleryCount, para ficheiros: ${savedCount - galleryCount}',
                ptBr: 'Para a galeria: $galleryCount, para arquivos: ${savedCount - galleryCount}',
                fr: 'Galerie : $galleryCount, fichiers : ${savedCount - galleryCount}',
                de: 'In Galerie: $galleryCount, in Dateien: ${savedCount - galleryCount}',
              )
            : chatText(
                context,
                ru: 'Сохранено $savedCount файл(ов) в ${dir.path}',
                en: 'Saved $savedCount file(s) to ${dir.path}',
                uk: 'Збережено файлів: $savedCount у ${dir.path}',
                es: 'Guardados $savedCount archivo(s) en ${dir.path}',
                pt: '$savedCount ficheiro(s) guardado(s) em ${dir.path}',
                ptBr: '$savedCount arquivo(s) salvo(s) em ${dir.path}',
                fr: '$savedCount fichier(s) enregistres dans ${dir.path}',
                de: '$savedCount Datei(en) gespeichert in ${dir.path}',
              );
        messenger.showSnackBar(SecretlySnackBar(content: Text(label)));
        return;
      }

      if (firstError != null) {
        throw firstError;
      }
    } catch (error) {
      if (!mounted) return;
      messenger.showSnackBar(
        SecretlySnackBar(
          content: Text(context.l10n.downloadFailed(error.toString())),
        ),
      );
    }
  }

  Future<void> _saveSingleAttachment({
    required AttachmentEventV1 attachment,
    required int createdAtMs,
  }) async {
    if (!mounted) return;
    final messenger = ScaffoldMessenger.of(context);

    try {
      final source = await _ensureAttachmentFile(attachment);
      final suggestedName = _attachmentDownloadSuggestedName(
        attachment,
        createdAtMs,
        source,
      );

      String? savePath;
      var pickerSupported = true;
      try {
        savePath = await FilePicker.platform.saveFile(fileName: suggestedName);
      } catch (_) {
        pickerSupported = false;
      }

      if (pickerSupported && (savePath == null || savePath.isEmpty)) {
        return;
      }

      if (!pickerSupported) {
        final savedPathLabel = await saveAttachmentToUserVisibleLocation(
          fileName: suggestedName,
          source: source,
          mime: attachment.mime,
        );
        if (!mounted) return;
        messenger.showSnackBar(
          SecretlySnackBar(content: Text(context.l10n.savedTo(savedPathLabel))),
        );
        return;
      }

      var resolvedPath = savePath!;
      final ext = p.extension(suggestedName);
      if (ext.isNotEmpty && p.extension(resolvedPath).isEmpty) {
        resolvedPath = '$resolvedPath$ext';
      }
      final target = File(resolvedPath);
      await target.parent.create(recursive: true);
      await source.copy(target.path);
      if (!mounted) return;
      messenger.showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.savedTo(target.path))),
      );
    } catch (error) {
      if (!mounted) return;
      messenger.showSnackBar(
        SecretlySnackBar(
          content: Text(context.l10n.downloadFailed(error.toString())),
        ),
      );
    }
  }

  /// Ставит пересылаемое вложение в ту же очередь загрузок, что и обычная
  /// отправка файла: пузырь с прогрессом появляется сразу.
  ///
  /// 🔴 ЗАЧЕМ (14.08.2026, жалоба владельца: «нажимаю „Отправить“ — секунд
  /// 20-30 ничего, и только потом появляется пузырь и грузится»).
  ///
  /// Пересылка звала отправку НАПРЯМУЮ и ждала её целиком: пока файл шифруется
  /// и уходит на сервер, в чате пусто и человек не знает, случилось ли что-то
  /// вообще. Обычная отправка файла так себя не ведёт — она кладёт задание в
  /// очередь, и пузырь виден с первой секунды.
  ///
  /// Файл берётся из кэша: он уже расшифрован на диске, и повторно скачивать
  /// его незачем. Докачка остаётся только для случая, когда кэш вычищен.
  Future<void> _enqueueForwardAttachment({
    required ForwardDraftItem item,
    required AttachmentEventV1 event,
    required String targetId,
    required bool isGroup,
  }) async {
    var file = await widget.controller.cachedAttachmentFile(event);
    file ??= await widget.controller.ensureCachedAttachmentFile(event);
    final mime = attachmentMimeFor(filename: item.filename, mime: item.mime);
    final totalBytes = event.sizeBytes > 0
        ? event.sizeBytes
        : await file.length();
    widget.controller.enqueuePhotoUpload(
      PendingPhotoUpload(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        filePath: file.path,
        mime: mime,
        caption: '',
        totalBytes: totalBytes,
        convoId: widget.convoId,
        targetId: targetId,
        isGroup: isGroup,
        topicId: isGroup ? _currentTopicId : null,
        filename: item.filename,
        // Документом — чтобы у пересланного файла осталась строка с именем, а
        // не безымянное превью.
        asFile: (item.filename ?? '').trim().isNotEmpty,
        // 🔴 ТОЛЬКО СВОИМ УСТРОЙСТВАМ (14.08.2026). Пересылая себе, отдаём тот
        // же blob и тот же ключ — заливать заново незачем, оба конца мои.
        //
        // Чужому получателю так делать нельзя: сервер увидит один blob в двух
        // разных чатах, то есть узнает, что файл переслан из A в B. Содержимое
        // при этом защищено одинаково, речь именно о метаданных.
        reuseBlobFrom: !isGroup && targetId == widget.controller.profileId
            ? event
            : null,
        // Песня уходит с теми же названием и исполнителем, что у исходного
        // сообщения, — иначе она приходила подписанной именем файла.
        musicTitle: taggedMusicTitle(event),
        musicArtist: taggedMusicArtist(event),
        // Голосовое остаётся голосовым: его отличает от песни только волна.
        waveform: event.waveform,
        durationMs: event.durationMs,
        // Кружок остаётся кружком (K-a).
        videoNote: event.videoNote,
      ),
    );
  }

  Future<void> _shareSingleAttachment({
    required AttachmentEventV1 attachment,
    required int createdAtMs,
    Rect? sharePositionOrigin,
  }) async {
    if (!mounted) return;

    try {
      final source = await _ensureAttachmentFile(attachment);
      // 🔴 ЧЕРЕЗ ОБЩИЙ ПУТЬ (14.08.2026, жалоба «всё равно .bin»).
      //
      // Здесь отдавался САМ ФАЙЛ КЭША, а он на диске зовётся `<blobId>.bin`.
      // Имя передавалось параметрами (`name`, `fileNameOverrides`), но
      // принимающее приложение читает имя С ДИСКА — и Telegram получал `.bin`
      // независимо от того, что мы объявили.
      //
      // `shareAttachmentFile` кладёт наружу копию с правильным именем и
      // выводит тип из имени, когда сам тип обезличен.
      await shareAttachmentFile(
        attachment: attachment,
        createdAtMs: createdAtMs,
        source: source,
        sharePositionOrigin: sharePositionOrigin,
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(context.l10n.downloadFailed(error.toString())),
        ),
      );
    }
  }

