  String? _sharedProfileIdFromMessageText(String text) {
    final trimmed = text.trim();
    if (trimmed.isEmpty || RegExp(r'\s').hasMatch(trimmed)) {
      return null;
    }
    final uri = Uri.tryParse(trimmed);
    if (uri == null) return null;
    return tryParseProfileShareUri(uri);
  }

  Future<_SharedProfileCardData?> _resolveSharedProfileCardData(
    String text, {
    Map<String, _SharedProfileCardData>? cache,
  }) async {
    final profileId = _sharedProfileIdFromMessageText(text);
    if (profileId == null) return null;

    final cached = cache?[profileId];
    if (cached != null) return cached;

    final contactPreviewText = chatText(
      context,
      ru: 'Контакт',
      en: 'Contact',
      uk: 'Контакт',
      es: 'Contacto',
      pt: 'Contato',
      fr: 'Contact',
      de: 'Kontakt',
    );
    final resolvedTitle = (await widget.controller.resolveConvoTitle(
      profileId,
    )).trim();
    final title = resolvedTitle.isEmpty || resolvedTitle == profileId
        ? profileId
        : resolvedTitle;
    final previewText = resolvedTitle.isEmpty || resolvedTitle == profileId
        ? contactPreviewText
        : resolvedTitle;
    final data = _SharedProfileCardData(
      profileId: profileId,
      title: title,
      previewText: previewText,
      avatarPath: await widget.controller.cachedProfileAvatarPath(profileId),
    );
    cache?[profileId] = data;
    return data;
  }

  RoomInviteTarget? _roomInviteTargetFromMessageText(String text) {
    final trimmed = text.trim();
    if (trimmed.isEmpty || RegExp(r'\s').hasMatch(trimmed)) {
      return null;
    }
    final uri = Uri.tryParse(trimmed);
    if (uri == null) return null;
    return tryParseRoomInviteUri(uri);
  }

  String _roomInvitePreviewText(RoomInvitePreview? preview) {
    if (preview == null) {
