  Future<_RoomInviteCardData?> _resolveRoomInviteCardData(
    String text, {
    Map<String, _RoomInviteCardData>? cache,
  }) async {
    final target = _roomInviteTargetFromMessageText(text);
    if (target == null) return null;

    final cacheKey = '${target.inviterProfileId}|${target.slug}';
    final cached = cache?[cacheKey];
    if (cached != null) return cached;

    RoomInvitePreview? preview;
    try {
      preview = await widget.controller.resolveRoomInviteTarget(target);
    } catch (_) {
      preview = null;
    }

    final data = _RoomInviteCardData(
      target: target,
      preview: preview,
      previewText: _roomInvitePreviewText(preview),
    );
    cache?[cacheKey] = data;
    return data;
  }

  Future<_LinkPreviewData?>? _linkPreviewFutureForMessage(String text) {
    final link = firstChatMessageLink(text);
    if (link == null) return null;
    final uri = link.uri;
    final key = uri.toString();
    return _linkPreviewFutures.putIfAbsent(
      key,
      () => _fetchLinkPreview(uri).then((data) {
        // Cache SUCCESSES only. `_fetchLinkPreview` also answers null for a
        // network blip, a timeout and a refused host — remembering those would
        // permanently hide a preview that a later visit would have loaded
        // fine. A link that genuinely has no preview simply costs one quiet
        // request per visit and shows nothing either way, which is the
        // cheaper mistake by far.
        if (data != null) {
          if (_linkPreviewResolved.length >= _linkPreviewCacheMax) {
            _linkPreviewResolved.remove(_linkPreviewResolved.keys.first);
          }
          _linkPreviewResolved[key] = data;
        } else {
          // Let a later visit try again.
          _linkPreviewFutures.remove(key);
        }
        return data;
      }),
    );
  }

  /// The preview for [text] if it has already loaded once — synchronously, so
  /// a re-entered chat paints the card in the SAME frame as its bubble instead
  /// of dropping it in afterwards.
  _LinkPreviewData? _linkPreviewInitialForMessage(String text) {
    final link = firstChatMessageLink(text);
    if (link == null) return null;
    return _linkPreviewResolved[link.uri.toString()];
  }

  // ── Карточка ссылки у сообщения ленты ─────────────────────────────────
  //
  // 🔴 ЧУЖИЕ ССЫЛКИ ТЕЛЕФОН БОЛЬШЕ НЕ ОТКРЫВАЕТ (решение владельца
  // 16.09.2026). Раньше превью грузилось и для входящих: любой собеседник
  // мог прислать ссылку на свой сервер и узнать адрес телефона, как только
  // получатель откроет чат, — ни на что не нажимая. Теперь карточку готовит
  // отправитель и присылает внутри сообщения.
  //
  // Свои сообщения без карточки (написанные до этого) грузятся, как раньше:
  // свою ссылку человек выбрал сам, и её сайт не узнает ничего нового.

  static final Expando<_LinkPreviewData> _carriedLinkPreviewData =
      Expando<_LinkPreviewData>('carriedLinkPreviewData');
  static final Expando<Future<_LinkPreviewData?>> _carriedLinkPreviewFuture =
      Expando<Future<_LinkPreviewData?>>('carriedLinkPreviewFuture');

  _LinkPreviewData? _carriedLinkPreview(_TimelineEntry entry) {
    final preview = entry.linkPreview;
    if (preview == null) return null;
    return _carriedLinkPreviewData[preview] ??=
        _LinkPreviewData.carried(preview);
  }

  bool _mayFetchOwnLinkPreview(_TimelineEntry entry) =>
      entry.isMe && entry.forwardedFrom == null;

  Future<_LinkPreviewData?>? _linkPreviewFutureForEntry(_TimelineEntry entry) {
    final carried = _carriedLinkPreview(entry);
    if (carried != null) {
      // Одно и то же будущее на каждую перерисовку: новое заставило бы
      // FutureBuilder подписываться заново.
      return _carriedLinkPreviewFuture[entry.linkPreview!] ??=
          SynchronousFuture<_LinkPreviewData?>(carried);
    }
    if (!_mayFetchOwnLinkPreview(entry)) return null;
    return _linkPreviewFutureForMessage(entry.messageText);
  }

  _LinkPreviewData? _linkPreviewInitialForEntry(_TimelineEntry entry) {
    final carried = _carriedLinkPreview(entry);
    if (carried != null) return carried;
    if (!_mayFetchOwnLinkPreview(entry)) return null;
    return _linkPreviewInitialForMessage(entry.messageText);
  }

  Future<void> _openExternalLink(Uri uri) async {
    final scheme = uri.scheme.toLowerCase();
    if (scheme != 'http' && scheme != 'https') return;
    try {
      final opened = await launchUrl(uri, mode: LaunchMode.externalApplication);
      if (opened || !mounted) return;
    } catch (_) {
      if (!mounted) return;
    }
    ScaffoldMessenger.of(context).showSnackBar(
      SecretlySnackBar(
        content: Text(
          chatText(
            context,
            ru: 'Не удалось открыть ссылку',
            en: 'Could not open link',
            uk: 'Не вдалося відкрити посилання',
            es: 'No se pudo abrir el enlace',
            pt: 'Não foi possível abrir o link',
            fr: 'Impossible d\'ouvrir le lien',
            de: 'Link konnte nicht geöffnet werden',
          ),
        ),
      ),
    );
  }

  Future<_LinkPreviewData?> _fetchLinkPreview(Uri uri) async {
    if (!_isSafeLinkPreviewUri(uri)) {
      return null;
    }

    final client = http_pkg.Client();
    try {
      final request = http_pkg.Request('GET', uri)
        ..headers['accept'] =
            'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.5'
        ..headers['user-agent'] =
            'Mozilla/5.0 (compatible; SecretlyLinkPreview/1.0)';
      final response = await client
          .send(request)
          .timeout(const Duration(seconds: 5));
      if (response.statusCode < 200 || response.statusCode >= 400) {
        return null;
      }
      final contentType = response.headers['content-type']?.toLowerCase() ?? '';
      if (contentType.isNotEmpty &&
          !contentType.contains('html') &&
          !contentType.contains('xml')) {
        return null;
      }
      final bytes = await _readLimitedLinkPreviewBytes(
        response.stream,
        384 * 1024,
      );
      if (bytes.isEmpty) return null;
      final html = utf8.decode(bytes, allowMalformed: true);
      return _parseLinkPreviewHtml(uri, html);
    } catch (_) {
      return null;
    } finally {
      client.close();
    }
  }

  bool _isSafeLinkPreviewUri(Uri uri) {
    final scheme = uri.scheme.toLowerCase();
    if (scheme != 'http' && scheme != 'https') return false;
    if (uri.userInfo.isNotEmpty) return false;
    if (uri.hasPort && uri.port != 80 && uri.port != 443) return false;

    final host = uri.host.trim().toLowerCase();
    if (host.isEmpty) return false;
    final normalizedHost = host.endsWith('.')
        ? host.substring(0, host.length - 1)
        : host;
    if (normalizedHost == 'localhost' ||
        normalizedHost.endsWith('.localhost') ||
        normalizedHost.endsWith('.local') ||
        !normalizedHost.contains('.')) {
      return false;
    }

    final address = InternetAddress.tryParse(normalizedHost);
    if (address == null) return true;
    return !_isPrivateLinkPreviewAddress(address);
  }

  bool _isPrivateLinkPreviewAddress(InternetAddress address) {
    if (address.isLoopback || address.isLinkLocal || address.isMulticast) {
      return true;
    }
    final raw = address.rawAddress;
    if (raw.length == 4) {
      final a = raw[0];
      final b = raw[1];
      return a == 0 ||
          a == 10 ||
          a == 127 ||
          (a == 100 && b >= 64 && b <= 127) ||
          (a == 169 && b == 254) ||
          (a == 172 && b >= 16 && b <= 31) ||
          (a == 192 && b == 168) ||
          (a == 198 && (b == 18 || b == 19)) ||
          a >= 224;
    }
    if (raw.length == 16) {
      final allZero = raw.every((byte) => byte == 0);
      return allZero ||
          raw[0] == 0xff ||
          (raw[0] & 0xfe) == 0xfc ||
          (raw[0] == 0xfe && (raw[1] & 0xc0) == 0x80);
    }
    return true;
  }

  Future<Uint8List> _readLimitedLinkPreviewBytes(
    Stream<List<int>> stream,
    int maxBytes,
  ) async {
    final builder = BytesBuilder(copy: false);
    await for (final chunk in stream.timeout(const Duration(seconds: 5))) {
      final remaining = maxBytes - builder.length;
      if (remaining <= 0) break;
      if (chunk.length <= remaining) {
        builder.add(chunk);
      } else {
        builder.add(chunk.sublist(0, remaining));
        break;
      }
    }
    return builder.takeBytes();
  }

  _LinkPreviewData? _parseLinkPreviewHtml(Uri url, String html) {
    final title = _firstNonEmpty([
      _linkMetaContent(html, const ['og:title']),
      _linkMetaContent(html, const ['twitter:title']),
      _htmlTitle(html),
    ]);
    final description = _firstNonEmpty([
      _linkMetaContent(html, const ['og:description']),
      _linkMetaContent(html, const ['twitter:description']),
      _linkMetaContent(html, const ['description']),
    ]);
    final siteName = _firstNonEmpty([
      _linkMetaContent(html, const ['og:site_name', 'application-name']),
      _prettyLinkHost(url.host),
    ]);
    final rawImage = _firstNonEmpty([
      _linkMetaContent(html, const ['og:image', 'og:image:url']),
      _linkMetaContent(html, const ['twitter:image', 'twitter:image:src']),
    ]);
    final imageUrl = rawImage == null
        ? null
        : _resolveLinkPreviewImage(url, rawImage);

    if ((title ?? '').trim().isEmpty &&
        (description ?? '').trim().isEmpty &&
        imageUrl == null) {
      return null;
    }

    return _LinkPreviewData(
      url: url,
      siteName: siteName ?? _prettyLinkHost(url.host),
      title: title,
      description: description,
      imageUrl: imageUrl,
    );
  }

  String? _linkMetaContent(String html, List<String> keys) {
    final wanted = keys.map((key) => key.toLowerCase()).toSet();
    final metaTagPattern = RegExp(r'<meta\b[^>]*>', caseSensitive: false);
    for (final tag in metaTagPattern.allMatches(html)) {
      final attrs = _htmlTagAttributes(tag.group(0) ?? '');
      final key = (attrs['property'] ?? attrs['name'] ?? attrs['itemprop'])
          ?.toLowerCase();
      if (key == null || !wanted.contains(key)) continue;
      final content = attrs['content'];
      if (content == null || content.trim().isEmpty) continue;
      return _cleanHtmlText(content);
    }
    return null;
  }

  Map<String, String> _htmlTagAttributes(String tag) {
    final attrs = <String, String>{};
    final attrPattern = RegExp(
      r'''([a-zA-Z_:.-]+)\s*=\s*(['"])(.*?)\2''',
      caseSensitive: false,
      dotAll: true,
    );
    for (final match in attrPattern.allMatches(tag)) {
      attrs[(match.group(1) ?? '').toLowerCase()] = match.group(3) ?? '';
    }
    return attrs;
  }

  String? _htmlTitle(String html) {
    final match = RegExp(
      r'<title[^>]*>(.*?)<\/title>',
      caseSensitive: false,
      dotAll: true,
    ).firstMatch(html);
    final title = match?.group(1);
    if (title == null || title.trim().isEmpty) return null;
    return _cleanHtmlText(title);
  }

  String? _resolveLinkPreviewImage(Uri baseUri, String rawImage) {
    final value = rawImage.trim();
    if (value.isEmpty) return null;
    final resolved = baseUri.resolve(value);
    if (!_isSafeLinkPreviewUri(resolved)) return null;
    return resolved.toString();
  }

  String? _firstNonEmpty(Iterable<String?> values) {
    for (final value in values) {
      final trimmed = value?.trim();
      if (trimmed != null && trimmed.isNotEmpty) return trimmed;
    }
    return null;
  }

  String _prettyLinkHost(String host) {
    final normalized = host.trim().toLowerCase();
    if (normalized.startsWith('www.')) return normalized.substring(4);
    return normalized;
  }

  String _cleanHtmlText(String value) {
    final withoutTags = value.replaceAll(RegExp(r'<[^>]+>'), ' ');
    return _decodeHtmlEntities(
      withoutTags.replaceAll(RegExp(r'\s+'), ' ').trim(),
    );
  }

  String _decodeHtmlEntities(String value) {
    const named = <String, String>{
      'amp': '&',
      'lt': '<',
      'gt': '>',
      'quot': '"',
      'apos': "'",
      '#39': "'",
      'nbsp': ' ',
    };
    return value.replaceAllMapped(RegExp(r'&(#x?[0-9a-fA-F]+|[a-zA-Z]+);'), (
      match,
    ) {
      final entity = match.group(1) ?? '';
      final lower = entity.toLowerCase();
      final namedValue = named[lower];
      if (namedValue != null) return namedValue;
      if (lower.startsWith('#x')) {
        final code = int.tryParse(lower.substring(2), radix: 16);
        return code == null ? match.group(0)! : String.fromCharCode(code);
      }
      if (lower.startsWith('#')) {
        final code = int.tryParse(lower.substring(1));
        return code == null ? match.group(0)! : String.fromCharCode(code);
      }
      return match.group(0)!;
    });
  }

  Future<void> _openSharedProfileConversation(
    _SharedProfileCardData card,
  ) async {
    final convoId = await widget.controller.prepareSharedProfileConversation(
      card.profileId,
    );
    if (!mounted) return;
    if (convoId == null || convoId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(
            chatText(
              context,
              ru: 'Не удалось открыть чат',
              en: 'Failed to open chat',
              uk: 'Не вдалося відкрити чат',
              es: 'No se pudo abrir el chat',
              pt: 'Não foi possível abrir o chat',
              fr: 'Impossible d\'ouvrir le chat',
              de: 'Chat konnte nicht geöffnet werden',
            ),
          ),
        ),
      );
      return;
    }
    if (convoId == widget.convoId) return;

    final destination = convoId.startsWith('req:')
        ? ChatScreen(
            controller: widget.controller,
            convoId: convoId,
            title: card.title,
            requestProfileId: card.profileId,
          )
        : ChatScreen(
            controller: widget.controller,
            convoId: card.profileId,
            title: card.title,
            peerProfileIdForSend: card.profileId,
          );

    await Navigator.of(
      context,
    ).push(SecretlyPageRoute(builder: (_) => destination));
  }

  Future<void> _openSharedRoomInvite(_RoomInviteCardData card) async {
    final messenger = ScaffoldMessenger.of(context);
    final failedOpenInviteLabel = chatText(
      context,
      ru: 'Не удалось открыть приглашение',
      en: 'Failed to open invite',
    );

    try {
      final preview =
          card.preview ??
          await widget.controller.resolveRoomInviteTarget(card.target);
      if (!mounted) return;
      if (preview.isAlreadyMember) {
        if (preview.groupId == widget.convoId) {
          return;
        }
        await Navigator.of(context).push(
          SecretlyPageRoute(
            builder: (_) => ChatScreen(
              controller: widget.controller,
              convoId: preview.groupId,
              title: preview.groupTitle,
            ),
          ),
        );
        return;
      }
    } catch (_) {
      // Fall back to the invite join screen below.
    }

    if (!mounted) return;
    final target = card.preview?.target ?? card.target;
    try {
      await Navigator.of(context).push(
        SecretlyPageRoute(
          builder: (_) => RoomInviteJoinScreen(
            controller: widget.controller,
            target: target,
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      messenger.showSnackBar(
        SecretlySnackBar(content: Text('$failedOpenInviteLabel: $error')),
      );
    }
  }

