  Future<void> _copySelectedMessages() async {
    final selected = await _loadSelectedEvents();
    if (selected.isEmpty) return;
    await _copyEventsToClipboard(selected);
    _clearSelection();
  }

  Future<void> _forwardSelectedMessages() async {
    final selected = await _loadSelectedEvents();
    if (selected.isEmpty) return;
    await _forwardEvents(selected);
    _clearSelection();
  }

  Future<void> _deleteSelectedMessages() async {
    final selected = await _loadSelectedEvents();
    if (selected.isEmpty) {
      _clearSelection();
      return;
    }
    // Always leave selection mode afterwards — even if the delete flow throws,
    // the selection toolbar must never stay stuck at the top.
    try {
      await _deleteEventsWithConfirm(selected);
    } finally {
      _clearSelection();
    }
  }

