  String _wallpaperPrefKey() => 'chat_wallpaper_v1_${widget.convoId}';
  String _notifPrefPrefix() => 'chat_notif_v1_${widget.convoId}_';
  String _pinnedMessagesPrefKey() =>
      '$_prefsPinnedMessagesPrefix${widget.convoId.trim()}';

  String _draftPrefKey() => '$_prefsDraftPrefix${widget.convoId.trim()}';

  /// Restores any unsent composer text saved when the user last left this chat.
  Future<void> _restoreDraft() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final draft = prefs.getString(_draftPrefKey());
      if (draft == null || draft.isEmpty) return;
      if (!mounted) return;
      // Don't clobber text the user already typed, or an active edit/forward.
      if (_text.text.isNotEmpty ||
          _editingTarget != null ||
          _forwardDraft != null) {
        return;
      }
      _text.value = TextEditingValue(
        text: draft,
        selection: TextSelection.collapsed(offset: draft.length),
      );
    } catch (_) {
      // best-effort
    }
  }

  /// Persists (or clears) the composer draft for this chat.
  Future<void> _persistDraft() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final text = _text.text;
      final key = _draftPrefKey();
      // Never persist a draft while editing/forwarding — that text is transient.
      if (text.trim().isEmpty ||
          _editingTarget != null ||
          _forwardDraft != null) {
        await prefs.remove(key);
      } else {
        await prefs.setString(key, text);
      }
    } catch (_) {
      // best-effort
    }
  }

  Future<void> _clearDraft() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.remove(_draftPrefKey());
    } catch (_) {
      // best-effort
    }
  }

  int _normalizedPinnedIndex(int index, int length) {
    if (length <= 0 || index < 0) return 0;
    if (index >= length) return length - 1;
    return index;
  }

  String _fallbackPinnedMessagePreview() {
    return chatText(
      context,
      ru: 'Закрепленное сообщение',
      en: 'Pinned message',
    );
  }

  String _entryIdForPin(_TimelineEntry entry) {
    return timelineRowId(entry.payloadEventId, entry.event.eventId).trim();
  }

  _TimelineEntry? _timelineEntryForEventId(String eventId) {
    final target = eventId.trim();
    if (target.isEmpty) return null;
    for (final timelineEntry in _lastTimeline) {
      if ((timelineEntry.payloadEventId ?? timelineEntry.event.eventId) ==
              target ||
          timelineEntry.event.eventId == target) {
        return timelineEntry;
      }
    }
    return null;
  }

  _PinnedMessage _pinnedMessageForEventId(
    String eventId, {
    String? previewText,
    int? pinnedAtMs,
  }) {
    final entry = _timelineEntryForEventId(eventId);
    final fallbackPreview = _fallbackPinnedMessagePreview();
    final resolvedPreview = entry == null
        ? _trimPreview(previewText ?? '')
        : _trimPreview(entry.previewText);
    return _PinnedMessage(
      eventId: eventId.trim(),
      previewText: resolvedPreview.isEmpty ? fallbackPreview : resolvedPreview,
      pinnedAtMs: pinnedAtMs ?? DateTime.now().millisecondsSinceEpoch,
    );
  }

  List<_PinnedMessage> _decodePinnedMessages(String? raw) {
    if (raw == null || raw.trim().isEmpty) return const <_PinnedMessage>[];
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! List) return const <_PinnedMessage>[];
      final seen = <String>{};
      final messages = <_PinnedMessage>[];
      for (final item in decoded) {
        final message = _PinnedMessage.fromJson(item);
        if (message == null || !seen.add(message.eventId)) continue;
        messages.add(message);
      }
      messages.sort((a, b) => b.pinnedAtMs.compareTo(a.pinnedAtMs));
      return messages.take(50).toList(growable: false);
    } catch (_) {
      return const <_PinnedMessage>[];
    }
  }

  Future<void> _restorePinnedMessages() async {
    final key = _pinnedMessagesPrefKey();
    final prefs = await SharedPreferences.getInstance();
    final restored = _decodePinnedMessages(prefs.getString(key));
    if (!mounted || key != _pinnedMessagesPrefKey()) return;
    setState(() {
      _pinnedMessages = restored;
      _visiblePinnedMessageIndex = _normalizedPinnedIndex(
        _visiblePinnedMessageIndex,
        _effectivePinnedMessages().length,
      );
    });
  }

  Future<void> _savePinnedMessages() async {
    final key = _pinnedMessagesPrefKey();
    final messages = _pinnedMessages;
    final prefs = await SharedPreferences.getInstance();
    if (messages.isEmpty) {
      await prefs.remove(key);
      return;
    }
    await prefs.setString(
      key,
      jsonEncode(messages.map((message) => message.toJson()).toList()),
    );
  }

  List<_PinnedMessage> _withoutPinnedMessage(
    List<_PinnedMessage> messages,
    String eventId,
  ) {
    final target = eventId.trim();
    if (target.isEmpty) return messages;
    return messages
        .where((message) => message.eventId != target)
        .toList(growable: false);
  }

  List<_PinnedMessage> _withPinnedMessage(
    List<_PinnedMessage> messages,
    _PinnedMessage message,
  ) {
    final target = message.eventId.trim();
    if (target.isEmpty) return messages;
    final next = <_PinnedMessage>[
      message,
      ...messages.where((item) => item.eventId != target),
    ];
    return next.take(50).toList(growable: false);
  }

  List<_PinnedMessage> _effectivePinnedMessages() {
    final serverPinnedEventId = (_groupPinnedMessageEventId ?? '').trim();
    if (!_isGroupChat || serverPinnedEventId.isEmpty) {
      return _pinnedMessages;
    }
    final hasServerPin = _pinnedMessages.any(
      (message) => message.eventId == serverPinnedEventId,
    );
    if (hasServerPin) return _pinnedMessages;
    return <_PinnedMessage>[
      _pinnedMessageForEventId(serverPinnedEventId),
      ..._pinnedMessages,
    ];
  }

  bool _isPinnedEventId(String eventId) {
    final target = eventId.trim();
    if (target.isEmpty) return false;
    return _effectivePinnedMessages().any(
      (message) => message.eventId == target,
    );
  }

  String get _effectiveWallpaperId {
    final resolved = resolveEffectiveChatWallpaperId(
      selectionId: _chatWallpaperSelectionId,
      defaultId: widget.controller.defaultChatWallpaperId,
    );
    // Revert a premium (server:) per-chat wallpaper to the standard default when
    // the cosmetic gate is locked (subscription lapsed). The saved selection is
    // preserved in prefs so it re-applies automatically on renewal. The default
    // returned here is itself already gated by the controller getter.
    if (!widget.controller.cosmeticWallpaperUsable(resolved)) {
      return widget.controller.defaultChatWallpaperId;
    }
    return resolved;
  }

  Future<void> _loadBundledWallpapers() async {
    await loadBundledChatWallpaperAssets();
  }

  Future<void> _restoreChatWallpaperSelection() async {
    final prefs = await SharedPreferences.getInstance();
    final saved = prefs.getString(_wallpaperPrefKey());
    final normalized = (saved == null || saved.trim().isEmpty)
        ? kGlobalChatWallpaperSelectionId
        : saved.trim();
    if (!mounted) return;
    setState(() {
      _chatWallpaperSelectionId = isValidChatWallpaperId(normalized)
          ? normalized
          : kGlobalChatWallpaperSelectionId;
    });
  }

  Future<void> _saveChatWallpaperSelection(String id) async {
    final prefs = await SharedPreferences.getInstance();
    if (id == kGlobalChatWallpaperSelectionId) {
      await prefs.remove(_wallpaperPrefKey());
      return;
    }
    await prefs.setString(_wallpaperPrefKey(), id);
  }

  Future<_ChatNotificationSettings> _loadChatNotificationSettings({
    required bool muted,
  }) async {
    final prefs = await SharedPreferences.getInstance();
    final prefix = _notifPrefPrefix();
    final enabled = prefs.getBool('${prefix}enabled') ?? !muted;
    final sound = prefs.getBool('${prefix}sound') ?? true;
    final vibration = prefs.getBool('${prefix}vibration') ?? true;
    final legacyPreviews = prefs.getBool('${prefix}preview') ?? true;
    // Per-conversation override is the source of truth (shared with the contact
    // profile sheet). For a 1:1 chat, honour a legacy per-contact override
    // (written by older builds of the contact sheet, keyed by the peer profile
    // id == convoId) so this menu shows the value the notification code uses.
    int? legacyContactOverride;
    if (!widget.convoId.startsWith('group:') &&
        !widget.convoId.startsWith('req:')) {
      legacyContactOverride = prefs.getInt(
        'contact_notif_privacy_level_v1_${widget.convoId.trim()}',
      );
    }
    final privacyLevel =
        (prefs.getInt('${prefix}privacy_level') ??
                legacyContactOverride ??
                (legacyPreviews ? 2 : 1))
            .clamp(0, 2)
            .toInt();
    final quietHours = prefs.getBool('${prefix}quiet_hours') ?? false;
    final startHour = (prefs.getInt('${prefix}quiet_start_hour') ?? 22).clamp(
      0,
      23,
    );
    final endHour = (prefs.getInt('${prefix}quiet_end_hour') ?? 8).clamp(0, 23);
    return _ChatNotificationSettings(
      enabled: enabled,
      sound: sound,
      vibration: vibration,
      previews: privacyLevel >= 2,
      privacyLevel: privacyLevel,
      quietHours: quietHours,
      quietStartHour: startHour,
      quietEndHour: endHour,
    );
  }

  Future<void> _saveChatNotificationSettings(
    _ChatNotificationSettings settings,
  ) async {
    final prefs = await SharedPreferences.getInstance();
    final prefix = _notifPrefPrefix();
    await prefs.setBool('${prefix}enabled', settings.enabled);
    await prefs.setBool('${prefix}sound', settings.sound);
    await prefs.setBool('${prefix}vibration', settings.vibration);
    await prefs.setBool('${prefix}preview', settings.privacyLevel >= 2);
    await prefs.setInt('${prefix}privacy_level', settings.privacyLevel);
    await prefs.setBool('${prefix}quiet_hours', settings.quietHours);
    await prefs.setInt('${prefix}quiet_start_hour', settings.quietStartHour);
    await prefs.setInt('${prefix}quiet_end_hour', settings.quietEndHour);
    widget.controller.refreshPushNotificationPolicy();
  }

  Widget _buildChatWallpaperBackground() {
    return buildChatWallpaperBackground(
      context,
      _effectiveWallpaperId,
      animMode: widget.controller.chatWallpaperAnimMode,
      conduct: widget.controller.chatWallpaperConduct,
      animKey: _wallpaperShimmerKey,
      blurController:
          (kIncomingBubbleWallpaperGlass &&
              widget.controller.bubbleGlassEnabled)
          ? _wallpaperBlur
          : null,
    );
  }

  // Готовит/обновляет размытую мини-текстуру обоев для «стеклянных» входящих
  // пузырей. Вызывается из build — дёшево: контроллер сам отсекает повторы по
  // ключу (обои, тема, размер вьюпорта); тяжёлая работа (декод + blur)
  // асинхронная и одноразовая на смену обоев.
  void _syncWallpaperBlur(BuildContext context) {
    if (!kIncomingBubbleWallpaperGlass ||
        !widget.controller.bubbleGlassEnabled) {
      return;
    }
    final id = _effectiveWallpaperId;
    final dark = Theme.of(context).brightness == Brightness.dark;
    final size = MediaQuery.sizeOf(context);
    final dpr = MediaQuery.devicePixelRatioOf(context);
    if (size.isEmpty) return;

    final assetPath = decodeAssetChatWallpaperId(id);
    if (assetPath != null) {
      _wallpaperBlurServerKey = null;
      final themed = themedChatWallpaperAssetPath(assetPath, darkMode: dark);
      _wallpaperBlur.configureStill(
        cacheKey: 'asset:$themed',
        provider: AssetImage(themed),
        viewportSize: size,
        devicePixelRatio: dpr,
      );
      return;
    }
    final filePath = decodeFileChatWallpaperId(id);
    if (filePath != null) {
      _wallpaperBlurServerKey = null;
      _wallpaperBlur.configureStill(
        cacheKey: 'file:$filePath',
        provider: FileImage(File(filePath)),
        viewportSize: size,
        devicePixelRatio: dpr,
      );
      return;
    }
    final animStyle = decodeAnimatedChatWallpaperStyle(id);
    if (animStyle != null) {
      // Кадры пушит сам TelegramWallpaper (см. blurController в
      // _buildChatWallpaperBackground) — здесь только переключаем режим.
      _wallpaperBlurServerKey = null;
      _wallpaperBlur.configureAnimated(
        cacheKey: 'anim:${animStyle.key}',
        viewportSize: size,
        devicePixelRatio: dpr,
      );
      return;
    }
    final serverItemId = decodeServerChatWallpaperId(id);
    if (serverItemId != null) {
      // Файл серверных обоев резолвится асинхронно (кэш каталога косметики);
      // ключ + generation защищают от гонок при быстрой смене обоев.
      final key = ('server', serverItemId, dark, size.width, size.height, dpr);
      if (_wallpaperBlurServerKey == key) return;
      _wallpaperBlurServerKey = key;
      final gen = ++_wallpaperBlurServerGen;
      unawaited(() async {
        try {
          final item = await CosmeticsCatalogService.instance.itemById(
            serverItemId,
          );
          final file = item == null
              ? null
              : await CosmeticsCatalogService.instance.fullFile(item);
          if (!mounted || gen != _wallpaperBlurServerGen || file == null) {
            return;
          }
          _wallpaperBlur.configureStill(
            cacheKey: 'server:${file.path}',
            provider: FileImage(file),
            viewportSize: size,
            devicePixelRatio: dpr,
          );
        } catch (_) {
          // Best-effort: без файла пузыри остаются на фолбэк-плите.
        }
      }());
      return;
    }
    // Однотонные градиентные обои ('default' / 'midnight'): текстура = тот же
    // диагональный градиент, что рисует фон чата (см.
    // buildChatWallpaperBackground), блюрить нечего.
    _wallpaperBlurServerKey = null;
    final colors = id == 'midnight'
        ? themedDarkSolidChatWallpaperColors(context)
        : themedLightSolidChatWallpaperColors(context);
    _wallpaperBlur.configureGradient(
      cacheKey:
          'solid:$id:${colors.first.toARGB32()}:${colors.last.toARGB32()}',
      colors: colors,
      viewportSize: size,
      devicePixelRatio: dpr,
    );
  }

  // One shimmer step of the animated wallpaper. No-op unless an `anim:`
  // wallpaper is currently mounted (the key's state is null otherwise).
  void _shimmerWallpaperOnSend() {
    if (widget.controller.chatWallpaperAnimMode == ChatWallpaperAnimMode.off) {
      return;
    }
    _wallpaperShimmerKey.currentState?.shimmer();
  }

  void _shimmerWallpaperOnEmptyTap() {
    if (widget.controller.chatWallpaperAnimMode != ChatWallpaperAnimMode.tap) {
      return;
    }
    _wallpaperShimmerKey.currentState?.shimmer();
  }

  // ── «Обои проводят сообщение» ──────────────────────────────────────────────
  //
  // ГДЕ ЗДЕСЬ ОПТИМИЗАЦИЯ. Волна стоит кадров, поэтому она обязана возникать
  // только там, где на неё смотрят. Отсекается по очереди:
  //
  //  1. эффект выключен — выходим, не трогая даже ключ;
  //  2. обои не анимированные (`anim:`) — `currentState` пуст, виджета нет;
  //  3. ЭКРАН ЧАТА НЕ ВЕРХНИЙ — открыт профиль, галерея, настройки поверх
  //     него: чат жив и продолжает получать сообщения, но не виден. Без этой
  //     проверки каждое входящее гоняло бы GPU за закрытой дверью;
  //  4. приложение в фоне — отсекается уже внутри виджета, там же где
  //     гасится летящая волна;
  //  5. ПАЧКА сообщений — виджет не перезапускает летящий импульс, так что
  //     десять сообщений подряд стоят ровно одной волны, а не десяти.
  //
  // Отдельно: когда чат ЗАКРЫТ, обоев нет вообще — виджет размонтирован, поле
  // и шейдер освобождены. Уведомления и фоновая доставка сюда не заходят.
  void _conductWallpaper({required bool incoming}) {
    if (!mounted || !widget.controller.chatWallpaperConduct) return;
    final route = ModalRoute.of(context);
    if (route != null && !route.isCurrent) return;
    _wallpaperShimmerKey.currentState?.conductMessage(incoming: incoming);
  }

  bool _conductPending = false;

  /// Вызывается из построения строки — поэтому запуск откладывается на конец
  /// кадра: трогать контроллер анимации во время build нельзя, а пачку
  /// пришедших строк надо свернуть в одно событие.
  void _conductWallpaperOnIncoming() {
    if (_conductPending || !widget.controller.chatWallpaperConduct) return;
    _conductPending = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _conductPending = false;
      _conductWallpaper(incoming: true);
    });
  }

  // Telegram-style content fade: dissolves only the message-list content
  // (bubbles, etc.) at the very top (under the floating header islands) and
  // bottom (above the composer) while leaving the chat wallpaper — a separate
  // Stack layer below the list — fully visible. Used as the ShaderMask
  // shaderCallback around the timeline ListView. Reversible: drop this helper +
  // the ShaderMask wrap to restore the previous behaviour.
  static Shader _chatContentFadeShader(
    Rect rect, {
    required double topFadeEndPx,
  }) {
    final h = rect.height <= 0 ? 1.0 : rect.height;
    // Content is fully opaque from the bottom edge of the top islands downward,
    // so bubbles dissolve smoothly behind the islands (not in a band lower
    // down). Clamp for unusually small/large viewports.
    final topStop = (topFadeEndPx / h).clamp(0.04, 0.4).toDouble();
    return LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: const [
        Colors.transparent,
        Colors.white,
        Colors.white,
        Colors.transparent,
      ],
      stops: [0.0, topStop, 0.93, 1.0],
    ).createShader(rect);
  }

  Future<void> _showWallpaperPickerSheet() async {
    final latestPaths = await loadBundledChatWallpaperAssets();
    // Point the cosmetics catalog at the relay before querying — must not depend
    // on whether the deferred relay setup / another screen configured it first,
    // or server wallpapers silently resolve to an empty list (configured=false)
    // and only the bundled ones show. (Mirrors the profile icon picker.)
    CosmeticsCatalogService.instance.configure(
      widget.controller.relayHttpBaseUrl,
    );
    final serverItems = await CosmeticsCatalogService.instance.wallpapers();
    if (!mounted) return;
    final serverWallpapers = serverItems
        .map((it) => (id: it.id, title: it.title))
        .toList(growable: false);
    final options = buildChatWallpaperOptions(
      context,
      assetPaths: latestPaths,
      filePaths: widget.controller.profileBackgroundPaths,
      serverWallpapers: serverWallpapers,
      includeGlobalOption: true,
    );
    final selected = await showWallpaperPickerSheet(
      context,
      options: options,
      selectedId: _chatWallpaperSelectionId,
      isLocked: (id) => !isCosmeticAllowed(
        widget.controller.entitlementStateNow,
        CosmeticKind.wallpaper,
        id,
      ),
      isAnimated: isAnimatedChatWallpaperId,
      onAnimatedUnlockedTap: (ctx, id) async {
        final style = decodeAnimatedChatWallpaperStyle(id);
        if (style == null) return null;
        final choice = await showAnimatedWallpaperPreview(
          ctx,
          style: style,
          initialMode: widget.controller.chatWallpaperAnimMode,
          initialConduct: widget.controller.chatWallpaperConduct,
        );
        if (choice == null) return null;
        await widget.controller.setChatWallpaperAnimMode(choice.mode);
        await widget.controller.setChatWallpaperConduct(choice.conduct);
        return id;
      },
      title: chatText(
        context,
        ru: 'Обои чата',
        en: 'Chat wallpapers',
        uk: 'Шпалери чату',
        es: 'Fondos de chat',
        pt: 'Papéis de parede do chat',
        fr: 'Fonds d\'\u00e9cran du chat',
        de: 'Chat-Hintergründe',
      ),
    );

    if (selected == null || !isValidChatWallpaperId(selected)) return;
    if (!mounted) return;
    // Server (premium) wallpaper while locked → paywall instead of applying.
    if (!isCosmeticAllowed(
      widget.controller.entitlementStateNow,
      CosmeticKind.wallpaper,
      selected,
    )) {
      await showPaywall(context, PaywallTrigger.cosmetic);
      return;
    }
    setState(() => _chatWallpaperSelectionId = selected);
    await _saveChatWallpaperSelection(selected);
  }

  Future<void> _openChatActionsMenu({
    required bool muted,
    required bool blocked,
    required String peerProfileId,
  }) async {
    var settings = await _loadChatNotificationSettings(muted: muted);
    var showNotifications = false;
    if (!mounted) return;

    await showGeneralDialog<void>(
      context: context,
      barrierLabel: 'chat_actions_menu',
      barrierColor: Colors.black.withValues(alpha: 0.12),
      barrierDismissible: true,
      transitionDuration: const Duration(milliseconds: 200),
      transitionBuilder: (context, animation, secondaryAnimation, child) {
        final curved = CurvedAnimation(
          parent: animation,
          curve: Curves.easeOutCubic,
          reverseCurve: Curves.easeInCubic,
        );
        return FadeTransition(
          opacity: curved,
          child: ScaleTransition(
            scale: Tween<double>(begin: 0.92, end: 1.0).animate(curved),
            alignment: Alignment.topRight,
            child: child,
          ),
        );
      },
      pageBuilder: (context, animation, secondaryAnimation) {
        final cs = Theme.of(context).colorScheme;
        final media = MediaQuery.of(context);
        final panelWidth = (media.size.width - 64).clamp(214.0, 264.0);

        Future<void> commitSettings(
          _ChatNotificationSettings next, {
          bool syncMuteWithEnabled = false,
        }) async {
          settings = next;
          await _saveChatNotificationSettings(next);
          if (syncMuteWithEnabled) {
            await widget.controller.setChatMuted(
              convoId: widget.convoId,
              muted: !next.enabled,
            );
          }
        }

        String privacyLevelLabel(int level) {
          switch (level.clamp(0, 2)) {
            case 0:
              return chatText(
                context,
                ru: 'Скрыто',
                en: 'Hidden',
                uk: 'Приховано',
                es: 'Oculto',
                pt: 'Oculto',
                fr: 'Masqué',
                de: 'Verborgen',
              );
            case 1:
              return chatText(
                context,
                ru: 'Только отправитель',
                en: 'Sender only',
                uk: 'Лише відправник',
                es: 'Solo remitente',
                pt: 'Apenas remetente',
                fr: 'Expéditeur uniquement',
                de: 'Nur Absender',
              );
            default:
              return chatText(
                context,
                ru: 'Отправитель и текст',
                en: 'Sender + message',
                uk: 'Відправник та повідомлення',
                es: 'Remitente + mensaje',
                pt: 'Remetente + mensagem',
                fr: 'Expéditeur + message',
                de: 'Absender + Nachricht',
              );
          }
        }

        Future<void> pickPrivacyLevel() async {
          final selected = await showModalBottomSheet<int>(
            context: context,
            showDragHandle: true,
            builder: (context) {
              const options = <int>[0, 1, 2];
              return SafeArea(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    for (final option in options)
                      ListTile(
                        title: Text(privacyLevelLabel(option)),
                        trailing: settings.privacyLevel == option
                            ? Icon(AppIcons.checkCircleSolid, color: cs.primary)
                            : null,
                        onTap: () => Navigator.of(context).pop(option),
                      ),
                  ],
                ),
              );
            },
          );
          if (selected == null) return;
          final next = settings.copyWith(
            privacyLevel: selected,
            previews: selected >= 2,
          );
          settings = next;
          await commitSettings(next);
        }

        return StatefulBuilder(
          builder: (context, setLocalState) {
            return Stack(
              children: [
                Positioned.fill(
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: () => Navigator.of(context).pop(),
                  ),
                ),
                Positioned(
                  top: media.padding.top + kToolbarHeight - 12,
                  right: 10,
                  child: Material(
                    color: Colors.transparent,
                    child: _FrostedGlass(
                      borderRadius: BorderRadius.circular(20),
                      sigmaX: 24,
                      sigmaY: 24,
                      backgroundColor: cs.surface.withValues(alpha: 0.24),
                      child: ConstrainedBox(
                        constraints: BoxConstraints(
                          maxWidth: panelWidth,
                          maxHeight: media.size.height * 0.72,
                        ),
                        child: SingleChildScrollView(
                          padding: const EdgeInsets.fromLTRB(6, 8, 6, 8),
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              ListTile(
                                contentPadding: const EdgeInsets.symmetric(
                                  horizontal: 10,
                                ),
                                minLeadingWidth: 22,
                                horizontalTitleGap: 10,
                                visualDensity: const VisualDensity(
                                  horizontal: -1,
                                  vertical: -1,
                                ),
                                dense: true,
                                leading: const Icon(AppIcons.bell, size: 22),
                                title: Text(
                                  chatText(
                                    context,
                                    ru: 'Уведомления',
                                    en: 'Notifications',
                                    uk: 'Сповіщення',
                                    es: 'Notificaciones',
                                    pt: 'Notificações',
                                    fr: 'Notifications',
                                    de: 'Benachrichtigungen',
                                  ),
                                  style: Theme.of(context).textTheme.titleMedium
                                      ?.copyWith(fontWeight: FontWeight.w600),
                                ),
                                trailing: AnimatedRotation(
                                  turns: showNotifications ? 0.5 : 0,
                                  duration: const Duration(milliseconds: 180),
                                  child: const Icon(
                                    AppIcons.chevronRight,
                                    size: 19,
                                  ),
                                ),
                                onTap: () => setLocalState(
                                  () => showNotifications = !showNotifications,
                                ),
                              ),
                              AnimatedSize(
                                duration: const Duration(milliseconds: 220),
                                curve: Curves.easeOutCubic,
                                child: showNotifications
                                    ? Padding(
                                        padding: const EdgeInsets.fromLTRB(
                                          12,
                                          0,
                                          12,
                                          8,
                                        ),
                                        child: Column(
                                          children: [
                                            SwitchListTile.adaptive(
                                              contentPadding: EdgeInsets.zero,
                                              value: settings.enabled,
                                              title: Text(
                                                chatText(
                                                  context,
                                                  ru: 'Включены',
                                                  en: 'Enabled',
                                                  uk: 'Увімкнено',
                                                  es: 'Activado',
                                                  pt: 'Ativado',
                                                  fr: 'Activé',
                                                  de: 'Aktiviert',
                                                ),
                                              ),
                                              onChanged: (v) async {
                                                final next = settings.copyWith(
                                                  enabled: v,
                                                );
                                                setLocalState(
                                                  () => settings = next,
                                                );
                                                await commitSettings(
                                                  next,
                                                  syncMuteWithEnabled: true,
                                                );
                                              },
                                            ),
                                            SwitchListTile.adaptive(
                                              contentPadding: EdgeInsets.zero,
                                              value: settings.sound,
                                              title: Text(
                                                chatText(
                                                  context,
                                                  ru: 'Звук',
                                                  en: 'Sound',
                                                  uk: 'Звук',
                                                  es: 'Sonido',
                                                  pt: 'Som',
                                                  fr: 'Son',
                                                  de: 'Ton',
                                                ),
