  Future<void> _copyEventsToClipboard(List<ChatEvent> events) async {
    final lines = <String>[];
    final isRu = chatLocaleIsRussian(context);
    final stickerBaseLabel = chatText(
      context,
      ru: 'Стикер',
      en: 'Sticker',
      uk: 'Стікер',
      es: 'Sticker',
      pt: 'Sticker',
      fr: 'Sticker',
      de: 'Sticker',
    );
    for (final event in events) {
      final payload = await widget.controller.payloadEventForChatEvent(event);
      String text;
      if (payload is MsgEventV1) {
        if (_isDeleteForAllCommandText(payload.text) ||
            _isHiddenSystemCommandText(payload.text)) {
          continue;
        }
        text = payload.text;
      } else if (payload is AttachmentEventV1) {
        text = _attachmentPreviewLabel(payload.mime, waveform: payload.waveform);
      } else if (payload is StickerEventV1) {
        text = SecretlyStickerCatalog.previewLabel(
          isRu: isRu,
          baseLabel: stickerBaseLabel,
          emojiHint: payload.emojiHint,
          label: payload.label,
        );
      } else {
        text = await widget.controller.decryptPlainAsync(event);
      }
      final who = widget.controller.isOwnDeviceId(event.senderDeviceId)
          ? _selfAuthorLabel()
          : widget.title;
      lines.add('$who: $text');
    }
    if (lines.isEmpty) return;
    await Clipboard.setData(ClipboardData(text: lines.join('\n')));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SecretlySnackBar(
        content: Text(chatText(context, ru: 'Скопировано', en: 'Copied')),
      ),
    );
  }

  void _showChatMessage(String text) {
    if (!mounted) return;
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SecretlySnackBar(content: Text(text)));
  }

  Future<void> _startSecureCallFromChat({
    required String peerProfileId,
    required bool video,
  }) async {
    final l10n = context.l10n;
    final cm = CallManager.instance;
    if (cm == null) {
      _showChatMessage(
        callErrorText(l10n, CallFailure(CallFailureCode.serviceUnavailable)),
      );
      return;
    }
    if (cm.state.value.isActive) {
      _showChatMessage(
        callErrorText(l10n, CallFailure(CallFailureCode.alreadyInProgress)),
      );
      return;
    }
    try {
      final titleFromScreen = widget.title.trim();
      var peerName = titleFromScreen;
      try {
        final resolvedTitle = (await widget.controller.resolveConvoTitle(
          peerProfileId,
        )).trim();
        if (resolvedTitle.isNotEmpty && resolvedTitle != peerProfileId) {
          peerName = resolvedTitle;
        }
      } catch (_) {}
      if (_isGenericCallPeerTitle(peerName, l10n)) {
        peerName = peerProfileId;
      }
      await cm.startCall(
        peerProfileId: peerProfileId,
        peerName: peerName.isNotEmpty ? peerName : peerProfileId,
        video: video,
      );
    } catch (e) {
      if (!mounted) return;
      _showChatMessage(callErrorText(l10n, e));
    }
  }

  bool _isGenericCallPeerTitle(String value, AppLocalizations l10n) {
    final normalized = value.trim().toLowerCase();
    if (normalized.isEmpty) return true;
    return normalized == 'chat' ||
        normalized == 'чат' ||
        normalized == l10n.notificationTitleChat.trim().toLowerCase() ||
        normalized == l10n.contactDetailsChat.trim().toLowerCase();
  }

  Future<void> _forwardEvents(List<ChatEvent> events) async {
    if (events.isEmpty || !mounted) return;
    final items = <ForwardDraftItem>[];
    final senderProfileIds = <String, String?>{};
    final selfAuthorLabel = _selfAuthorLabel();
    final privacySkippedText = chatText(
      context,
      ru: 'Эти сообщения нельзя переслать из-за ограничений приватности.',
      en: 'These messages cannot be forwarded because of privacy restrictions.',
      uk: 'Ці повідомлення не можна переслати через обмеження приватності.',
      es: 'Estos mensajes no se pueden reenviar por restricciones de privacidad.',
      pt: 'Estas mensagens nao podem ser reencaminhadas por restricoes de privacidade.',
      ptBr:
          'Estas mensagens nao podem ser encaminhadas por restricoes de privacidade.',
      fr: 'Ces messages ne peuvent pas etre transferes a cause des restrictions de confidentialite.',
      de: 'Diese Nachrichten koennen wegen Datenschutzeinschraenkungen nicht weitergeleitet werden.',
    );
    final noForwardMessagesText = chatText(
      context,
      ru: 'Нет сообщений для пересылки.',
      en: 'No messages to forward.',
      uk: 'Немає повідомлень для пересилання.',
      es: 'No hay mensajes para reenviar.',
      pt: 'Nao ha mensagens para reencaminhar.',
      ptBr: 'Nao ha mensagens para encaminhar.',
      fr: 'Aucun message a transferer.',
      de: 'Keine Nachrichten zum Weiterleiten.',
    );
    var blockedCount = 0;

    Future<String?> resolveSourceProfileId(String senderDeviceId) async {
      if (widget.controller.isOwnDeviceId(senderDeviceId)) {
        return null;
      }
      if (senderProfileIds.containsKey(senderDeviceId)) {
        return senderProfileIds[senderDeviceId];
      }
      // WEAK NETWORK (2026-07-29, field report "нажимаю переслать — ничего не
      // происходит, список открылся с десятой попытки"): resolving a sender
      // device that is NOT in the local cache goes to the keys server, whose
      // HTTP timeout is 8 s — and that await sits between the "Forward" tap and
      // the chat picker, so on a bad connection the screen simply never opened.
      // The resolved profile is only used for the "forwarded from X" label and
      // the per-peer forward-privacy check, and a lookup that FAILS already
      // degrades to null today — so bound the wait instead of blocking the UI on
      // it. The (possibly null) result is cached for this pass, so a chat with
      // several unknown senders still costs at most one short wait each.
      String? resolved;
      try {
        resolved = await widget.controller
            .resolveSenderProfileId(senderDeviceId)
            .timeout(const Duration(milliseconds: 1500));
      } catch (_) {
        resolved = null;
      }
      senderProfileIds[senderDeviceId] = resolved;
      return resolved;
    }

    for (final event in events) {
      final sourceProfileId = await resolveSourceProfileId(
        event.senderDeviceId,
      );
      if (!await widget.controller.canForwardFromProfile(sourceProfileId)) {
        blockedCount += 1;
        continue;
      }
      final payload = await widget.controller.payloadEventForChatEvent(event);
      if (payload is MsgEventV1) {
        if (_isDeleteForAllCommandText(payload.text) ||
            _isHiddenSystemCommandText(payload.text)) {
          continue;
        }
        final author = widget.controller.isOwnDeviceId(event.senderDeviceId)
            ? selfAuthorLabel
            : sourceProfileId != null && sourceProfileId.isNotEmpty
            ? await widget.controller.resolveConvoTitle(sourceProfileId)
            : widget.title;
        items.add(
          ForwardDraftItem.text(
            authorName: author,
            text: payload.text,
            sourceProfileId: sourceProfileId,
            sourceConvoId: widget.convoId,
          ),
        );
        continue;
      }
      if (payload is AttachmentEventV1) {
        // 🔴 ФАЙЛ ЗДЕСЬ НЕ ТРОГАЕМ ВОВСЕ (14.08.2026).
        //
        // Здесь стоял `downloadAndDecryptAttachment`: он выкачивал блоб С
        // СЕРВЕРА (не заглядывая в кэш) и отдавал файл ЦЕЛИКОМ в память — и всё
        // это ДО показа списка чатов. Владелец видел ровно это: «долго
        // открывалось окно со списком пользователей», а затем «чат невероятно
        // сильно лагает», потому что 73 МБ жили в черновике.
        //
        // Черновику содержимое не нужно: файл требуется в момент отправки.
        // Список открывается мгновенно, файл берётся из кэша уже при отправке.
        final author = widget.controller.isOwnDeviceId(event.senderDeviceId)
            ? _selfAuthorLabel()
            : sourceProfileId != null && sourceProfileId.isNotEmpty
            ? await widget.controller.resolveConvoTitle(sourceProfileId)
            : widget.title;
        items.add(
          ForwardDraftItem.attachment(
            authorName: author,
            mime: payload.mime ?? 'application/octet-stream',
            attachmentEvent: payload,
            // 🔴 Имя обязано пережить пересылку: без него получатель видит
            // безымянный файл с обезличенным типом, то есть `.bin`.
            filename: payload.filename,
            sourceProfileId: sourceProfileId,
            sourceConvoId: widget.convoId,
          ),
        );
        // 🔴 ЗАМЕР ПЕРЕСЫЛКИ (14.08.2026). Первый замер показал, что при жалобе
        // «всё равно .bin» путь выгрузки не вызывался НИ РАЗУ — значит файл
        // уходит другой дорогой. Без отметки здесь мы снова будем гадать.
        DiagLog.event('media', 'forward_draft_item', <String, Object?>{
          'has_filename': (payload.filename ?? '').trim().isNotEmpty,
          'mime': (payload.mime ?? '').trim(),
          'blob': payload.blobId.length > 8
              ? payload.blobId.substring(0, 8)
              : payload.blobId,
        });
        continue;
      }
      if (payload is StickerEventV1) {
        final sticker = SecretlyStickerCatalog.resolveEvent(payload);
        final author = widget.controller.isOwnDeviceId(event.senderDeviceId)
            ? selfAuthorLabel
            : sourceProfileId != null && sourceProfileId.isNotEmpty
            ? await widget.controller.resolveConvoTitle(sourceProfileId)
            : widget.title;
        items.add(
          ForwardDraftItem.sticker(
            authorName: author,
            sticker: sticker,
            sourceProfileId: sourceProfileId,
            sourceConvoId: widget.convoId,
          ),
        );
      }
    }
    if (items.isEmpty) {
      _showChatMessage(
        blockedCount > 0 ? privacySkippedText : noForwardMessagesText,
      );
      return;
    }

    final draft = ForwardDraft(items: items);
    widget.controller.setForwardDraft(draft);
    if (!mounted) return;
    // Leave selection mode and open the full-screen «Переслать…» chat picker.
    if (_selectionMode) {
      setState(() => _selectedEventIds.clear());
    }

    if (blockedCount > 0) {
      _showChatMessage(
        chatText(
          context,
          ru: 'Часть сообщений пропущена из-за ограничений приватности.',
          en: 'Some messages were skipped because of privacy restrictions.',
        ),
      );
    }

    final target = await Navigator.of(context).push<Conversation>(
      SecretlyPageRoute(
        builder: (_) =>
            ForwardTargetPickerScreen(controller: widget.controller),
      ),
    );
    if (target == null || !mounted) return;

    // Open the chosen conversation with the forward draft pre-loaded, where the
    // user can add a caption and confirm the send.
    final isGroupTarget = target.convoId.startsWith('group:');
    final destination = isGroupTarget
        ? ChatScreen(
            controller: widget.controller,
            convoId: target.convoId,
            title: target.title,
            initialForwardDraft: draft,
          )
        : ChatScreen(
            controller: widget.controller,
            convoId: target.peerProfileId ?? target.convoId,
            title: target.title,
            peerProfileIdForSend: target.peerProfileId ?? target.convoId,
            initialForwardDraft: draft,
          );
    await Navigator.of(
      context,
    ).push(SecretlyPageRoute(builder: (_) => destination));
  }

  Future<void> _deleteEventsWithConfirm(List<ChatEvent> events) async {
    if (events.isEmpty || !mounted) return;

    final localEventIds = events
        .map((event) => event.eventId.trim())
        .where((eventId) => eventId.isNotEmpty)
        .toSet()
        .toList(growable: false);
    if (localEventIds.isEmpty) return;

    final peer = widget.peerProfileIdForSend;
    final deleteForAllPayloadIds = events
        .where((event) => widget.controller.isOwnDeviceId(event.senderDeviceId))
        .map((event) => (event.payloadEventId ?? '').trim())
        .where((payloadEventId) => payloadEventId.isNotEmpty)
        .toSet()
        .toList(growable: false);
    final canDeleteForAll =
        deleteForAllPayloadIds.isNotEmpty &&
        ((_isGroupChat && _roomCanSendTextNow()) ||
            (peer != null && peer.isNotEmpty));
    var deleteForAll = canDeleteForAll;

    final ok = await showDialog<bool>(
      context: context,
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setState) {
            return AlertDialog(
              title: Text(
                localEventIds.length == 1
                    ? chatText(
                        context,
                        ru: 'Удалить сообщение?',
                        en: 'Delete message?',
                      )
                    : chatText(
                        context,
                        ru: 'Удалить сообщения?',
                        en: 'Delete messages?',
                      ),
              ),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    canDeleteForAll
                        ? chatText(
                            context,
                            ru: 'Выберите, удалить сообщения только на этом устройстве или у всех участников.',
                            en: 'Choose whether to delete the messages only on this device or for everyone.',
                          )
                        : chatText(
                            context,
                            ru: 'Сообщения будут удалены только на этом устройстве.',
                            en: 'Messages will be deleted only on this device.',
                          ),
                  ),
                  if (canDeleteForAll) ...[
                    const SizedBox(height: 12),
                    CheckboxListTile(
                      value: deleteForAll,
                      onChanged: (value) =>
                          setState(() => deleteForAll = value == true),
                      controlAffinity: ListTileControlAffinity.leading,
                      contentPadding: EdgeInsets.zero,
                      title: Text(
                        chatText(
                          context,
                          ru: 'Удалить у всех?',
                          en: 'Delete for everyone?',
                          uk: 'Видалити для всіх?',
                          es: '¿Eliminar para todos?',
                          pt: 'Excluir para todos?',
                          fr: 'Supprimer pour tout le monde?',
                          de: 'Für alle löschen?',
                        ),
                      ),
                    ),
                  ],
                ],
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(context).pop(false),
                  child: Text(
                    chatText(
                      context,
                      ru: 'Отмена',
                      en: 'Cancel',
                      uk: 'Скасувати',
                      es: 'Cancelar',
                      pt: 'Cancelar',
                      fr: 'Annuler',
                      de: 'Abbrechen',
                    ),
                  ),
                ),
                TextButton(
                  style: TextButton.styleFrom(foregroundColor: Colors.red),
                  onPressed: () => Navigator.of(context).pop(true),
                  child: Text(
                    chatText(
                      context,
                      ru: 'Удалить',
                      en: 'Delete',
                      uk: 'Видалити',
                      es: 'Eliminar',
                      pt: 'Excluir',
                      fr: 'Supprimer',
                      de: 'Löschen',
                    ),
                  ),
                ),
              ],
            );
          },
        );
      },
    );
    if (ok != true) return;

    await widget.controller.deleteEventsLocal(
      convoId: widget.convoId,
      eventIds: localEventIds,
    );

    // The delete-for-all broadcast is BEST-EFFORT: the local delete already
    // succeeded, so a transient send failure (slow link, session hiccup) must
    // NOT throw out of here — that used to abort the caller before it cleared
    // the selection, leaving the selection toolbar stuck even though the
    // messages were gone.
    if (deleteForAll) {
      try {
        if (_isGroupChat) {
          await widget.controller.sendGroupMessage(
            groupId: widget.convoId,
            text: _buildDeleteForAllCommand(deleteForAllPayloadIds),
          );
        } else if (peer != null && peer.isNotEmpty) {
          await widget.controller.sendMessage(
            peerProfileId: peer,
            text: _buildDeleteForAllCommand(deleteForAllPayloadIds),
          );
        }
      } catch (_) {
        // Local delete stands; the peer re-syncs the removal on its next fetch.
      }
    }
  }

  Future<void> _showMessageActions({
    required _TimelineEntry entry,
    required List<MessageReaction> reactions,
    Offset? anchorGlobalPosition,
  }) async {
    if (_selectionMode) return;
    // Drop composer focus BEFORE opening the action menu. The menu is a route;
    // on dismiss Flutter would otherwise RESTORE focus to the composer and pop
    // the keyboard back up even though the user only tapped a bubble. Reply
    // re-focuses intentionally (see the reply handler).
    FocusManager.instance.primaryFocus?.unfocus();

    final selfProfileId = widget.controller.profileId;
    final selfReaction = reactions
        .where((r) => r.profileId == selfProfileId)
        .map((r) => r.emoji)
        .where((e) => e.isNotEmpty)
        .cast<String?>()
        .firstOrNull;

    var canPinMessages = true;
    var isPinnedEntry = false;
    var reactionOptions = _quickReactions;
    final entryEventId = _entryIdForPin(entry);
    if (_isGroupChat) {
      // Use the room policy ALREADY loaded for this chat (on open) so the menu
      // opens INSTANTLY — no DB round-trip between the tap and the popup, which
      // was the source of the lag. A null policy (not loaded yet) fails open to
      // the default quick reactions; the next open reflects the real policy.
      final policy = _roomPolicyState;
      canPinMessages = policy?.canPinMessages ?? true;
      isPinnedEntry = _isPinnedEventId(entryEventId);
      reactionOptions = (policy == null || policy.canReact)
          ? _quickReactions
                .where(
                  (emoji) => policy == null || policy.isReactionAllowed(emoji),
                )
                .toList(growable: false)
          : const <String>[];
    } else {
      isPinnedEntry = _isPinnedEventId(entryEventId);
    }
    // Telegram-style bar: show at most the first 7 quick reactions; the 8th slot
    // is always the trailing "expand" (⌄) button that opens the full picker.
    if (reactionOptions.length > 7) {
      reactionOptions = reactionOptions.take(7).toList(growable: false);
    }
    if (!mounted) return;

    // Premium reaction gate (TZ-MONETIZE-01 §C-3) resolved up-front so the ⌄
    // chip can either expand the picker in place (unlocked / fail-open) or fall
    // back to the centralized paywall path. Fail-open: when monetization is
    // disabled this is always true and the gate is inert.
    final reactionsUnlocked = FeatureGate.isUnlocked(
      widget.controller.entitlementStateNow,
      GatedFeature.premiumStickers,
    );

    final media = MediaQuery.of(context);
    final screenSize = media.size;
    // The reaction STRIP stays wide: it must fit 7 reaction chips + the expand
    // (⌄) chip (8 × 34px + gaps + padding ≈ 300); capped to the screen so the
    // chevron is never clipped and the left-clamp below can't invert on narrow
    // phones. The FUNCTIONS menu below keeps its own fixed (narrower) width.
    final panelWidth = (screenSize.width - 16.0).clamp(0.0, 316.0).toDouble();
    const actionsWidth = 252.0;
    const reactionsHeight = 52.0;
    const panelGap = 6.0;
    final showReactionStrip = reactionOptions.isNotEmpty;
    final showWhoRead = _isGroupChat && entry.payloadEventId != null;
    final actionCount =
        (canPinMessages ? 5 : 4) + (showWhoRead ? 1 : 0);
    final actionsHeight = (actionCount * 46.0) + 12.0;
    final totalPanelHeight =
        (showReactionStrip ? (reactionsHeight + panelGap) : 0.0) +
        actionsHeight;
    final anchor =
        anchorGlobalPosition ??
        Offset(screenSize.width / 2, screenSize.height / 2);

    var panelLeft = anchor.dx - (panelWidth / 2);
    panelLeft = panelLeft.clamp(8.0, screenSize.width - panelWidth - 8.0);

    final minTop = media.padding.top + 8;

    // --- Collapsed geometry (strip + functions menu) -----------------------
    var panelTop = anchor.dy - totalPanelHeight - 10;
    final maxTop =
        screenSize.height - media.padding.bottom - totalPanelHeight - 8;
    if (panelTop < minTop) {
      panelTop = anchor.dy + 10;
    }
    panelTop = panelTop.clamp(minTop, maxTop);

    // --- Expanded geometry (strip + inline emoji picker) -------------------
    // When the user taps ⌄ the functions menu is replaced by the full emoji
    // picker, which is tall. Pre-compute a top/height that keeps the strip +
    // picker fully on-screen (picker height bounded to the free space, and the
    // strip pinned just under the top safe-area when it would otherwise clip).
    final expandedBottomLimit = screenSize.height - media.padding.bottom - 8;
    final expandedAvail =
        expandedBottomLimit - minTop - reactionsHeight - panelGap;
    // Desired picker height, then bounded to the free vertical space (with a
    // small floor so the clamp bounds can never invert on tiny screens).
    final pickerCap = expandedAvail < 160.0 ? 160.0 : expandedAvail;
    final pickerHeight = (screenSize.height * 0.55)
        .clamp(280.0, 560.0)
        .toDouble()
        .clamp(160.0, pickerCap)
        .toDouble();
    final expandedTotalHeight = reactionsHeight + panelGap + pickerHeight;
    var expandedTop = anchor.dy - expandedTotalHeight - 10;
    final expandedMaxTop = expandedBottomLimit - expandedTotalHeight;
    if (expandedTop < minTop) {
      // Prefer opening below the anchor; otherwise pin to the top safe-area.
      final belowTop = anchor.dy + 10;
      expandedTop = belowTop <= expandedMaxTop ? belowTop : minTop;
    }
    expandedTop = expandedTop.clamp(
      minTop,
      expandedMaxTop < minTop ? minTop : expandedMaxTop,
    );

    // --- Who-read expanded geometry (functions menu + inline reader list) --
    // Bounded to a fixed cap — long reader lists scroll internally instead of
    // growing the popup further — so this reposition is deterministic
    // regardless of how many people have read the message.
    final whoReadTotalHeight = totalPanelHeight + _whoReadListMaxHeight;
    var whoReadTop = anchor.dy - whoReadTotalHeight - 10;
    final whoReadMaxTop = expandedBottomLimit - whoReadTotalHeight;
    if (whoReadTop < minTop) {
      final belowTop = anchor.dy + 10;
      whoReadTop = belowTop <= whoReadMaxTop ? belowTop : minTop;
    }
    whoReadTop = whoReadTop.clamp(
      minTop,
      whoReadMaxTop < minTop ? minTop : whoReadMaxTop,
    );

    // Grow the popup out of the tapped bubble: convert the global tap point to
    // screen-normalized Alignment (-1..1) for the scale origin.
    final scaleAlignment = anchorGlobalPosition != null
        ? Alignment(
            ((anchorGlobalPosition.dx / screenSize.width) * 2 - 1).clamp(
              -1.0,
              1.0,
            ),
            ((anchorGlobalPosition.dy / screenSize.height) * 2 - 1).clamp(
              -1.0,
              1.0,
            ),
          )
        : Alignment.center;
    final selected = await showReactionDialog<String>(
      context: context,
      scaleAlignment: scaleAlignment,
      builder: (context) {
        final cs = Theme.of(context).colorScheme;
        // In-place expand: tapping ⌄ flips this flag, swapping the functions
        // menu for the emoji picker and re-positioning the panel — all in the
        // same popup (StatefulBuilder), no separate sheet.
        var expanded = false;
        // Inline "who read" expand: tapping the row (now LAST in the list)
        // grows the SAME popup downward to show readers — no separate sheet.
        // Re-tapping collapses it; long lists scroll within a capped height
        // instead of growing the popup further (see _whoReadListMaxHeight).
        var whoReadExpanded = false;
        var whoReadLoading = false;
        var whoReadFetched = false;
        var whoReadReaders = const <({String profileId, int readAtMs})>[];
        var whoReadMembers = const <String, RoomMember>{};
        return StatefulBuilder(
          builder: (context, setPopupState) {
            Widget glassCard({required Widget child, double alpha = 0.8}) {
              return ClipRRect(
                borderRadius: BorderRadius.circular(16),
                child: BackdropFilter(
                  filter: ImageFilter.blur(sigmaX: 18, sigmaY: 18),
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      color: cs.surface.withValues(alpha: alpha),
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(
                        color: cs.outlineVariant.withValues(alpha: 0.34),
                      ),
                    ),
                    child: child,
                  ),
                ),
              );
            }

            final functionsMenu = SizedBox(
              width: actionsWidth,
              child: glassCard(
                child: Material(
                  type: MaterialType.transparency,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      _menuActionItem(
                        context,
                        icon: AppIcons.reply,
                        label: context.l10n.chatMenuReply,
                        value: 'reply',
                      ),
                      if (entry.isMe &&
                          entry.event.localState ==
                              MessageLocalState.scheduled)
                        _menuActionItem(
                          context,
                          icon: Icons.send_rounded,
                          label: chatText(
                            context,
                            ru: 'Отправить сейчас',
                            en: 'Send now',
                          ),
                          value: 'send_now',
                        ),
                      if (entry.isMe &&
                          entry.payloadEventId != null &&
                          entry.attachment == null &&
                          entry.stickerEvent == null &&
                          entry.callEvent == null &&
                          entry.systemEvent == null)
                        _menuActionItem(
                          context,
                          icon: AppIcons.edit,
                          label: context.l10n.edit,
                          value: 'edit',
                        ),
                      _menuActionItem(
                        context,
                        icon: AppIcons.copy,
                        label: context.l10n.chatMenuCopy,
                        value: 'copy',
                      ),
                      _menuActionItem(
                        context,
                        icon: AppIcons.forward,
                        label: context.l10n.chatMenuForward,
                        value: 'forward',
                      ),
                      if (canPinMessages)
                        _menuActionItem(
                          context,
                          icon: AppIcons.pin,
                          label: isPinnedEntry
                              ? context.l10n.unpin
                              : context.l10n.chatMenuPin,
                          value: 'pin',
                        ),
                      _menuActionItem(
                        context,
                        icon: AppIcons.delete,
                        label: context.l10n.chatMenuDelete,
                        value: 'delete',
                      ),
                      if (showWhoRead)
                        _menuActionItem(
                          context,
                          icon: Icons.visibility_outlined,
                          label: chatText(
                            context,
                            ru: 'Кто прочитал',
                            en: 'Who read',
                          ),
                          trailing: AnimatedRotation(
                            turns: whoReadExpanded ? 0.5 : 0.0,
                            duration: const Duration(milliseconds: 200),
                            child: Icon(
                              Icons.keyboard_arrow_down_rounded,
                              size: 20,
                              color: cs.onSurface.withValues(alpha: 0.55),
                            ),
                          ),
                          onTap: () {
                            if (whoReadExpanded) {
                              setPopupState(() => whoReadExpanded = false);
                              return;
                            }
                            setPopupState(() => whoReadExpanded = true);
                            if (whoReadFetched) return;
                            unawaited(() async {
                              setPopupState(() => whoReadLoading = true);
                              final payloadEventId =
                                  timelineRowId(entry.payloadEventId, entry.event.eventId)
                                      .trim();
                              final fetchedReaders = await widget.controller
                                  .roomMessageReaders(payloadEventId);
                              if (!context.mounted) return;
                              var memberMap = const <String, RoomMember>{};
                              if (fetchedReaders.isNotEmpty) {
                                final members = await widget.controller
                                    .listRoomMembersDetailed(widget.convoId);
                                if (!context.mounted) return;
                                memberMap = {
                                  for (final m in members) m.profileId: m,
                                };
                              }
                              setPopupState(() {
                                whoReadReaders = fetchedReaders;
                                whoReadMembers = memberMap;
                                whoReadLoading = false;
                                whoReadFetched = true;
                              });
                            }());
                          },
                        ),
                      if (showWhoRead)
                        AnimatedSize(
                          duration: const Duration(milliseconds: 200),
                          curve: Curves.easeOutCubic,
                          alignment: Alignment.topCenter,
                          child: !whoReadExpanded
                              ? const SizedBox(width: double.infinity)
                              : _whoReadInlinePanel(
                                  context,
                                  loading: whoReadLoading,
                                  readers: whoReadReaders,
                                  members: whoReadMembers,
                                  onTapReader: (reader, member, name) {
                                    Navigator.of(context).pop();
                                    _openPeerDetails(
                                      profileId: reader.profileId,
                                      avatarPath: member?.avatarPath,
                                      initialTitle: name,
                                      // Reader is a room member — open THEIR
                                      // profile + 1:1, not the room.
                                      convoId: reader.profileId,
                                      openChatByPush: true,
                                    );
                                  },
                                ),
                        ),
                    ],
                  ),
                ),
              ),
            );

            final emojiPicker = SizedBox(
              width: panelWidth,
              height: pickerHeight,
              child: glassCard(
                child: _ReactionEmojiPicker(
                  categories: _emojiPickerCategories(context),
                  bottomInset: 16,
                  onPick: (chosen) =>
                      Navigator.of(context).pop('react:$chosen'),
                ),
              ),
            );

            return Material(
              type: MaterialType.transparency,
              child: Stack(
                children: [
                  Positioned.fill(
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: () => Navigator.of(context).pop(),
                    ),
                  ),
                  AnimatedPositioned(
                    duration: const Duration(milliseconds: 240),
                    curve: Curves.easeOutCubic,
                    left: panelLeft,
                    top: expanded
                        ? expandedTop
                        : (whoReadExpanded ? whoReadTop : panelTop),
                    width: panelWidth,
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (showReactionStrip) ...[
                          glassCard(
                            alpha: 0.76,
                            child: Padding(
                              padding: const EdgeInsets.fromLTRB(8, 6, 8, 6),
                              child: Row(
                                mainAxisAlignment:
                                    MainAxisAlignment.spaceBetween,
                                children: [
                                  for (final e in reactionOptions)
                                    GestureDetector(
                                      onTap: () =>
                                          Navigator.of(context).pop('react:$e'),
                                      child: Container(
                                        width: 34,
                                        height: 34,
                                        alignment: Alignment.center,
                                        decoration: BoxDecoration(
                                          shape: BoxShape.circle,
                                          color: selfReaction == e
                                              ? cs.primaryContainer.withValues(
                                                  alpha: 0.82,
                                                )
                                              : Colors.transparent,
                                        ),
                                        child: _NotoEmojiLottie(
                                          emoji: e,
                                          size: 29,
                                          // Bundled cookie Lottie while the Noto
                                          // CDN file loads — never tofu (□).
                                          assetFallback:
                                              _reactionAssetByEmoji[e],
                                        ),
                                      ),
                                    ),
                                  GestureDetector(
                                    onTap: () {
                                      // Premium gate (TZ §C-3, fail-open): when
                                      // monetization is off the state resolves
                                      // open and we expand inline for everyone.
                                      // Only free + monetization-on falls back
                                      // to the centralized 'react_more' →
                                      // paywall path below.
                                      if (reactionsUnlocked) {
                                        setPopupState(() => expanded = true);
                                      } else {
                                        Navigator.of(context).pop('react_more');
                                      }
                                    },
                                    child: Container(
                                      width: 34,
                                      height: 34,
                                      alignment: Alignment.center,
                                      decoration: BoxDecoration(
                                        shape: BoxShape.circle,
                                        color: cs.onSurface.withValues(
                                          alpha: 0.06,
                                        ),
                                      ),
                                      child: AnimatedRotation(
                                        turns: expanded ? 0.5 : 0.0,
                                        duration: const Duration(
                                          milliseconds: 240,
                                        ),
                                        child: Icon(
                                          Icons.keyboard_arrow_down_rounded,
                                          size: 22,
                                          color: cs.onSurface.withValues(
                                            alpha: 0.82,
                                          ),
                                        ),
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                          const SizedBox(height: panelGap),
                        ],
                        AnimatedSize(
                          duration: const Duration(milliseconds: 240),
                          curve: Curves.easeOutCubic,
                          alignment: Alignment.topCenter,
                          child: AnimatedSwitcher(
                            duration: const Duration(milliseconds: 200),
                            transitionBuilder: (child, anim) =>
                                FadeTransition(opacity: anim, child: child),
                            child: expanded
                                ? KeyedSubtree(
                                    key: const ValueKey('reaction_picker'),
                                    child: emojiPicker,
                                  )
                                : KeyedSubtree(
                                    key: const ValueKey('reaction_actions'),
                                    child: functionsMenu,
                                  ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );

    if (selected == null || !mounted) return;

    if (selected == 'react_more') {
      await _handleMoreReactions(entry);
      return;
    }

    if (selected.startsWith('react:')) {
      final emoji = selected.substring('react:'.length);
      if (emoji.isNotEmpty) {
        await _applyReaction(
          eventId: entry.payloadEventId ?? entry.event.eventId,
          emoji: emoji,
        );
      }
      return;
    }

    switch (selected) {
      case 'reply':
        _startReply(
          payloadEventId: entry.payloadEventId,
          previewText: entry.previewText,
          authorName: entry.isMe ? _selfAuthorLabel() : widget.title,
          authorIsMe: entry.isMe,
        );
        return;
      case 'copy':
        await _copyEventsToClipboard([entry.event]);
        return;
      case 'edit':
        await _startEdit(entry);
        return;
      case 'forward':
        await _forwardEvents(_eventsForTimelineEntry(entry).toList());
        return;
      case 'pin':
        await _pinTimelineEntry(entry);
        return;
      case 'delete':
        await _deleteEventsWithConfirm(_eventsForTimelineEntry(entry).toList());
        return;
      case 'send_now':
        await widget.controller.sendScheduledMessageNow(
          convoId: widget.convoId,
          eventId: entry.event.eventId,
        );
        return;
    }
  }

  Future<({bool canPinMessages, bool isPinnedEntry})> _resolvePinStateForEntry(
    _TimelineEntry entry,
  ) async {
    var canPinMessages = true;
    var isPinnedEntry = false;
    final entryEventId = _entryIdForPin(entry);
    if (_isGroupChat) {
      // Kick both DB reads concurrently so the menu isn't serialized behind two
      // sequential round-trips before it can open.
      final policyF = widget.controller.getRoomPolicyState(widget.convoId);
      final settingsF = widget.controller.getRoomSettings(widget.convoId);
      final policy = await policyF;
      final settings = await settingsF;
      final pinnedEventId = (settings.pinnedMessageEventId ?? '').trim();
      canPinMessages = policy.canPinMessages;
      isPinnedEntry =
          (pinnedEventId.isNotEmpty && pinnedEventId == entryEventId) ||
          _isPinnedEventId(entryEventId);
    } else {
      isPinnedEntry = _isPinnedEventId(entryEventId);
    }
    return (canPinMessages: canPinMessages, isPinnedEntry: isPinnedEntry);
  }

