  /// [merged] = this strip is a ROW inside a shared glass group (see
  /// [_buildHeaderIslandGroup]), so it must not carry its own blur/highlight/
  /// shadow/rounding — the group owns all of that. Otherwise the seams between
  /// glued strips would show two stacked edges and a specular line.
  Widget _buildPinnedMessageBanner(
    _PinnedMessage pinnedMessage, {
    bool merged = false,
  }) {
    final l10n = context.l10n;
    // If the pinned message is a `scheduled` ("send later") placeholder, mark it
    // with the same minimalist time+date badge used in the bubble.
    final pinnedEntry = _timelineEntryForEventId(pinnedMessage.eventId);
    final pinnedScheduledAtMs =
        pinnedEntry?.event.localState == MessageLocalState.scheduled
            ? pinnedEntry?.event.scheduledAtMs
            : null;
    final canUnpin =
        !_isGroupChat || (_roomPolicyState?.canPinMessages ?? false);
    final canShowAll = _effectivePinnedMessages().length > 1;
    const radius = _kChatIslandRadius;
    final br = BorderRadius.circular(radius);
    // Same glass island as the chat header / main islands (dense light fill +
    // specular highlight + outer shadow in light theme), instead of a separate
    // fainter plate. The height is PINNED to the shared island height: it used
    // to be content-driven, so it rendered shorter than the fixed-height music
    // island next to it and left slack inside the AppBar's reserved slot.
    final content = Material(
      color: Colors.transparent,
      child: InkWell(
        // Merged rows must not round their own ink: the group clips the outer
        // corners and the inner seams are square.
        borderRadius: merged ? null : br,
        onTap: () => unawaited(_handlePinnedMessageTap(pinnedMessage)),
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 8, 8, 8),
          child: Row(
              children: [
                Icon(
                  AppIcons.pin,
                  size: 18,
                  color: Theme.of(context).colorScheme.primary,
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    pinnedMessage.previewText,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: Theme.of(context).textTheme.bodyMedium,
                  ),
                ),
                if (pinnedScheduledAtMs != null && pinnedScheduledAtMs > 0) ...[
                  const SizedBox(width: 8),
                  _ScheduledTimeBadge(
                    scheduledAtMs: pinnedScheduledAtMs,
                    color: Theme.of(context).colorScheme.onSurfaceVariant,
                  ),
                ],
                if (canShowAll)
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    constraints: const BoxConstraints.tightFor(
                      width: 30,
                      height: 30,
                    ),
                    padding: EdgeInsets.zero,
                    tooltip: chatText(
                      context,
                      ru: 'Показать все',
                      en: 'Show all',
                    ),
                    onPressed: () => unawaited(_showPinnedMessagesSheet()),
                    icon: const Icon(AppIcons.menu, size: 18),
                  ),
                if (canUnpin)
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    constraints: const BoxConstraints.tightFor(
                      width: 30,
                      height: 30,
                    ),
                    padding: EdgeInsets.zero,
                    tooltip: l10n.unpin,
                    onPressed: () =>
                        unawaited(_clearPinnedMessage(pinnedMessage)),
                    icon: const Icon(AppIcons.close, size: 17),
                  ),
              ],
            ),
          ),
        ),
      );
    if (merged) return content;
    return _frostedHeaderIsland(
      radius: radius,
      height: _kChatIslandHeight,
      child: content,
    );
  }

  Widget _buildRoomCallReturnBanner(CachedRoomCall call) {
    final sp = call.selfParticipant;
    return RuntimeAwareRoomCallReturnBanner(
      // Same side margins + bottom gap as every other island in the stack.
      margin: _kChatIslandMargin,
      title: widget.title,
      call: call,
      onMicTap: sp != null && sp.isJoined
          ? () => unawaited(
              widget.controller.updateRelayRoomCallParticipant(
                roomId: call.roomId,
                callId: call.callId,
                reconnecting: sp.isReconnecting,
                muted: !sp.muted,
                deafened: sp.deafened,
                videoEnabled: sp.videoEnabled,
                screenShareEnabled: sp.screenShareEnabled,
                speaking: sp.speaking,
              ),
            )
          : null,
      onTap: _openRoomCallScreen,
    );
  }

  bool _shouldShowOutgoingSendStateMenu(_TimelineEntry entry) {
    if (!entry.isMe) return false;
    return MessageLocalState.isOutgoingActionable(entry.event.localState);
  }

  Future<void> _handleEventTapAction({
    required _TimelineEntry entry,
    required List<MessageReaction> reactions,
    Offset? tapPosition,
  }) async {
    if (_shouldShowOutgoingSendStateMenu(entry)) {
      await _showOutgoingSendStateActions(
        entry: entry,
        anchorGlobalPosition: tapPosition,
      );
      return;
    }
    await _showMessageActions(
      entry: entry,
      reactions: reactions,
      anchorGlobalPosition: tapPosition,
    );
  }

  Future<void> _showOutgoingSendStateActions({
    required _TimelineEntry entry,
    Offset? anchorGlobalPosition,
  }) async {
    final media = MediaQuery.of(context);
    final anchor =
        anchorGlobalPosition ??
        Offset(media.size.width / 2, media.size.height / 2);
    final l10n = context.l10n;

    final selected = await showMenu<String>(
      context: context,
      position: RelativeRect.fromLTRB(
        anchor.dx,
        anchor.dy,
        media.size.width - anchor.dx,
        media.size.height - anchor.dy,
      ),
      items: [
        PopupMenuItem<String>(
          value: 'cancel',
          child: Row(
            children: [
              const Icon(AppIcons.close, size: 18),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  chatText(
                    context,
                    ru: 'Отменить отправку',
                    en: 'Cancel sending',
                    uk: 'Скасувати відправку',
                    es: 'Cancelar envío',
                    pt: 'Cancelar envio',
                    fr: 'Annuler l\'envoi',
                    de: 'Senden abbrechen',
                  ),
                ),
              ),
            ],
          ),
        ),
        PopupMenuItem<String>(
          value: 'retry',
          child: Row(
            children: [
              const Icon(AppIcons.refresh, size: 18),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  chatText(
                    context,
                    ru: 'Повторить отправку',
                    en: 'Retry sending',
                    uk: 'Повторити відправку',
                    es: 'Reintentar envío',
                    pt: 'Tentar enviar novamente',
                    fr: 'Réessayer l\'envoi',
                    de: 'Erneut senden',
                  ),
                ),
              ),
            ],
          ),
        ),
        PopupMenuItem<String>(
          value: 'copy',
          child: Row(
            children: [
              const Icon(AppIcons.copy, size: 18),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  chatText(
                    context,
                    ru: 'Копировать SMS',
                    en: 'Copy SMS',
                    uk: 'Копіювати SMS',
                    es: 'Copiar SMS',
                    pt: 'Copiar SMS',
                    fr: 'Copier SMS',
                    de: 'SMS kopieren',
                  ),
                ),
              ),
            ],
          ),
        ),
      ],
    );

    if (selected == null || !mounted) return;

    try {
      switch (selected) {
        case 'cancel':
          await widget.controller.cancelOutgoingEventSend(
            localEventId: entry.event.eventId,
          );
          return;
        case 'retry':
          await widget.controller.retryOutgoingEventSend(
            localEventId: entry.event.eventId,
          );
          return;
        case 'copy':
          await _copyEventsToClipboard([entry.event]);
          return;
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(l10n.sendFailed(e.toString()))),
      );
    }
  }

  Widget _menuActionItem(
    BuildContext context, {
    required IconData icon,
    required String label,
    String? value,
    VoidCallback? onTap,
    Widget? trailing,
  }) {
    return ListTile(
      dense: true,
