  // Fixed cap for the inline "who read" reader list (see _showMessageActions'
  // who-read expand geometry) — long lists scroll internally instead of
  // growing the popup further, so the reserved space stays deterministic.
  static const double _whoReadListMaxHeight = 224.0;

  /// Inline content shown below the (now last) "Кто прочитал" row when
  /// expanded — same popup, no separate sheet. Capped height + internal
  /// scroll for long reader lists.
  Widget _whoReadInlinePanel(
    BuildContext context, {
    required bool loading,
    required List<({String profileId, int readAtMs})> readers,
    required Map<String, RoomMember> members,
    required void Function(
      ({String profileId, int readAtMs}) reader,
      RoomMember? member,
      String name,
    )
    onTapReader,
  }) {
    if (loading) {
      return const Padding(
        padding: EdgeInsets.symmetric(vertical: 18),
        child: Center(
          child: SizedBox(
            width: 18,
            height: 18,
            child: CircularProgressIndicator(strokeWidth: 2),
          ),
        ),
      );
    }
    if (readers.isEmpty) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(16, 4, 16, 14),
        child: Text(
          chatText(
            context,
            ru: 'Пока никто не прочитал',
            en: 'No one has read this yet',
          ),
          style: Theme.of(context).textTheme.bodySmall?.copyWith(
            color: Theme.of(context).colorScheme.onSurfaceVariant,
          ),
        ),
      );
    }
    return ConstrainedBox(
      constraints: const BoxConstraints(maxHeight: _whoReadListMaxHeight),
      child: Scrollbar(
        child: ListView.separated(
          shrinkWrap: true,
          padding: EdgeInsets.zero,
          itemCount: readers.length,
          separatorBuilder: (_, __) => const Divider(height: 1, indent: 52),
          itemBuilder: (context, i) {
            final reader = readers[i];
            final member = members[reader.profileId];
            final name = (member?.displayName.trim().isNotEmpty ?? false)
                ? member!.displayName.trim()
                : reader.profileId;
            return ListTile(
              dense: true,
              visualDensity: const VisualDensity(vertical: -2),
              leading: _RoomMemberMessageAvatar(
                title: name,
                avatarPath: member?.avatarPath,
                seed: reader.profileId,
              ),
              title: Text(
                name,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontSize: 14),
              ),
              trailing: Text(
                _formatTime(reader.readAtMs),
                style: Theme.of(context).textTheme.bodySmall,
              ),
              onTap: () => onTapReader(reader, member, name),
            );
          },
        ),
      ),
    );
  }

  Future<void> _applyReaction({
    required String eventId,
    required String emoji,
  }) async {
    final selfProfileId = widget.controller.profileId;
    if (selfProfileId.isEmpty || emoji.trim().isEmpty) return;

    try {
      final before = await widget.controller.loadMessageReactions(
        eventIds: [eventId],
      );
      final beforeMine = (before[eventId] ?? const <MessageReaction>[])
          .where((r) => r.profileId == selfProfileId)
          .map((r) => r.emoji)
          .where((e) => e.isNotEmpty)
          .cast<String?>()
          .firstOrNull;

      await widget.controller.toggleMessageReaction(
        convoId: widget.convoId,
        eventId: eventId,
        emoji: emoji,
      );

      final after = await widget.controller.loadMessageReactions(
        eventIds: [eventId],
      );
      final afterMine = (after[eventId] ?? const <MessageReaction>[])
          .where((r) => r.profileId == selfProfileId)
          .map((r) => r.emoji)
          .where((e) => e.isNotEmpty)
          .cast<String?>()
          .firstOrNull;
      final removed = beforeMine == emoji && afterMine != emoji;

      if (!removed && afterMine == emoji && mounted) {
        final selfReaction = (after[eventId] ?? const <MessageReaction>[])
            .where(
              (reaction) =>
                  reaction.profileId == selfProfileId &&
                  reaction.emoji == emoji,
            )
            .cast<MessageReaction?>()
            .firstOrNull;
        final key = '$eventId|$selfProfileId|$emoji';
        if (selfReaction != null) {
          _reactionUpdatedAtByKey[key] = selfReaction.updatedAtMs;
          final seenKey = _reactionSeenAnimationKey(selfReaction);
          _seenReactionAnimationKeys.add(seenKey);
          unawaited(_markReactionAnimationsSeen(<String>{seenKey}));
        }
        setState(() {
          _assignReactionPlayToken(key);
        });
        unawaited(widget.controller.triggerUiHaptic());
      }

      await widget.controller.broadcastReactionUpdate(
        convoId: widget.convoId,
        eventId: eventId,
        emoji: emoji,
        removed: removed,
      );
    } catch (e) {
      if (!mounted) return;
      final l10n = context.l10n;
      final roomPolicyText = tryRoomPolicyErrorText(l10n, e);
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(roomPolicyText ?? l10n.sendFailed(e.toString())),
        ),
      );
    }
  }

  @override
  void dispose() {
    // Persist any unsent composer text so it's restored next time.
    unawaited(_persistDraft());
    widget.controller.clearActiveConversation(widget.convoId);
    // M1: do NOT cancel in-flight uploads on dispose — they now live in the
    // controller and MUST keep running (and stay visible) when the user leaves
    // and re-enters the chat. Cancelling here is exactly what used to make the
    // file "disappear" on re-entry. Cancellation is now explicit (the ✕ button).
    chatRouteObserver.unsubscribe(this);
    unawaited(_pendingUploadsSub?.cancel());
    unawaited(_attachmentUploadErrorSub?.cancel());
    widget.controller.sharedAudioPlayback.removeListener(
      _handleSharedAudioPlaybackChanged,
    );
    _audioTick.dispose();
    widget.controller.chatFocusRequest.removeListener(_onChatFocusRequest);
    _voiceTimer?.cancel();
    _voicePressTimer?.cancel();
    unawaited(_voiceAmpSub?.cancel());
    // Tear down any in-flight video-note recorder (releases the camera).
    _videoNoteRecorderController?.signalCancel();
    _videoNoteRecorderController = null;
    _voiceLockBounceController.dispose();
    _chatSearchRevealController.dispose();
    unawaited(_voiceRecorder.dispose());
    _smileIconController.dispose();
    _voicePulseController.dispose();
    _roomPolicyRefreshTimer?.cancel();
    _retentionTimer?.cancel();
    _retentionTimer = null;
    // Flush any pending read mark immediately when leaving the screen —
    // the 450 ms debounce may not have fired yet if the user closed quickly.
    _markReadDebounce?.cancel();
    _markReadDebounce = null;
    final flushPeer = _markReadPeerProfileId;
    final flushIsRequest =
        widget.requestProfileId != null && widget.requestProfileId!.isNotEmpty;
    // Leave-time flush: the route is already popping so isCurrent is false —
    // mark read iff the chat was GENUINELY viewed at some point
    // (`_wasEverVisiblyOpen`), catching the case where the 450 ms debounce
    // hadn't fired yet. An off-stage transient that was never visibly open
    // stays unmarked.
    if (shouldAutoMarkChatRead(
      appInForeground: widget.controller.appInForeground,
      isChatVisible: _wasEverVisiblyOpen,
      isNearLatestMessages: _isNearLatestMessages(),
      isRequestConvo: flushIsRequest,
      peerProfileId: flushPeer,
    )) {
      unawaited(widget.controller.markChatRead(peerProfileId: flushPeer!));
    }
    _scrollStateDebounce?.cancel();
    unawaited(_persistScrollOffset());
    _typingStopDebounce?.cancel();
    _stopTypingNow();
    _changedSub?.cancel();
    _chatSearchController.dispose();
    _chatSearchFocusNode.dispose();
    _searchDebounce?.cancel();
    unawaited(_searchTickPlayer?.dispose());
    _messageInputFocusNode.dispose();
    _sendButtonFocusNode.dispose();
    _text.removeListener(_onComposerTextChanged);
    _text.dispose();
    _linkPreviewDraft.dispose();
    _highlightTimer?.cancel();
    _scroll.removeListener(_handleScrollChanged);
    _floatingDayHideTimer?.cancel();
    _floatingDay.dispose();
    _showJumpToLatest.dispose();
    _jumpUnreadCount.dispose();
    _pendingUploadsTick.dispose();
    for (final tx in _voiceTx.values) {
      tx.dispose();
    }
    _voiceTx.clear();
    _scroll.dispose();
    _keyboardInsetForGradient.dispose();
    _wallpaperBlur.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final isRequest =
        widget.requestProfileId != null && widget.requestProfileId!.isNotEmpty;
    final peerProfileId = widget.peerProfileIdForSend;
    final l10n = context.l10n;
    // Стекло входящих пузырей: держим размытую мини-текстуру обоев в
    // актуальном состоянии (no-op, если обои/тема/размер не менялись).
    _syncWallpaperBlur(context);
    // 🔴 Заглушка шапки, пока не разрешится настоящее присутствие. Раньше сюда
    // передавался ЖЁСТКИЙ НОЛЬ, и он форматировался в «был(а) 01.01 03:00» —
    // эпоха 1970-го в московском поясе. Теперь неизвестное время передаётся
    // как null и читается как «был(а) недавно».
    final offlineStatusText = chatLastSeenText(
      context,
      timestampMs: null,
      now: DateTime.now(),
    );
    const chatToolbarHeight = 64.0;
    final cs = Theme.of(context).colorScheme;
    final visuals = Theme.of(context).extension<ChatVisualsThemeExtension>();
    final topBarTop = visuals?.topBarTop ?? cs.surface;
    final topBarBottom = visuals?.topBarBottom ?? cs.surfaceContainerHighest;
    final topBarBorder = visuals?.topBarBorder ?? cs.outlineVariant;
    final roomPolicyBannerText = _groupComposerPolicyBannerText(l10n);
    final mentionSuggestions = _visibleRoomMentionCandidates();
    final currentUserCanReceiveAdminMentions =
        _isGroupChat && (_roomPolicyState?.canReceiveAdminMentions ?? false);
    final roomPolicyBannerHeight =
        (!_selectionMode && !isRequest && roomPolicyBannerText != null)
        ? 42.0
        : 0.0;

    // Peer cosmetics (header avatar frame / status emoji) inside the chat obey
    // the user's animation setting; profile pages stay animated.
    return BackdropGroup(
      // Lets the grouped chat-header islands (leading + title) share ONE
      // backdrop read instead of one blur each (2026-07-23 perf audit). The
      // shared backdrop is captured at the first grouped filter — the header —
      // so it sees the chat body behind it exactly as separate filters would.
      child: CosmeticAnimationScope(
        enabled: widget.controller.peerCosmeticAnimEnabled,
        child: BottomSystemFadeVisibility(
      enabled: false,
      child: Scaffold(
        extendBody: true,
        extendBodyBehindAppBar: true,
        resizeToAvoidBottomInset: false,
        appBar: frostedAppBar(
          toolbarHeight: chatToolbarHeight,
          // Experimental chat header: in the normal chat view the bar itself is
          // fully transparent and the back / identity / actions live in separate
          // frosted "islands" (see leading/title/actions below). Selection and
          // request modes keep the classic single frosted bar.
          flexibleSpace: isRequest
              ? ClipRect(
                  child: BackdropFilter(
                    filter: ImageFilter.blur(sigmaX: 16, sigmaY: 16),
                    child: DecoratedBox(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                          colors: [
                            topBarTop.withValues(alpha: 0.74),
                            topBarBottom.withValues(alpha: 0.62),
                          ],
                        ),
                        border: topBarBorder.a <= 0
                            ? null
                            : Border(
                                bottom: BorderSide(
                                  color: topBarBorder.withValues(alpha: 0.28),
                                ),
                              ),
                      ),
                      child: const SizedBox.expand(),
                    ),
                  ),
                )
              : const SizedBox.shrink(),
          // Selection mode now floats glass islands over the wallpaper, exactly
          // like the normal chat header — so it uses the same leading width.
          leadingWidth: isRequest ? null : 60,
          leading: isRequest
              ? null
              // Persistent leading island: the frosted circle never pops in/out
              // — only the icon morphs (back ⇄ close) with a quarter-turn as
              // selection mode toggles, matching the list-screen bubble morph.
              : Align(
                  alignment: Alignment.centerLeft,
                  child: Padding(
                    padding: const EdgeInsets.only(left: 8),
                    child: _frostedHeaderIsland(
                      radius: _kHeaderIslandRadius,
                      grouped: true,
                      child: SizedBox(
                        width: _kHeaderIslandHeight,
                        height: _kHeaderIslandHeight,
                        child: Material(
                          color: Colors.transparent,
                          shape: const CircleBorder(),
                          child: InkResponse(
                            onTap: _selectionMode
                                ? _clearSelection
                                : () => Navigator.of(context).maybePop(),
                            radius: 26,
                            child: Center(
                              child: TweenAnimationBuilder<double>(
                                tween: Tween<double>(
                                  end: _selectionMode ? 1.0 : 0.0,
                                ),
                                duration: const Duration(milliseconds: 280),
                                curve: Curves.easeOutBack,
                                builder: (context, selRaw, _) {
                                  final selO = selRaw.clamp(0.0, 1.0);
                                  return Stack(
                                    alignment: Alignment.center,
                                    children: [
                                      Opacity(
                                        opacity: 1 - selO,
                                        child: Transform.rotate(
                                          angle: selO * 1.5708,
                                          child: const Icon(
                                            AppIcons.arrowBack,
                                            size: 22,
                                          ),
                                        ),
                                      ),
                                      Opacity(
                                        opacity: selO,
                                        child: Transform.rotate(
                                          angle: (1 - selO) * -1.5708,
                                          child: const Icon(
                                            AppIcons.close,
                                            size: 22,
                                          ),
                                        ),
                                      ),
                                    ],
                                  );
                                },
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
          bottom:
              (!_selectionMode &&
                  !isRequest &&
                  (_shouldShowTopicBar ||
                      _resolvedPinnedMessage() != null ||
                      _activeNowPlayingItem != null))
              ? PreferredSize(
                  preferredSize: Size.fromHeight(_headerBottomHeight()),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      // Topic switcher first, then the secondary strips.
                      if (_shouldShowTopicBar) _buildTopicBar(),
                      ..._buildSecondaryIslandStack(),
                      // Search no longer unrolls below the header — it morphs
                      // out of the header island in place (see the title slot).
                    ],
                  ),
                )
              : null,
          titleSpacing: 4,
          // Persistent title island: the frosted frame stays put and only the
          // content cross-fades — identity (avatar + name + status) ⇄ the
          // "selected N" counter ⇄ the in-chat search field — so the bubble
          // reshapes in place instead of popping. The search field morphs OUT of
          // this island (cross-fade here + the right actions island collapses to
          // zero width) exactly like the home Chats screen.
          // AnimatedBuilder scopes the _chatSearchRevealController tick to
          // just this header island instead of the whole chat screen (it
          // used to setState() the entire _ChatScreenState per frame).
          title: AnimatedBuilder(
            animation: _chatSearchRevealController,
            builder: (context, _) => TweenAnimationBuilder<double>(
            tween: Tween<double>(end: _selectionMode ? 1.0 : 0.0),
            duration: const Duration(milliseconds: 280),
            curve: Curves.easeOutBack,
            builder: (context, selRaw, _) {
              final selO = selRaw.clamp(0.0, 1.0);
              // 0 = idle, 1 = search field fully revealed (same curve as
              // chats_screen's `_searchReveal`).
              final s = _chatSearchReveal;
              return _frostedHeaderIsland(
                radius: _kHeaderIslandRadius,
                height: _kHeaderIslandHeight,
                grouped: true,
                // Symmetric avatar inset: left gap == top/bottom gap
                // ((islandHeight - avatarSize) / 2 = (48 - 42) / 2 = 3).
                padding: const EdgeInsets.fromLTRB(3, 0, 12, 0),
                child: Stack(
                  alignment: Alignment.centerLeft,
                  children: [
                    // Identity layer — fades out as selection OR search engages.
                    Opacity(
                      opacity: ((1 - selO) * (1 - s)).clamp(0.0, 1.0),
                      child: IgnorePointer(
                        ignoring: selO > 0.5 || s > 0.5,
                        child: StreamBuilder<void>(
                          stream: widget.controller.changed,
                          builder: (context, _) {
                            return FutureBuilder<Conversation?>(
                              future: _headerConversationFuture(),
                              // Frame ONE paints the avatar the chats list has
                              // already loaded, instead of a hole that fills in
                              // a moment later. See [cachedConversation].
                              initialData: widget.controller.cachedConversation(
                                widget.convoId,
                              ),
                              builder: (context, snapshot) {
                                final conversation = snapshot.data;
                                final avatarPath = conversation?.avatarPath;
                                final baseHeaderTitle = _isFavoritesChat
                                    ? localizedFavoritesTitle(context)
                                    : conversation?.title ?? widget.title;
                                // Peer's premium emoji status (profile_meta) is
                                // shown next to the name so it is visible to the
                                // contact; falls back to the local contact emoji.
                                final headerStatusEmoji =
                                    (conversation?.emojiStatus != null &&
                                        conversation!.emojiStatus!
                                            .trim()
                                            .isNotEmpty)
                                    ? conversation.emojiStatus!.trim()
                                    : ((conversation?.emoji != null &&
                                              conversation!.emoji!
                                                  .trim()
                                                  .isNotEmpty)
                                          ? conversation.emoji!.trim()
                                          : '');
                                // Title text no longer concatenates the emoji —
                                // the status is rendered beside the name as a Noto
                                // asset (animated / tofu-safe) just below.
                                final headerTitle = baseHeaderTitle;
                                final statusText = _isFavoritesChat
                                    ? chatText(
                                        context,
                                        ru: 'Личный блокнот',
                                        en: 'Personal notebook',
                                        uk: 'Особистий блокнот',
                                        es: 'Cuaderno personal',
                                        pt: 'Caderno pessoal',
                                        fr: 'Carnet personnel',
                                        de: 'Persönliches Notizbuch',
                                      )
                                    : offlineStatusText;
                                final isPeerTyping =
                                    !_isFavoritesChat &&
                                    widget.controller.isConversationTyping(
                                      widget.convoId,
                                    );
                                final peerOnlineFuture =
                                    (!_isFavoritesChat && !_isGroupChat)
                                    ? widget.controller
                                          .isConversationPeerOnline(
                                            widget.convoId,
                                          )
                                    : Future<bool>.value(false);
                                final headerProfileId =
                                    peerProfileId ?? widget.requestProfileId;
                                return FutureBuilder<List<Object?>>(
                                  future: Future.wait<Object?>([
                                    peerOnlineFuture,
                                    _isGroupChat
                                        ? widget.controller.getCachedRoomCall(
                                            widget.convoId,
                                          )
                                        : Future<CachedRoomCall?>.value(null),
                                  ]),
                                  builder: (context, onlineSnapshot) {
                                    final isPeerOnline =
                                        (onlineSnapshot.data?[0] as bool?) ??
                                        false;
                                    final activeRoomCall =
                                        onlineSnapshot.data?[1]
                                            as CachedRoomCall?;
                                    // ONE tap target for the WHOLE island —
                                    // avatar, name, status and the empty gaps
                                    // between them all open the profile/room
                                    // page (opaque behavior catches taps on
                                    // the transparent areas too).
                                    return GestureDetector(
                                      behavior: HitTestBehavior.opaque,
                                      onTap: _isGroupChat
                                          ? _openRoomDetails
                                          : (headerProfileId == null ||
                                                    headerProfileId.isEmpty
                                                ? null
                                                : () => _openPeerDetails(
