  Future<File?> _ensureImagePreviewFile(AttachmentEventV1 attachment) async {
    final cached = await widget.controller.cachedAttachmentFile(attachment);
    if (cached != null) return cached;
    if (_imagePreviewFailedBlobIds.contains(attachment.blobId)) return null;
    if (_imagePreviewLoadingBlobIds.contains(attachment.blobId)) return null;

    _imagePreviewLoadingBlobIds.add(attachment.blobId);
    try {
      return await widget.controller.ensureCachedAttachmentFile(attachment);
    } catch (_) {
      _imagePreviewFailedBlobIds.add(attachment.blobId);
      return null;
    } finally {
      _imagePreviewLoadingBlobIds.remove(attachment.blobId);
      if (mounted) {
        setState(() {});
      }
    }
  }

  Future<List<File?>> _loadPreviewImageFiles(
    List<AttachmentEventV1> attachments,
  ) async {
    return Future.wait(
      attachments.map(_ensureImagePreviewFile),
      eagerError: false,
    );
  }

  Widget _wrapSelectableEventItem({
    required ChatEvent event,
    required Widget child,
    required ValueChanged<Offset?> onTapAction,
    required VoidCallback onDoubleTapAction,
    bool ownsTap = false,
  }) {
    final selected = _selectedEventIds.contains(event.eventId);
    return _SelectableEventWrapper(
      selectionMode: _selectionMode,
      selected: selected,
      // When [ownsTap] is set the child handles single-tap itself (e.g. a
      // video note's tap-to-enlarge-with-sound). Outside selection mode we drop
      // the wrapper's own single-tap so it doesn't steal the gesture — but in
      // selection mode we MUST keep a tap handler so tapping toggles selection.
      // Long-press (context menu) and double-tap (❤️) always come through here.
      onTap: (ownsTap && !_selectionMode)
          ? null
          : (tapPosition) {
              if (_selectionMode) {
                _toggleSelection(event.eventId);
                return;
              }
              onTapAction(tapPosition);
            },
      onDoubleTap: () {
        if (_selectionMode) return;
        onDoubleTapAction();
      },
      onLongPress: () {
        if (_selectionMode) {
          _toggleSelection(event.eventId);
        } else {
          _startSelection(event.eventId);
        }
      },
      child: child,
    );
  }

  String _attachmentPreviewLabel(String? mime, {List<int>? waveform}) {
    final m = (mime ?? '').toLowerCase();
    final l10n = context.l10n;
    if (m.startsWith('image/')) return '📷 ${l10n.photo}';
    if (m.startsWith('video/')) return '🎬 ${l10n.video}';
    if (m.startsWith('audio/')) {
      // Voice note (AAC/m4a = `audio/mp4`, same as music) is told apart by its
      // captured waveform — label it as a voice message, never «Музыка».
      final isVoice = _isVoiceMessageMime(m) || (waveform?.isNotEmpty ?? false);
      return isVoice
          ? '🎤 ${_voiceMessageLabel(context)}'
          : '🎵 ${l10n.music}';
    }
    return '📎 ${l10n.file}';
  }

  /// Reply/quote label for a round video NOTE (квадратик) — its mime is
  /// `video/*` with no filename, so the generic [_attachmentPreviewLabel] would
  /// say "🎬 Video"; a video message deserves its own label.
  String _videoNotePreviewLabel() {
    return wave1Text(
      context,
      ru: '🎥 Видеосообщение',
      en: '🎥 Video message',
      uk: '🎥 Відеоповідомлення',
      es: '🎥 Videomensaje',
      pt: '🎥 Mensagem de vídeo',
      ptBr: '🎥 Mensagem de vídeo',
      fr: '🎥 Message vidéo',
      de: '🎥 Videonachricht',
    );
  }

  String _stickerPreviewLabel(StickerEventV1 sticker) {
    final resolved = SecretlyStickerCatalog.resolveEvent(sticker);
    return SecretlyStickerCatalog.previewLabel(
      isRu: chatLocaleIsRussian(context),
      baseLabel: chatText(
        context,
        ru: 'Стикер',
        en: 'Sticker',
        uk: 'Стікер',
        es: 'Sticker',
        pt: 'Sticker',
        fr: 'Sticker',
        de: 'Sticker',
      ),
      emojiHint: sticker.emojiHint.isNotEmpty
          ? sticker.emojiHint
          : resolved.emojiHint,
      label: sticker.label.isNotEmpty ? sticker.label : resolved.label,
    );
  }

  String _trimPreview(String value) {
    final compact = value.replaceAll('\n', ' ').trim();
    if (compact.length <= 72) return compact;
    return '${compact.substring(0, 72)}…';
  }

  bool _isUnresolvedPlaceholderText(E2eEventV1? payload, String text) {
    return payload == null && text.trim() == '…';
  }

  String _resolvedTimelineCacheKey(ChatEvent event) {
    // eventId is stable+unique per message, so it's the primary key — cheap
    // to compare, unlike hashing the full (often large) base64 ciphertext on
    // every timeline rebuild. An EDIT rewrites the ciphertext in place for the
    // same eventId (localState/payloadEventId unchanged), and re-encryption
    // uses a fresh random nonce, so the LENGTH alone can collide (e.g. editing
    // "hello"→"world" keeps the byte count) and the decoded text would render
    // stale. A short tail slice of the ciphertext always differs after any
    // edit (new nonce) at near-zero cost, so it reliably invalidates the cache.
    String tail(String? s) {
      if (s == null || s.isEmpty) return '';
      return s.length <= 12 ? s : s.substring(s.length - 12);
    }

    return '${event.eventId}|${event.localState}|${event.payloadEventId ?? ''}'
        '|${event.localCiphertextB64?.length ?? 0}|${event.ciphertextB64.length}'
        '|${tail(event.localCiphertextB64)}|${tail(event.ciphertextB64)}';
  }

  void _startReply({
    String? payloadEventId,
    required String previewText,
    required String authorName,
    required bool authorIsMe,
  }) {
    if (payloadEventId == null || payloadEventId.isEmpty) return;
    setState(() {
      _editingTarget = null;
      _replyTo = _ReplyTarget(
        payloadEventId: payloadEventId,
        authorName: authorName,
        previewText: _trimPreview(previewText),
        authorIsMe: authorIsMe,
      );
    });
    _messageInputFocusNode.requestFocus();
  }

  Future<void> _startEdit(_TimelineEntry entry) async {
    final payloadId = (entry.payloadEventId ?? '').trim();
    if (!entry.isMe || payloadId.isEmpty) return;
    final payload = await widget.controller.payloadEventForChatEvent(
      entry.event,
    );
    if (!mounted || payload is! MsgEventV1) return;
    if (_isDeleteForAllCommandText(payload.text) ||
        _isHiddenSystemCommandText(payload.text)) {
      return;
    }
    setState(() {
      _editingTarget = _EditingTarget(
        payloadEventId: payloadId,
        originalText: payload.text,
        previewText: _trimPreview(payload.text),
      );
      _replyTo = null;
      _forwardDraft = null;
      _composerMentionDraft = null;
    });
    widget.controller.clearForwardDraft();
    _text.value = TextEditingValue(
      text: payload.text,
      selection: TextSelection.collapsed(offset: payload.text.length),
    );
    _messageInputFocusNode.requestFocus();
  }

  void _cancelEdit() {
    setState(() {
      _editingTarget = null;
      _composerMentionDraft = null;
    });
    _text.clear();
  }

  /// True when two message timestamps fall on the same calendar day in the
  /// DEVICE's local timezone — the day separator has to follow the reader's
  /// clock, not UTC, or it would break at the wrong message near midnight.
  static bool _isSameCalendarDay(int aMs, int bMs) {
    final a = DateTime.fromMillisecondsSinceEpoch(aMs);
    final b = DateTime.fromMillisecondsSinceEpoch(bMs);
    return a.year == b.year && a.month == b.month && a.day == b.day;
  }

  GlobalKey _getEventRowKey(String id) =>
      _eventRowKeys.putIfAbsent(id, GlobalKey.new);

  /// 🔴 ЕДИНСТВЕННОЕ ПРАВИЛО «ЧЕМ ОПОЗНАЁТСЯ СТРОКА ЛЕНТЫ» (20.08.2026).
  ///
  /// Раньше оно было написано в десяти местах как `payloadEventId ?? eventId`.
  /// `??` ловит только null — пустая строка проходила как полноценный
  /// идентификатор, и ВСЕ такие строки получали один ключ ''. Два следствия,
  /// оба видел пользователь: дедуп схлопывал их в одну (сообщения исчезали с
  /// экрана, оставаясь в базе), а `GlobalKey` дублировался — а это уже отказ
  /// построения ВСЕГО списка, после которого чат становится неработающим
  /// блоком ошибки и перезапуск не помогает.
  ///
  /// Правило обязано быть ОДНО на дедуп и на ключ строки: разойдутся — вернётся
  /// ровно тот дубликат ключа.
  static String timelineRowId(String? payloadEventId, String eventId) {
    final pid = (payloadEventId ?? '').trim();
    return pid.isEmpty ? eventId : pid;
  }

  /// "Show in chat", arriving from a gallery that is about to pop back onto us.
  ///
  /// We are still UNDER that screen when this fires, so the scroll happens
  /// off-camera and the chat is already sitting on the message once the pop
  /// finishes. A request naming another conversation belongs to a different
  /// ChatScreen — leave it alone rather than consuming it.
  void _onChatFocusRequest() {
    final request = widget.controller.chatFocusRequest.value;
    if (request == null || request.convoId != widget.convoId) return;
    if (!mounted) return;
    widget.controller.chatFocusRequest.value = null;
    unawaited(_scrollToReply(request.payloadEventId));
  }

  Future<void> _scrollToReply(String targetPayloadId) async {
    _highlightTimer?.cancel();
    if (mounted) setState(() => _highlightedPayloadId = targetPayloadId);

    Future<void> tryEnsureVisible() async {
      final ctx = _eventRowKeys[targetPayloadId]?.currentContext;
      if (ctx == null) return;
      await Scrollable.ensureVisible(
        ctx,
        duration: const Duration(milliseconds: 350),
        curve: Curves.easeOutCubic,
        alignment: 0.5,
      );
    }

    if (_eventRowKeys[targetPayloadId]?.currentContext != null) {
      await tryEnsureVisible();
    } else {
      final timeline = _lastTimeline;
      final idx = timeline.indexWhere(
        (e) => (e.payloadEventId ?? e.event.eventId) == targetPayloadId,
      );
      if (idx >= 0 && _scroll.hasClients) {
        final approx = (idx * 76.0).clamp(
          0.0,
          _scroll.position.maxScrollExtent,
        );
        _scroll.jumpTo(approx);
      }
      await Future<void>.delayed(const Duration(milliseconds: 120));
      await tryEnsureVisible();
    }

    _highlightTimer = Timer(const Duration(milliseconds: 650), () {
      if (mounted) setState(() => _highlightedPayloadId = null);
    });
  }

  /// Stable signature of [events] for timeline-future memoization. Includes
  /// every field that can change how an event renders — id, order, type,
  /// scheduling, and the per-event resolve cache key (which already folds in
  /// localState + payloadEventId + both ciphertext hashes, so edits and
  /// delivery/read receipts of OUR rows always bust it). If this string is
  /// unchanged, the resolved timeline is guaranteed identical.
  /// Последний список, для которого подпись уже посчитана, и сама подпись.
  ///
  /// 🔴 ПОЧЕМУ (02.09.2026, аудит плавности). Подпись строится в `build()`, а
  /// `build()` вызывается на каждый кадр, где что-то шевельнулось: появление
  /// клавиатуры, прокрутка, смена темы, любой `MediaQuery`. При двухстах
  /// событиях это тысяча записей в буфер и строка на 15–30 КБ — каждый раз
  /// заново, ради результата, который в подавляющем большинстве случаев
  /// побайтово совпадает с предыдущим.
  ///
  /// Сравнение по `identical`, а не по содержимому: список событий приходит из
  /// `_eventsFutureForCurrentVersion`, который между тиками отдаёт ТОТ ЖЕ
  /// экземпляр. Значит несовпадение ссылки означает «данные действительно
  /// перечитаны», и подпись честно считается заново. Семантика подписи не
  /// меняется вовсе — меняется только то, сколько раз её вычисляют.
  List<ChatEvent>? _lastSignatureInput;
  String? _lastSignatureValue;

  String _timelineSignatureFor(List<ChatEvent> events) {
    final cachedInput = _lastSignatureInput;
    final cachedValue = _lastSignatureValue;
    if (cachedValue != null &&
        cachedInput != null &&
        identical(cachedInput, events)) {
      return cachedValue;
    }
    final value = _computeTimelineSignature(events);
    _lastSignatureInput = events;
    _lastSignatureValue = value;
    return value;
  }

  String _computeTimelineSignature(List<ChatEvent> events) {
    final sb = StringBuffer();
    sb.write(events.length);
    for (final e in events) {
      sb
        ..write('')
        ..write(e.eventId)
        ..write('')
        ..write(e.createdAtMs)
        ..write('')
        ..write(e.type)
        ..write('')
        ..write(e.scheduledAtMs ?? 0)
        ..write('')
        ..write(_resolvedTimelineCacheKey(e));
    }
    return sb.toString();
  }

  /// Returns a memoized `loadEvents` future, re-querying only when the
  /// controller's changeVersion moved (i.e. a `changed` tick happened since).
  /// Every other rebuild of the chat body (keyboard inset, overlay toggles,
  /// voice-UI setState) reuses the completed future, so sqlite is not hit
  /// again for a layout-only rebuild.
  Future<List<ChatEvent>> _eventsFutureForCurrentVersion() {
    final version = widget.controller.changeVersion;
    if (widget.convoId != _eventsFutureConvoId) {
      // New conversation → fresh paging window (newest page only).
      _timelineLoadLimit = _timelineLoadLimitStep;
      _timelineMaybeHasMore = true;
      _timelineGrowInFlight = false;
    }
    final cached = _eventsFuture;
    if (cached != null &&
        version == _eventsFutureVersion &&
        widget.convoId == _eventsFutureConvoId &&
        _timelineLoadLimit == _eventsFutureLimit) {
      return cached;
    }
    final requestedLimit = _timelineLoadLimit;
    final fut = widget.controller
        .loadEvents(widget.convoId, applyRetention: false, limit: requestedLimit)
        .then((events) {
          // A short page means the DB has no more history than this — stop
          // growing. (>= keeps paging when albums/receipts pad the count.)
          _timelineMaybeHasMore = events.length >= requestedLimit;
          return events;
        })
        .whenComplete(() {
          // Errors propagate to the FutureBuilder; the paging gate must still
          // re-arm either way or scroll-up would go silent for this convo.
          _timelineGrowInFlight = false;
        });
    _eventsFuture = fut;
    _eventsFutureVersion = version;
    _eventsFutureConvoId = widget.convoId;
    _eventsFutureLimit = requestedLimit;
    return fut;
  }

  /// TIMELINE PAGING (2026-07-18, "старые смс исчезают сверху"): the timeline
  /// loads the newest [_timelineLoadLimit] rows; scrolling near the TOP of the
  /// chat (reverse list → high pixel offsets) grows the window by a step, so
  /// older history streams in Telegram-style instead of silently falling out
  /// of a fixed newest-200 window as new messages arrive. Growing the limit
  /// re-queries; the per-event resolve cache keeps already-shown rows cheap,
  /// and a reverse list anchors at the newest row so the prepend never jumps
  /// the scroll position.
  static const int _timelineLoadLimitStep = 200;
  int _timelineLoadLimit = _timelineLoadLimitStep;
  bool _timelineMaybeHasMore = true;
  bool _timelineGrowInFlight = false;
  int _eventsFutureLimit = 0;

  void _maybeGrowTimelineWindow() {
    if (!mounted || _timelineGrowInFlight || !_timelineMaybeHasMore) return;
    if (!_scroll.hasClients) return;
    final position = _scroll.position;
    if (!position.hasContentDimensions) return;
    // reverse:true → the oldest loaded message sits at maxScrollExtent.
    if (position.maxScrollExtent - position.pixels > 900) return;
    _timelineGrowInFlight = true;
    setState(() {
      _timelineLoadLimit += _timelineLoadLimitStep;
      // Invalidate the memoized chain so the wider window re-queries now.
      _eventsFuture = null;
    });
  }

  /// Memoized `loadMessageReactions` future.
  ///
  /// The FutureBuilder that shows reactions used to build its future INSIDE
  /// build, so EVERY rebuild fired a fresh query — and that query is expensive:
  /// one `IN (...)` over the whole visible timeline plus, per reaction row, a
  /// sequentially-awaited contact + profile_meta lookup. During a media upload
  /// the screen rebuilds ~12x/second, so this alone was a sustained sqlite
  /// storm that also starved the DB queue the scrolling rows depend on. It is
  /// also scroll-coupled: any setState while scrolling re-fired it.
  ///
  /// Keyed on the IDENTITY of [reactionIds] — the timeline memo above hands
  /// back the same list instance while the events and pending uploads are
  /// unchanged, which is exactly what makes this cache possible. A genuine
  /// change (new/removed row) mints a new list, so reactions still refresh.
  Future<Map<String, List<MessageReaction>>> _reactionsFutureFor(
    List<String> reactionIds,
  ) {
    // ALSO keyed on changeVersion. Identity alone broke reactions outright:
    // adding one changes no event row, so the timeline memo hands back the
    // same ids instance and the stale future was reused forever — a reaction
    // would not show until the chat was closed and reopened. Every reaction
    // write emits `changed`, so folding changeVersion in restores the old
    // refresh semantics; upload-progress ticks ride their own stream and do
    // NOT move changeVersion, so the storm this cache was built against
    // (12 queries/s during a send) stays fixed.
    final version = widget.controller.changeVersion;
    final cached = _reactionsFuture;
    if (cached != null &&
        identical(reactionIds, _reactionsFutureIds) &&
        version == _reactionsFutureVersion) {
      return cached;
    }
    final fut = widget.controller.loadMessageReactions(eventIds: reactionIds).then((
      map,
    ) {
      // Warm the synchronous cache so the NEXT build paints reactions with the
      // bubbles instead of a frame later. Guarded on `mounted`: a chat closed
      // mid-query must not touch state.
      if (mounted) _reactionsShown = map;
      return map;
    });
    _reactionsFutureIds = reactionIds;
    _reactionsFutureVersion = version;
    _reactionsFuture = fut;
    return fut;
  }

  /// Returns a memoized [_buildTimelineEntries] future, rebuilding it only when
  /// the [events] signature actually changes. Reused across the redundant
  /// `controller.changed` ticks (typing / presence / peer receipts) that don't
  /// alter our event rows.
  Future<List<_TimelineEntry>> _timelineEntriesFutureFor(
    List<ChatEvent> events,
  ) {
    // 🔴 ВЫБРАННАЯ ВЕТКА — ЧАСТЬ ПОДПИСИ (16.09.2026, по жалобе владельца
    // «при нажатии на темы комнат ничего не меняется»).
    //
    // Лента собирается один раз на набор событий и кэшируется по их подписи, а
    // фильтр по ветке стоит ВНУТРИ сборки. Пока в подписи не было самой ветки,
    // переключение тем возвращало ТОТ ЖЕ готовый список: события не менялись,
    // значит подпись совпадала, значит пересборка не запускалась. Человек
    // нажимал «Основа», «релиз», «созвон» — и видел одно и то же.
    //
    // Список тем тоже входит в подпись: фильтр считает неизвестную ветку
    // «Основой», и переименование или удаление ветки меняет раскладку ленты,
    // не трогая ни одного события.
    final sig =
        '${_timelineSignatureFor(events)}'
        '|${_currentTopicId ?? ''}'
        '|${_roomTopics.map((t) => t.id).join(',')}';
    final cached = _timelineEntriesFuture;
    if (cached != null && sig == _timelineEntriesSignature) {
      return cached;
    }
    final fut = _buildTimelineEntries(events);
    _timelineEntriesSignature = sig;
    _timelineEntriesFuture = fut;
    return fut;
  }

  /// Runs the conversation retention sweep out-of-band (chat open + periodic
  /// timer) so it no longer rides on the per-render `loadEvents`. When the sweep
  /// actually prunes rows the controller emits `changed`, which re-runs
  /// `loadEvents` (now retention-free) and refreshes the list normally.
  void _runRetentionSweep() {
    unawaited(widget.controller.applyConversationRetention(widget.convoId));
  }

  Future<List<_TimelineEntry>> _buildTimelineEntries(
    List<ChatEvent> events,
  ) async {
    final liveEventIds = events.map((e) => e.eventId).toSet();
    _resolvedTimelineCacheByEventId.removeWhere(
      (eventId, _) => !liveEventIds.contains(eventId),
    );

    final resolved = <_ResolvedTimelineItem>[];
    final isRu = chatLocaleIsRussian(context);
    final l10n = context.l10n;
    final sharedProfileCardCache = <String, _SharedProfileCardData>{};
    final roomInviteCardCache = <String, _RoomInviteCardData>{};
    // Avatar paths for forwarded-message authors, resolved once per profile id.
    final forwardAvatarCache = <String, String?>{};
    // PERF: each event resolves independently (decrypt + preview text), but
    // this used to await them ONE BY ONE — ~200 sequential crypto round-trips
    // was the multi-second "wallpaper only" hang on chat open. Resolve in
    // bounded parallel chunks instead, preserving order.
    Future<_ResolvedTimelineItem> resolveOne(ChatEvent event) async {
      final cacheKey = _resolvedTimelineCacheKey(event);
      final cached = _resolvedTimelineCacheByEventId[event.eventId];
      if (cached != null && cached.cacheKey == cacheKey) {
        return cached.item;
      }

      final payload = await widget.controller.payloadEventForChatEvent(event);
      String text;
      if (payload is MsgEventV1) {
        final pollSpec = parsePollCommand(payload.text);
        final eventSpec = pollSpec == null
            ? parseEventCommand(payload.text)
            : null;
        final fwdSpec = (pollSpec == null && eventSpec == null)
            ? parseForwardCommand(payload.text)
            : null;
        if (pollSpec != null) {
          text = '📊 ${pollSpec.question}';
        } else if (eventSpec != null) {
          text = '📅 ${eventSpec.title}';
        } else if (fwdSpec != null) {
          text = stripChatFormattingMarkers(fwdSpec.text);
        } else {
          final sharedProfileCard = await _resolveSharedProfileCardData(
            payload.text,
            cache: sharedProfileCardCache,
          );
          final roomInviteCard = sharedProfileCard == null
              ? await _resolveRoomInviteCardData(
                  payload.text,
                  cache: roomInviteCardCache,
                )
              : null;
          text = stripChatFormattingMarkers(
            sharedProfileCard?.previewText ??
                roomInviteCard?.previewText ??
                payload.text,
          );
        }
      } else if (payload is SystemEventV1) {
        text = formatSystemEventText(
          payload,
          isRu: isRu,
          selfProfileId: widget.controller.profileId,
        );
      } else if (payload is AttachmentEventV1) {
        text = _attachmentPreviewLabel(payload.mime, waveform: payload.waveform);
      } else if (payload is StickerEventV1) {
        text = _stickerPreviewLabel(payload);
      } else if (payload is CallEventV1) {
        text = buildCallEventPreviewText(
          l10n: l10n,
          isRu: isRu,
          result: payload.result,
          direction: payload.direction,
          isVideo: payload.hadVideo,
          durationMs: payload.durationMs,
        );
      } else {
        text = await widget.controller.decryptPlainAsync(event);
      }

      final item = _ResolvedTimelineItem(
        event: event,
        payload: payload,
        displayText: text,
      );
      // F-CONTENTKEY-4 (2026-07-31): never cache a FAILURE.
      //
      // An unresolved item is "we could not decrypt this right now" — crypto
      // not ready yet on a cold open, a keychain still warming. The cache key
      // is built from the event id and the ciphertext, neither of which changes
      // when crypto becomes available, and eviction only happens when the event
      // leaves the live set. So caching the placeholder froze a one-second
      // hiccup into "my messages turned into '…'" for the whole screen session,
      // which is what made a transient fault look like permanent data loss.
      //
      // Skipping the write costs one re-decrypt per rebuild for those items
      // only, and they resolve on the very next one.
      if (!_isUnresolvedPlaceholderText(payload, text)) {
        _resolvedTimelineCacheByEventId[event.eventId] =
            _ResolvedTimelineCacheEntry(cacheKey: cacheKey, item: item);
      }
      return item;
    }

    const resolveChunk = 24;
    for (var i = 0; i < events.length; i += resolveChunk) {
      final end = (i + resolveChunk < events.length)
          ? i + resolveChunk
          : events.length;
      resolved.addAll(
        await Future.wait(events.sublist(i, end).map(resolveOne)),
      );
    }

    // Room-wide pin sync: pick up the newest pin-sync control message and, if
    // it's newer than what we've applied, adopt its pin list for everyone.
    if (_isGroupChat) {
      _maybeAdoptSharedPins(resolved);
      _maybeAdoptRoomTopics(resolved);
      if (_roomTopics.isNotEmpty) {
        _recomputeTopicUnread(resolved);
      }
    }

    final authorByDeviceId = <String, _AuthorMeta>{};
    if (_isGroupChat) {
      final roomMembersByProfileId = <String, RoomMember>{
        for (final member in await widget.controller.listRoomMembersDetailed(
          widget.convoId,
        ))
          if (member.isActive) member.profileId: member,
      };
      final senderDeviceIds = resolved
          .map((item) => item.event.senderDeviceId)
          .where((id) => id.isNotEmpty && !widget.controller.isOwnDeviceId(id))
          .toSet();
      final lookups = await Future.wait(
        senderDeviceIds.map((deviceId) async {
          final contact = await widget.controller.contactByDeviceId(deviceId);
          final profileId =
              await widget.controller.cachedProfileIdByDeviceId(deviceId) ??
              contact?.profileId ??
              '';
          if (profileId.isEmpty) {
            // Never-seen sender: warm device→profile from the server (throttled)
            // so the raw device fallback becomes a real name on a later rebuild.
            widget.controller.warmProfileIdForDeviceSoon(deviceId);
          } else {
            _roomAuthorProfileIdByDevice[deviceId] = profileId;
          }
          final roomMember = roomMembersByProfileId[profileId];
          final nameCandidate = roomMember?.displayName ?? contact?.displayName;
          final name = nameCandidate != null && nameCandidate.trim().isNotEmpty
              ? nameCandidate.trim()
              : _authorFallbackFromDevice(deviceId);
          return MapEntry(
            deviceId,
            _AuthorMeta(
              name: name,
              avatarPath: contact?.avatarPath ?? roomMember?.avatarPath,
              tag: _normalizedRoomMemberTag(roomMember?.tag),
            ),
          );
        }),
      );
      for (final entry in lookups) {
        authorByDeviceId[entry.key] = entry.value;
      }
    }

    final roomReceiptStatusTextByPayloadId = <String, String>{};
    if (_isGroupChat) {
      // Room size excluding me — the yardstick for "did everyone get it?".
      // Best-effort: on failure it stays 0 = unknown, and the counter keeps its
      // previous always-on behaviour rather than vanishing on a roster hiccup.
      var otherMemberCount = 0;
      try {
        final me = widget.controller.profileId.trim();
        final members = await widget.controller.listGroupMembers(
          widget.convoId,
        );
        otherMemberCount = members
            .map((m) => m.trim())
            .where((m) => m.isNotEmpty && m != me)
            .toSet()
            .length;
      } catch (_) {
        otherMemberCount = 0;
      }
      final outgoingPayloadIds = resolved
          .where(
            (item) =>
                widget.controller.isOwnDeviceId(item.event.senderDeviceId),
          )
          .map((item) => (item.event.payloadEventId ?? '').trim())
          .where((payloadEventId) => payloadEventId.isNotEmpty)
          .toSet()
          .toList(growable: false);
      final receiptCounts = await Future.wait(
        outgoingPayloadIds.map((payloadEventId) async {
          final counts = await widget.controller.roomMessageReceiptCounts(
            payloadEventId,
          );
          return MapEntry(payloadEventId, counts);
        }),
      );
      for (final entry in receiptCounts) {
        final statusText = _roomReceiptStatusText(
          entry.value,
          otherMemberCount: otherMemberCount,
        );
        if (statusText == null || statusText.isEmpty) continue;
        roomReceiptStatusTextByPayloadId[entry.key] = statusText;
      }
    }

    final deletedPayloadIds = <String>{};
    for (final item in resolved) {
      final payload = item.payload;
      if (payload is! MsgEventV1) continue;
      if (!_isDeleteForAllCommandText(payload.text)) continue;
      deletedPayloadIds.addAll(_parseDeleteForAllCommand(payload.text));
    }

    // Tally poll votes (latest vote per voter per poll wins). Votes are hidden
    // control messages already present in `resolved`, so the card always shows
    // a live tally without any extra storage.
    final pollVotesByPoll =
        <String, Map<String, ({List<int> opts, int atMs})>>{};
    for (final item in resolved) {
      final payload = item.payload;
      if (payload is! MsgEventV1) continue;
      final vote = parsePollVoteCommand(payload.text);
      if (vote == null) continue;
      final atMs = item.event.createdAtMs;
      final byVoter = pollVotesByPoll.putIfAbsent(
        vote.pollId,
        () => <String, ({List<int> opts, int atMs})>{},
      );
      final existing = byVoter[vote.voterProfileId];
      if (existing == null || atMs >= existing.atMs) {
        byVoter[vote.voterProfileId] = (opts: vote.optionIndices, atMs: atMs);
      }
    }
    final myProfileIdForPolls = widget.controller.profileId;

    // Tally event RSVPs (latest per voter per event).
    final rsvpByEvent = <String, Map<String, ({String status, int atMs})>>{};
    for (final item in resolved) {
      final payload = item.payload;
      if (payload is! MsgEventV1) continue;
      final rsvp = parseEventRsvpCommand(payload.text);
      if (rsvp == null) continue;
      final atMs = item.event.createdAtMs;
      final byVoter = rsvpByEvent.putIfAbsent(
        rsvp.eventId,
        () => <String, ({String status, int atMs})>{},
      );
      final existing = byVoter[rsvp.voterProfileId];
      if (existing == null || atMs >= existing.atMs) {
        byVoter[rsvp.voterProfileId] = (status: rsvp.status, atMs: atMs);
      }
    }

    // Resolve each poll's creator profileId from the poll SPEC's sender, so a
    // close-command below can be validated against it. Client-derived trust
    // only (same model already used for room pins/roles — no server-side
    // enforcement), but it stops any random member from closing someone
    // else's poll via a crafted close command.
    final pollCreatorProfileIdByPollId = <String, String>{};
    if (_isGroupChat) {
      final myProfileId = widget.controller.profileId;
      final unresolvedDeviceIdByPollId = <String, String>{};
      for (final item in resolved) {
        final payload = item.payload;
        if (payload is! MsgEventV1) continue;
        final spec = parsePollCommand(payload.text);
        if (spec == null || pollCreatorProfileIdByPollId.containsKey(spec.pollId)) {
          continue;
        }
        if (widget.controller.isOwnDeviceId(item.event.senderDeviceId)) {
          if (myProfileId.isNotEmpty) {
            pollCreatorProfileIdByPollId[spec.pollId] = myProfileId;
          }
        } else {
          unresolvedDeviceIdByPollId[spec.pollId] = item.event.senderDeviceId;
        }
      }
      if (unresolvedDeviceIdByPollId.isNotEmpty) {
        final resolvedEntries = await Future.wait(
          unresolvedDeviceIdByPollId.entries.map((entry) async {
            final profileId = await widget.controller.cachedProfileIdByDeviceId(
              entry.value,
            );
            return MapEntry(entry.key, profileId ?? '');
          }),
        );
        for (final entry in resolvedEntries) {
          if (entry.value.isNotEmpty) {
            pollCreatorProfileIdByPollId[entry.key] = entry.value;
          }
        }
      }
    }

    // Tally poll-close commands (only the resolved creator's close counts).
    final pollClosedAtMsByPollId = <String, int>{};
    for (final item in resolved) {
      final payload = item.payload;
      if (payload is! MsgEventV1) continue;
      final close = parsePollCloseCommand(payload.text);
      if (close == null) continue;
      final creatorProfileId = pollCreatorProfileIdByPollId[close.pollId];
      if (creatorProfileId == null || creatorProfileId != close.closerProfileId) {
        continue;
      }
      final existing = pollClosedAtMsByPollId[close.pollId];
      if (existing == null || close.closedAtMs < existing) {
        pollClosedAtMsByPollId[close.pollId] = close.closedAtMs;
      }
    }

    final previewByPayloadId = <String, _ReplySnippet>{};
    for (final item in resolved) {
      final pid = item.event.payloadEventId;
      if (pid == null || pid.isEmpty) continue;
      if (deletedPayloadIds.contains(pid)) continue;
      final payload = item.payload;
      if (payload is SystemEventV1) continue;
      if (_isUnresolvedPlaceholderText(payload, item.displayText)) continue;
      if (payload is MsgEventV1 &&
          (_isDeleteForAllCommandText(payload.text) ||
              _isHiddenSystemCommandText(payload.text))) {
        continue;
      }
      final authorName =
          widget.controller.isOwnDeviceId(item.event.senderDeviceId)
          ? _selfAuthorLabel()
          : (_isGroupChat
                ? (authorByDeviceId[item.event.senderDeviceId]?.name ??
                      _authorFallbackFromDevice(item.event.senderDeviceId))
                : widget.title);
      previewByPayloadId[pid] = _ReplySnippet(
        authorName: authorName,
        previewText: _trimPreview(item.displayText),
        authorIsMe: widget.controller.isOwnDeviceId(item.event.senderDeviceId),
        authorSeed: item.event.senderDeviceId,
      );
    }

    bool sameImageGroup(_ResolvedTimelineItem a, _ResolvedTimelineItem b) {
      final pa = a.payload;
      final pb = b.payload;
      if (pa is! AttachmentEventV1 || pb is! AttachmentEventV1) return false;
      final ga = pa.mediaGroupId;
      final gb = pb.mediaGroupId;
      if (ga == null || ga.isEmpty || gb == null || gb.isEmpty) return false;
      // Only true photos (image/video mime AND no filename) collapse into an
      // album. Photos sent AS FILES carry a filename and must each stay their
      // own document bubble — never grouped.
      if (!_attachmentRendersAsPhoto(pa) || !_attachmentRendersAsPhoto(pb)) {
        return false;
      }
      return ga == gb && a.event.senderDeviceId == b.event.senderDeviceId;
    }

    final out = <_TimelineEntry>[];
    var i = 0;
    while (i < resolved.length) {
      final item = resolved[i];
      if (item.event.payloadEventId != null &&
          deletedPayloadIds.contains(item.event.payloadEventId)) {
        i++;
        continue;
      }
      final payload = item.payload;
      if (_isUnresolvedPlaceholderText(payload, item.displayText)) {
        i++;
        continue;
      }
      if (payload is MsgEventV1 &&
          (_isDeleteForAllCommandText(payload.text) ||
              _isHiddenSystemCommandText(payload.text))) {
        i++;
        continue;
      }
      // Topic filter: when the room has topics, only show events that belong to
      // the selected topic (General = events with no topic). Messages whose
      // topic was deleted fall back to General so nothing is ever lost.
      if (_isGroupChat && _roomTopics.isNotEmpty) {
        final raw = (_eventTopicId(payload) ?? '');
        final knownTopicIds = _roomTopics.map((topic) => topic.id).toSet();
        final eventTopic = (raw.isEmpty || knownTopicIds.contains(raw))
            ? raw
            : '';
        if (eventTopic != (_currentTopicId ?? '')) {
          i++;
          continue;
        }
      }
      if (payload is AttachmentEventV1) {
        // A photo sent AS A FILE (filename present) renders as a document row,
        // not an image/album bubble — only filename-less photos are "images".
        final isImage = _attachmentRendersAsPhoto(payload);
        final hasGroup = (payload.mediaGroupId ?? '').isNotEmpty;
        if (isImage && hasGroup) {
          final group = <AttachmentEventV1>[payload];
          final groupItems = <_TimelineImageItem>[
            _TimelineImageItem(event: item.event, attachment: payload),
          ];
          var j = i + 1;
          while (j < resolved.length && sameImageGroup(item, resolved[j])) {
            final nextPayload = resolved[j].payload;
            if (nextPayload is AttachmentEventV1) {
              group.add(nextPayload);
              groupItems.add(
                _TimelineImageItem(
                  event: resolved[j].event,
                  attachment: nextPayload,
                ),
              );
            }
            j++;
          }

          out.add(
            _TimelineEntry(
              event: item.event,
              isMe: widget.controller.isOwnDeviceId(item.event.senderDeviceId),
              payloadEventId: item.event.payloadEventId,
              previewText: _attachmentPreviewLabel(
                payload.mime,
                waveform: payload.waveform,
              ),
              replySnippet: previewByPayloadId[payload.replyToEventId],
              authorName:
                  widget.controller.isOwnDeviceId(item.event.senderDeviceId)
                  ? _selfAuthorLabel()
                  : (_isGroupChat
                        ? (authorByDeviceId[item.event.senderDeviceId]?.name ??
                              _authorFallbackFromDevice(
                                item.event.senderDeviceId,
                              ))
                        : widget.title),
              authorAvatarPath:
                  authorByDeviceId[item.event.senderDeviceId]?.avatarPath,
              authorTag: authorByDeviceId[item.event.senderDeviceId]?.tag,
              roomReceiptStatusText:
                  roomReceiptStatusTextByPayloadId[(item.event.payloadEventId ??
                          '')
                      .trim()],
              imageAttachments: group,
              imageItems: groupItems,
              replyTargetPayloadId: payload.replyToEventId,
            ),
          );
          i = j;
          continue;
        }

        out.add(
          _TimelineEntry(
            event: item.event,
            isMe: widget.controller.isOwnDeviceId(item.event.senderDeviceId),
            payloadEventId: item.event.payloadEventId,
            previewText: payload.videoNote
                ? _videoNotePreviewLabel()
                : _attachmentPreviewLabel(
                    payload.mime,
                    waveform: payload.waveform,
                  ),
            replySnippet: previewByPayloadId[payload.replyToEventId],
            authorName:
                widget.controller.isOwnDeviceId(item.event.senderDeviceId)
                ? _selfAuthorLabel()
                : (_isGroupChat
                      ? (authorByDeviceId[item.event.senderDeviceId]?.name ??
                            _authorFallbackFromDevice(
                              item.event.senderDeviceId,
                            ))
                      : widget.title),
            authorAvatarPath:
                authorByDeviceId[item.event.senderDeviceId]?.avatarPath,
            authorTag: authorByDeviceId[item.event.senderDeviceId]?.tag,
            roomReceiptStatusText:
                roomReceiptStatusTextByPayloadId[(item.event.payloadEventId ??
                        '')
                    .trim()],
            attachment: payload,
            imageItems: isImage
                ? <_TimelineImageItem>[
                    _TimelineImageItem(event: item.event, attachment: payload),
                  ]
                : null,
            isImageAttachment: isImage,
            replyTargetPayloadId: payload.replyToEventId,
          ),
        );
        i++;
        continue;
      }

      if (payload is StickerEventV1) {
        out.add(
          _TimelineEntry(
            event: item.event,
            isMe: widget.controller.isOwnDeviceId(item.event.senderDeviceId),
            payloadEventId: item.event.payloadEventId,
            previewText: item.displayText,
            replySnippet: previewByPayloadId[payload.replyToEventId],
            authorName:
                widget.controller.isOwnDeviceId(item.event.senderDeviceId)
                ? _selfAuthorLabel()
                : (_isGroupChat
                      ? (authorByDeviceId[item.event.senderDeviceId]?.name ??
                            _authorFallbackFromDevice(
                              item.event.senderDeviceId,
                            ))
                      : widget.title),
            authorAvatarPath:
                authorByDeviceId[item.event.senderDeviceId]?.avatarPath,
            authorTag: authorByDeviceId[item.event.senderDeviceId]?.tag,
            roomReceiptStatusText:
                roomReceiptStatusTextByPayloadId[(item.event.payloadEventId ??
                        '')
                    .trim()],
            messageText: item.displayText,
            stickerEvent: payload,
            replyTargetPayloadId: payload.replyToEventId,
          ),
        );
        i++;
        continue;
      }

      if (payload is CallEventV1) {
        out.add(
          _TimelineEntry(
            event: item.event,
            isMe: widget.controller.isOwnDeviceId(item.event.senderDeviceId),
            payloadEventId: item.event.payloadEventId,
            previewText: item.displayText,
            replySnippet: null,
            authorName:
                widget.controller.isOwnDeviceId(item.event.senderDeviceId)
                ? _selfAuthorLabel()
                : (_isGroupChat
                      ? (authorByDeviceId[item.event.senderDeviceId]?.name ??
                            _authorFallbackFromDevice(
                              item.event.senderDeviceId,
                            ))
                      : widget.title),
            authorAvatarPath:
                authorByDeviceId[item.event.senderDeviceId]?.avatarPath,
            authorTag: authorByDeviceId[item.event.senderDeviceId]?.tag,
            roomReceiptStatusText:
                roomReceiptStatusTextByPayloadId[(item.event.payloadEventId ??
                        '')
                    .trim()],
            messageText: item.displayText,
            callEvent: payload,
          ),
        );
        i++;
        continue;
      }

      if (payload is SystemEventV1) {
        out.add(
          _TimelineEntry(
            event: item.event,
            isMe: widget.controller.isOwnDeviceId(item.event.senderDeviceId),
            payloadEventId: item.event.payloadEventId,
            previewText: item.displayText,
            replySnippet: null,
            authorName: '',
            systemEvent: payload,
            messageText: item.displayText,
          ),
        );
        i++;
        continue;
      }

      final msg = payload is MsgEventV1 ? payload : null;
      // Poll spec → interactive poll card with the live tally.
      _PollViewData? pollData;
      if (msg != null) {
        final spec = parsePollCommand(msg.text);
        if (spec != null) {
          final byVoter =
              pollVotesByPoll[spec.pollId] ??
              const <String, ({List<int> opts, int atMs})>{};
          final counts = List<int>.filled(spec.options.length, 0);
          final mine = <int>{};
          for (final voteEntry in byVoter.entries) {
            for (final idx in voteEntry.value.opts) {
              if (idx >= 0 && idx < counts.length) counts[idx]++;
            }
            if (myProfileIdForPolls.isNotEmpty &&
                voteEntry.key == myProfileIdForPolls) {
              mine.addAll(
                voteEntry.value.opts.where(
                  (idx) => idx >= 0 && idx < spec.options.length,
                ),
              );
            }
          }
          final creatorProfileId = pollCreatorProfileIdByPollId[spec.pollId];
          pollData = _PollViewData(
            pollId: spec.pollId,
            question: spec.question,
            options: spec.options,
            multiple: spec.multiple,
            anonymous: spec.anonymous,
            optionVotes: counts,
            totalVoters: byVoter.length,
            myOptionIndices: mine,
            closedAtMs: pollClosedAtMsByPollId[spec.pollId],
            isCreator:
                creatorProfileId != null &&
                myProfileIdForPolls.isNotEmpty &&
                creatorProfileId == myProfileIdForPolls,
          );
        }
      }
      // Event spec → RSVP card with the live tally.
      _EventViewData? eventData;
      if (msg != null && pollData == null) {
        final spec = parseEventCommand(msg.text);
        if (spec != null) {
          final byVoter =
              rsvpByEvent[spec.eventId] ??
              const <String, ({String status, int atMs})>{};
          var going = 0;
          var maybe = 0;
          var no = 0;
          var myStatus = '';
          for (final entry in byVoter.entries) {
            switch (entry.value.status) {
              case 'going':
                going++;
                break;
              case 'maybe':
                maybe++;
                break;
              case 'no':
                no++;
                break;
            }
            if (myProfileIdForPolls.isNotEmpty &&
                entry.key == myProfileIdForPolls) {
              myStatus = entry.value.status;
            }
          }
          eventData = _EventViewData(
            eventId: spec.eventId,
            title: spec.title,
            startMs: spec.startMs,
            description: spec.description,
            location: spec.location,
            goingCount: going,
            maybeCount: maybe,
            noCount: no,
            myStatus: myStatus,
          );
        }
      }
      final sharedProfileCard =
          msg == null || pollData != null || eventData != null
          ? null
          : await _resolveSharedProfileCardData(
              msg.text,
              cache: sharedProfileCardCache,
            );
      final roomInviteCard = msg == null || sharedProfileCard != null
          ? null
          : await _resolveRoomInviteCardData(
              msg.text,
              cache: roomInviteCardCache,
            );
      // Forwarded message → header «Переслано от <name>» + unwrapped body.
      String? forwardedFrom;
      String? forwardedFromProfileId;
      String? forwardedFromAvatarPath;
      String? forwardedFromSourceConvoId;
      var resolvedMessageText = msg?.text ?? item.displayText;
      if (msg != null &&
          pollData == null &&
          eventData == null &&
          sharedProfileCard == null &&
          roomInviteCard == null) {
        final fwd = parseForwardCommand(msg.text);
        if (fwd != null) {
          forwardedFrom = fwd.authorName;
          forwardedFromProfileId = fwd.authorProfileId;
          forwardedFromSourceConvoId = fwd.sourceConvoId;
          resolvedMessageText = fwd.text;
          final pid = fwd.authorProfileId?.trim() ?? '';
          if (pid.isNotEmpty) {
            if (forwardAvatarCache.containsKey(pid)) {
              forwardedFromAvatarPath = forwardAvatarCache[pid];
            } else {
              forwardedFromAvatarPath = await widget.controller
                  .cachedProfileAvatarPath(pid);
              forwardAvatarCache[pid] = forwardedFromAvatarPath;
            }
          }
        }
      }
      out.add(
        _TimelineEntry(
          event: item.event,
          isMe: widget.controller.isOwnDeviceId(item.event.senderDeviceId),
          payloadEventId: item.event.payloadEventId,
          previewText: item.displayText,
          replySnippet: previewByPayloadId[msg?.replyToEventId],
          authorName: widget.controller.isOwnDeviceId(item.event.senderDeviceId)
              ? _selfAuthorLabel()
              : (_isGroupChat
                    ? (authorByDeviceId[item.event.senderDeviceId]?.name ??
                          _authorFallbackFromDevice(item.event.senderDeviceId))
                    : widget.title),
          authorAvatarPath:
              authorByDeviceId[item.event.senderDeviceId]?.avatarPath,
          authorTag: authorByDeviceId[item.event.senderDeviceId]?.tag,
          roomReceiptStatusText:
              roomReceiptStatusTextByPayloadId[(item.event.payloadEventId ?? '')
                  .trim()],
          messageText: resolvedMessageText,
          messageMentions: msg?.mentions ?? const <MsgMentionV1>[],
          sharedProfileCard: sharedProfileCard,
          roomInviteCard: roomInviteCard,
          pollData: pollData,
          eventData: eventData,
          forwardedFrom: forwardedFrom,
          forwardedFromProfileId: forwardedFromProfileId,
          forwardedFromAvatarPath: forwardedFromAvatarPath,
          forwardedFromSourceConvoId: forwardedFromSourceConvoId,
          replyTargetPayloadId: msg?.replyToEventId,
          // Пересланное едет командой без карточки; у остальных карточка
          // показывается, только если она от ссылки из самого текста.
          linkPreview: forwardedFrom == null
              ? acceptIncomingLinkPreview(msg?.linkPreview, resolvedMessageText)
              : null,
        ),
      );
      i++;
    }
    return out;
  }

  Future<void> _queueSelectedPhotoPaths({
    required String targetId,
    required List<ChatAttachmentPickerMediaItem> mediaItems,
  }) async {
    final existingMediaItems = <ChatAttachmentPickerMediaItem>[];
    for (final item in mediaItems) {
      final path = item.path.trim();
      if (path.isEmpty) continue;
      final file = File(path);
      if (await file.exists()) {
        existingMediaItems.add(
          ChatAttachmentPickerMediaItem(
            path: path,
            kind: item.kind,
            mime: item.mime,
            // Preserve the send-editor caption — this rebuild dropped it, which
            // is why captions never showed under the photo/video (single AND
            // album).
            caption: item.caption,
          ),
        );
      }
    }

    if (existingMediaItems.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.attachmentFileMissing)),
      );
      return;
    }

    final hasMany = existingMediaItems.length > 1;
    final groupId = hasMany
        ? DateTime.now().microsecondsSinceEpoch.toString()
        : null;
    final replyToEventId = _replyTo?.payloadEventId;

    if (hasMany) {
      final pendingItems = <PendingPhotoUpload>[];
      for (var index = 0; index < existingMediaItems.length; index++) {
        final mediaItem = existingMediaItems[index];
        final resolvedPath = mediaItem.path;
        final file = File(resolvedPath);
        final fileBytes = await file.length();
        pendingItems.add(
          PendingPhotoUpload(
            id: '${DateTime.now().microsecondsSinceEpoch}_$index',
            filePath: resolvedPath,
            mime: mediaItem.resolvedMime,
            // Per-photo caption from the send editor — was hardcoded '' here, so
            // captions vanished when several photos were sent as an album (the
            // single-photo path already honoured it).
            caption: mediaItem.caption,
            totalBytes: fileBytes,
            replyToPayloadEventId: index == 0 ? replyToEventId : null,
            mediaGroupId: groupId,
          ),
        );
      }
      if (pendingItems.isEmpty || !mounted) return;
      final album = PendingPhotoAlbumUpload(
        id: groupId ?? DateTime.now().microsecondsSinceEpoch.toString(),
        items: pendingItems,
        convoId: widget.convoId,
        targetId: targetId,
        isGroup: _isGroupChat,
        topicId: _isGroupChat ? _currentTopicId : null,
      );
      setState(() => _replyTo = null);
      widget.controller.enqueuePhotoAlbumUpload(album);
      return;
    }

    for (var index = 0; index < existingMediaItems.length; index++) {
      final mediaItem = existingMediaItems[index];
      final resolvedPath = mediaItem.path;
      // SEND EDITOR (2026-07-17): the caption comes ONLY from the fullscreen
      // pre-send editor (single and multi photo). The old chat-side single-photo
      // caption window was retired — the editor is the one caption entry point.
      final String caption = mediaItem.caption;
      final file = File(resolvedPath);
      final fileBytes = await file.length();
      final mime = mediaItem.resolvedMime;

      final pending = PendingPhotoUpload(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        filePath: resolvedPath,
        mime: mime,
        caption: caption,
        totalBytes: fileBytes,
        convoId: widget.convoId,
        targetId: targetId,
        isGroup: _isGroupChat,
        topicId: _isGroupChat ? _currentTopicId : null,
        replyToPayloadEventId: index == 0 ? replyToEventId : null,
        mediaGroupId: groupId,
      );
      if (!mounted) return;
      // Consume the reply the moment we hand off (the executor used to clear it
      // after upload — but it now lives in the controller and can't touch the
      // composer, so clear it here).
      if (index == 0 && replyToEventId != null) {
        setState(() => _replyTo = null);
      }
      widget.controller.enqueuePhotoUpload(pending);
    }
  }

  /// Telegram-style «Галерея» on the FILE tab: send each picked gallery
  /// photo/video AS A FILE — original bytes, original mime, NOT recompressed,
  /// each in its OWN document bubble (NO shared mediaGroupId → no album).
  ///
  /// Routes every item through the generic-file send path
  /// (`sendAttachmentFile` / `sendGroupAttachmentFile`) with a real filename
  /// (so the document row shows name + "FORMAT • SIZE" and an image thumbnail).
  Future<void> _queueGalleryPhotosAsFiles({
    required String targetId,
    required List<ChatAttachmentPickerMediaItem> mediaItems,
  }) async {
    final existingItems = <ChatAttachmentPickerMediaItem>[];
    for (final item in mediaItems) {
      final path = item.path.trim();
      if (path.isEmpty) continue;
      if (await File(path).exists()) {
        existingItems.add(
          ChatAttachmentPickerMediaItem(
            path: path,
            kind: item.kind,
            mime: item.mime,
          ),
        );
      }
    }

    if (existingItems.isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.attachmentFileMissing)),
      );
      return;
    }

    // Reply (if any) attaches to the FIRST item only.
    final replyToEventId = _replyTo?.payloadEventId;

    // Each item becomes its OWN document bubble (full quality, no mediaGroupId).
    // They appear instantly and upload in the BACKGROUND, one at a time via the
    // serialized worker (never racing the ratchet).
    final newPending = <PendingPhotoUpload>[];
    for (var index = 0; index < existingItems.length; index++) {
      final mediaItem = existingItems[index];
      final resolvedPath = mediaItem.path;
      final file = File(resolvedPath);
      final fileBytes = await file.length();
      final fileName = p.basename(resolvedPath);
      // Prefer the extension-derived mime so the FORMAT label matches the real
      // file; fall back to the picker's reported mime.
      final resolvedMime = _guessMime(resolvedPath) ?? mediaItem.resolvedMime;
      newPending.add(
        PendingPhotoUpload(
          id: '${DateTime.now().microsecondsSinceEpoch}_$index',
          filePath: resolvedPath,
          mime: resolvedMime,
          caption: mediaItem.caption,
          totalBytes: fileBytes,
          convoId: widget.convoId,
          targetId: targetId,
          isGroup: _isGroupChat,
          topicId: _isGroupChat ? _currentTopicId : null,
          replyToPayloadEventId: index == 0 ? replyToEventId : null,
          filename: fileName,
          asFile: true,
        ),
      );
      // Mirror the system-picker behaviour: remember the pick under «Недавние»
      // on the FILE tab (best-effort, durable copy + index).
      unawaited(
        RecentAttachmentsStore.instance.record(
          kind: 'file',
          sourcePath: resolvedPath,
          fileName: fileName,
          sizeBytes: fileBytes,
        ),
      );
    }

    if (!mounted || newPending.isEmpty) return;
    if (replyToEventId != null) setState(() => _replyTo = null);
    // Batch enqueue: display the FIRST picked topmost, but upload in picked
    // order (first picked sends first) — exactly the old insert-reversed /
    // enqueue-forward behaviour.
    widget.controller.enqueuePhotoUploads(newPending);
  }

  Widget _buildComposerContextMenu(
    BuildContext context,
    EditableTextState editableTextState,
  ) {
    // Keep the platform's own actions FIRST (Cut / Copy / Paste / Select all),
    // then our extras. Everything lives in one vertically-centred, horizontally
    // scrollable row — no overflow «⋮» button (which rendered off-centre).
    final buttonItems = editableTextState.contextMenuButtonItems.toList(
      growable: true,
    );

    if (!_voiceRecording && _composerAttachmentTargetId().isNotEmpty) {
      buttonItems.add(
        ContextMenuButtonItem(
          label: chatText(context, ru: 'Вставить фото', en: 'Paste photo'),
          onPressed: () {
            ContextMenuController.removeAny();
            unawaited(_pasteImageFromClipboard());
          },
        ),
      );
    }

    // Formatting actions come AFTER the standard ones, only when text is
    // selected. They wrap the selection in markers (bold/italic/etc.).
    final selection = _text.selection;
    final hasSelection =
        selection.isValid &&
        !selection.isCollapsed &&
        selection.start >= 0 &&
        selection.end <= _text.text.length;
    if (hasSelection) {
      final formats = <({String label, String left, String right})>[
        (
          label: chatText(context, ru: 'Жирный', en: 'Bold'),
          left: '**',
          right: '**',
        ),
        (
          label: chatText(context, ru: 'Курсив', en: 'Italic'),
          left: '__',
          right: '__',
        ),
        (
          label: chatText(context, ru: 'Зачёркнутый', en: 'Strikethrough'),
          left: '~~',
          right: '~~',
        ),
        (
          label: chatText(context, ru: 'Моно', en: 'Monospace'),
          left: '`',
          right: '`',
        ),
        (
          label: chatText(context, ru: 'Спойлер', en: 'Spoiler'),
          left: '||',
          right: '||',
        ),
      ];
      for (final format in formats) {
        buttonItems.add(
          ContextMenuButtonItem(
            label: format.label,
            onPressed: () {
              ContextMenuController.removeAny();
              _wrapComposerSelection(format.left, format.right);
            },
          ),
        );
      }
    }

    // Standard platform toolbar: the first actions (Cut/Copy/Paste/Select-all)
    // stay visible and the rest (formatting) fold into the native «⋮» overflow
    // vertical menu.
    return AdaptiveTextSelectionToolbar.buttonItems(
      anchors: editableTextState.contextMenuAnchors,
      buttonItems: buttonItems,
    );
  }

  /// Wraps the current composer selection with [left]/[right] markers and
  /// places the caret just after the wrapped text.
  void _wrapComposerSelection(String left, String right) {
    final value = _text.value;
    final selection = value.selection;
    if (!selection.isValid || selection.isCollapsed) return;
    final start = selection.start.clamp(0, value.text.length);
    final end = selection.end.clamp(0, value.text.length);
    if (end <= start) return;
    final selected = value.text.substring(start, end);
    final newText =
        value.text.substring(0, start) +
        left +
        selected +
        right +
        value.text.substring(end);
    final caret = end + left.length + right.length;
    _text.value = TextEditingValue(
      text: newText,
      selection: TextSelection.collapsed(offset: caret),
      composing: TextRange.empty,
    );
    _messageInputFocusNode.requestFocus();
  }

  String _composerAttachmentTargetId() {
    return _isGroupChat ? widget.convoId : (widget.peerProfileIdForSend ?? '');
  }

  bool _ensureComposerMediaAllowed() {
    if (!_isGroupChat || _roomCanSendMediaNow()) return true;
    final text = _groupComposerPolicyBannerText(context.l10n);
    if (text != null && mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SecretlySnackBar(content: Text(text)));
    }
    return false;
  }

  Future<void> _pasteImageFromClipboard() async {
    final targetId = _composerAttachmentTargetId();
    if (targetId.isEmpty || _sendingAttachment) return;
    if (!_ensureComposerMediaAllowed()) return;

    try {
      final item = await PlatformClipboardMedia.readImage();
      if (!mounted) return;
      if (item == null) {
        _showClipboardPasteSnackBar(
          ru: 'В буфере нет изображения',
          en: 'No image in clipboard',
        );
        return;
      }
      await _queueClipboardImageItem(targetId: targetId, item: item);
    } catch (error) {
      if (!mounted) return;
      _showClipboardPasteSnackBar(
        ru: 'Не удалось вставить изображение',
        en: 'Could not paste image',
      );
    }
  }

  Future<void> _handleComposerInsertedContent(
    KeyboardInsertedContent content,
  ) async {
    final targetId = _composerAttachmentTargetId();
    if (targetId.isEmpty || _sendingAttachment) return;
    if (!_isImageMime(content.mimeType)) return;
    if (!_ensureComposerMediaAllowed()) return;

    try {
      PlatformClipboardMediaItem? item;
      if (content.hasData && content.data != null) {
        final path = await _writeInsertedImageBytes(
          content.data!,
          content.mimeType,
        );
        item = PlatformClipboardMediaItem(
          path: path,
          mime: content.mimeType,
          name: 'inserted_image.${_extensionForImageMime(content.mimeType)}',
        );
      } else {
        final uri = content.uri.trim();
        if (uri.isNotEmpty) {
          item = await PlatformClipboardMedia.copyUri(
            uri: uri,
            mime: content.mimeType,
          );
        }
      }

      if (!mounted) return;
      if (item == null) {
        _showClipboardPasteSnackBar(
          ru: 'Не удалось вставить изображение',
          en: 'Could not paste image',
        );
        return;
      }
      await _queueClipboardImageItem(targetId: targetId, item: item);
    } catch (error) {
      if (!mounted) return;
      _showClipboardPasteSnackBar(
        ru: 'Не удалось вставить изображение',
        en: 'Could not paste image',
      );
    }
  }

  Future<void> _queueClipboardImageItem({
    required String targetId,
    required PlatformClipboardMediaItem item,
  }) async {
    final path = item.path.trim();
    if (path.isEmpty) return;
    await _queueSelectedPhotoPaths(
      targetId: targetId,
      mediaItems: <ChatAttachmentPickerMediaItem>[
        ChatAttachmentPickerMediaItem(
          path: path,
          kind: ChatAttachmentPickerMediaKind.image,
          mime: item.resolvedMime,
        ),
      ],
    );
  }

  Future<String> _writeInsertedImageBytes(Uint8List bytes, String mime) async {
    final tempDir = await getTemporaryDirectory();
    final mediaDir = Directory(p.join(tempDir.path, 'secretly_inserted_media'));
    await mediaDir.create(recursive: true);
    unawaited(_pruneInsertedMediaTempDir(mediaDir));
    final extension = _extensionForImageMime(mime);
    final fileName =
        'inserted_${DateTime.now().microsecondsSinceEpoch}.$extension';
    final file = File(p.join(mediaDir.path, fileName));
    await file.writeAsBytes(bytes, flush: true);
    return file.path;
  }

  Future<void> _pruneInsertedMediaTempDir(Directory mediaDir) async {
    try {
      final cutoff = DateTime.now().subtract(const Duration(days: 3));
      await for (final entity in mediaDir.list(followLinks: false)) {
        if (entity is! File) continue;
        final modified = await entity.lastModified();
        if (modified.isBefore(cutoff)) {
          await entity.delete();
        }
      }
    } catch (_) {}
  }

  void _showClipboardPasteSnackBar({required String ru, required String en}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SecretlySnackBar(
        content: Text(chatText(context, ru: ru, en: en)),
      ),
    );
  }

  bool _isImageMime(String mime) {
    return mime.trim().toLowerCase().startsWith('image/');
  }

  String _extensionForImageMime(String mime) {
    final normalized = mime.trim().toLowerCase();
    if (normalized.contains('png')) return 'png';
    if (normalized.contains('webp')) return 'webp';
    if (normalized.contains('gif')) return 'gif';
    if (normalized.contains('heic')) return 'heic';
    if (normalized.contains('heif')) return 'heif';
    if (normalized.contains('bmp')) return 'bmp';
    if (normalized.contains('tiff')) return 'tiff';
    return 'jpg';
  }

  Future<void> _sendFileAttachmentPath({
    required String targetId,
    required String filePath,
    String? fileName,
  }) async {
    final path = filePath.trim();
    final file = File(path);
    if (path.isEmpty || !await file.exists()) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.attachmentFileMissing)),
      );
      return;
    }

    // Preserve the picker's original file name (PlatformFile.name) so the
    // document bubble shows the real name + format.
    final resolvedFileName = (fileName != null && fileName.trim().isNotEmpty)
        ? fileName.trim()
        : p.basename(path);
    final totalBytes = await file.length();
    if (!mounted) return;

    // BACKGROUND, SERIALIZED upload (controller-owned worker): the document
    // bubble appears instantly and uploads in the background — no blocking
    // modal, and the send is queued so it never races another send. Owned by
    // the controller so the bubble survives leaving/re-entering the chat.
    final pending = PendingPhotoUpload(
      id: DateTime.now().microsecondsSinceEpoch.toString(),
      filePath: path,
      mime: _guessMime(path) ?? 'application/octet-stream',
      caption: '',
      totalBytes: totalBytes,
      convoId: widget.convoId,
      targetId: targetId,
      isGroup: _isGroupChat,
      topicId: _isGroupChat ? _currentTopicId : null,
      replyToPayloadEventId: _replyTo?.payloadEventId,
      filename: resolvedFileName,
      asFile: true,
    );
    setState(() => _replyTo = null);
    widget.controller.enqueuePhotoUpload(pending);
  }

  Future<void> _sendAudioAttachmentPath({
    required String targetId,
    required String filePath,
  }) async {
    final path = filePath.trim();
    if (path.isEmpty || !await File(path).exists()) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.attachmentFileMissing)),
      );
      return;
    }

    await _enqueuePendingAudioFile(
      targetId: targetId,
      filePath: path,
      replyToPayloadEventId: _replyTo?.payloadEventId,
    );
  }

  Future<void> _attach() async {
    final targetId = _composerAttachmentTargetId();
    if (targetId.isEmpty) return;

    if (!_ensureComposerMediaAllowed()) return;

    if (_sendingAttachment) return;

    // Keep composer unfocused while attachment sheet is open and after close.
    _messageInputFocusNode.unfocus();
    FocusManager.instance.primaryFocus?.unfocus();
    SystemChannels.textInput.invokeMethod<void>('TextInput.hide');

    // Polls + topics are room-only, so those chips only appear in groups.
    // The actual permission for creating a topic is enforced when the topic
    // list is broadcast (broadcastRoomTopics), so the chip itself shows for any
    // group member — mirroring how «Опрос» behaves.
    final selection = await showChatAttachmentPickerSheet(
      context,
      showPoll: _isGroupChat,
      showTopic: _isGroupChat,
      showEvent: _isGroupChat,
    );
    if (!mounted || selection == null) return;

    try {
      switch (selection.kind) {
        case ChatAttachmentPickerResultKind.photos:
          await _queueSelectedPhotoPaths(
            targetId: targetId,
            mediaItems: selection.mediaItems,
          );
          return;
        case ChatAttachmentPickerResultKind.filesFromGallery:
          // Telegram-style «Галерея» on the FILE tab: gallery photos/videos
          // sent AS FILES (uncompressed, full quality) through the generic-file
          // path — each its OWN document bubble (no album grouping).
          await _queueGalleryPhotosAsFiles(
            targetId: targetId,
            mediaItems: selection.mediaItems,
          );
          return;
        case ChatAttachmentPickerResultKind.file:
          final path = selection.primaryPath;
          if (path == null) return;
          await _sendFileAttachmentPath(
            targetId: targetId,
            filePath: path,
            fileName: selection.fileName,
          );
          return;
        case ChatAttachmentPickerResultKind.audio:
          final path = selection.primaryPath;
          if (path == null) return;
          await _sendAudioAttachmentPath(targetId: targetId, filePath: path);
          return;
        case ChatAttachmentPickerResultKind.poll:
          await _openPollComposer(targetId: targetId);
          return;
        case ChatAttachmentPickerResultKind.topic:
          await _createTopic();
          return;
        case ChatAttachmentPickerResultKind.event:
          await _openEventComposer(targetId: targetId);
          return;
      }
    } catch (e) {
      if (!mounted) return;
      await _reportAttachmentError(e);
    }
  }

  Future<void> _voteOnPoll(_PollViewData poll, Set<int> tappedIndices) async {
    if (!_isGroupChat || poll.isClosed) return;
    final Set<int> next;
    if (poll.multiple) {
      // Toggle each tapped option on/off in my current selection.
      next = <int>{...poll.myOptionIndices};
      for (final index in tappedIndices) {
        if (next.contains(index)) {
          next.remove(index);
        } else {
          next.add(index);
        }
      }
    } else {
      // Single choice: tapping the already-selected option retracts it.
      if (tappedIndices.length == 1 &&
          poll.myOptionIndices.contains(tappedIndices.first)) {
        next = <int>{};
      } else {
        next = <int>{...tappedIndices};
      }
    }
    try {
      await widget.controller.voteGroupPoll(
        groupId: widget.convoId,
        pollId: poll.pollId,
        optionIndices: next.toList(growable: false),
      );
    } catch (e) {
      if (!mounted) return;
      await _reportAttachmentError(e);
    }
  }

  Future<void> _closePoll(_PollViewData poll) async {
    if (!_isGroupChat || poll.isClosed || !poll.isCreator) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(
          chatText(
            dialogContext,
            ru: 'Завершить опрос?',
            en: 'Close this poll?',
          ),
        ),
        content: Text(
          chatText(
            dialogContext,
            ru: 'Никто больше не сможет проголосовать. Это действие нельзя отменить.',
            en: 'No one will be able to vote anymore. This can\'t be undone.',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: Text(chatText(dialogContext, ru: 'Отмена', en: 'Cancel')),
          ),
          TextButton(
            style: TextButton.styleFrom(foregroundColor: Colors.red),
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: Text(
              chatText(dialogContext, ru: 'Завершить', en: 'Close'),
            ),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    try {
      await widget.controller.closeGroupPoll(
        groupId: widget.convoId,
        pollId: poll.pollId,
      );
    } catch (e) {
      if (!mounted) return;
      await _reportAttachmentError(e);
    }
  }

  Future<void> _rsvpEvent(_EventViewData event, String status) async {
    if (!_isGroupChat) return;
    // Tapping the active status again clears it — an empty status is a real,
    // already-modeled "no response yet" state (see _EventViewData.myStatus
    // docstring), so it round-trips correctly through the tally switch above
    // (an empty string matches none of the going/maybe/no cases).
    final next = event.myStatus == status ? '' : status;
    try {
      await widget.controller.rsvpGroupEvent(
        groupId: widget.convoId,
        eventId: event.eventId,
        status: next,
      );
    } catch (e) {
      if (!mounted) return;
      await _reportAttachmentError(e);
    }
  }

  Future<void> _openEventComposer({required String targetId}) async {
    final draft = await showModalBottomSheet<_EventDraft>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => const _EventComposerSheet(),
    );
    if (draft == null || !mounted) return;
    try {
      await widget.controller.sendGroupEvent(
        groupId: targetId,
        title: draft.title,
        startMs: draft.startMs,
        description: draft.description,
        location: draft.location,
        topicId: _currentTopicId,
      );
    } catch (e) {
      if (!mounted) return;
      await _reportAttachmentError(e);
    }
  }

  Future<void> _openPollComposer({required String targetId}) async {
    final draft = await showModalBottomSheet<_PollDraft>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => const _PollComposerSheet(),
    );
    if (draft == null || !mounted) return;
    try {
      await widget.controller.sendGroupPoll(
        groupId: targetId,
        question: draft.question,
        options: draft.options,
        multiple: draft.multiple,
        anonymous: draft.anonymous,
        topicId: _currentTopicId,
      );
    } catch (e) {
      if (!mounted) return;
      await _reportAttachmentError(e);
    }
  }

  void _insertTextAtCursor(String value) {
    final textValue = _text.value;
    final full = textValue.text;
    final sel = textValue.selection;
    final start = (sel.start >= 0 && sel.start <= full.length)
        ? sel.start
        : full.length;
    final end = (sel.end >= 0 && sel.end <= full.length)
        ? sel.end
        : full.length;
    final left = full.substring(0, start);
    final right = full.substring(end);
    final next = '$left$value$right';
    final caret = left.length + value.length;
    _text.value = TextEditingValue(
      text: next,
      selection: TextSelection.collapsed(offset: caret),
      composing: TextRange.empty,
    );
    _messageInputFocusNode.requestFocus();
  }

  /// Emoji catalog shared by the composer panel ([_openEmojiPanel]) and the
  /// premium reaction picker ([_pickReactionEmoji]). Single source of truth so
  /// both surfaces stay in sync.
  List<({String label, List<String> emoji})> _emojiPickerCategories(
    BuildContext context,
  ) {
    // Localized section titles for the 9 Noto animation categories.
    String labelFor(String slug) {
      switch (slug) {
        case 'smileys_and_emotions':
          return chatText(
            context,
            ru: 'Смайлики и эмоции',
            en: 'Smileys & emotions',
            uk: 'Смайли та емоції',
            es: 'Emoticonos',
            pt: 'Emoticons',
            ptBr: 'Emoticons',
            fr: 'Émoticônes',
            de: 'Smileys & Emotionen',
          );
        case 'people':
          return chatText(
            context,
            ru: 'Люди и жесты',
            en: 'People & body',
            uk: 'Люди та жести',
            es: 'Personas',
            pt: 'Pessoas',
            ptBr: 'Pessoas',
            fr: 'Personnes',
            de: 'Personen',
          );
        case 'animals_and_nature':
          return chatText(
            context,
            ru: 'Животные и природа',
            en: 'Animals & nature',
            uk: 'Тварини та природа',
            es: 'Animales y naturaleza',
            pt: 'Animais e natureza',
            ptBr: 'Animais e natureza',
            fr: 'Animaux et nature',
            de: 'Tiere & Natur',
          );
        case 'food_and_drink':
          return chatText(
            context,
            ru: 'Еда и напитки',
            en: 'Food & drink',
            uk: 'Їжа та напої',
            es: 'Comida y bebida',
            pt: 'Comida e bebida',
            ptBr: 'Comida e bebida',
            fr: 'Nourriture et boissons',
            de: 'Essen & Trinken',
          );
        case 'travel_and_places':
          return chatText(
            context,
            ru: 'Путешествия и места',
            en: 'Travel & places',
            uk: 'Подорожі та місця',
            es: 'Viajes y lugares',
            pt: 'Viagens e lugares',
            ptBr: 'Viagens e lugares',
            fr: 'Voyages et lieux',
            de: 'Reisen & Orte',
          );
        case 'activities_and_events':
          return chatText(
            context,
            ru: 'Активности',
            en: 'Activities',
            uk: 'Активності',
            es: 'Actividades',
            pt: 'Atividades',
            ptBr: 'Atividades',
            fr: 'Activités',
            de: 'Aktivitäten',
          );
        case 'objects':
          return chatText(
            context,
            ru: 'Предметы',
            en: 'Objects',
            uk: 'Об’єкти',
            es: 'Objetos',
            pt: 'Objetos',
            ptBr: 'Objetos',
            fr: 'Objets',
            de: 'Objekte',
          );
        case 'symbols':
          return chatText(
            context,
            ru: 'Символы',
            en: 'Symbols',
            uk: 'Символи',
            es: 'Símbolos',
            pt: 'Símbolos',
            ptBr: 'Símbolos',
            fr: 'Symboles',
            de: 'Symbole',
          );
        case 'flags':
          return chatText(
            context,
            ru: 'Флаги',
            en: 'Flags',
            uk: 'Прапори',
            es: 'Banderas',
            pt: 'Bandeiras',
            ptBr: 'Bandeiras',
            fr: 'Drapeaux',
            de: 'Flaggen',
          );
        default:
          return slug;
      }
    }

    // Bucket the full 881-emoji catalog by category, preserving manifest order.
    final buckets = <String, List<String>>{
      for (final slug in kNotoCategoryOrder) slug: <String>[],
    };
    for (final emoji in kNotoCodepoints.keys) {
      // Skin-tone variants are collapsed under their base swatch (chooser on tap).
      if (kNotoSkinToneHidden.contains(emoji)) continue;
      final slug = kNotoCategories[emoji] ?? 'symbols';
      (buckets[slug] ??= <String>[]).add(emoji);
    }
    return [
      for (final slug in kNotoCategoryOrder)
        if ((buckets[slug] ?? const <String>[]).isNotEmpty)
          (label: labelFor(slug), emoji: buckets[slug]!),
    ];
  }

  /// Premium reaction affordance (TZ-MONETIZE-01 §C-3): tapping the "+" at the
  /// end of the quick-reaction strip lands here.
  ///
  /// Fail-open contract: when monetization is disabled (kill-switch off) the
  /// entitlement state resolves to fully-open, so [FeatureGate.isUnlocked]
  /// returns true and the gate is INERT — the picker opens for everyone. Only
  /// when monetization is enabled AND the profile is on the free tier do we show
  /// the paywall instead. Security features are untouched (Appendix B).
  Future<void> _handleMoreReactions(_TimelineEntry entry) async {
    final unlocked = FeatureGate.isUnlocked(
      widget.controller.entitlementStateNow,
      GatedFeature.premiumStickers,
    );
    if (!unlocked) {
      if (!mounted) return;
      await showPaywall(context, PaywallTrigger.cosmetic);
      return;
    }

    final emoji = await _pickReactionEmoji();
    if (emoji == null || emoji.trim().isEmpty || !mounted) return;
    await _applyReaction(
      eventId: entry.payloadEventId ?? entry.event.eventId,
      emoji: emoji,
    );
  }

  /// Full emoji picker used for premium reactions. Returns the chosen emoji, or
  /// null if dismissed. Read-only over the same catalog as the composer panel;
  /// does not touch the message send/receive path. Shares its body
  /// ([_ReactionEmojiPicker]) with the in-place expanded reaction popup.
  Future<String?> _pickReactionEmoji() async {
    final emojiCategory = _emojiPickerCategories(context);

    return showModalBottomSheet<String>(
      context: context,
      enableDrag: true,
      isDismissible: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withValues(alpha: 0.38),
      builder: (sheetCtx) {
        final sheetHeight = (MediaQuery.of(sheetCtx).size.height * 0.62)
            .clamp(360.0, 720.0)
            .toDouble();
        final safeBottom = MediaQuery.paddingOf(sheetCtx).bottom;

        // Во всю ширину и за системной панелью; отступ под неё содержимое уже
        // получает через `bottomInset`.
        return SecretlyGlassSheetSurface(
          borderRadius: const BorderRadius.vertical(top: Radius.circular(30)),
          flushToEdges: true,
          child: SizedBox(
            height: sheetHeight + safeBottom,
            child: _ReactionEmojiPicker(
              categories: emojiCategory,
              bottomInset: safeBottom + 16,
              onPick: (chosen) => Navigator.of(sheetCtx).pop(chosen),
            ),
          ),
        );
      },
    );
  }

