  /// F0 photo→sticker flow: pick a photo, square-crop it (reusing the proven
  /// CoverCropScreen), downscale to the 512px sticker canvas, and send it as a
  /// user sticker (E2EE blob) to [targetId]. The AI cutout + full editor land in
  /// later phases (F1+).
  Future<void> _createStickerFromPhoto(String targetId) async {
    // Choose: a sticker from a PHOTO, or a TEXT-only sticker (no photo).
    final mode = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: const Color(0xFF1C1C1E),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetCtx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const SizedBox(height: 8),
            ListTile(
              leading: const Icon(Icons.photo_rounded, color: Colors.white),
              title: const Text(
                'Из фото',
                style: TextStyle(color: Colors.white),
              ),
              onTap: () => Navigator.of(sheetCtx).pop('photo'),
            ),
            ListTile(
              leading: const Icon(Icons.title_rounded, color: Colors.white),
              title: const Text(
                'Текстовый стикер',
                style: TextStyle(color: Colors.white),
              ),
              onTap: () => Navigator.of(sheetCtx).pop('text'),
            ),
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
    if (mode == null || !mounted) return;
    try {
      final textOnly = mode == 'text';
      String sourcePath = '';
      if (!textOnly) {
        final picked = await ImagePicker().pickImage(
          source: ImageSource.gallery,
          maxWidth: 2048,
          maxHeight: 2048,
          imageQuality: 95,
        );
        if (picked == null || !mounted) return;
        sourcePath = picked.path;
      }

      // The editor pushes the preview itself and bubbles the final result back,
      // so Back steps editor → here without auto-sending. The preview saves to
      // packs on its own; the chat only sends.
      final result = await Navigator.of(context).push<StickerFlowResult>(
        MaterialPageRoute(
          builder: (_) => StickerEditorScreen(
            sourcePath: sourcePath,
            controller: widget.controller,
            textOnly: textOnly,
          ),
        ),
      );
      if (result == null || !mounted) return;

      if (result.action == StickerPreviewAction.send) {
        // An «оживлённый» sticker is already a finished animated WebP — send it
        // as-is (the PNG finalizer would flatten it to one frame). Static
        // stickers still go through _finalizeStickerPng.
        final isAnimated = result.format == SecretlyStickerFormat.webp;
        final filePath = isAnimated
            ? result.stickerPath
            : await _finalizeStickerPng(result.stickerPath);
        if (!mounted) return;
        await widget.controller.sendUserStickerFromFile(
          peerProfileId: targetId,
          stickerFile: File(filePath),
          emoji: result.emoji,
          format: result.format,
          animated: isAnimated,
        );
      }
      // StickerPreviewAction.done — already saved to a pack by the preview.
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(
            '${chatText(context, ru: 'Не удалось создать стикер', en: 'Could not create sticker')}: $e',
          ),
        ),
      );
    }
  }

  /// Fit the square crop into the 512px sticker canvas and re-encode as PNG.
  /// Returns the original path on any failure (always yields a usable file).
  Future<String> _finalizeStickerPng(String srcPath) async {
    try {
      final bytes = await File(srcPath).readAsBytes();
      final decoded = img.decodeImage(bytes);
      if (decoded == null) return srcPath;
      final tallest = decoded.height > decoded.width;
      final longest = tallest ? decoded.height : decoded.width;
      final img.Image sized = longest > 512
          ? img.copyResize(
              decoded,
              width: tallest ? null : 512,
              height: tallest ? 512 : null,
              interpolation: img.Interpolation.average,
            )
          : decoded;
      final out = img.encodePng(sized, level: 9);
      final dir = await getTemporaryDirectory();
      final path =
          '${dir.path}/sticker_${DateTime.now().millisecondsSinceEpoch}.png';
      await File(path).writeAsBytes(out, flush: true);
      return path;
    } catch (_) {
      return srcPath;
    }
  }

  /// Tap a sticker → open the pack it belongs to. For a local pack (our own /
  /// already installed) the whole set is shown immediately. For a sticker a peer
  /// sent us we hold only the one — the sheet offers «Установить», which pulls
  /// the rest of the author's pack over the e2ee WS and installs it.
  Future<void> _showStickerPackSheet(StickerEventV1 event) async {
    FocusManager.instance.primaryFocus?.unfocus();
    // Best-effort resolve of the TAPPED sticker so the sheet has something to
    // show before (or instead of) a full install.
    SecretlyStickerDescriptor? tapped;
    try {
      tapped = await widget.controller.ensureUserStickerCached(event);
    } catch (_) {}
    tapped ??= SecretlyStickerCatalog.resolveEvent(event);
    if (!mounted) return;

    final myPid = widget.controller.profileId;
    final packId = event.packId;
    // Author to fetch the pack from: the stamped origin, else (1-1 chat) the
    // conversation peer = the sender of this received sticker. Empty for groups.
    final stampedOrigin = event.packOriginPid ?? '';
    final originPid = stampedOrigin.isNotEmpty
        ? stampedOrigin
        : (widget.convoId.startsWith('group:') ? '' : widget.convoId.trim());
    final isOwnPack = packId.startsWith('user:$myPid');

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: const Color(0xFF1B1E25),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetCtx) => _StickerPackSheet(
        controller: widget.controller,
        event: event,
        packId: packId,
        originPid: originPid,
        isOwnPack: isOwnPack,
        tappedSticker: tapped,
        onSendSticker: (descriptor) async {
          Navigator.of(sheetCtx).pop();
          await _sendSticker(targetId: widget.convoId, sticker: descriptor);
        },
      ),
    );
  }

  Future<void> _sendSticker({
    required String targetId,
    required SecretlyStickerDescriptor sticker,
  }) async {
    if (targetId.isEmpty) return;
    try {
      if (mounted) setState(() => _sendingAttachment = true);
      await widget.controller.sendSticker(
        peerProfileId: targetId,
        sticker: sticker,
        replyToPayloadEventId: _replyTo?.payloadEventId,
      );
      if (mounted) setState(() => _replyTo = null);
    } catch (e) {
      if (!mounted) return;
      final roomPolicyText = tryRoomPolicyErrorText(context.l10n, e);
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(
            roomPolicyText ??
                chatText(
                  context,
                  ru: 'Стикер не отправлен: $e',
                  en: 'Sticker was not sent: $e',
                  uk: 'Стікер не надіслано: $e',
                  es: 'No se envio el sticker: $e',
                  pt: 'O sticker nao foi enviado: $e',
                  ptBr: 'O sticker nao foi enviado: $e',
                  fr: 'Le sticker na pas ete envoye : $e',
                  de: 'Sticker wurde nicht gesendet: $e',
                ),
          ),
        ),
      );
    } finally {
      if (mounted) setState(() => _sendingAttachment = false);
    }
  }

  /// Стоит ли повторять неудавшуюся загрузку GIF.
  ///
  /// 🔴 Только сетевой класс. Ответ сервера — это доказательство, что связь
  /// есть, и повторять его бессмысленно: «нет такой гифки» останется тем же
  /// самым, лишь втрое медленнее. 5xx обрабатывается отдельно, в самом цикле.
  static bool _gifDownloadIsWorthRetrying(Object error) =>
      error is SocketException ||
      error is TimeoutException ||
      error is HandshakeException ||
      error is http_pkg.ClientException;

  /// Скачивает GIF, переживая пропавший маршрут.
  ///
  /// 🔴 ПОЧЕМУ ПОВТОР (07.08.2026, полевая жалоба со скриншотом:
  /// «ClientException with SocketException: No route to host, errno = 113,
  /// address = media3.giphy.com»). errno 113 (EHOSTUNREACH) — это не «нет
  /// интернета», а «маршрута к хосту прямо сейчас нет»: переход между сетями,
  /// просыпающееся радио, мёртвый маршрут IPv6 при живой AAAA-записи. Через
  /// секунду на свежем сокете он почти всегда есть. Приложение уже знает этот
  /// отказ в лицо — `_isConnectStallFailure` в resilient_http_client_io.dart
  /// перечисляет и errno 113, и строку 'no route to host' (диагноз 19.06 по
  /// Xiaomi). До этой правки здесь была ровно одна попытка, и отправка гибла
  /// навсегда от секундного провала маршрута.
  ///
  /// 🔴 ПОЧЕМУ НЕ ЧЕРЕЗ createResilientHttpClient(), хотя весь остальной
  /// сетевой код идёт через него. Его лечение — обход по литеральному IPv4 из
  /// таблицы, а в таблице только свои хосты (relay/keys/links). Для Giphy
  /// записи нет и быть не может: это Fastly, адрес переезжает. Без записи тот
  /// клиент делает обычный connect — то есть пропустить GIF через него значило
  /// бы изобразить лечение, ничего не вылечив.
  ///
  /// 🔴 ПОЧЕМУ НЕ ПЕРЕБОР ЗЕРКАЛ media0…media4. Проверено: все пять — один
  /// CNAME Fastly и один адрес. Перебор хостов повторил бы тот же отказ
  /// дословно.
  Future<http_pkg.Response> _downloadGifWithRetry(String gifUrl) async {
    const maxAttempts = 3;
    const backoff = <Duration>[
      Duration(milliseconds: 600),
      Duration(milliseconds: 1500),
    ];
    final uri = Uri.parse(gifUrl);
    Object lastError = const SocketException('GIF download failed');

    for (var attempt = 0; attempt < maxAttempts; attempt++) {
      if (attempt > 0) {
        await Future<void>.delayed(backoff[attempt - 1]);
        // Экран закрыли, пока мы ждали — отправлять уже некуда и некому.
        if (!mounted) break;
      }
      try {
        final resp =
            await http_pkg.get(uri).timeout(const Duration(seconds: 20));
        if (resp.statusCode == 200) return resp;
        final failure = HttpException('HTTP ${resp.statusCode}', uri: uri);
        // 🔴 Сервер ОТВЕТИЛ — связь есть, и дело не в ней. Повторяем только
        // 5xx: они бывают временными, а 404/410 значит «гифки больше нет» и
        // повтором не лечится.
        if (resp.statusCode < 500) throw failure;
        lastError = failure;
      } catch (error) {
        if (!_gifDownloadIsWorthRetrying(error)) rethrow;
        lastError = error;
      }
    }
    throw lastError;
  }

  Future<void> _sendGifUrl({
    required String targetId,
    required String gifUrl,
  }) async {
    if (targetId.isEmpty) return;
    final replyToPayloadEventId = _replyTo?.payloadEventId;
    try {
      if (mounted) setState(() => _sendingAttachment = true);
      final resp = await _downloadGifWithRetry(gifUrl);
      // Persist to a temp file so the GIF takes the SAME room/DM attachment
      // routing as every other media. The old code called sendAttachment()
      // unconditionally — that path is DM-only (no `group:` routing), so GIFs
      // never reached room members. Route rooms through sendGroupAttachmentFile.
      final tmpDir = await getTemporaryDirectory();
      final gifFile = File(
        '${tmpDir.path}/gif_${DateTime.now().millisecondsSinceEpoch}.gif',
      );
      await gifFile.writeAsBytes(resp.bodyBytes, flush: true);
      if (_isGroupChat) {
        await widget.controller.sendGroupAttachmentFile(
          groupId: widget.convoId,
          filePath: gifFile.path,
          mime: 'image/gif',
          replyToPayloadEventId: replyToPayloadEventId,
          topicId: _currentTopicId,
        );
      } else {
        final peerProfileId = widget.peerProfileIdForSend ?? targetId;
        if (peerProfileId.trim().isEmpty) return;
        await widget.controller.sendAttachmentFile(
          peerProfileId: peerProfileId,
          filePath: gifFile.path,
          mime: 'image/gif',
          replyToPayloadEventId: replyToPayloadEventId,
        );
      }
      if (mounted) setState(() => _replyTo = null);
    } catch (e) {
      if (!mounted) return;
      // 🔴 Сырое исключение человеку НЕ показываем. До этой правки сюда
      // подставлялось `$e` целиком, и на экран выпадала стена из
      // ClientException + SocketException + errno + номера порта + URL на две
      // сотни символов — ровно то, что человек прислал скриншотом. Разделение
      // на «связь» и «всё остальное» — это единственное, что ему нужно знать:
      // первое лечится повтором, второе нет.
      final connectionFailed = _gifDownloadIsWorthRetrying(e);
      final message = connectionFailed
          ? chatText(
              context,
              ru: 'GIF не отправлен: связь прервалась',
              en: 'GIF was not sent: the connection dropped',
              uk: 'GIF не надіслано: зв\'язок перервався',
              es: 'No se envio el GIF: se perdio la conexion',
              pt: 'O GIF nao foi enviado: a ligacao caiu',
              ptBr: 'O GIF nao foi enviado: a conexao caiu',
              fr: 'Le GIF na pas ete envoye : la connexion a ete perdue',
              de: 'GIF wurde nicht gesendet: die Verbindung wurde unterbrochen',
            )
          : chatText(
              context,
              ru: 'GIF не отправлен',
              en: 'GIF was not sent',
              uk: 'GIF не надіслано',
              es: 'No se envio el GIF',
              pt: 'O GIF nao foi enviado',
              ptBr: 'O GIF nao foi enviado',
              fr: 'Le GIF na pas ete envoye',
              de: 'GIF wurde nicht gesendet',
            );
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(message),
          // 🔴 ЛОВУШКА: `SecretlySnackBar` делит заданную длительность ПОПОЛАМ
          // (`_shortenedDuration`), а по умолчанию держит плашку 2 секунды. За
          // две секунды кнопку не нажать, поэтому здесь 12 → на экране 6.
          duration: const Duration(seconds: 12),
          // 🔴 Без этой кнопки гифка просто терялась: URL оставался у нас в
          // руках, а человеку приходилось заново открывать подборщик и искать
          // её среди лент. Ответ (`_replyTo`) при неудаче не сбрасывается —
          // он снимается только после успешной отправки, — так что повтор
          // уходит в тот же контекст, что и первая попытка.
          action: SnackBarAction(
            label: chatText(
              context,
              ru: 'Повторить',
              en: 'Retry',
              uk: 'Повторити',
              es: 'Reintentar',
              pt: 'Repetir',
              ptBr: 'Repetir',
              fr: 'Reessayer',
              de: 'Wiederholen',
            ),
            onPressed: () {
              if (!mounted) return;
              _sendGifUrl(targetId: targetId, gifUrl: gifUrl);
            },
          ),
        ),
      );
    } finally {
      if (mounted) setState(() => _sendingAttachment = false);
    }
  }

  String _voiceElapsedLabel(Duration value) {
    final minutes = value.inMinutes;
    final seconds = value.inSeconds % 60;
    final tenths = (value.inMilliseconds % 1000) ~/ 100;
    final secText = seconds.toString().padLeft(2, '0');
    return '$minutes:$secText,$tenths';
  }

  Future<void> _enqueuePendingAudioFile({
    required String targetId,
    required String filePath,
    String? replyToPayloadEventId,
    List<int>? waveform,
  }) async {
    final file = File(filePath);
    if (!await file.exists()) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.attachmentFileMissing)),
      );
      return;
    }
    final totalBytes = await file.length();
    final mime = (_guessMime(filePath) ?? '').toLowerCase();
    // 🔴 Голосовое пишется в AAC — `audio/mp4`, как обычная музыка, и по типу
    // его не отличить; отличает волна (17.09.2026). Раньше голосовое считалось
    // песней: заготовка рисовалась песней «voice_….m4a», а в сообщение уходило
    // «название» и имя файла.
    final isVoice =
        _isVoiceMessageMime(mime) || (waveform?.isNotEmpty ?? false);
    final fallbackTitle = p.basename(filePath);
    final pending = PendingAudioUpload(
      id: DateTime.now().microsecondsSinceEpoch.toString(),
      filePath: filePath,
      mime: mime.isNotEmpty ? mime : 'audio/mpeg',
      totalBytes: totalBytes,
      convoId: widget.convoId,
      targetId: targetId,
      isGroup: _isGroupChat,
      topicId: _isGroupChat ? _currentTopicId : null,
      replyToPayloadEventId: replyToPayloadEventId,
      isVoice: isVoice,
      title: isVoice ? null : fallbackTitle,
      waveform: waveform,
    );
    if (!mounted) return;
    if (!isVoice) {
      // Теги читаются вместе с постановкой в очередь, а очередь ждёт их перед
      // отправкой (`tagsReady`): стартует она сразу и раньше забирала подписи,
      // не дождавшись тегов.
      pending.tagsReady = () async {
        final tags = await MusicTagReader.read(filePath);
        if (tags == null) return;
        // Update the (controller-owned) model; repaint if we're still on-screen.
        pending.title = tags.title ?? fallbackTitle;
        pending.artist = tags.artist;
        pending.tagsFromFile = true;
        if (mounted) setState(() {});
      }();
    }
    setState(() => _replyTo = null);
    widget.controller.enqueueAudioUpload(pending);
  }

  Future<void> _startVoiceRecording() async {
    if (_voiceRecordingBusy || _voiceRecording) return;
    final targetId = _isGroupChat
        ? widget.convoId
        : (widget.peerProfileIdForSend ?? '');
    if (targetId.isEmpty) return;

    if (_isGroupChat && !_roomCanSendMediaNow()) {
      final text = _groupComposerPolicyBannerText(context.l10n);
      if (text != null && mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SecretlySnackBar(content: Text(text)));
      }
      return;
    }

    setState(() => _voiceRecordingBusy = true);
    try {
      final hasPermission = await _voiceRecorder.hasPermission();
      if (!hasPermission) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SecretlySnackBar(
            content: Text(
              chatText(
                context,
                ru: 'Нет доступа к микрофону',
                en: 'Microphone access is not available',
                uk: 'Немає доступу до мікрофона',
                es: 'No hay acceso al microfono',
                pt: 'Sem acesso ao microfone',
                ptBr: 'Sem acesso ao microfone',
                fr: 'Acces au microphone indisponible',
                de: 'Kein Zugriff auf das Mikrofon',
              ),
            ),
          ),
        );
        return;
      }

      final dir = await getTemporaryDirectory();
      final path = p.join(
        dir.path,
        'voice_${DateTime.now().microsecondsSinceEpoch}.m4a',
      );
      const config = RecordConfig(
        encoder: AudioEncoder.aacLc,
        bitRate: 128000,
        sampleRate: 44100,
      );
      await _voiceRecorder.start(config, path: path);

      // Begin sampling the live amplitude envelope (dBFS) for the waveform.
      _voiceAmpSamples.clear();
      _voiceAmpSub?.cancel();
      _voiceAmpSub = _voiceRecorder
          .onAmplitudeChanged(const Duration(milliseconds: 90))
          .listen((amp) {
            // current is in dBFS: ~0 (loud) down to ~-60 (silence). Map a
            // useful speech range [-45, 0] → [0, 1].
            const floorDb = 45.0;
            final norm = ((amp.current + floorDb) / floorDb).clamp(0.0, 1.0);
            _voiceAmpSamples.add(norm);
          }, onError: (_) {});

      _voiceTimer?.cancel();
      _voiceStartedAt = DateTime.now();
      _voiceRecordingPath = path;
      _voiceElapsed = Duration.zero;
      _voiceTimer = Timer.periodic(const Duration(milliseconds: 90), (_) {
        final started = _voiceStartedAt;
        if (!mounted || started == null || !_voiceRecording) return;
        setState(() {
          _voiceElapsed = DateTime.now().difference(started);
        });
      });

      if (!mounted) return;
      HapticFeedback.selectionClick();
      setState(() {
        _voiceRecording = true;
        _voiceRecordingLocked = false;
        _voiceRecordingCancelHint = false;
        _voiceDragDx = 0;
        _voiceDragDy = 0;
      });
      _syncComposerTickers();
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.sendFailed(e.toString()))),
      );
    } finally {
      if (mounted) setState(() => _voiceRecordingBusy = false);
    }
  }

  // ── Raw pointer handlers for voice button ──────────────────────────────
  // Using Listener instead of GestureDetector so swipes register immediately
  // without waiting for the ~500 ms long-press recognition delay.

  void _onVoicePointerDown(PointerDownEvent event) {
    if (_voiceRecording || _voiceRecordingBusy) return;
    _voicePointerId = event.pointer;
    _voicePressOrigin = event.position;
    _capturePressPending = true;
    _voicePressTimer?.cancel();
    _voicePressTimer = Timer(const Duration(milliseconds: 200), () {
      if (!mounted) return;
      _capturePressPending = false;
      unawaited(_startVoiceRecording());
    });
  }

  void _onVoicePointerMove(PointerMoveEvent event) {
    if (event.pointer != _voicePointerId) return;
    final origin = _voicePressOrigin;
    if (origin == null) return;

    final dx = event.position.dx - origin.dx;
    final dy = event.position.dy - origin.dy;

    // Cancel press-timer early if user clearly swipes away before recording starts
    if (!_voiceRecording) {
      if (dx.abs() > 12 || dy.abs() > 12) {
        _capturePressPending = false;
      }
      if (dx <= -_voiceCancelThresholdPx * 0.5) {
        _voicePressTimer?.cancel();
        _voicePressTimer = null;
        _voicePointerId = null;
        _voicePressOrigin = null;
      }
      return;
    }

    if (_voiceRecordingLocked) return;

    final cancelHint = dx <= -_voiceCancelThresholdPx;
    final shouldLock = dy <= -_voiceLockThresholdPx;

    setState(() {
      _voiceDragDx = dx;
      _voiceDragDy = dy;
      _voiceRecordingCancelHint = cancelHint;
    });

    if (cancelHint) {
      HapticFeedback.lightImpact();
      _voicePointerId = null;
      _voicePressOrigin = null;
      unawaited(_cancelVoiceRecording());
      return;
    }

    if (shouldLock) {
      HapticFeedback.mediumImpact();
      _voiceLockBounceController.forward(from: 0);
      setState(() {
        _voiceRecordingLocked = true;
        _voiceRecordingCancelHint = false;
      });
    }
  }

  void _onVoicePointerUp(PointerUpEvent event) {
    if (event.pointer != _voicePointerId) return;
    final wasTap = _capturePressPending && _voicePressTimer?.isActive == true;
    _voicePressTimer?.cancel();
    _voicePressTimer = null;
    _voicePressOrigin = null;
    _voicePointerId = null;
    _capturePressPending = false;
    if (wasTap && !_voiceRecording) {
      _toggleComposerCaptureMode();
      return;
    }
    if (!_voiceRecording) return;
    if (_voiceRecordingLocked) return; // locked: user taps send/cancel manually
    unawaited(_finishVoiceRecording(send: true));
  }

  void _onVoicePointerCancel(PointerCancelEvent event) {
    if (event.pointer != _voicePointerId) return;
    _voicePressTimer?.cancel();
    _voicePressTimer = null;
    _voicePressOrigin = null;
    _voicePointerId = null;
    if (!_voiceRecording) return;
    if (_voiceRecordingLocked) return;
    unawaited(_cancelVoiceRecording());
  }

  // ── Unified composer capture pointer handlers ──────────────────────────
  // A quick TAP (no recording started, little movement) toggles voice⇄video.
  // A press-and-hold records in the active mode (voice OR video note); the
  // same swipe-up-to-lock / swipe-left-to-cancel gestures apply to both.

  /// True when the current press was released as a quick tap (the press-timer
  /// had not yet promoted it into a recording) — used to flip the mode.
  bool _capturePressPending = false;

  void _onCapturePointerDown(PointerDownEvent event) {
    if (_composerVideoMode) {
      _onVideoNotePointerDown(event);
    } else {
      _onVoicePointerDown(event);
    }
  }

  void _onCapturePointerMove(PointerMoveEvent event) {
    if (_composerVideoMode) {
      _onVideoNotePointerMove(event);
    } else {
      _onVoicePointerMove(event);
    }
  }

  void _onCapturePointerUp(PointerUpEvent event) {
    if (_composerVideoMode) {
      _onVideoNotePointerUp(event);
    } else {
      _onVoicePointerUp(event);
    }
  }

  void _onCapturePointerCancel(PointerCancelEvent event) {
    if (_composerVideoMode) {
      _onVideoNotePointerCancel(event);
    } else {
      _onVoicePointerCancel(event);
    }
  }

  void _onVideoNotePointerDown(PointerDownEvent event) {
    if (_videoNoteRecording || _videoNoteBusy) return;
    _voicePointerId = event.pointer;
    _voicePressOrigin = event.position;
    _capturePressPending = true;
    _voicePressTimer?.cancel();
    _voicePressTimer = Timer(const Duration(milliseconds: 220), () {
      if (!mounted) return;
      _capturePressPending = false;
      unawaited(_startVideoNoteRecording());
    });
  }

  void _onVideoNotePointerMove(PointerMoveEvent event) {
    if (event.pointer != _voicePointerId) return;
    final origin = _voicePressOrigin;
    if (origin == null) return;
    final dx = event.position.dx - origin.dx;
    final dy = event.position.dy - origin.dy;

    if (!_videoNoteRecording) {
      // Treat any meaningful movement before the timer fires as a drag, not a
      // tap — cancel the pending press so it does not toggle the mode.
      if (dx.abs() > 12 || dy.abs() > 12) {
        _capturePressPending = false;
        if (dx <= -_voiceCancelThresholdPx * 0.5) {
          _voicePressTimer?.cancel();
          _voicePressTimer = null;
          _voicePointerId = null;
          _voicePressOrigin = null;
        }
      }
      return;
    }

    final controller = _videoNoteRecorderController;
    if (controller == null) return;
    controller.updateDrag(dx: dx, dy: dy);
    if (dy <= -_voiceLockThresholdPx) {
      _voicePointerId = null;
      _voicePressOrigin = null;
      controller.signalLock();
    }
  }

  void _onVideoNotePointerUp(PointerUpEvent event) {
    if (event.pointer != _voicePointerId) return;
    final wasTap = _capturePressPending && _voicePressTimer?.isActive == true;
    _voicePressTimer?.cancel();
    _voicePressTimer = null;
    _voicePressOrigin = null;
    _voicePointerId = null;
    _capturePressPending = false;
    if (wasTap) {
      _toggleComposerCaptureMode();
      return;
    }
    if (!_videoNoteRecording) return;
    _videoNoteRecorderController?.signalRelease();
  }

  void _onVideoNotePointerCancel(PointerCancelEvent event) {
    if (event.pointer != _voicePointerId) return;
    _voicePressTimer?.cancel();
    _voicePressTimer = null;
    _voicePressOrigin = null;
    _voicePointerId = null;
    _capturePressPending = false;
    if (!_videoNoteRecording) return;
    _videoNoteRecorderController?.signalCancel();
  }

  Future<void> _cancelVoiceRecording() async {
    if (!_voiceRecording && !_voiceRecordingBusy) return;
    _voiceTimer?.cancel();
    try {
      await _voiceRecorder.cancel();
    } catch (_) {
      try {
        await _voiceRecorder.stop();
      } catch (_) {}
    }

    final tmp = _voiceRecordingPath;
    if (tmp != null && tmp.isNotEmpty) {
      try {
        final f = File(tmp);
        if (await f.exists()) await f.delete();
      } catch (_) {}
    }

    if (!mounted) return;
    setState(() {
      _voiceRecording = false;
      _voiceRecordingLocked = false;
      _voiceRecordingCancelHint = false;
      _voiceRecordingBusy = false;
      _voiceDragDx = 0;
      _voiceDragDy = 0;
      _voiceRecordingPath = null;
      _voiceStartedAt = null;
      _voiceElapsed = Duration.zero;
    });
    _syncComposerTickers();
  }

  Future<void> _finishVoiceRecording({required bool send}) async {
    if (!_voiceRecording) return;

    final elapsed = _voiceElapsed;
    _voiceTimer?.cancel();
    await _voiceAmpSub?.cancel();
    _voiceAmpSub = null;
    final waveform = _buildVoiceWaveform();
    _voiceAmpSamples.clear();
    String? path;
    try {
      path = await _voiceRecorder.stop();
    } catch (_) {
      path = null;
    }
    path ??= _voiceRecordingPath;

    if (!mounted) return;
    setState(() {
      _voiceRecording = false;
      _voiceRecordingLocked = false;
      _voiceRecordingCancelHint = false;
      _voiceRecordingBusy = false;
      _voiceDragDx = 0;
      _voiceDragDy = 0;
      _voiceRecordingPath = null;
      _voiceStartedAt = null;
      _voiceElapsed = Duration.zero;
    });
    _syncComposerTickers();

    if (!send || path == null || path.isEmpty) {
      if (path != null && path.isNotEmpty) {
        try {
          final f = File(path);
          if (await f.exists()) await f.delete();
        } catch (_) {}
      }
      return;
    }

    if (elapsed < _voiceMinDuration) {
      try {
        final f = File(path);
        if (await f.exists()) await f.delete();
      } catch (_) {}
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(
            chatText(
              context,
              ru: 'Слишком короткое аудио',
              en: 'Audio is too short',
              uk: 'Аудіо занадто коротке',
              es: 'El audio es demasiado corto',
              pt: 'O audio e curto demais',
              ptBr: 'O audio e curto demais',
              fr: 'Laudio est trop court',
              de: 'Audio ist zu kurz',
            ),
          ),
        ),
      );
      return;
    }

    final targetId = _isGroupChat
        ? widget.convoId
        : (widget.peerProfileIdForSend ?? '');
    if (targetId.isEmpty) return;
    await _enqueuePendingAudioFile(
      targetId: targetId,
      filePath: path,
      replyToPayloadEventId: _replyTo?.payloadEventId,
      waveform: waveform,
    );
  }

  /// Downsamples the captured amplitude stream to a fixed number of bars in
  /// [0, 100]. Uses the peak per bucket (punchier, Telegram-like) and a gentle
  /// normalisation against the loudest bar so quiet recordings still fill the
  /// strip. Returns null when nothing was captured (renderer falls back).
  List<int> _buildVoiceWaveform() {
    final samples = _voiceAmpSamples;
    final bars = _voiceWaveformBars;
    if (samples.isEmpty) {
      // Amplitude stream produced nothing on this device — still return a
      // (synthetic) envelope so the message is reliably recognised as a voice
      // note and renders with the waveform layout rather than the music card.
      final rng = Random(DateTime.now().microsecondsSinceEpoch);
      return List<int>.generate(bars, (_) {
        final r = rng.nextDouble();
        return (12 + r * r * 88).round().clamp(0, 100);
      }, growable: false);
    }
    final out = List<double>.filled(bars, 0);
    if (samples.length <= bars) {
      for (var i = 0; i < bars; i++) {
        final src = (i * samples.length / bars).floor().clamp(
          0,
          samples.length - 1,
        );
        out[i] = samples[src];
      }
    } else {
      for (var i = 0; i < bars; i++) {
        final start = (i * samples.length / bars).floor();
        final end = ((i + 1) * samples.length / bars).floor().clamp(
          start + 1,
          samples.length,
        );
        var peak = 0.0;
        for (var j = start; j < end; j++) {
          if (samples[j] > peak) peak = samples[j];
        }
        out[i] = peak;
      }
    }
    // Normalise against the loudest bar so the waveform always uses full range.
    var maxV = 0.0;
    for (final v in out) {
      if (v > maxV) maxV = v;
    }
    final scale = maxV > 0.05 ? 1.0 / maxV : 1.0;
    return out
        .map((v) => (v * scale * 100).round().clamp(0, 100))
        .toList(growable: false);
  }

  // ── Composer capture mode (voice ⇄ video note) ─────────────────────────
  Future<void> _restoreComposerCaptureMode() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      var video = prefs.getBool(_kComposerCaptureModePrefKey) ?? false;
      // Only restore video mode if camera + mic are ALREADY granted; else fall
      // back to voice so the first press-and-hold can't trigger a permission
      // dialog mid-gesture (which cancels the touch → the recorder flickered
      // open and shut). Re-toggling to video re-requests the permissions.
      if (video) {
        final camOk = await Permission.camera.isGranted;
        final micOk = await Permission.microphone.isGranted;
        if (!camOk || !micOk) video = false;
      }
      if (!mounted) return;
      if (video != _composerVideoMode) {
        setState(() => _composerVideoMode = video);
      }
    } catch (_) {}
  }

  void _toggleComposerCaptureMode() {
    if (_voiceRecording || _videoNoteRecording) return;
    if (!_composerVideoMode) {
      // Switching TO video: request camera + mic NOW (on this tap) so the
      // system permission dialog cannot interrupt the later press-and-hold
      // recording gesture — a mid-hold dialog cancels the touch and made the
      // recorder flicker open and close. Switch only once both are granted.
      unawaited(_enableVideoComposerMode());
      return;
    }
    setState(() => _composerVideoMode = false);
    HapticFeedback.selectionClick();
    _persistComposerCaptureMode(false);
  }

  Future<void> _enableVideoComposerMode() async {
    bool granted = false;
    try {
      final cam = await Permission.camera.request();
      final mic = await Permission.microphone.request();
      granted = cam.isGranted && mic.isGranted;
    } catch (_) {
      granted = false;
    }
    if (!mounted) return;
    if (!granted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(
            wave1Text(
              context,
              ru: 'Для видео нужен доступ к камере и микрофону',
              en: 'Video needs camera and microphone access',
              uk: 'Для відео потрібні камера та мікрофон',
              es: 'El video necesita cámara y micrófono',
              pt: 'O vídeo precisa de câmara e microfone',
              ptBr: 'O vídeo precisa de câmera e microfone',
              fr: 'La vidéo nécessite la caméra et le micro',
              de: 'Video braucht Kamera- und Mikrofonzugriff',
            ),
          ),
        ),
      );
      return;
    }
    setState(() => _composerVideoMode = true);
    HapticFeedback.selectionClick();
    _persistComposerCaptureMode(true);
  }

  void _persistComposerCaptureMode(bool video) {
    unawaited(() async {
      try {
        final prefs = await SharedPreferences.getInstance();
        await prefs.setBool(_kComposerCaptureModePrefKey, video);
      } catch (_) {}
    }());
  }

  // ── Video-note recording (driven by the composer press gesture) ────────
  Future<void> _startVideoNoteRecording() async {
    if (_videoNoteBusy || _videoNoteRecording) return;
    // Dismiss the keyboard before the round-video recorder opens — otherwise it
    // covers the recorder UI and there's no way to hide it mid-recording.
    _messageInputFocusNode.unfocus();
    FocusManager.instance.primaryFocus?.unfocus();
    final targetId = _isGroupChat
        ? widget.convoId
        : (widget.peerProfileIdForSend ?? '');
    if (targetId.isEmpty) return;

    if (_isGroupChat && !_roomCanSendMediaNow()) {
      final text = _groupComposerPolicyBannerText(context.l10n);
      if (text != null && mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SecretlySnackBar(content: Text(text)));
      }
      return;
    }

    _videoNoteBusy = true;
    final controller = VideoNoteRecorderController();
    _videoNoteRecorderController = controller;
    setState(() => _videoNoteRecording = true);
    HapticFeedback.selectionClick();

    VideoNoteRecorderResult? result;
    try {
      result = await showVideoNoteRecorder(context, controller: controller);
    } catch (_) {
      result = null;
    }

    _videoNoteRecorderController = null;
    _videoNoteBusy = false;
    if (mounted) {
      setState(() => _videoNoteRecording = false);
    }
    if (result == null) return;
    await _sendVideoNote(result);
  }

  Future<void> _sendVideoNote(VideoNoteRecorderResult result) async {
    final replyToPayloadEventId = _replyTo?.payloadEventId;
    try {
      if (_isGroupChat) {
        await widget.controller.sendGroupAttachmentFile(
          groupId: widget.convoId,
          filePath: result.filePath,
          mime: 'video/mp4',
          videoNote: true,
          durationMs: result.durationMs,
          replyToPayloadEventId: replyToPayloadEventId,
          topicId: _currentTopicId,
        );
      } else {
        final peerProfileId = widget.peerProfileIdForSend ?? '';
        if (peerProfileId.isEmpty) return;
        await widget.controller.sendAttachmentFile(
          peerProfileId: peerProfileId,
          filePath: result.filePath,
          mime: 'video/mp4',
          videoNote: true,
          durationMs: result.durationMs,
          replyToPayloadEventId: replyToPayloadEventId,
        );
      }
      if (mounted && _replyTo != null) {
        setState(() => _replyTo = null);
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.sendFailed(e.toString()))),
      );
    } finally {
      try {
        final f = File(result.filePath);
        if (await f.exists()) await f.delete();
      } catch (_) {}
    }
  }

  /// All three composer actions (send / voice / video) route through here, so
  /// the forgiving touch target and the water-drop press are automatically the
  /// same on each — see [_ComposerActionButton].
  Widget _buildComposerActionButton({
    Key? key,
    required Color topColor,
    required Color bottomColor,
    required Color iconColor,
    required double size,
    required Widget child,
    VoidCallback? onPressed,
    VoidCallback? onLongPress,
    FocusNode? focusNode,
  }) {
    return _ComposerActionButton(
      key: key,
      topColor: topColor,
      bottomColor: bottomColor,
      iconColor: iconColor,
      size: size,
      onPressed: onPressed,
      onLongPress: onLongPress,
      focusNode: focusNode,
      child: child,
    );
  }

  // Frosted-glass "island" for the experimental chat header: a back circle,
  // an identity pill (avatar + name), an actions pill, and the search bubble.
  // Density matches the top bar / bottom nav so the islands feel native.
  /// Панель подписана на `_audioTick` сама: позиция здесь меняется пять раз в
  /// секунду, и без подписки полоса прогресса в шапке застыла бы, пока полоса
  /// в пузыре ленты продолжает ехать.
  ///
  /// Защита от `null`: между исчезновением трека и перестроением родителя
  /// панель ещё смонтирована, а `_activeNowPlayingItem` уже пуст — раньше это
  /// было невозможно, потому что перестраивалось всё разом.
  Widget _buildNowPlayingStrip({required bool merged}) => ListenableBuilder(
    listenable: _audioTick,
    builder: (context, _) {
      final item = _activeNowPlayingItem;
      if (item == null) return const SizedBox.shrink();
      return _buildNowPlayingPanel(merged: merged, item: item);
    },
  );

  Widget _buildNowPlayingPanel({
    required bool merged,
    required _NowPlayingItem item,
  }) => _NowPlayingPanel(
    merged: merged,
    item: item,
    isAudioPlaying: _sharedAudioPlayback.playing,
    audioPosition: _sharedAudioPlayback.position,
    audioDuration: _sharedAudioPlayback.duration,
    onClose: () async {
      final item = _activeNowPlayingItem;
      if (item?.kind == _NowPlayingKind.audio) {
        await widget.controller.stopSharedAudio();
      }
      if (!mounted) return;
      setState(() {
        if (item?.kind == _NowPlayingKind.video) {
          _nowPlaying = null;
        }
      });
    },
    onPlayPause: () async {
      if (_activeNowPlayingItem?.kind != _NowPlayingKind.audio) {
        return;
      }
      await widget.controller.toggleSharedAudioPlayback();
    },
    onOpen: () async {
      final item = _activeNowPlayingItem;
      if (item == null) return;
      if (item.kind == _NowPlayingKind.audio) {
        await _openChatAudioPlayerSheet();
        return;
      }
      await _openVideoPlayerDialog(item.file, title: item.title);
    },
  );

  /// The secondary strips below the toolbar, in order: pinned, then now-playing.
  /// Two or more ⇒ they glue into a single pill (see [_buildHeaderIslandGroup]);
  /// one ⇒ a plain island. Keep in sync with [_headerBottomHeight].
  List<Widget> _buildSecondaryIslandStack() {
    final pinned = _resolvedPinnedMessage();
    final hasPlayer = _activeNowPlayingItem != null;
    final merge = _kMergeHeaderIslands && pinned != null && hasPlayer;
    if (merge) {
      return [
        Padding(
          padding: _kChatIslandMargin,
          child: _buildHeaderIslandGroup([
            _buildPinnedMessageBanner(pinned, merged: true),
            _buildNowPlayingStrip(merged: true),
          ]),
        ),
      ];
    }
    return [
      if (pinned != null)
        Padding(
          padding: _kChatIslandMargin,
          child: _buildPinnedMessageBanner(pinned),
        ),
      if (hasPlayer)
        Padding(
          padding: _kChatIslandMargin,
          child: _buildNowPlayingStrip(merged: false),
        ),
    ];
  }

  /// Exact height of the AppBar's bottom slot. It must match what
  /// [_buildSecondaryIslandStack] actually renders: any slack pools at the
  /// AppBar's bottom edge and pushes the call strip — which the body positions
  /// against that edge — further down than the strips are from each other.
  double _headerBottomHeight() {
    final topic = _shouldShowTopicBar ? 44.0 : 0.0;
    final hasPinned = _resolvedPinnedMessage() != null;
    final hasPlayer = _activeNowPlayingItem != null;
    final strips = (hasPinned ? 1 : 0) + (hasPlayer ? 1 : 0);
    if (strips == 0) return topic;
    if (_kMergeHeaderIslands && strips > 1) {
      // One pill: N rows + the hairlines between them + ONE bottom gap.
      return topic +
          strips * _kChatIslandHeight +
          (strips - 1) * _kChatIslandSeam +
          _kChatIslandGap;
    }
    return topic + strips * _kChatIslandSlot;
  }

  /// Glues the secondary header strips (pinned / now-playing) into ONE glass
  /// pill — the Telegram behaviour. A single [_frostedHeaderIsland] provides the
  /// blur, the specular edge, the outer shadow and the corner clip for the whole
  /// group, so the strips inside have no rounding, no highlight and no edge of
  /// their own: an inner seam is just a hairline, and the middle strip of three
  /// has no rounded corner anywhere. Rows are handed in already built in their
  /// `merged` form.
  ///
  /// One row ⇒ plain island (nothing to glue). Zero ⇒ nothing.
  Widget _buildHeaderIslandGroup(List<Widget> rows) {
    if (rows.isEmpty) return const SizedBox.shrink();
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final seamColor = isDark
        ? Colors.white.withValues(alpha: 0.10)
        : Colors.black.withValues(alpha: 0.07);
    return _frostedHeaderIsland(
      radius: _kChatIslandRadius,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          for (var i = 0; i < rows.length; i++) ...[
            if (i > 0)
              Container(height: _kChatIslandSeam, color: seamColor),
            SizedBox(height: _kChatIslandHeight, child: rows[i]),
          ],
        ],
      ),
    );
  }

  Widget _frostedHeaderIsland({
    required Widget child,
    double radius = 24,
    double? height,
    EdgeInsetsGeometry padding = EdgeInsets.zero,
    bool showHighlight = true,
    bool transparentFill = false,
    // Perf (2026-07-23): join the nearest [BackdropGroup] so the stacked chat-
    // header islands share ONE backdrop read instead of one each. They don't
    // overlap, so the shared backdrop is pixel-identical; without a group
    // ancestor `.grouped` falls back to a normal BackdropFilter (null key), so
    // passing this is always safe.
    bool grouped = false,
  }) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    // Telegram-style glass:
    //  1) big backdrop blur (matte — content behind stays recognizable but
    //     loses sharpness),
    //  2) translucent white fill as a soft vertical gradient (lighter at the
    //     top, slightly darker at the bottom) for density — ~60-75% white in
    //     light theme, ~8-14% white in dark theme,
    //  3) a specular highlight stroke that is bright white along the TOP edge
    //     and fades to transparent toward the middle/bottom, so the plate
    //     reads as lit from above and looks convex rather than flat.
    // Very light lightening veil: the matte blur should dominate, the white
    // fill only takes the dirtiness off the blur (keeps a soft top->bottom
    // gradient for a hint of volume). Highlight (specular top edge) carries the
    // 3D look.
    // `transparentFill` drops the white veil to almost nothing (pure matte
    // blur) — used for the message composer so its background reads as
    // transparent, just like the search field.
    // LIGHT theme: match the main-page top islands — a dense near-white plate
    // lifted by the OUTER shadow (added after the highlight block), so the
    // in-chat top/bottom panels read as the same component. DARK theme keeps the
    // glassy look (composer/search stay transparent via transparentFill).
    // 🔴 With the blur OFF these fills are invisible in dark mode (white at
    // alpha 0.0–0.06 — they exist only to take the dirtiness off a blur), so
    // the panels vanished and the chat showed through them (field report
    // 2026-08-01). Off ⇒ paint a solid plate; see `opaquePanelFill`.
    final panelsFrosted = widget.controller.frostedPanelsEnabled;
    final solidFill = opaquePanelFill(context);
    final fillTop = !panelsFrosted
        ? solidFill
        : isDark
        ? Colors.white.withValues(alpha: transparentFill ? 0.015 : 0.06)
        : Colors.white.withValues(alpha: 0.65);
    final fillBottom = !panelsFrosted
        ? solidFill
        : isDark
        ? Colors.white.withValues(alpha: transparentFill ? 0.0 : 0.03)
        : Colors.white.withValues(alpha: 0.55);
    final br = BorderRadius.circular(radius);
    final blurFilter = ImageFilter.blur(sigmaX: 24, sigmaY: 24);
    final blurChild = DecoratedBox(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [fillTop, fillBottom],
        ),
        borderRadius: br,
      ),
      child: Padding(padding: padding, child: child),
    );
    // POWER SETTING (2026-07-31). A BackdropFilter re-samples and blurs
    // everything behind it EVERY frame it is composited — the single most
    // expensive thing on these screens, and there are ten of these islands.
    // With the setting off we keep the same plate, fill and shadow and simply
    // do not blur: the layout, colours and geometry are untouched, so nothing
    // moves — the background behind the plate just stays sharp.
    final blurAllowed = widget.controller.frostedPanelsEnabled;
    Widget island = ClipRRect(
      borderRadius: br,
      child: !blurAllowed
          ? blurChild
          : grouped
          ? BackdropFilter.grouped(filter: blurFilter, child: blurChild)
          : BackdropFilter(filter: blurFilter, child: blurChild),
    );
    // Optional specular highlight (off by default — the soft top-lighter
    // gradient already gives subtle volume without a pronounced bright edge).
    // Painted as a foreground over the island WITHOUT a Stack so the island
    // keeps its exact layout/constraints.
    if (showHighlight) {
      final highlight = isDark
          ? Colors.white.withValues(alpha: 0.24)
          : Colors.white.withValues(alpha: 0.42);
      island = CustomPaint(
        foregroundPainter: GlassHighlightBorderPainter(
          radius: radius,
          strokeWidth: 1.3,
          color: highlight,
        ),
        child: island,
      );
    }
    // LIGHT theme only: thin OUTER-ring drop shadow (interior clipped) so the
    // glass panel lifts off the page without graying through its translucency.
    if (!isDark) {
      island = CustomPaint(
        painter: IslandOuterShadowPainter(
          radius: radius,
          color: Colors.black.withValues(alpha: 0.07),
        ),
        child: island,
      );
    }
    return height == null ? island : SizedBox(height: height, child: island);
  }

  // Shared geometry so the three chat-header islands stay identical in size.
  static const double _kHeaderIslandHeight = 48;
  static const double _kHeaderIslandRadius = 24;

  Widget _buildComposerSoftActionButton({
    required double size,
    required Color softBase,
    required Color iconColor,
    required VoidCallback? onPressed,
    required Widget child,
  }) {
    // Minimal: no circular background, gradient, border, or shadow — just the
    // icon with a subtle circular tap ripple. (`softBase` kept for call-site
    // compatibility but intentionally unused.)
    return Material(
      color: Colors.transparent,
      shape: const CircleBorder(),
      child: InkResponse(
        onTap: onPressed,
        radius: size * 0.55,
        customBorder: const CircleBorder(),
        child: SizedBox(
          width: size,
          height: size,
          child: IconTheme(
            data: IconThemeData(color: iconColor),
            child: Center(child: child),
          ),
        ),
      ),
    );
  }

  Color _resolveComposerActionIconColor(Color actionCenter) {
    if (widget.controller.appThemePresetId == 'flutter_dash') {
      return Colors.white;
    }
    return ThemeData.estimateBrightnessForColor(actionCenter) == Brightness.dark
        ? Colors.white
        : const Color(0xFF2A1A12);
  }

  Widget _buildVoiceComposerButton({bool enabled = true}) {
    final visuals = Theme.of(context).extension<ChatVisualsThemeExtension>();
    final cs = Theme.of(context).colorScheme;
    final top = visuals?.actionTop ?? cs.primary;
    final bottom = visuals?.actionBottom ?? cs.secondary;
    final center = Color.lerp(top, bottom, 0.5) ?? cs.primary;
    final iconColor = _resolveComposerActionIconColor(center);

    final recordingActive = _voiceRecording || _videoNoteRecording;

    Widget buttonChild() {
      // 🔴 ОДНА кнопка на оба режима, а не две подменяемые. Раньше здесь стояли
      // две ветки `if`, и нажатие меняло значок рывком: круг пересобирался
      // целиком, анимации не было вовсе.
      //
      // Размер значка одинаковый для микрофона и камеры. Раньше было 18 против
      // 20, и это само по себе читалось как «кнопка меняет размер».
      final glyph = recordingActive ? 21.0 : 19.0;
      return _buildComposerActionButton(
        topColor: top,
        bottomColor: bottom,
        iconColor: iconColor,
        size: recordingActive ? 48 : 40,
        onPressed: enabled ? () {} : null,
        child: ComposerGlyphMorph(
          box: recordingActive ? 26 : 23,
          child: _composerVideoMode
              ? Icon(
                  AppIcons.videoSolid,
                  key: const ValueKey<String>('composer-glyph-video'),
                  size: glyph,
                  color: iconColor,
                )
              : Image.asset(
                  AppAssetPaths.settingsMicPng,
                  key: const ValueKey<String>('composer-glyph-mic'),
                  width: glyph,
                  height: glyph,
                  color: iconColor,
                  colorBlendMode: BlendMode.srcIn,
                  errorBuilder: (context, error, stackTrace) => Icon(
                    AppIcons.mic,
                    size: glyph,
                    color: iconColor,
                  ),
                ),
        ),
      );
    }

    if (!enabled && !recordingActive) {
      return buttonChild();
    }

    return Listener(
      onPointerDown: _onCapturePointerDown,
      onPointerMove: _onCapturePointerMove,
      onPointerUp: _onCapturePointerUp,
      onPointerCancel: _onCapturePointerCancel,
      behavior: HitTestBehavior.opaque,
      child: AnimatedBuilder(
        animation: _voicePulseController,
        builder: (context, child) {
          final t = _voicePulseController.value;
          final ripple1Opacity = _voiceRecording ? (0.45 * (1.0 - t)) : 0.0;
          final ripple1Scale = _voiceRecording ? 1.0 + (0.65 * t) : 0.0;
          final ripple2Opacity = _voiceRecording
              ? (0.25 * (1.0 - Curves.easeIn.transform(t)))
              : 0.0;
          final ripple2Scale = _voiceRecording
              ? 1.0 + (1.1 * Curves.easeIn.transform(t))
              : 0.0;
          final btnScale = _voiceRecording
              ? 1 + (0.06 * Curves.easeOut.transform(t))
              : 1.0;
          return Stack(
            alignment: Alignment.center,
            clipBehavior: Clip.none,
            children: [
              if (_voiceRecording) ...[
                Transform.scale(
                  scale: ripple2Scale,
                  child: Container(
                    width: 56,
                    height: 56,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: bottom.withValues(alpha: ripple2Opacity * 0.18),
                    ),
                  ),
                ),
                Transform.scale(
                  scale: ripple1Scale,
                  child: Container(
                    width: 56,
                    height: 56,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: top.withValues(alpha: ripple1Opacity),
                        width: 2.5,
                      ),
                    ),
                  ),
                ),
              ],
              Transform.scale(scale: btnScale, child: child),
            ],
          );
        },
        child: buttonChild(),
      ),
    );
  }

  Widget _buildVoiceRecordingInlineContent(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final cancelColor = cs.error.withValues(alpha: 0.9);
    final slideLeftProgress = (-_voiceDragDx / _voiceCancelThresholdPx)
        .clamp(0.0, 1.0)
        .toDouble();
    final timerColor = Color.lerp(
      Theme.of(context).textTheme.titleMedium?.color,
      cancelColor,
      Curves.easeIn.transform(slideLeftProgress),
    );

    return Transform.translate(
      offset: Offset(-slideLeftProgress * 22.0, 0),
      child: SizedBox(
        height: 40,
        child: Row(
          children: [
            AnimatedBuilder(
              animation: _voicePulseController,
              builder: (context, child) {
                final pulse =
                    1.0 +
                    (0.28 *
                        Curves.easeOut.transform(_voicePulseController.value));
                final cancelGrow = 1.0 + slideLeftProgress * 0.5;
                return Transform.scale(scale: pulse * cancelGrow, child: child);
              },
              child: Icon(
                Icons.fiber_manual_record_rounded,
                size: 14,
                color: _voiceRecordingCancelHint
                    ? cancelColor
                    : Colors.redAccent,
              ),
            ),
            const SizedBox(width: 8),
            Text(
              _voiceElapsedLabel(_voiceElapsed),
              style: Theme.of(context).textTheme.titleMedium?.copyWith(
                fontWeight: FontWeight.w700,
                color: timerColor,
              ),
            ),
            const SizedBox(width: 10),
            Expanded(
              child: _voiceRecordingLocked
                  ? GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: () => unawaited(_cancelVoiceRecording()),
                      child: Text(
                        chatText(
                          context,
                          ru: 'ОТМЕНА',
                          en: 'CANCEL',
                          uk: 'СКАСУВАТИ',
                          es: 'CANCELAR',
                          pt: 'CANCELAR',
                          ptBr: 'CANCELAR',
                          fr: 'ANNULER',
                          de: 'ABBRECHEN',
                        ),
                        style: Theme.of(context).textTheme.labelLarge?.copyWith(
                          color: cancelColor,
                          fontWeight: FontWeight.w700,
                          letterSpacing: 1.2,
                        ),
                      ),
                    )
                  : AnimatedSwitcher(
                      duration: const Duration(milliseconds: 220),
                      transitionBuilder: (child, anim) => FadeTransition(
                        opacity: anim,
                        child: SlideTransition(
                          position:
                              Tween<Offset>(
                                begin: const Offset(-0.15, 0),
                                end: Offset.zero,
                              ).animate(
                                CurvedAnimation(
                                  parent: anim,
                                  curve: Curves.easeOutCubic,
                                ),
                              ),
                          child: child,
                        ),
                      ),
                      child: Text(
                        key: ValueKey(_voiceRecordingCancelHint),
                        _voiceRecordingCancelHint
                            ? chatText(
                                context,
                                ru: 'Отпустите — отмена',
                                en: 'Release to cancel',
                                uk: 'Відпустіть, щоб скасувати',
                                es: 'Suelta para cancelar',
                                pt: 'Solte para cancelar',
                                ptBr: 'Solte para cancelar',
                                fr: 'Relachez pour annuler',
                                de: 'Loslassen zum Abbrechen',
                              )
                            : chatText(
                                context,
                                ru: '< Влево — отмена',
                                en: '< Slide left to cancel',
                                uk: '< Вліво, щоб скасувати',
                                es: '< Desliza a la izquierda para cancelar',
                                pt: '< Deslize para a esquerda para cancelar',
                                ptBr: '< Deslize para a esquerda para cancelar',
                                fr: '< Glissez a gauche pour annuler',
                                de: '< Nach links schieben zum Abbrechen',
                              ),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                          color: _voiceRecordingCancelHint
                              ? cancelColor
                              : cs.onSurfaceVariant,
                          fontWeight: _voiceRecordingCancelHint
                              ? FontWeight.w600
                              : null,
                        ),
                      ),
                    ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildVoiceLockBubble(ColorScheme cs) {
    final rawProgress = (-_voiceDragDy / _voiceLockThresholdPx).clamp(0.0, 1.0);
    final slideUpProgress = rawProgress.toDouble();
    final isNearLock = slideUpProgress > 0.5;
    final showBubble = _voiceRecording && !_voiceRecordingLocked;
    final riseOffset = slideUpProgress * -24.0;

    final bubbleColor = Color.lerp(
      cs.surfaceContainerHighest.withValues(alpha: 0.96),
      cs.primary.withValues(alpha: 0.97),
      Curves.easeIn.transform(slideUpProgress),
    )!;
    final iconColor = Color.lerp(
      cs.onSurfaceVariant,
      cs.onPrimary,
      Curves.easeIn.transform(slideUpProgress),
    )!;

    return AnimatedOpacity(
      duration: const Duration(milliseconds: 200),
      opacity: showBubble ? 1.0 : 0.0,
      child: AnimatedScale(
        duration: const Duration(milliseconds: 300),
        curve: Curves.easeOutBack,
        scale: showBubble ? 1.0 : 0.2,
        child: Transform.translate(
          offset: Offset(0, riseOffset),
          child: AnimatedBuilder(
            animation: Listenable.merge([
              _voicePulseController,
              _voiceLockBounceController,
            ]),
            builder: (context, child) {
              final pv = _voicePulseController.value;
              final bv = _voiceLockBounceController.value;
              // Horizontal wiggle near lock threshold, driven by pulse
              final shake = (isNearLock && bv < 0.85)
                  ? sin(pv * pi * 5) * 2.8 * (1.0 - (bv > 0 ? bv : 0.0))
                  : 0.0;
              // Scale bounce on lock-in (one-shot)
              final bounceScale = bv > 0 ? (1.0 + 0.32 * sin(bv * pi)) : 1.0;
              return Transform.translate(
                offset: Offset(shake, 0),
                child: Transform.scale(
                  scale: bounceScale,
                  alignment: Alignment.center,
                  child: child,
                ),
              );
            },
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 44,
                  height: 52,
                  decoration: BoxDecoration(
                    color: bubbleColor,
                    borderRadius: BorderRadius.circular(22),
                    boxShadow: [
                      BoxShadow(
                        color: (isNearLock ? cs.primary : Colors.black)
                            .withValues(alpha: 0.26 + slideUpProgress * 0.12),
                        blurRadius: 14,
                        offset: const Offset(0, 4),
                      ),
                    ],
                  ),
                  child: Stack(
                    alignment: Alignment.center,
                    children: [
                      SizedBox(
                        width: 32,
                        height: 32,
                        child: CircularProgressIndicator(
                          value: slideUpProgress,
                          strokeWidth: 2.8,
                          color: iconColor.withValues(alpha: 0.7),
                          backgroundColor: iconColor.withValues(alpha: 0.14),
                          strokeCap: StrokeCap.round,
                        ),
                      ),
                      Icon(
                        isNearLock
                            ? Icons.lock_rounded
                            : Icons.lock_open_rounded,
                        size: 16,
                        color: iconColor,
                      ),
                    ],
                  ),
                ),
                ClipPath(
                  clipper: _VoiceLockArrowClipper(),
                  child: Container(width: 14, height: 8, color: bubbleColor),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  /// Tap handler for GENERIC (non image/video/audio) file bubbles. Shows a
  /// circular download spinner on the bubble (per-blobId state) while the blob
  /// is fetched + decrypted, then opens it via the OS. The "…" menu stays a
  /// separate, always-available path. No-op while already downloading.
  Future<void> _openGenericFileFromTap(
    AttachmentEventV1 a, {
    int? createdAtMs,
  }) async {
    final blobId = a.blobId;
    if (_downloadingFileBlobIds.contains(blobId)) return;
    // Already cached → open immediately, no spinner needed.
    final cached = await widget.controller.cachedAttachmentFile(a);
    if (cached != null && await cached.exists()) {
      if (!mounted) return;
      await _openGenericAttachmentFile(
        attachment: a,
        file: cached,
        createdAtMs: createdAtMs,
      );
      return;
    }
    if (!mounted) return;
    setState(() => _downloadingFileBlobIds.add(blobId));
    try {
      final file = await _ensureAttachmentFile(a);
      if (!mounted) return;
      await _openGenericAttachmentFile(
        attachment: a,
        file: file,
        createdAtMs: createdAtMs,
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(context.l10n.downloadFailed(e.toString())),
        ),
      );
    } finally {
      if (mounted) {
        setState(() => _downloadingFileBlobIds.remove(blobId));
      } else {
        _downloadingFileBlobIds.remove(blobId);
      }
    }
  }

  Future<void> _openAttachment(
    AttachmentEventV1 a, {
    String? payloadEventId,
    int? createdAtMs,
  }) async {
    final l10n = context.l10n;

    try {
      final file = await _ensureAttachmentFile(a);

      if (!mounted) return;
      final mime = (a.mime ?? '').toLowerCase();
      final isVideo = mime.startsWith('video/');
      if (mime.startsWith('image/') || isVideo) {
        // A photo/video sent AS A FILE opens in the SAME fullscreen viewer as a
        // normally-sent photo — tap toggles the chrome islands, videos get the
        // centered play/pause control, swipe dismisses. (Previously photo files
        // opened a cramped 78%-height dialog and video files a separate player,
        // which is the "какое-то окно" the user reported.)
        final entry = _findTimelineEntryForAttachment(
          a,
          payloadEventId: payloadEventId,
        );
        if (entry != null) {
          await _presentChatImageGallery(
            galleryItems: [
              MediaViewerItem(event: entry.event, attachment: a),
            ],
            startIndex: 0,
          );
          return;
        }
        // No live timeline entry (opened from a detached context) — fall back
        // to the legacy presentation so the media still opens.
        if (isVideo) {
          if (!mounted) return;
          setState(() {
            _nowPlaying = _NowPlayingItem(
              kind: _NowPlayingKind.video,
              title: p.basename(file.path),
              subtitle: context.l10n.video,
              file: file,
              sourceBlobId: a.blobId,
            );
          });
          await _openVideoPlayerDialog(file, title: p.basename(file.path));
        } else {
          await showDialog<void>(
            context: context,
            builder: (context) {
              final maxHeight = MediaQuery.of(context).size.height * 0.78;
              return Dialog(
                insetPadding: const EdgeInsets.all(16),
                clipBehavior: Clip.antiAlias,
                child: ConstrainedBox(
                  constraints: BoxConstraints(maxHeight: maxHeight),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Expanded(
                        child: InteractiveViewer(
                          child: Image.file(
                            file,
                            fit: BoxFit.contain,
                            errorBuilder: (_, _, _) =>
                                const _BrokenMediaBox(iconSize: 48),
                          ),
                        ),
                      ),
                      Padding(
                        padding: const EdgeInsets.fromLTRB(12, 8, 8, 8),
                        child: Row(
                          children: [
                            Expanded(
                              child: Text(
                                p.basename(file.path),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: Theme.of(context).textTheme.bodySmall,
                              ),
                            ),
                            TextButton(
                              onPressed: () => Navigator.of(context).pop(),
                              child: Text(l10n.close),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        }
      } else if (mime.startsWith('audio/')) {
        await _startAudioPlaybackFromAttachment(
          a,
          file: file,
          payloadEventId: payloadEventId,
        );
      } else {
        await _openGenericAttachmentFile(
          attachment: a,
          file: file,
          createdAtMs: createdAtMs,
        );
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(l10n.downloadFailed(e.toString()))),
      );
    }
  }

  Future<void> _openGenericAttachmentFile({
    required AttachmentEventV1 attachment,
    required File file,
    int? createdAtMs,
  }) async {
    final effectiveCreatedAtMs =
        createdAtMs ?? DateTime.now().millisecondsSinceEpoch;
    final suggestedName = _attachmentDownloadSuggestedName(
      attachment,
      effectiveCreatedAtMs,
      file,
    );
    // IN-APP READER (2026-07-29): a PDF opens in OUR full-screen reader — same
    // chrome as the photo gallery — instead of being handed to another app that
    // may not exist ("Нет приложения для открытия"). Pages are rasterised by the
    // platform's own PDF renderer; see PdfDocument for why we do not bundle an
    // engine. If the file cannot be opened as a PDF (encrypted/corrupt) or the
    // platform has no renderer yet, fall through to the external-app path below.
    final mime = attachment.mime ?? _guessMime(file.path) ?? '';
    final looksPdf =
        mime.toLowerCase().contains('pdf') ||
        file.path.toLowerCase().endsWith('.pdf');
    if (looksPdf && PdfDocument.isSupported) {
      final doc = await PdfDocument.open(file.path);
      if (doc != null) {
        if (!mounted) {
          doc.dispose();
          return;
        }
        await Navigator.of(context).push(
          SecretlyPageRoute(
            builder: (_) => DocumentReaderScreen(
              document: doc,
              title: suggestedName,
              // Через общий путь: он даёт файлу правильное имя НА ДИСКЕ и тип
              // по имени. Здесь стояло прямое обращение, и потому документ
              // уходил под служебным именем кэша — `<blobId>.bin`.
              onShare: () => shareAttachmentFile(
                attachment: attachment,
                createdAtMs: effectiveCreatedAtMs,
                source: file,
              ),
            ),
          ),
        );
        return;
      }
    }
    // Plain text (.txt/.log/.json/.csv/…) opens in-app too. Unlike PDF this
    // needs no rendering engine — we just decode the bytes — so it costs nothing
    // in size or attack surface, and it saves the same dead end on a phone with
    // no text viewer installed.
    if (TextFileReaderScreen.canOpen(path: file.path, mime: mime)) {
      if (!mounted) return;
      await Navigator.of(context).push(
        SecretlyPageRoute(
          builder: (_) => TextFileReaderScreen(
            file: file,
            title: suggestedName,
            onShare: () => shareAttachmentFile(
              attachment: attachment,
              createdAtMs: effectiveCreatedAtMs,
              source: file,
            ),
          ),
        ),
      );
      return;
    }
    final opened = await PlatformFileOpen.open(
      // 🔴 Наружу отдаём файл с ПРАВИЛЬНЫМ ИМЕНЕМ НА ДИСКЕ и типом, выведенным
      // из имени. Здесь уходил кэш `<blobId>.bin` с обезличенным типом — по
      // такому описанию система не находит ни одного приложения, и человек
      // видел «нет приложения для открытия» даже там, где приложение есть.
      path: (await prepareAttachmentFileForExport(
        source: file,
        filename: suggestedName,
        mime: attachment.mime,
        createdAtMs: effectiveCreatedAtMs,
      )).path,
      mime: attachmentMimeFor(filename: suggestedName, mime: attachment.mime),
      displayName: suggestedName,
    );
    if (opened || !mounted) return;
    // NO-VIEWER FALLBACK (2026-07-29, field report "не открывается PDF — пишет
    // «Нет приложения для открытия»"): a direct VIEW intent only succeeds when
    // some installed app claims that exact mime, so on a phone without a PDF /
    // document viewer the user hit a dead end — the file was decrypted and ready
    // on disk, but there was no way to reach it. Offer the system share sheet
    // instead: its chooser lists every app that can take the file (viewers,
    // Drive, browser, mail), which is the standard Android way out of this, and
    // it also lets the user move the file somewhere they can open it.
    final decision = await showModalBottomSheet<String>(
      context: context,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 18, 20, 8),
              child: Text(
                chatText(
                  sheetContext,
                  ru: 'На устройстве нет приложения для этого типа файла',
                  en: 'No app on this device can open this file type',
                ),
                textAlign: TextAlign.center,
              ),
            ),
            ListTile(
              leading: const Icon(Icons.ios_share_rounded),
              title: Text(
                chatText(
                  sheetContext,
                  ru: 'Открыть в другом приложении',
                  en: 'Open with another app',
                ),
              ),
              onTap: () => Navigator.of(sheetContext).pop('share'),
            ),
            // A file nothing can display should still be RETRIEVABLE: put it in
            // the phone's public Downloads (visible in Files / any file manager)
            // so an installer, archive or office document can be dealt with
            // outside the app. Android only — iOS has no shared Downloads, and
            // its share sheet already covers "save to Files".
            if (Platform.isAndroid)
              ListTile(
                leading: const Icon(Icons.download_rounded),
                title: Text(
                  chatText(
                    sheetContext,
                    ru: 'Сохранить в Загрузки',
                    en: 'Save to Downloads',
                  ),
                ),
                onTap: () => Navigator.of(sheetContext).pop('save'),
              ),
            const SizedBox(height: 6),
          ],
        ),
      ),
    );
    if (!mounted) return;
    if (decision == 'save') {
      try {
        final saved = await const MethodChannel(
          'secretly/media_store',
        ).invokeMethod<String>('saveToDownloads', {
          'fileName': suggestedName,
          'sourcePath': file.path,
          // 🔴 Тип обязателен. Без него запись шла типом
          // `application/octet-stream`, и система считала файл двоичным мусором:
          // установщик не предлагал поставить apk, проводник не открывал
          // документ, и в «Недавних» файл не появлялся.
          'mimeType': attachmentMimeFor(
            filename: suggestedName,
            mime: attachment.mime,
          ),
        });
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SecretlySnackBar(
            content: Text(
              saved != null && saved.trim().isNotEmpty
                  ? chatText(
                      context,
                      ru: 'Сохранено в Загрузки',
                      en: 'Saved to Downloads',
                    )
                  : chatText(
                      context,
                      ru: 'Не удалось сохранить',
                      en: 'Could not save',
                    ),
            ),
          ),
        );
      } catch (e) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SecretlySnackBar(content: Text('$e')),
        );
      }
      return;
    }
    if (decision != 'share') return;
    try {
      // Тот же довод, что в `_shareSingleAttachment`: наружу должен уходить файл
      // с правильным именем НА ДИСКЕ, а не имя в параметрах.
      await shareAttachmentFile(
        attachment: attachment,
        createdAtMs: effectiveCreatedAtMs,
        source: file,
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text('$e')),
      );
    }
  }

  Future<void> _startAudioPlaybackFromAttachment(
    AttachmentEventV1 attachment, {
    required File file,
    String? payloadEventId,
  }) async {
    final queue = await _loadAudioQueue();
    if (!mounted) return;
    final musicLabel = context.l10n.music;
    final unknownArtistLabel = _unknownMusicArtistLabel(context);
    var index = queue.indexWhere(
      (t) => t.attachment.blobId == attachment.blobId,
    );
    var mutableQueue = queue;
    if (index < 0) {
      final isVoice = _isVoiceMessageAttachment(attachment);
      final voiceMessageLabel = _voiceMessageLabel(context);
      final resolvedMusic = !isVoice
          ? await _resolveMusicMetadataForPlayback(
              attachment,
              file: file,
              payloadEventId: payloadEventId,
            )
          : null;
      final track = _ChatAudioTrack(
        id: attachment.blobId,
        title: isVoice
            ? voiceMessageLabel
            : (resolvedMusic?.title ?? musicLabel),
        artist: isVoice ? '' : (resolvedMusic?.artist ?? unknownArtistLabel),
        attachment: attachment,
        cachedFile: file,
      );
      mutableQueue = [track, ...queue];
      index = 0;
    }
    await _playAudioTrackAt(index, queue: mutableQueue, fileOverride: file);
  }

  SharedAudioTrack _sharedAudioTrackFromChatTrack(
    _ChatAudioTrack track, {
    File? fileOverride,
  }) {
    final overridePath = fileOverride?.path.trim();
    final cachedPath = track.cachedFile?.path.trim();
    final resolvedPath = (overridePath != null && overridePath.isNotEmpty)
        ? overridePath
        : ((cachedPath != null && cachedPath.isNotEmpty) ? cachedPath : null);
    return SharedAudioTrack(
      trackId: track.id,
      kind: SharedAudioTrackKind.attachment,
      title: track.title,
      artist: track.artist,
      sourceBlobId: track.attachment.blobId,
      sourcePath: resolvedPath,
      sourceConvoId: widget.convoId,
      resolveFilePath: () async {
        if (resolvedPath != null && resolvedPath.isNotEmpty) {
          return resolvedPath;
        }
        final ensured = await widget.controller.ensureCachedAttachmentFile(
          track.attachment,
        );
        return ensured.path;
      },
    );
  }

  Future<List<_ChatAudioTrack>> _loadAudioQueue() async {
    final musicLabel = context.l10n.music;
    final unknownArtistLabel = _unknownMusicArtistLabel(context);
    final voiceMessageLabel = _voiceMessageLabel(context);
    final events = await widget.controller.loadEvents(widget.convoId);
    final tracks = <_ChatAudioTrack>[];
    for (final e in events) {
      final payload = await widget.controller.payloadEventForChatEvent(e);
      if (payload is! AttachmentEventV1) continue;
      final mime = (payload.mime ?? '').toLowerCase();
      if (!mime.startsWith('audio/')) continue;
      final isVoice = _isVoiceMessageAttachment(payload);
      final cached = await widget.controller.cachedAttachmentFile(payload);
      final resolvedMusic = !isVoice
          ? await _resolveMusicMetadataForPlayback(
              payload,
              file: cached,
              payloadEventId: e.payloadEventId,
            )
          : null;
      final title = isVoice
          ? voiceMessageLabel
          : (resolvedMusic?.title ?? '$musicLabel ${tracks.length + 1}');
      final artist = isVoice
          ? ''
          : (resolvedMusic?.artist ?? unknownArtistLabel);
      tracks.add(
        _ChatAudioTrack(
          id: e.payloadEventId ?? payload.blobId,
          title: title,
          artist: artist,
          attachment: payload,
          cachedFile: cached,
        ),
      );
    }
    return tracks;
  }

  Future<_ResolvedMusicMetadata?> _resolveMusicMetadataForPlayback(
    AttachmentEventV1 attachment, {
    File? file,
    String? payloadEventId,
  }) async {
    final musicLabel = context.l10n.music;
    final unknownArtistLabel = _unknownMusicArtistLabel(context);
    // 🔴 То, что прочёл отправитель, — ПЕРВЫМ, как и в самом пузыре
    // (`_resolvedMusicMetadataForAttachment`), 17.09.2026. Плеер и экран
    // блокировки смотрели только на теги, прочитанные из файла, и на iPhone,
    // где их не читали, играли песню под именем «Музыка / Неизвестен», хотя
    // название и исполнитель ехали в самом сообщении.
    final payloadTitle = taggedMusicTitle(attachment);
    final payloadArtist = taggedMusicArtist(attachment);
    final blobId = attachment.blobId;
    var probed = _musicMetadataByBlobId[blobId];
    // 🔴 Очередь собирается при КАЖДОМ нажатии и проходит все песни чата.
    // Файл без тегов не перечитываем (17.09.2026): чтение теперь идёт и через
    // систему, а она медленнее библиотеки, и чат с тридцатью песнями без
    // тегов задерживал старт даже голосового. Ждём не дольше
    // [_kPlaybackTagsWait]; опоздавший ответ всё равно запоминается.
    if (probed == null &&
        (payloadTitle == null || payloadArtist == null) &&
        !_musicMetadataMissBlobIds.contains(blobId) &&
        file != null &&
        await file.exists()) {
      final read = _readResolvedMusicMetadata(file.path);
      unawaited(
        read.then((metadata) {
          if (metadata == null) {
            _musicMetadataMissBlobIds.add(blobId);
          } else {
            _musicMetadataByBlobId[blobId] = metadata;
          }
        }, onError: (_) {}),
      );
      probed = await read.timeout(_kPlaybackTagsWait, onTimeout: () => null);
    }
    final payloadFallback = payloadEventId == null
        ? null
        : _musicMetadataByPayloadEventId[payloadEventId];
    final filename = attachment.filename?.trim() ?? '';
    final filenameStem = filename.isEmpty
        ? null
        : _normalizeMusicMetadataLabel(p.basenameWithoutExtension(filename));
    final title =
        payloadTitle ??
        probed?.title ??
        payloadFallback?.title ??
        filenameStem;
    final artist = payloadArtist ?? probed?.artist ?? payloadFallback?.artist;
    if (title == null && artist == null) return null;
    return _ResolvedMusicMetadata(
      title: title ?? musicLabel,
      artist: artist ?? unknownArtistLabel,
    );
  }

  Future<void> _playAudioTrackAt(
    int index, {
    List<_ChatAudioTrack>? queue,
    File? fileOverride,
  }) async {
    final targetQueue = queue ?? await _loadAudioQueue();
    if (targetQueue.isEmpty) return;
    if (index < 0 || index >= targetQueue.length) return;
    final track = targetQueue[index];
    final updatedQueue = [...targetQueue];
    if (fileOverride != null) {
      updatedQueue[index] = track.copyWith(cachedFile: fileOverride);
    }
    final sharedQueue = updatedQueue
        .map(
          (queueTrack) => _sharedAudioTrackFromChatTrack(
            queueTrack,
            fileOverride: queueTrack.id == track.id ? fileOverride : null,
          ),
        )
        .toList(growable: false);
    await widget.controller.playSharedAudioQueue(
      queue: sharedQueue,
      index: index,
    );
  }

  Future<void> _openChatAudioPlayerSheet() async {
    await showSharedAudioPlayerSheet(context, controller: widget.controller);
  }

