  Future<File> _ensureImageFile(AttachmentEventV1 attachment) async {
    final cached = await widget.controller.cachedAttachmentFile(attachment);
    if (cached != null) return cached;
    return await widget.controller.ensureCachedAttachmentFile(attachment);
  }

  List<MediaViewerItem> _buildChatImageGalleryItems() {
    final items = <MediaViewerItem>[];
    final seenKeys = <String>{};
    for (final entry in _lastTimeline) {
      final imageItems = entry.imageItems;
      if (imageItems == null || imageItems.isEmpty) continue;
      for (final imageItem in imageItems) {
        final key = '${imageItem.event.eventId}|${imageItem.attachment.blobId}';
        if (!seenKeys.add(key)) continue;
        items.add(
          MediaViewerItem(
            event: imageItem.event,
            attachment: imageItem.attachment,
          ),
        );
      }
    }
    return items;
  }

  Future<void> _saveSingleAttachmentToGallery({
    required AttachmentEventV1 attachment,
    required int createdAtMs,
  }) async {
    if (!mounted) return;

    try {
      final source = await _ensureAttachmentFile(attachment);
      // GALLERY SAVE FIX (2026-07-17): photos/videos go through the SYSTEM
      // media store so they show up in the Gallery/Photos app immediately —
      // the old app-private copy was invisible to it. Falls back to the
      // Secretly download folder on denied permission / non-media.
      final inGallery = await saveMediaToSystemGallery(
        attachment: attachment,
        createdAtMs: createdAtMs,
        source: source,
      );
      if (inGallery) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SecretlySnackBar(content: Text(_savedToGalleryLabel(context))),
        );
        return;
      }
      final suggestedName = _attachmentDownloadSuggestedName(
        attachment,
        createdAtMs,
        source,
      );
      final dir = await _resolveMediaDownloadDirectory();
      final target = await _uniqueDownloadTarget(dir, suggestedName);
      await source.copy(target.path);
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(context.l10n.savedTo(target.path))),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(context.l10n.downloadFailed(error.toString())),
        ),
      );
    }
  }

  String _savedToGalleryLabel(BuildContext context) => chatText(
    context,
    ru: 'Сохранено в галерею',
    en: 'Saved to gallery',
    uk: 'Збережено в галерею',
    es: 'Guardado en la galeria',
    pt: 'Guardado na galeria',
    ptBr: 'Salvo na galeria',
    fr: 'Enregistre dans la galerie',
    de: 'In der Galerie gespeichert',
  );

  Future<void> _openTimelineImageGallery({
    required _TimelineEntry entry,
    AttachmentEventV1? selectedAttachment,
    int initialIndex = 0,
  }) async {
    final imageItems = entry.imageItems;
    if (imageItems == null || imageItems.isEmpty) {
      final fallbackAttachment = selectedAttachment ?? entry.attachment;
      if (fallbackAttachment != null) {
        await _openAttachment(
          fallbackAttachment,
          payloadEventId: entry.payloadEventId,
        );
      }
      return;
    }

    final resolvedIndex = initialIndex.clamp(0, imageItems.length - 1);
    final targetAttachment =
        selectedAttachment ?? imageItems[resolvedIndex].attachment;
    final galleryItems = _buildChatImageGalleryItems();
    if (galleryItems.isEmpty) {
      await _openAttachment(
        targetAttachment,
        payloadEventId: entry.payloadEventId,
      );
      return;
    }

    var startIndex = 0;
    for (var index = 0; index < galleryItems.length; index++) {
      if (galleryItems[index].attachment.blobId == targetAttachment.blobId) {
        startIndex = index;
        break;
      }
    }

    await _presentChatImageGallery(
      galleryItems: galleryItems,
      startIndex: startIndex,
    );
  }

  /// Opens the shared fullscreen media viewer ([MediaViewerDialog]) for a
  /// prepared list of gallery items. Used both by the in-timeline photo/album
  /// tap ([_openTimelineImageGallery]) and by single photo/video FILES opened
  /// from a document bubble ([_openAttachment]) — so a photo sent as a file
  /// opens EXACTLY like a normally-sent photo (fullscreen, tap-to-toggle
  /// chrome, swipe-to-dismiss) instead of the old cramped dialog.
  Future<void> _presentChatImageGallery({
    required List<MediaViewerItem> galleryItems,
    required int startIndex,
  }) async {
    if (galleryItems.isEmpty) return;
    await showDialog<void>(
      context: context,
      // EDGE-TO-EDGE (2026-07-17): без useSafeArea:false диалог inset-ится
      // системными панелями и медиа не может занять весь экран.
      useSafeArea: false,
      builder: (context) {
        return Dialog.fullscreen(
          child: MediaViewerDialog(
            items: galleryItems,
            initialIndex: startIndex.clamp(0, galleryItems.length - 1),
            chatTitle: widget.title,
            loadImageFile: _ensureImageFile,
            // The chat draws a video's filmstrip frame with a live player
            // surface. That is affordable here (a handful of strip cells) but
            // NOT in a profile gallery's grid, so the viewer takes it as a
            // callback instead of owning it.
            thumbnailBuilder: (context, file, mime, {bool forStrip = false}) =>
                _ChatGalleryMediaThumbnail(
                  file: file,
                  mime: mime,
                  // The strip draws its own tiny bare triangle (2026-07-17).
                  showPlayGlyph: !forStrip,
                ),
            onForward: (item) => _forwardEvents([item.event]),
            onReply: (item) async {
              final payloadEventId = (item.payloadEventId ?? '').trim();
              if (payloadEventId.isEmpty) return;
              // The viewer no longer carries the timeline entry (that was its
              // only tie to the chat). Resolve it here, where the timeline
              // lives.
              final entry = _findTimelineEntryForAttachment(
                item.attachment,
                payloadEventId: payloadEventId,
              );
              if (entry == null) return;
              _startReply(
                payloadEventId: payloadEventId,
                previewText: entry.previewText,
                authorName: entry.isMe ? _selfAuthorLabel() : entry.authorName,
                authorIsMe: entry.isMe,
              );
            },
            onSaveToGallery: (item) => _saveSingleAttachmentToGallery(
              attachment: item.attachment,
              createdAtMs: item.event.createdAtMs,
            ),
            onShare: (item) => _shareSingleAttachment(
              attachment: item.attachment,
              createdAtMs: item.event.createdAtMs,
            ),
            // Delete ONLY the photo being viewed, not the whole album — each
            // album photo is its own event, so the timeline regroups the
            // remaining ones into a smaller collage.
            onDelete: (item) => _deleteEventsWithConfirm(<ChatEvent>[item.event]),
            onShowInChat: (item) async {
              final targetId = (item.payloadEventId ?? item.event.eventId)
                  .trim();
              if (targetId.isEmpty) return;
              _messageInputFocusNode.unfocus();
              FocusManager.instance.primaryFocus?.unfocus();
              await SystemChannels.textInput.invokeMethod<void>(
                'TextInput.hide',
              );
              await _scrollToReply(targetId);
            },
          ),
        );
      },
    );
  }

  /// Finds the live timeline entry that owns [attachment] (matched by blob id,
  /// with a payload-event-id fallback) so a single media FILE can be opened in
  /// the shared gallery viewer with full forward/reply/save context.
  _TimelineEntry? _findTimelineEntryForAttachment(
    AttachmentEventV1 attachment, {
    String? payloadEventId,
  }) {
    final blobId = attachment.blobId;
    final wantedPayload = (payloadEventId ?? '').trim();
    for (final entry in _lastTimeline) {
      if (entry.attachment?.blobId == blobId) return entry;
      final items = entry.imageItems;
      if (items != null) {
        for (final item in items) {
          if (item.attachment.blobId == blobId) return entry;
        }
      }
    }
    if (wantedPayload.isNotEmpty) {
      for (final entry in _lastTimeline) {
        if ((entry.payloadEventId ?? '').trim() == wantedPayload) return entry;
      }
    }
    return null;
  }

  bool _sendInFlight = false;

  /// Re-entry guard. A plain text send is already safe (the field is cleared
  /// synchronously before the first await), but a FORWARD's draft isn't cleared
  /// until later — so a rapid double-tap could send it twice. Ignore re-taps
  /// until the in-flight send settles.
  Future<void> _send({int? scheduledAtMs}) async {
    if (_sendInFlight) return;
    _sendInFlight = true;
    try {
      await _sendInner(scheduledAtMs: scheduledAtMs);
    } finally {
      _sendInFlight = false;
    }
  }

  /// Central handler for attachment-send failures. A "too large" file that
  /// WOULD fit under Premium gets the Telegram-style upsell dialog (explain +
  /// one-tap to the paywall); everything else keeps the inline snackbar.
  Future<void> _reportAttachmentError(Object e) async {
    if (!mounted) return;
    final failure = describeAttachmentFailure(e);
    if (failure.code == AttachmentFailureCode.tooLarge) {
      final bytes = failure.bytes ?? parseAttachmentFailureBytes(e) ?? 0;
      if (bytes > 0 && widget.controller.attachmentTooLargeUpsell(bytes)) {
        await showAttachmentTooLargeDialog(
          context: context,
          fileBytes: bytes,
          limitBytes: widget.controller.effectiveAttachmentMaxBytes,
        );
        return;
      }
    }
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SecretlySnackBar(content: Text(attachmentErrorText(context.l10n, e))),
    );
  }

  /// Empty-chat "wave" affordance: sends a solo 👋 through the NORMAL send
  /// pipeline (so it renders as the standard bubble-free 160px animated emoji
  /// message). Any text the user already typed in the composer is preserved.
  /// Empty-chat state: E2EE note + the big animated wave invite. Shared by
  /// BOTH empty checks — the fast raw-events one and the visible-timeline one
  /// (WAVE FIX 2026-07-17).
  /// 🔴 Чат пуст, но мы ЕЩЁ НЕ ЗНАЕМ, пуст ли он на самом деле.
  ///
  /// Полевой отчёт 03.08.2026: пришло уведомление, тестировщик нажал на него,
  /// попал в чат — а там пусто, и лишь секунд через пятнадцать появилось
  /// сообщение. Пустота была «честной» только формально: сообщение в тот
  /// момент лежало на реле, ещё не скачанное и не расшифрованное.
