  /// True for a solo waving-hand message (any skin tone, with or without the
  /// emoji variation selector) — the trigger for the reciprocal-wave chip.
  bool _isWaveEmojiText(String text) {
    var t = text.trim();
    if (t.isEmpty) return false;
    // Strip variation selector + skin-tone modifiers, keep the base scalar.
    const skinTones = ['\u{1F3FB}', '\u{1F3FC}', '\u{1F3FD}', '\u{1F3FE}', '\u{1F3FF}'];
    t = t.replaceAll('\uFE0F', '');
    for (final tone in skinTones) {
      t = t.replaceAll(tone, '');
    }
    return t == '👋';
  }

