  Future<void> _sendWaveEmoji() async {
    if (_sendInFlight) return;
    final draft = _text.text;
    _text.text = '👋';
    await _send();
    if (!mounted) return;
    if (draft.trim().isNotEmpty && _text.text.trim().isEmpty) {
      _text.text = draft;
    }
  }

  Future<void> _sendInner({int? scheduledAtMs}) async {
    final text = _text.text.trim();
    final editingTarget = _editingTarget;
    final hasForward = _forwardDraft != null;
    if (text.isEmpty && !hasForward) return;
    // Telegram-style: pulse the animated wallpaper when a message is sent.
    if (editingTarget == null) {
      _shimmerWallpaperOnSend();
      _conductWallpaper(incoming: false);
    }
    final editFailedText = chatText(
      context,
      ru: 'Не удалось изменить это сообщение.',
      en: 'Could not edit this message.',
    );
    final someForwardSkippedText = chatText(
      context,
      ru: 'Часть пересылаемых сообщений была пропущена из-за настроек приватности отправителя.',
      en: 'Some forwarded messages were skipped because the sender restricted forwarding.',
    );
    final allForwardBlockedText = chatText(
      context,
      ru: 'Эти сообщения нельзя пересылать из-за настроек приватности отправителя.',
      en: 'These messages cannot be forwarded because the sender restricted forwarding.',
    );
    // Карточку ссылки берём ДО очистки поля: очистка сбрасывает черновик.
    // У правки карточка своя — из исходного сообщения.
    final linkPreview = editingTarget == null
        ? _linkPreviewDraft.takeFor(text)
        : null;
    _text.clear();
    _linkPreviewDraft.reset();
    unawaited(_clearDraft());
    _stopTypingNow();
    final replyToPayloadEventId = _replyTo?.payloadEventId;
    try {
      if (editingTarget != null) {
        if (text == editingTarget.originalText.trim()) {
          if (mounted) {
            setState(() {
              _editingTarget = null;
              _composerMentionDraft = null;
            });
          }
          return;
        }
        final mentions = _isGroupChat
            ? await _resolveOutgoingGroupMentions(text)
            : const <MsgMentionV1>[];
        final changed = await widget.controller.editTextMessage(
          convoId: widget.convoId,
          payloadEventId: editingTarget.payloadEventId,
          text: text,
          mentions: mentions,
        );
        if (!changed) {
          throw StateError(editFailedText);
        }
        if (mounted) {
          setState(() {
            _editingTarget = null;
            _replyTo = null;
            _composerMentionDraft = null;
          });
        }
        return;
      }

      if (_isGroupChat) {
        final mentions = text.isEmpty
            ? const <MsgMentionV1>[]
            : await _resolveOutgoingGroupMentions(text);
        if (hasForward) {
          var sentForwardContent = false;
          var blockedForwardCount = 0;
          if (text.isNotEmpty) {
            await widget.controller.sendGroupMessage(
              groupId: widget.convoId,
              text: text,
              replyToPayloadEventId: replyToPayloadEventId,
              mentions: mentions,
              scheduledAtMs: scheduledAtMs,
              topicId: _currentTopicId,
              linkPreview: linkPreview,
            );
            sentForwardContent = true;
          }
          final draft = _forwardDraft;
          if (draft != null) {
            for (final item in draft.items) {
              if (!await widget.controller.canForwardFromProfile(
                item.sourceProfileId,
              )) {
                blockedForwardCount += 1;
                continue;
              }
              if (item.isText) {
                await widget.controller.sendGroupMessage(
                  groupId: widget.convoId,
                  text: buildForwardCommand(
                    authorName: item.authorName,
                    text: item.text ?? '',
                    authorProfileId: item.sourceProfileId,
                    sourceConvoId: item.sourceConvoId,
                  ),
                  topicId: _currentTopicId,
                );
                sentForwardContent = true;
              } else if (item.isSticker) {
                final sticker = item.sticker;
                if (sticker == null) continue;
                await widget.controller.sendGroupSticker(
                  groupId: widget.convoId,
                  sticker: sticker,
                  topicId: _currentTopicId,
                );
                sentForwardContent = true;
              } else {
                // Пересылка вложения В ГРУППУ. Раньше здесь байты писались во
                // временный файл, а расширение бралось как «часть типа после
                // дроби»: у `application/octet-stream` выходило `.octet-stream`.
                final forwardEvent = item.attachmentEvent;
                if (forwardEvent == null) continue;
                // Тот же довод, что в личной ветке: пузырь с прогрессом сразу,
                // а не молчание на всё время загрузки.
                await _enqueueForwardAttachment(
                  item: item,
                  event: forwardEvent,
                  targetId: widget.convoId,
                  isGroup: true,
                );
                sentForwardContent = true;
              }
            }
          }
          if (mounted) {
            setState(() {
              _forwardDraft = null;
              _replyTo = null;
            });
          }
          widget.controller.clearForwardDraft();
          if (blockedForwardCount > 0) {
            _showChatMessage(
              sentForwardContent
                  ? someForwardSkippedText
                  : allForwardBlockedText,
            );
          }
          return;
        }

        await widget.controller.sendGroupMessage(
          groupId: widget.convoId,
          text: text,
          replyToPayloadEventId: replyToPayloadEventId,
          mentions: mentions,
          scheduledAtMs: scheduledAtMs,
          topicId: _currentTopicId,
          linkPreview: linkPreview,
        );
        if (mounted && _replyTo != null) {
          setState(() => _replyTo = null);
        }
        return;
      }

      final peer = widget.peerProfileIdForSend;
      if (peer == null || peer.isEmpty) {
        throw StateError(context.l10n.missingRecipient);
      }

      if (hasForward) {
        var sentForwardContent = false;
        var blockedForwardCount = 0;
        if (text.isNotEmpty) {
          await widget.controller.sendMessage(
            peerProfileId: peer,
            text: text,
            replyToPayloadEventId: replyToPayloadEventId,
            scheduledAtMs: scheduledAtMs,
            linkPreview: linkPreview,
          );
          sentForwardContent = true;
        }
        final draft = _forwardDraft;
        if (draft != null) {
          for (final item in draft.items) {
            if (!await widget.controller.canForwardFromProfile(
              item.sourceProfileId,
            )) {
              blockedForwardCount += 1;
              continue;
            }
            if (item.isText) {
              await widget.controller.sendMessage(
                peerProfileId: peer,
                text: buildForwardCommand(
                  authorName: item.authorName,
                  text: item.text ?? '',
                  authorProfileId: item.sourceProfileId,
                  sourceConvoId: item.sourceConvoId,
                ),
              );
              sentForwardContent = true;
            } else if (item.isSticker) {
              final sticker = item.sticker;
              if (sticker == null) continue;
              await widget.controller.sendSticker(
                peerProfileId: peer,
                sticker: sticker,
              );
              sentForwardContent = true;
            } else {
              final forwardEvent = item.attachmentEvent;
              if (forwardEvent == null) continue;
              // 🔴 ПУЗЫРЬ ПОЯВЛЯЕТСЯ СРАЗУ (14.08.2026, жалоба: «после нажатия
              // „Отправить“ ничего не происходит секунд 20-30»).
              //
              // Здесь стояла ПРЯМАЯ отправка: она ждёт, пока файл зашифруется и
              // уйдёт на сервер целиком, и всё это время в чате пусто. Обычная
              // отправка файла так себя не ведёт — она кладёт задание в очередь
              // загрузок, и пузырь с прогрессом виден с первой секунды.
              // Пересылка теперь идёт тем же путём.
              await _enqueueForwardAttachment(
                item: item,
                event: forwardEvent,
                targetId: peer,
                isGroup: false,
              );
              sentForwardContent = true;
            }
          }
        }
        if (mounted) {
          setState(() {
            _forwardDraft = null;
            _replyTo = null;
          });
        }
        widget.controller.clearForwardDraft();
        if (blockedForwardCount > 0) {
          _showChatMessage(
            sentForwardContent ? someForwardSkippedText : allForwardBlockedText,
          );
        }
        return;
      }

      await widget.controller.sendMessage(
        peerProfileId: peer,
        text: text,
        replyToPayloadEventId: replyToPayloadEventId,
        scheduledAtMs: scheduledAtMs,
        linkPreview: linkPreview,
      );
      if (mounted && _replyTo != null) {
        setState(() => _replyTo = null);
      }
    } catch (e) {
      if (!mounted) return;

      final l10n = context.l10n;
      final roomPolicyText = tryRoomPolicyErrorText(l10n, e);
      if (roomPolicyText != null) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SecretlySnackBar(content: Text(roomPolicyText)));
        return;
      }

      final peer = widget.peerProfileIdForSend;
      final isUnverified =
          e is StateError &&
          e.message.toString().startsWith('Contact is unverified');
      if (isUnverified && peer != null && peer.isNotEmpty) {
        // Раньше здесь была всплывающая полоска с малозаметной кнопкой —
        // человек видел красную галочку и «проверьте, чтобы продолжить», не
        // понимая ни что случилось, ни зачем ему какие-то номера. Теперь это
        // разговор: что произошло, что переписка по-прежнему зашифрована, и
        // два внятных выхода.
        final strict = widget.controller.blockUnverified;
        final choice = await showDialog<String>(
          context: context,
          builder: (dialogContext) => AlertDialog(
            title: Text(
              strict ? l10n.verifyRequired : l10n.safetyNumberChangedTitle,
            ),
            content: Text(
              strict ? l10n.safetyNumberStrictBody : l10n.safetyNumberChangedBody,
            ),
            actions: [
              // «Отправить всё равно» НЕ предлагается в строгом режиме: человек
              // сам включил «блокировать отправку непроверенным», и кнопка,
              // обходящая эту настройку, обессмысливала бы её.
              if (!strict)
                TextButton(
                  onPressed: () => Navigator.of(dialogContext).pop('send'),
                  child: Text(l10n.sendAnyway),
                ),
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop('verify'),
                child: Text(l10n.verify),
              ),
            ],
          ),
        );
        if (!mounted) return;
        if (choice == 'verify') {
          Navigator.of(context).push(
            SecretlyPageRoute(
              builder: (_) => VerifyContactScreen(
                controller: widget.controller,
                peerProfileId: peer,
                title: widget.title,
              ),
            ),
          );
          return;
        }
        if (choice == 'send') {
          try {
            await widget.controller.approveUnverifiedContactDevices(peer);
            await widget.controller.sendMessage(
              peerProfileId: peer,
              text: text,
              replyToPayloadEventId: replyToPayloadEventId,
              scheduledAtMs: scheduledAtMs,
              linkPreview: linkPreview,
            );
          } catch (retryError) {
            if (!mounted) return;
            ScaffoldMessenger.of(context).showSnackBar(
              SecretlySnackBar(
                content: Text(directMessageErrorText(l10n, retryError)),
              ),
            );
          }
        }
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(content: Text(directMessageErrorText(l10n, e))),
      );
    } finally {
      if (mounted) {
        _messageInputFocusNode.requestFocus();
      }
    }
  }

