  String _formatAuditTimestamp(int ms) {
    final dt = DateTime.fromMillisecondsSinceEpoch(ms).toLocal();
    String two(int v) => v.toString().padLeft(2, '0');
    return '${two(dt.day)}.${two(dt.month)}.${dt.year} ${two(dt.hour)}:${two(dt.minute)}';
  }

  Future<void> _openMuteOptions({required bool muted}) async {
    final mute = await widget.controller.getChatMute(widget.convoId);
    if (!mounted) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    final cs = Theme.of(context).colorScheme;

    Widget tile({
      required IconData icon,
      required String label,
      String? subtitle,
      required VoidCallback onTap,
      Color? color,
    }) {
      return ListTile(
        leading: Icon(
          icon,
          color: color ?? cs.onSurface.withValues(alpha: 0.8),
        ),
        title: Text(
          label,
          style: color == null ? null : TextStyle(color: color),
        ),
        subtitle: subtitle == null ? null : Text(subtitle),
        onTap: onTap,
      );
    }

    await showModalBottomSheet<void>(
      context: context,
      showDragHandle: true,
      backgroundColor: Theme.of(context).colorScheme.surface,
      builder: (sheetContext) {
        return SafeArea(
          top: false,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: <Widget>[
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 4, 20, 8),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    chatText(context, ru: 'Уведомления', en: 'Notifications'),
                    style: Theme.of(sheetContext).textTheme.titleMedium
                        ?.copyWith(fontWeight: FontWeight.w700),
                  ),
                ),
              ),
              tile(
                icon: AppIcons.schedule,
                label: chatText(
                  context,
                  ru: 'Без звука 1 час',
                  en: 'Mute for 1 hour',
                ),
                onTap: () {
                  Navigator.of(sheetContext).pop();
                  unawaited(
                    widget.controller.setChatMute(
                      convoId: widget.convoId,
                      untilMs: now + 60 * 60 * 1000,
                      mentionsOnly: mute.mentionsOnly,
                    ),
                  );
                },
              ),
              tile(
                icon: AppIcons.schedule,
                label: chatText(
                  context,
                  ru: 'Без звука 8 часов',
                  en: 'Mute for 8 hours',
                ),
                onTap: () {
                  Navigator.of(sheetContext).pop();
                  unawaited(
                    widget.controller.setChatMute(
                      convoId: widget.convoId,
                      untilMs: now + 8 * 60 * 60 * 1000,
                      mentionsOnly: mute.mentionsOnly,
                    ),
                  );
                },
              ),
              tile(
                icon: AppIcons.bellOff,
                label: chatText(
                  context,
                  ru: 'Без звука навсегда',
                  en: 'Mute until I turn it back on',
                ),
                onTap: () {
                  Navigator.of(sheetContext).pop();
                  unawaited(
                    widget.controller.setChatMute(
                      convoId: widget.convoId,
                      untilMs: -1,
                      mentionsOnly: mute.mentionsOnly,
                    ),
                  );
                },
              ),
              if (_isGroupChat)
                SwitchListTile.adaptive(
                  secondary: Icon(
                    AppIcons.at,
                    color: cs.onSurface.withValues(alpha: 0.8),
                  ),
                  title: Text(
                    chatText(
                      context,
                      ru: 'Только упоминания',
                      en: 'Mentions only',
                    ),
                  ),
                  subtitle: Text(
                    chatText(
                      context,
                      ru: 'Уведомлять, только когда вас упомянули',
                      en: 'Notify only when you are @mentioned',
                    ),
                  ),
                  value: mute.mentionsOnly,
                  onChanged: (value) {
                    Navigator.of(sheetContext).pop();
                    final until = mute.untilMs == 0 ? -1 : mute.untilMs;
                    unawaited(
                      widget.controller.setChatMute(
                        convoId: widget.convoId,
                        untilMs: until,
                        mentionsOnly: value,
                      ),
                    );
                  },
                ),
              if (muted || mute.untilMs != 0)
                tile(
                  icon: AppIcons.bell,
                  label: chatText(context, ru: 'Включить звук', en: 'Unmute'),
                  color: cs.primary,
                  onTap: () {
                    Navigator.of(sheetContext).pop();
                    unawaited(
                      widget.controller.setChatMute(
                        convoId: widget.convoId,
                        untilMs: 0,
                        mentionsOnly: false,
                      ),
                    );
                  },
                ),
              const SizedBox(height: 6),
            ],
          ),
        );
      },
    );
  }

  /// Room (group) overflow menu — opened from the room header's 3-dots.
  ///
  /// Replaces the previous behaviour where the 3-dots pushed [RoomDetailsScreen]
  /// directly. Each item reuses existing logic so 1:1 behaviour is untouched:
  ///  • Room info        → [_openRoomDetails] (full room profile stays reachable,
  ///                       in addition to the avatar/title header tap).
  ///  • Notifications     → [_openMuteOptions] (the same per-convo sheet 1:1 uses).
  ///  • Change wallpaper  → [_showWallpaperPickerSheet] (per-convo, local-only).
  ///  • Clear history     → admin gets the "clear for all" checkbox (server
  ///                       fanout via [AppController.clearChatHistoryEverywhere]);
  ///                       non-admins clear only their own copy via
  ///                       [AppController.clearChatHistory].
  ///  • Leave group       → confirmation with an optional "Block" checkbox; on
  ///                       confirm leaves via [_leaveRoomAndPop] and (if ticked)
  ///                       blocks the room owner via
  ///                       [AppController.setProfileBlocked].
  Future<void> _openRoomActionsMenu() async {
    final muted = await widget.controller.isChatMuted(widget.convoId);
    RoomPolicyState? policy;
    try {
      policy = await widget.controller.getRoomPolicyState(widget.convoId);
    } catch (_) {
      policy = null;
    }
    if (!mounted) return;
    final isAdmin = policy?.canManageSettings ?? false;
    final isOwner = policy?.isOwner ?? false;
    final ownerProfileId = policy?.settings.ownerProfileId.trim() ?? '';
    final cs = Theme.of(context).colorScheme;

    // Anchor a dropdown ("burger") menu to the 3-dots button so it drops down
    // from it, instead of sliding up as a bottom sheet.
    final overlay =
        Overlay.of(context).context.findRenderObject() as RenderBox?;
    final buttonBox =
        _roomMenuButtonKey.currentContext?.findRenderObject() as RenderBox?;
    final RelativeRect position;
    if (overlay != null && buttonBox != null) {
      position = RelativeRect.fromRect(
        Rect.fromPoints(
          buttonBox.localToGlobal(Offset.zero, ancestor: overlay),
          buttonBox.localToGlobal(
            buttonBox.size.bottomRight(Offset.zero),
            ancestor: overlay,
          ),
        ),
        Offset.zero & overlay.size,
      );
    } else {
      final media = MediaQuery.of(context);
      position = RelativeRect.fromLTRB(
        media.size.width,
        media.padding.top + kToolbarHeight,
        8,
        0,
      );
    }

    PopupMenuItem<String> menuItem({
      required String value,
      required IconData icon,
      required String label,
      Color? color,
    }) {
      return PopupMenuItem<String>(
        value: value,
        child: Row(
          children: [
            Icon(
              icon,
              size: 20,
              color: color ?? cs.onSurface.withValues(alpha: 0.85),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Text(
                label,
                style: color == null ? null : TextStyle(color: color),
              ),
            ),
          ],
        ),
      );
    }

    final selected = await showMenu<String>(
      context: context,
      position: position,
      items: [
        menuItem(
          value: 'info',
          icon: AppIcons.groups,
          label: chatText(
            context,
            ru: 'Информация о комнате',
            en: 'Room info',
            uk: 'Інформація про кімнату',
            es: 'Información de la sala',
            pt: 'Informações da sala',
            fr: 'Infos du salon',
            de: 'Rauminfo',
          ),
        ),
        menuItem(
          value: 'notifs',
          icon: muted ? AppIcons.bellOff : AppIcons.bell,
          label: chatText(
            context,
            ru: 'Уведомления',
            en: 'Notifications',
            uk: 'Сповіщення',
            es: 'Notificaciones',
            pt: 'Notificações',
            fr: 'Notifications',
            de: 'Benachrichtigungen',
          ),
        ),
        menuItem(
          value: 'share_room',
          icon: AppIcons.reply,
          label: chatText(
            context,
            ru: 'Поделиться комнатой',
            en: 'Share room',
            uk: 'Поділитися кімнатою',
            es: 'Compartir sala',
            pt: 'Partilhar sala',
            fr: 'Partager le salon',
            de: 'Raum teilen',
          ),
        ),
        menuItem(
          value: 'wallpaper',
          icon: AppIcons.wallpaper,
          label: chatText(
            context,
            ru: 'Сменить обои',
            en: 'Change wallpaper',
            uk: 'Змінити шпалери',
            es: 'Cambiar fondo',
            pt: 'Alterar papel de parede',
            fr: 'Changer le fond',
            de: 'Hintergrund ändern',
          ),
        ),
        menuItem(
          value: 'clear',
          icon: AppIcons.delete,
          label: chatText(
            context,
            ru: 'Очистить историю',
            en: 'Clear history',
            uk: 'Очистити історію',
            es: 'Borrar historial',
            pt: 'Limpar histórico',
            fr: 'Effacer l\'historique',
            de: 'Verlauf löschen',
          ),
          color: cs.error,
        ),
        menuItem(
          value: 'leave',
          icon: AppIcons.leaveRoomAction,
          label: chatText(
            context,
            ru: 'Выйти из группы',
            en: 'Leave group',
            uk: 'Вийти з групи',
            es: 'Salir del grupo',
            pt: 'Sair do grupo',
            fr: 'Quitter le groupe',
            de: 'Gruppe verlassen',
          ),
          color: cs.error,
        ),
      ],
    );

    if (!mounted || selected == null) return;
    switch (selected) {
      case 'info':
        _openRoomDetails();
        break;
      case 'notifs':
        unawaited(_openMuteOptions(muted: muted));
        break;
      case 'share_room':
        unawaited(_shareRoomExternally());
        break;
      case 'wallpaper':
        unawaited(_showWallpaperPickerSheet());
        break;
      case 'clear':
        unawaited(_clearRoomHistoryFromMenu(isAdmin: isAdmin));
        break;
      case 'leave':
        unawaited(
          _leaveRoomFromMenu(ownerProfileId: ownerProfileId, isOwner: isOwner),
        );
        break;
    }
  }

