  /// Leave-group flow for the room menu. Confirmation dialog with an optional
  /// "Block" checkbox. On confirm, leaves via [AppController.leaveRoom]; if the
  /// box is ticked and the room owner is resolvable (and not me), also blocks
  /// that owner profile via the existing block API, then pops the chat.
  ///
  /// Owners with other members cannot leave without first transferring
  /// ownership — that flow lives in [RoomDetailsScreen], so we route them there
  /// instead of attempting an inline leave that would fail.
  Future<void> _leaveRoomFromMenu({
    required String ownerProfileId,
    required bool isOwner,
  }) async {
    if (isOwner) {
      _openRoomDetails();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(
            chatText(
              context,
              ru: 'Вы владелец. Передайте права или удалите комнату в настройках комнаты.',
              en: 'You are the owner. Transfer ownership or delete the room from room settings.',
              uk: 'Ви власник. Передайте права або видаліть кімнату в налаштуваннях кімнати.',
              es: 'Eres el propietario. Transfiere la propiedad o elimina la sala desde los ajustes de la sala.',
              pt: 'Você é o proprietário. Transfira a propriedade ou exclua a sala nas configurações da sala.',
              fr: 'Vous êtes le propriétaire. Transférez la propriété ou supprimez le salon dans les paramètres du salon.',
              de: 'Du bist der Eigentümer. Übertrage die Eigentümerschaft oder lösche den Raum in den Raumeinstellungen.',
            ),
          ),
        ),
      );
      return;
    }
    final myProfileId = widget.controller.profileId.trim();
    final canBlockOwner =
        ownerProfileId.isNotEmpty && ownerProfileId != myProfileId;
    bool block = false;
    final ok = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return StatefulBuilder(
          builder: (dialogContext, setLocalState) {
            return AlertDialog(
              title: Text(
                chatText(
                  context,
                  ru: 'Выйти из группы?',
                  en: 'Leave group?',
                  uk: 'Вийти з групи?',
                  es: '¿Salir del grupo?',
                  pt: 'Sair do grupo?',
                  fr: 'Quitter le groupe ?',
                  de: 'Gruppe verlassen?',
                ),
              ),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    chatText(
                      context,
                      ru: 'Вы действительно хотите покинуть эту группу?',
                      en: 'Do you really want to leave this group?',
                      uk: 'Ви дійсно хочете покинути цю групу?',
                      es: '¿Seguro que quieres salir de este grupo?',
                      pt: 'Tem certeza de que deseja sair deste grupo?',
                      fr: 'Voulez-vous vraiment quitter ce groupe ?',
                      de: 'Möchtest du diese Gruppe wirklich verlassen?',
                    ),
                  ),
                  if (canBlockOwner) ...[
                    const SizedBox(height: 12),
                    CheckboxListTile(
                      value: block,
                      onChanged: (v) => setLocalState(() => block = v == true),
                      title: Text(
                        chatText(
                          context,
                          ru: 'Заблокировать',
                          en: 'Block',
                          uk: 'Заблокувати',
                          es: 'Bloquear',
                          pt: 'Bloquear',
                          fr: 'Bloquer',
                          de: 'Blockieren',
                        ),
                      ),
                      controlAffinity: ListTileControlAffinity.leading,
                      contentPadding: EdgeInsets.zero,
                    ),
                  ],
                ],
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(dialogContext).pop(false),
                  child: Text(context.l10n.cancel),
                ),
                TextButton(
                  style: TextButton.styleFrom(foregroundColor: Colors.red),
                  onPressed: () => Navigator.of(dialogContext).pop(true),
                  child: Text(
                    chatText(
                      context,
                      ru: 'Выйти',
                      en: 'Leave',
                      uk: 'Вийти',
                      es: 'Salir',
                      pt: 'Sair',
                      fr: 'Quitter',
                      de: 'Verlassen',
                    ),
                  ),
                ),
              ],
            );
          },
        );
      },
    );
    if (ok != true) return;
    try {
      if (block && canBlockOwner) {
        await widget.controller.setProfileBlocked(
          profileId: ownerProfileId,
          blocked: true,
          deleteChatHistory: false,
        );
      }
      await widget.controller.leaveRoom(widget.convoId);
      if (!mounted) return;
      Navigator.of(context).pop();
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(context.l10n.actionFailed(e.toString())),
        ),
      );
    }
  }

  Future<void> _handleMenu(
    String v, {
    required bool muted,
    required bool blocked,
    required String peerProfileId,
  }) async {
    try {
      switch (v) {
        case 'verify':
          Navigator.of(context).push(
            SecretlyPageRoute(
              builder: (_) => VerifyContactScreen(
                controller: widget.controller,
                peerProfileId: peerProfileId,
                title: widget.title,
              ),
            ),
          );
          return;
        case 'mute':
          await _openMuteOptions(muted: muted);
          return;
        case 'search':
          if (!_chatSearchOpen) {
            _toggleChatSearch();
            return;
          }
          await _search();
          return;
        case 'set_photo':
          final picked = await FilePicker.platform.pickFiles(
            withData: true,
            type: FileType.custom,
            allowedExtensions: const [
              'jpg',
              'jpeg',
              'png',
              'webp',
              'heic',
              'heif',
            ],
          );
          final f = picked?.files.single;
          if (f == null || f.bytes == null) return;
          final bytes = f.bytes!;
          if (!mounted) return;
          // FIX (2026-07-13): crop over the FULL image (not a forced centre-
          // square) before saving a contact's photo — same crop UX as own
          // profile + room avatars.
          final cropped = await cropCircleAvatarBytes(context, bytes);
          if (cropped == null || cropped.isEmpty) return;
          await widget.controller.setContactAvatarFromImageBytes(
            profileId: peerProfileId,
            bytes: cropped,
          );
          return;
        case 'remove_photo':
          await widget.controller.removeContactAvatar(profileId: peerProfileId);
          return;
        case 'block':
          if (blocked) {
            final ok = await showDialog<bool>(
              context: context,
              builder: (context) {
                return AlertDialog(
                  title: Text(context.l10n.unblockUserConfirmTitle),
                  content: Text(peerProfileId),
                  actions: [
                    TextButton(
                      onPressed: () => Navigator.of(context).pop(false),
                      child: Text(context.l10n.cancel),
                    ),
                    FilledButton(
                      onPressed: () => Navigator.of(context).pop(true),
                      child: Text(context.l10n.unblock),
                    ),
                  ],
                );
              },
            );
            if (ok != true) return;
            await widget.controller.setProfileBlocked(
              profileId: peerProfileId,
              blocked: false,
              deleteChatHistory: false,
            );
            return;
          }

          bool deleteChat = false;
          final ok = await showDialog<bool>(
            context: context,
            builder: (context) {
              return StatefulBuilder(
                builder: (context, setState) {
                  return AlertDialog(
                    title: Text(context.l10n.blockUserConfirmTitle),
                    content: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(peerProfileId),
                        const SizedBox(height: 12),
                        CheckboxListTile(
                          value: deleteChat,
                          onChanged: (v) =>
                              setState(() => deleteChat = v == true),
                          title: Text(context.l10n.alsoDeleteChat),
                          controlAffinity: ListTileControlAffinity.leading,
                          contentPadding: EdgeInsets.zero,
                        ),
                      ],
                    ),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.of(context).pop(false),
                        child: Text(context.l10n.cancel),
                      ),
                      TextButton(
                        style: TextButton.styleFrom(
                          foregroundColor: Colors.red,
                        ),
                        onPressed: () => Navigator.of(context).pop(true),
                        child: Text(context.l10n.block),
                      ),
                    ],
                  );
                },
              );
            },
          );
          if (ok != true) return;
          await widget.controller.setProfileBlocked(
            profileId: peerProfileId,
            blocked: true,
            deleteChatHistory: deleteChat,
          );
          if (!mounted) return;
          if (deleteChat) {
            Navigator.of(context).pop();
          }
          return;
        case 'delete':
          final ok = await showDialog<bool>(
            context: context,
            builder: (context) {
              return AlertDialog(
                title: Text(context.l10n.deleteChatConfirmTitle),
                content: Text(context.l10n.deleteChatConfirmBody),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.of(context).pop(false),
                    child: Text(context.l10n.cancel),
                  ),
                  TextButton(
                    style: TextButton.styleFrom(foregroundColor: Colors.red),
                    onPressed: () => Navigator.of(context).pop(true),
                    child: Text(context.l10n.delete),
                  ),
                ],
              );
            },
          );
          if (ok != true) return;
          await widget.controller.deleteChat(convoId: widget.convoId);
          if (!mounted) return;
          Navigator.of(context).pop();
          return;
        case 'clear_history':
          final ok = await showDialog<bool>(
            context: context,
            builder: (context) {
              return AlertDialog(
                title: Text(
                  chatText(
                    context,
                    ru: 'Очистить историю?',
                    en: 'Clear history?',
                  ),
                ),
                content: Text(
                  chatText(
                    context,
                    ru: 'Сообщения будут удалены у вас и у собеседника на всех подключенных устройствах.',
                    en: 'Messages will be cleared for you and the other participant on all connected devices.',
                  ),
                ),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.of(context).pop(false),
                    child: Text(context.l10n.cancel),
                  ),
                  TextButton(
                    style: TextButton.styleFrom(foregroundColor: Colors.red),
                    onPressed: () => Navigator.of(context).pop(true),
                    child: Text(context.l10n.clear),
                  ),
                ],
              );
            },
          );
          if (ok != true) return;
          await widget.controller.clearChatHistoryEverywhere(
            convoId: widget.convoId,
            directPeerProfileId: peerProfileId,
          );
          return;
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SecretlySnackBar(
          content: Text(context.l10n.actionFailed(e.toString())),
        ),
      );
    }
  }

  void _toggleChatSearch({bool? open}) {
    final nextOpen = open ?? !_chatSearchOpen;
    if (_chatSearchOpen == nextOpen) return;
    setState(() {
      _chatSearchOpen = nextOpen;
      if (!_chatSearchOpen) {
        _chatSearchController.clear();
        // Tear down all search state so highlights vanish and the composer
        // comes back clean.
        _searchDebounce?.cancel();
        _searchRunToken++;
        _searchHits = const <ChatSearchHit>[];
        _currentSearchHitIndex = -1;
        _chatSearchInProgress = false;
        _activeSearchQuery = '';
      }
    });
    _syncComposerTickers();
    // Tap-only: morph the header island into the search field (and back) exactly
    // like chats_screen — same controller, same open/close curves.
    _chatSearchRevealController.animateTo(
      nextOpen ? 1.0 : 0.0,
      curve: nextOpen ? Curves.easeOutCubic : Curves.easeInCubic,
    );
    if (_chatSearchOpen) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _chatSearchFocusNode.requestFocus();
      });
    } else {
      _chatSearchFocusNode.unfocus();
    }
  }

  /// Resolves the day of the row currently at the TOP of the timeline viewport
  /// and drives the floating day chip.
  ///
  /// Deliberately cheap: it walks only the rows Flutter has actually built
  /// (`_eventRowKeys` is pruned to roughly the visible window + 64), runs only
  /// while scrolling, and is throttled — a per-frame render-box walk here would
  /// re-introduce exactly the scroll jank the timeline memo just removed.
  void _updateFloatingDay() {
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    if (nowMs - _lastFloatingDayScanMs < 80) return;
    _lastFloatingDayScanMs = nowMs;
    final timeline = _memoVisibleTimeline;
    if (timeline == null || timeline.isEmpty) return;

    // Topmost row that is not yet fully scrolled behind the islands.
    final topEdge = _timelineTopEdgePx;
    double? bestDy;
    String? bestId;
    for (final entry in _eventRowKeys.entries) {
      final ctx = entry.value.currentContext;
      if (ctx == null) continue;
      final box = ctx.findRenderObject();
      if (box is! RenderBox || !box.hasSize || !box.attached) continue;
      final dy = box.localToGlobal(Offset.zero).dy;
      if (dy + box.size.height <= topEdge) continue; // fully above
      if (bestDy == null || dy < bestDy) {
        bestDy = dy;
        bestId = entry.key;
      }
    }
    if (bestId == null) return;

    int? dayMs;
    for (final t in timeline) {
      if (timelineRowId(t.payloadEventId, t.event.eventId) == bestId) {
        dayMs = t.event.createdAtMs;
        break;
      }
    }
    if (dayMs == null) return;

    final current = _floatingDay.value;
    final needsShow =
        current == null ||
        !_isSameCalendarDay(current.dayMs, dayMs) ||
        !current.visible;
    if (needsShow) {
      // Notifier write, not setState — this runs on scroll ticks and a
      // setState here rebuilt the whole chat mid-fling (see the field docs).
      _floatingDay.value = (dayMs: dayMs, visible: true);
    }
    // Fade out shortly after scrolling stops (Telegram behaviour).
    _floatingDayHideTimer?.cancel();
    _floatingDayHideTimer = Timer(const Duration(milliseconds: 900), () {
      if (!mounted) return;
      final v = _floatingDay.value;
      if (v != null) {
        _floatingDay.value = (dayMs: v.dayMs, visible: false);
      }
    });
  }

  bool _handleChatSearchSwipe(ScrollNotification notification) {
    // PERF: freeze cosmetic frame animations while the timeline is flinging
    // (ballistic updates carry no dragDetails); they auto-resume ~120 ms
    // after the fling settles. See CosmeticMotionGate.
    if (notification is ScrollUpdateNotification &&
        notification.dragDetails == null) {
      CosmeticMotionGate.noteBallisticScroll();
    }
    // Search is controlled only by the magnifier button.
    // Swipe gestures should not open/close it.
    if (notification.metrics.axis != Axis.vertical) return false;
    if (notification is ScrollUpdateNotification) {
      _updateFloatingDay();
    }
    return false;
  }

  /// Debounced entry point wired to the header search field's `onChanged`.
  /// Clears hits immediately when the box is emptied; otherwise waits ~250ms of
  /// idle typing before running the (potentially expensive) full-conversation
  /// match so every keystroke doesn't decrypt the whole chat.
  void _onSearchQueryChanged() {
    _searchDebounce?.cancel();
    final raw = _chatSearchController.text.trim();
    if (raw.isEmpty) {
      // Invalidate any in-flight run and drop highlights right away.
      _searchRunToken++;
      if (_searchHits.isNotEmpty ||
          _currentSearchHitIndex != -1 ||
          _chatSearchInProgress ||
          _activeSearchQuery.isNotEmpty) {
        setState(() {
          _searchHits = const <ChatSearchHit>[];
          _currentSearchHitIndex = -1;
          _chatSearchInProgress = false;
          _activeSearchQuery = '';
        });
      }
      return;
    }
    _searchDebounce = Timer(const Duration(milliseconds: 250), _search);
  }

  /// Runs a full-conversation search for the current query, stores all hits,
  /// selects + scrolls to the first one, and triggers a rebuild so bubbles
  /// highlight. Fail-soft: any error leaves the chat usable (empty result set).
  Future<void> _search() async {
    if (!_chatSearchOpen) return;
    final query = _chatSearchController.text.trim();
    if (query.isEmpty) return;
    final token = ++_searchRunToken;
    setState(() => _chatSearchInProgress = true);

    List<ChatSearchHit> hits;
    try {
      hits = await widget.controller.searchChatMatches(
        convoId: widget.convoId,
        query: query,
      );
    } catch (_) {
      hits = const <ChatSearchHit>[];
    }
    // A newer query (or a close) superseded this run — discard stale results.
    if (!mounted || token != _searchRunToken || !_chatSearchOpen) return;

    setState(() {
      _searchHits = hits;
      _activeSearchQuery = query;
      _chatSearchInProgress = false;
      _currentSearchHitIndex = hits.isEmpty ? -1 : 0;
    });
    if (hits.isNotEmpty) {
      final hit = hits.first;
      unawaited(_scrollToReply(hit.payloadEventId ?? hit.eventId));
    }
  }

  /// Selects hit [i] (clamped), scrolls it into view + briefly flashes it via the
  /// shared reply-highlight, and plays a soft tick. No-op when there are no hits.
  void _gotoSearchHit(int i) {
    if (_searchHits.isEmpty) return;
    final idx = i.clamp(0, _searchHits.length - 1);
    setState(() => _currentSearchHitIndex = idx);
    final hit = _searchHits[idx];
    unawaited(_scrollToReply(hit.payloadEventId ?? hit.eventId));
    unawaited(_playSearchTick());
  }

  void _nextSearchHit() {
    if (_searchHits.isEmpty) return;
    final next = (_currentSearchHitIndex + 1) % _searchHits.length;
    _gotoSearchHit(next);
  }

  void _prevSearchHit() {
    if (_searchHits.isEmpty) return;
    final prev =
        (_currentSearchHitIndex - 1 + _searchHits.length) % _searchHits.length;
    _gotoSearchHit(prev);
  }

  /// Soft click on search navigation. Loads a short bundled in-chat sound, plays
  /// it, and disposes the previous player. Best-effort — any failure is silent.
  Future<void> _playSearchTick() async {
    try {
      final prev = _searchTickPlayer;
      final player = AudioPlayer();
      _searchTickPlayer = player;
      unawaited(prev?.dispose());
      await player.setAsset('assets/app_ui/sounds/inchat/click_s7.mp3');
      await player.play();
    } catch (_) {
      // Sound is non-essential; ignore load/playback errors.
    }
  }

  /// The query bubbles should highlight, or null when search is inactive. Gated
  /// on `_chatSearchOpen` so no highlight work happens outside search.
  String? get _bubbleSearchQuery {
    if (!_chatSearchOpen) return null;
    final q = _activeSearchQuery;
    return q.isEmpty ? null : q;
  }

  /// True when [entry] is the bubble holding the currently-selected search hit.
  bool _isCurrentSearchHitEntry(_TimelineEntry entry) {
    if (!_chatSearchOpen) return false;
    if (_currentSearchHitIndex < 0 ||
        _currentSearchHitIndex >= _searchHits.length) {
      return false;
    }
    final hit = _searchHits[_currentSearchHitIndex];
    final hitId = hit.payloadEventId ?? hit.eventId;
    final entryId = entry.payloadEventId ?? entry.event.eventId;
    return hitId == entryId;
  }

  /// P3 — date carousel. Opens the island wheel picker; on a chosen date jumps
  /// to the FIRST hit whose timestamp is >= start-of-that-day (or the last hit
  /// when the chosen day is after every match). Fail-soft: any error is
  /// swallowed so the chat stays usable.
  Future<void> _onSearchCalendarTapPlaceholder() async {
    if (!mounted) return;
    if (_searchHits.isEmpty) return;
    // Initial date = current hit's date (falls back to now).
    DateTime initial = DateTime.now();
    if (_currentSearchHitIndex >= 0 &&
        _currentSearchHitIndex < _searchHits.length) {
      initial = DateTime.fromMillisecondsSinceEpoch(
        _searchHits[_currentSearchHitIndex].createdAtMs,
      );
    }
    // Year range floor = earliest hit's year (else now-5).
    int earliestYear = DateTime.now().year - 5;
    try {
      final earliestMs = _searchHits
          .map((h) => h.createdAtMs)
          .reduce((a, b) => a < b ? a : b);
      earliestYear = DateTime.fromMillisecondsSinceEpoch(earliestMs).year;
    } catch (_) {
      // keep default
    }

    DateTime? chosen;
    try {
      chosen = await showSearchDateCarousel(
        context,
        initialDate: initial,
        earliestYear: earliestYear,
      );
    } catch (_) {
      chosen = null;
    }
    if (!mounted || chosen == null) return;

    final startOfDay = DateTime(
      chosen.year,
      chosen.month,
      chosen.day,
    ).millisecondsSinceEpoch;
    // Hits are chronological (oldest→newest); first one on/after the chosen day.
    var target = -1;
    for (var i = 0; i < _searchHits.length; i++) {
      if (_searchHits[i].createdAtMs >= startOfDay) {
        target = i;
        break;
      }
    }
    if (target < 0) target = _searchHits.length - 1; // all matches are earlier
    _gotoSearchHit(target);
  }

  /// P2 — results list screen. Pushes the full hit list; on a returned index
  /// scrolls/flashes that hit. Fail-soft.
  Future<void> _onSearchListTapPlaceholder() async {
    if (!mounted) return;
    if (_searchHits.isEmpty) return;
    int? index;
    try {
      index = await Navigator.of(context).push<int>(
        MaterialPageRoute<int>(
          builder: (_) => SearchResultsListScreen(
            controller: widget.controller,
            hits: _searchHits,
            query: _activeSearchQuery,
          ),
        ),
      );
    } catch (_) {
      index = null;
    }
    if (!mounted || index == null) return;
    _gotoSearchHit(index);
  }

  // RETIRED (2026-07-17): the old single-photo caption window. The fullscreen
  // pre-send editor is now the one caption entry point, so this is no longer
  // reachable. Kept (unreferenced) to avoid a risky large deletion; safe to
  // delete wholesale in a cleanup pass.
  // ignore: unused_element
  Future<_PhotoDraft?> _showPhotoPreviewDraft(
    BuildContext context, {
    required String filePath,
  }) async {
    final l10n = context.l10n;
    final c = TextEditingController();
    final file = File(filePath);
    final size = await file.length();
    if (!context.mounted) {
      c.dispose();
      return null;
    }

    final res = await showModalBottomSheet<_PhotoDraft>(
      context: context,
      isScrollControlled: true,
      showDragHandle: false,
      backgroundColor: Colors.transparent,
      builder: (context) {
        // CAPTION SHEET RESTYLE (2026-07-17): the default grey material sheet
        // read cheap next to the app's glass. This is now a proper island —
        // backdrop blur + the shared dense fill — the photo keeps its TRUE
        // aspect and takes most of the sheet's width/height, and the caption
        // field is a quiet rounded fill instead of a harsh outlined box.
        final theme = Theme.of(context);
        final cs = theme.colorScheme;
        final isDark = theme.brightness == Brightness.dark;
        final fillTop = isDark
            ? Colors.white.withValues(alpha: 0.06)
            : Colors.white.withValues(alpha: 0.65);
        final fillBottom = isDark
            ? Colors.white.withValues(alpha: 0.03)
            : Colors.white.withValues(alpha: 0.55);
        final screenH = MediaQuery.sizeOf(context).height;
        return ClipRRect(
          borderRadius: const BorderRadius.vertical(top: Radius.circular(28)),
          child: BackdropFilter(
            filter: ImageFilter.blur(sigmaX: 24, sigmaY: 24),
            child: Container(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [fillTop, fillBottom],
                ),
                border: Border(
                  top: BorderSide(
                    color: Colors.white.withValues(
                      alpha: isDark ? 0.22 : 0.42,
                    ),
                    width: 1.2,
                  ),
                ),
              ),
              child: SafeArea(
                top: false,
                child: Padding(
                  padding: EdgeInsets.only(
                    bottom: MediaQuery.viewInsetsOf(context).bottom,
                  ),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const SizedBox(height: 10),
                      Container(
                        width: 36,
                        height: 4,
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(999),
                          color: cs.onSurface.withValues(alpha: 0.25),
                        ),
                      ),
                      const SizedBox(height: 12),
                      Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 10),
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(18),
                          child: ConstrainedBox(
                            constraints: BoxConstraints(
                              maxHeight: screenH * 0.56,
                            ),
                            // TRUE aspect, full width: the photo owns the
                            // sheet instead of a small square crop.
                            child: LayoutBuilder(
                              builder: (context, constraints) {
                                final dpr = MediaQuery.devicePixelRatioOf(
                                  context,
                                );
                                final w = constraints.maxWidth;
                                final cacheDim = w.isFinite && w > 0
                                    ? (w * dpr).round()
                                    : null;
                                return Image.file(
                                  file,
                                  fit: BoxFit.contain,
                                  width: double.infinity,
                                  cacheWidth: cacheDim,
                                  errorBuilder: (_, _, _) =>
                                      const _BrokenMediaBox(iconSize: 32),
                                );
                              },
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(height: 12),
                      Padding(
                        padding: const EdgeInsets.fromLTRB(12, 0, 12, 10),
                        child: TextField(
                          controller: c,
                          decoration: InputDecoration(
                            hintText: l10n.addCaption,
                            hintStyle: TextStyle(
                              color: cs.onSurface.withValues(alpha: 0.45),
                            ),
                            filled: true,
                            fillColor: cs.onSurface.withValues(alpha: 0.06),
                            contentPadding: const EdgeInsets.symmetric(
                              horizontal: 14,
                              vertical: 11,
                            ),
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(14),
                              borderSide: BorderSide.none,
                            ),
                            focusedBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(14),
                              borderSide: BorderSide(
                                color: cs.primary.withValues(alpha: 0.45),
                                width: 1.2,
                              ),
                            ),
                          ),
                          keyboardType: TextInputType.multiline,
                          textCapitalization: TextCapitalization.sentences,
                          autocorrect: true,
                          enableSuggestions: true,
                          smartDashesType: SmartDashesType.enabled,
                          smartQuotesType: SmartQuotesType.enabled,
                          maxLines: 3,
                          minLines: 1,
                        ),
                      ),
                      Padding(
                        padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                        child: Row(
                          children: [
                            TextButton(
                              onPressed: () => Navigator.of(context).pop(null),
                              child: Text(l10n.cancel),
                            ),
                            const Spacer(),
                            FilledButton.icon(
                              onPressed: () {
                                Navigator.of(context).pop(
                                  _PhotoDraft(
                                    caption: c.text.trim(),
                                    fileBytes: size,
                                  ),
                                );
                              },
                              icon: const Icon(AppIcons.send),
                              label: Text(l10n.send),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
    c.dispose();
    return res;
  }

}

enum _RoomMentionCandidateKind { member, all, here, admins }


/// Composer action button — send / voice / video, all three share this.
///
/// TWO jobs beyond drawing a circle:
///
/// **1. A forgiving touch target.** The visual stays [size] (40), but the
/// widget claims [size] + 2×[hitSlop] and centres the circle inside it, so the
/// tappable area reaches the 48dp Android/iOS minimum without the button
/// looking any bigger. Users kept just missing it — a 40dp target is below the
/// guideline for a control this important, and it sits at the very edge of the
/// screen where thumbs are least precise. Flutter will NOT deliver taps that
/// land outside a widget's own box, so growing the box is the only honest fix;
/// the caller trims the neighbouring gap so nothing moves visually.
///
/// **2. A water-drop press.** Down: the circle compresses like a droplet
/// meeting a surface. Release: it springs back past 1.0 and settles, while a
/// ring expands from its rim and fades — the "бульк". Deliberately quiet:
/// 0.9 scale, one thin ring, ~0.4 s. A send button is pressed hundreds of times
/// a day, and anything louder becomes tiring long before it becomes charming.
///
/// Honours the platform's reduce-motion setting: with animations disabled the
/// button still responds, just without the flourish.
class _ComposerActionButton extends StatefulWidget {
  const _ComposerActionButton({
    super.key,
    required this.topColor,
    required this.bottomColor,
    required this.iconColor,
    required this.size,
    required this.child,
    this.onPressed,
    this.onLongPress,
    this.focusNode,
  });

  final Color topColor;
  final Color bottomColor;
  final Color iconColor;
  final double size;
  final Widget child;
  final VoidCallback? onPressed;
  final VoidCallback? onLongPress;
  final FocusNode? focusNode;

  @override
  State<_ComposerActionButton> createState() => _ComposerActionButtonState();
}

class _ComposerActionButtonState extends State<_ComposerActionButton>
    with TickerProviderStateMixin {
  late final AnimationController _press = AnimationController(
    vsync: this,
    // Slower on the way in so the compression is actually seen, and a long,
    // soft rebound so the spring reads as liquid rather than a twitch.
    // The press follows the finger quickly enough to feel responsive; the
    // RELEASE is where the length lives, because that is the part you watch.
    duration: const Duration(milliseconds: 200),
    reverseDuration: const Duration(milliseconds: 840),
  );
  late final AnimationController _ripple = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 900),
  );

  bool get _enabled => widget.onPressed != null;

  @override
  void dispose() {
    _press.dispose();
    _ripple.dispose();
    super.dispose();
  }

  void _down() {
    if (!_enabled) return;
    HapticFeedback.lightImpact();
    _press.forward();
  }

  /// Springs back and drops the ring. Used by both release and cancel so a
  /// finger that slides off never leaves the button stuck compressed.
  void _up() {
    if (_press.value == 0) return;
    _press.reverse();
  }

  void _tap() {
    if (!_enabled) return;
    _ripple.forward(from: 0);
    widget.onPressed!.call();
  }

  @override
  Widget build(BuildContext context) {
    final reduceMotion = MediaQuery.maybeOf(context)?.disableAnimations ?? false;
    // +4 on every side: a 40 visual becomes a 48 target, the platform minimum.
    const hitSlop = 4.0;
    final box = widget.size + hitSlop * 2;
    final resolvedTop = _enabled
        ? widget.topColor
        : widget.topColor.withValues(alpha: 0.45);
    final resolvedBottom = _enabled
        ? widget.bottomColor
        : widget.bottomColor.withValues(alpha: 0.45);
    final resolvedIcon = _enabled
        ? widget.iconColor
        : widget.iconColor.withValues(alpha: 0.55);

    final visual = DecoratedBox(
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [resolvedTop, resolvedBottom],
        ),
        boxShadow: [
          BoxShadow(
            color: resolvedBottom.withValues(alpha: _enabled ? 0.32 : 0.14),
            blurRadius: 14,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: SizedBox(
        width: widget.size,
        height: widget.size,
        child: IconTheme(
          data: IconThemeData(color: resolvedIcon),
          child: Center(child: widget.child),
        ),
      ),
    );

    return Focus(
      focusNode: widget.focusNode,
      child: GestureDetector(
        // Opaque so the whole slop area counts, not just the painted circle.
        behavior: HitTestBehavior.opaque,
        onTapDown: reduceMotion ? null : (_) => _down(),
        onTapUp: reduceMotion ? null : (_) => _up(),
        onTapCancel: reduceMotion ? null : _up,
        onTap: _tap,
        onLongPress: widget.onLongPress,
        child: SizedBox(
          width: box,
          height: box,
          child: Center(
            child: reduceMotion
                ? visual
                : AnimatedBuilder(
                    animation: Listenable.merge([_press, _ripple]),
                    builder: (context, child) {
                      // 1.0 → 0.90 down; elasticOut on the way back gives the
                      // little overshoot that reads as a droplet rebound.
                      // easeInOutCubic going down (no snap), and a gentler
                      // spring coming back: elasticOut overshoots hard and
                      // reads as a bounce; this settles like a drop.
                      // easeOutCubic on the way down: moves immediately with
                      // the finger, then eases into the bottom instead of
                      // hitting it — that landing is what reads as "soft".
                      final t = _press.status == AnimationStatus.reverse
                          ? _softSpring(1 - _press.value)
                          : 1 - Curves.easeOutCubic.transform(_press.value);
                      // 0.76: clearly visible travel. Deeper than this and the
                      // icon starts to shrink noticeably, which looks cheap.
                      final scale = 0.76 + 0.24 * t.clamp(0.0, 1.14);
                      return CustomPaint(
                        painter: _DropletRipplePainter(
                          progress: _ripple.value,
                          color: resolvedBottom,
                          radius: widget.size / 2,
                        ),
                        child: Transform.scale(scale: scale, child: child),
                      );
                    },
                    child: visual,
                  ),
          ),
        ),
      ),
    );
  }
}

/// A spring that overshoots ONCE, gently, then settles.
///
/// `Curves.elasticOut` wobbles several times and reads as a bounce — fine for a
/// toy, wrong for a control pressed hundreds of times a day. This is a single
/// damped overshoot of a few percent: the eye registers "it sprang back"
/// without the button ever looking unstable.
double _softSpring(double t) {
  if (t <= 0) return 0;
  if (t >= 1) return 1;
  // Lower damping ⇒ the overshoot is actually visible; the frequency is kept
  // below 2 so there is still only ONE swing back, not a wobble.
  const damping = 3.4;
  const frequency = 1.35;
  return 1 - exp(-damping * t) * cos(frequency * pi * t) * (1 - t * 0.35);
}

/// The ring that expands from the button's rim and fades — the visible half of
/// the "бульк". One thin stroke, never a filled splash: a filled one reads as a
/// loading state at this size.
class _DropletRipplePainter extends CustomPainter {
  const _DropletRipplePainter({
    required this.progress,
    required this.color,
    required this.radius,
  });

  final double progress;
  final Color color;
  final double radius;

  @override
  void paint(Canvas canvas, Size size) {
    if (progress <= 0 || progress >= 1) return;
    final centre = Offset(size.width / 2, size.height / 2);
    // TWO rings, the second trailing by a fifth of the cycle: one ring reads as
    // a blip, two read as a ripple spreading on water. The trailing one is
    // fainter so it supports the first instead of competing with it.
    // THREE rings now, each trailing the last: a single ring blinks, two read
    // as a ripple, three read as a ripple that keeps spreading — which is what
    // water actually does. Each is fainter than the one before it, so the eye
    // follows the leading edge outwards instead of seeing three equal circles.
    for (final ring in const <({double delay, double strength})>[
      (delay: 0.0, strength: 1.0),
      (delay: 0.16, strength: 0.62),
      (delay: 0.32, strength: 0.34),
    ]) {
      final local = (progress - ring.delay) / (1 - ring.delay);
      if (local <= 0 || local >= 1) continue;
      final eased = Curves.easeOutCubic.transform(local);
      final alpha = (1 - eased) * 0.78 * ring.strength;
      if (alpha <= 0.01) continue;
      canvas.drawCircle(
        centre,
        radius + eased * (radius * 1.35),
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 3.0 * (1 - eased) + 0.5
          ..color = color.withValues(alpha: alpha),
      );
    }
  }

  @override
  bool shouldRepaint(_DropletRipplePainter old) =>
      old.progress != progress || old.color != color || old.radius != radius;
}


/// Room header subtitle: who is TYPING, else who is HERE, else the plain label.
///
/// Ordering is deliberate. Typing is the only thing on this line that is about
/// to change the conversation, so it wins; presence is context; the static word
/// is the fallback when there is nothing to say. A live call outranks all three
/// and is handled by the caller.
///
/// Names are trimmed, never wrapped: the header is one line beside the room
/// title, and an ellipsis there reads as breakage. When several people type at
/// once the names shorten together (full → 4 letters → 3) and only then does
/// the list turn into "+N", so the line degrades smoothly instead of snapping.
class _RoomPresenceStatus extends StatelessWidget {
  const _RoomPresenceStatus({
    required this.controller,
    required this.convoId,
    required this.fallback,
    required this.style,
  });

  final AppController controller;
  final String convoId;
  final String fallback;
  final TextStyle? style;

  /// Trims a display name to [letters] graphemes-ish without leaving a dangling
  /// separator. Deliberately simple: these are first names in a 1-line header.
  static String _short(String name, int letters) {
    final n = name.trim();
    if (n.length <= letters) return n;
    return n.substring(0, letters);
  }

  /// Builds the tightest label that fits [maxWidth], degrading in steps.
  static String _fit({
    required List<String> names,
    required int overflowCount,
    required TextStyle? style,
    required double maxWidth,
    required TextDirection dir,
    required String suffix,
  }) {
    String render(List<String> parts, int extra) {
      final joined = parts.join(', ');
      final more = extra > 0 ? ' +$extra' : '';
      return '$joined$more$suffix';
    }

    double width(String text) {
      final tp = TextPainter(
        text: TextSpan(text: text, style: style),
        maxLines: 1,
        textDirection: dir,
      )..layout();
      return tp.width;
    }

    // Full names, then 4 letters, then 3 — everyone shortens together, which
    // looks intentional; shortening one name and not the next looks like a bug.
    for (final cut in <int?>[null, 4, 3]) {
      final parts = cut == null
          ? names
          : names.map((n) => _short(n, cut)).toList(growable: false);
      final text = render(parts, overflowCount);
      if (width(text) <= maxWidth) return text;
    }
    // Still too wide: drop names from the end, counting them into "+N".
    var kept = names.map((n) => _short(n, 3)).toList();
    var extra = overflowCount;
    while (kept.length > 1) {
      kept = kept.sublist(0, kept.length - 1);
      extra++;
      final text = render(kept, extra);
      if (width(text) <= maxWidth) return text;
    }
    return render(kept, extra);
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<void>(
      stream: controller.changed,
      builder: (context, _) {
        final typing = controller.conversationTypingProfileIds(convoId);
        if (typing.isNotEmpty) {
          return _RoomStatusLine(
            controller: controller,
            profileIds: typing,
            style: style,
            // The animated dots ARE the "typing" verb — no word needed, and it
            // keeps the line short enough to fit real names.
            trailing: const _TypingDots(),
          );
        }
        return FutureBuilder<List<String>>(
          future: controller.onlineRoomMemberProfileIds(convoId),
          builder: (context, snap) {
            final online = snap.data ?? const <String>[];
            if (online.isEmpty) {
              return Text(
                fallback,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: style,
              );
            }
            return _RoomStatusLine(
              controller: controller,
              profileIds: online,
              style: style,
              // A green dot instead of the word "Онлайн": the colour already
              // means it, and the characters are better spent on names.
              leading: Container(
                width: 6,
                height: 6,
                margin: const EdgeInsets.only(right: 5),
                decoration: const BoxDecoration(
                  color: Color(0xFF34C759),
                  shape: BoxShape.circle,
                ),
              ),
            );
          },
        );
      },
    );
  }
}

/// Resolves display names for [profileIds] and lays them out on one line.
class _RoomStatusLine extends StatelessWidget {
  const _RoomStatusLine({
    required this.controller,
    required this.profileIds,
    required this.style,
    this.leading,
    this.trailing,
  });

  final AppController controller;
  final List<String> profileIds;
  final TextStyle? style;
  final Widget? leading;
  final Widget? trailing;

  static const int _maxNames = 3;

  @override
  Widget build(BuildContext context) {
    final shown = profileIds.take(_maxNames).toList(growable: false);
    final extra = profileIds.length - shown.length;
    return FutureBuilder<List<String>>(
      future: Future.wait(
        shown.map((id) async {
          final t = (await controller.resolveConvoTitle(id)).trim();
          // A resolver that echoes the id has nothing better to offer; a raw
          // profile id in the header is noise, so such a member is dropped.
          return t == id ? '' : t;
        }),
      ),
      builder: (context, snap) {
        final names = (snap.data ?? const <String>[])
            .map((n) => n.trim())
            .where((n) => n.isNotEmpty)
            .toList(growable: false);
        if (names.isEmpty) return const SizedBox.shrink();
        return LayoutBuilder(
          builder: (context, c) {
            final reserved =
                (leading != null ? 11.0 : 0) + (trailing != null ? 18.0 : 0);
            final text = _RoomPresenceStatus._fit(
              names: names,
              overflowCount: extra,
              style: style,
              maxWidth: (c.maxWidth - reserved).clamp(24.0, double.infinity),
              dir: Directionality.of(context),
              suffix: '',
            );
            return Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (leading != null) leading!,
                Flexible(
                  child: Text(
                    text,
                    maxLines: 1,
                    overflow: TextOverflow.clip,
                    softWrap: false,
                    style: style,
                  ),
                ),
                if (trailing != null) trailing!,
              ],
            );
          },
        );
      },
    );
  }
}

/// Three dots that rise and fall in sequence — the same idiom as the 1:1 chat,
/// so a room reads the same way a private chat does.
class _TypingDots extends StatefulWidget {
  const _TypingDots();

  @override
  State<_TypingDots> createState() => _TypingDotsState();
}

class _TypingDotsState extends State<_TypingDots>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1100),
  )..repeat();

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (MediaQuery.maybeOf(context)?.disableAnimations ?? false) {
      return Text('…', style: Theme.of(context).textTheme.labelSmall);
    }
    final color =
        Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.75);
    return Padding(
      padding: const EdgeInsets.only(left: 4),
      child: AnimatedBuilder(
        animation: _c,
        builder: (context, _) => Row(
          mainAxisSize: MainAxisSize.min,
          children: List.generate(3, (i) {
            // Staggered thirds: each dot leads the next by a third of a cycle.
            final t = (_c.value + i / 3) % 1.0;
            final lift = (t < 0.5 ? t : 1 - t) * 2; // 0..1..0
            return Container(
              width: 3,
              height: 3,
              margin: EdgeInsets.only(
                left: i == 0 ? 0 : 2.5,
                bottom: 1 + lift * 2.5,
              ),
              decoration: BoxDecoration(
                color: color.withValues(alpha: 0.45 + lift * 0.55),
                shape: BoxShape.circle,
              ),
            );
          }),
        ),
      ),
    );
  }
}

class _RoomMentionCandidate {
  const _RoomMentionCandidate._({
    required this.kind,
    required this.handle,
    required this.title,
    this.displayName,
    this.profileId,
    this.avatarPath,
    this.role = RoomMemberRole.member,
  });

  const _RoomMentionCandidate.member({
    required String profileId,
    required String displayName,
    required String handle,
    String? avatarPath,
    RoomMemberRole role = RoomMemberRole.member,
  }) : this._(
         kind: _RoomMentionCandidateKind.member,
         handle: handle,
         title: displayName,
         displayName: displayName,
         profileId: profileId,
         avatarPath: avatarPath,
         role: role,
       );

  const _RoomMentionCandidate.broadcast({
    required _RoomMentionCandidateKind kind,
    required String handle,
    required String title,
  }) : this._(kind: kind, handle: handle, title: title, displayName: title);

  final _RoomMentionCandidateKind kind;
  final String handle;
  final String title;
  final String? displayName;
  final String? profileId;
  final String? avatarPath;
  final RoomMemberRole role;

  String get token => '@$handle';

  String subtitle(BuildContext context) {
    switch (kind) {
      case _RoomMentionCandidateKind.member:
        final roleText = switch (role) {
          RoomMemberRole.owner => chatText(
            context,
            ru: 'владелец',
            en: 'owner',
          ),
          RoomMemberRole.admin => chatText(
            context,
            ru: 'администратор',
            en: 'admin',
          ),
          RoomMemberRole.moderator => chatText(
            context,
            ru: 'модератор',
            en: 'moderator',
          ),
          RoomMemberRole.member => chatText(
            context,
            ru: 'участник',
            en: 'member',
          ),
          RoomMemberRole.restricted => chatText(
            context,
            ru: 'ограниченный участник',
            en: 'restricted member',
          ),
          RoomMemberRole.guest => chatText(
            context,
            ru: 'только чтение',
            en: 'read-only member',
          ),
        };
        return '$token • $roleText';
      case _RoomMentionCandidateKind.all:
        return chatText(
          context,
          ru: 'Упомянуть всех участников',
          en: 'Mention everyone in the room',
        );
      case _RoomMentionCandidateKind.here:
        return chatText(
          context,
          ru: 'Упомянуть всех в комнате',
          en: 'Mention everyone here',
        );
      case _RoomMentionCandidateKind.admins:
        return chatText(
          context,
          ru: 'Упомянуть владельца, админов и модераторов',
          en: 'Mention the owner, admins, and moderators',
        );
    }
  }

  bool matchesQuery(String query) {
    final needle = query.trim().toLowerCase();
    if (needle.isEmpty) {
      return true;
    }
    return <String>[
      handle,
      token,
      title,
      displayName ?? '',
      profileId ?? '',
    ].any((value) => value.toLowerCase().contains(needle));
  }
}

