/// Live view of an event for rendering: the spec plus the current RSVP tally.
class _EventViewData {
  const _EventViewData({
    required this.eventId,
    required this.title,
    required this.startMs,
    required this.description,
    required this.location,
    required this.goingCount,
    required this.maybeCount,
    required this.noCount,
    required this.myStatus,
  });

  final String eventId;
  final String title;
  final int startMs;
  final String description;
  final String location;
  final int goingCount;
  final int maybeCount;
  final int noCount;

  /// 'going' | 'maybe' | 'no' | '' (no response yet)
  final String myStatus;

  bool get isPast =>
      startMs > 0 && startMs < DateTime.now().millisecondsSinceEpoch;
}

/// Live view of a poll for rendering: the immutable spec plus the current tally
/// derived from all vote events in the conversation.
class _PollViewData {
  const _PollViewData({
    required this.pollId,
    required this.question,
    required this.options,
    required this.multiple,
    required this.anonymous,
    required this.optionVotes,
    required this.totalVoters,
    required this.myOptionIndices,
    this.closedAtMs,
    this.isCreator = false,
  });

  final String pollId;
  final String question;
  final List<String> options;
  final bool multiple;
  final bool anonymous;

  /// Vote count per option (same length/order as [options]).
  final List<int> optionVotes;

  /// Distinct voters who have cast at least one vote.
  final int totalVoters;

  /// Indices the current user has selected.
  final Set<int> myOptionIndices;

  /// Non-null once a validated close command from the resolved creator
  /// exists — the poll no longer accepts votes.
  final int? closedAtMs;

  /// Whether the current user is the resolved creator (only they see the
  /// close affordance).
  final bool isCreator;

  bool get hasVoted => myOptionIndices.isNotEmpty;
  bool get isClosed => closedAtMs != null;
}

