class _CallEventBubble extends StatelessWidget {
  const _CallEventBubble({
    required this.callEvent,
    required this.timestampMs,
    required this.isMe,
    required this.localState,
    required this.isRu,
    this.viewportListenable,
  });

  final CallEventV1 callEvent;
  final int timestampMs;
  final bool isMe;
  final String localState;
  final bool isRu;
  final Listenable? viewportListenable;

  @override
  Widget build(BuildContext context) {
    final displayAsOutgoing =
        callEvent.direction == CallRecordDirection.outgoing;
    final cs = Theme.of(context).colorScheme;
    final fg = displayAsOutgoing ? Colors.white : cs.onSurface;
    final title = callRecordResultLabel(
      callEvent.result,
      l10n: context.l10n,
      isRu: isRu,
      direction: callEvent.direction,
      isVideo: callEvent.hadVideo,
    );
    final iconColor = displayAsOutgoing
        ? Colors.white.withValues(alpha: 0.96)
        : cs.primary.withValues(alpha: 0.98);
    final leadingColor = _callEventAccentColor();

    return _ChatMessageFrame(
      isMe: displayAsOutgoing,
      showGroupAuthorHeader: false,
      showGroupAvatar: false,
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 320),
        child: IntrinsicWidth(
          child: _ChatBubbleSurface(
            isMe: displayAsOutgoing,
            viewportListenable: viewportListenable,
            borderRadius: BorderRadius.only(
              topLeft: const Radius.circular(20),
              topRight: const Radius.circular(20),
              bottomLeft: Radius.circular(displayAsOutgoing ? 20 : 8),
              bottomRight: Radius.circular(displayAsOutgoing ? 8 : 20),
            ),
            child: Padding(
              padding: const EdgeInsets.fromLTRB(14, 10, 14, 9),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: Theme.of(context).textTheme.titleSmall
                              ?.copyWith(
                                color: fg,
                                fontWeight: FontWeight.w700,
                                height: 1.15,
                              ),
                        ),
                      ),
                      const SizedBox(width: 10),
                      Icon(
                        callEvent.hadVideo
                            ? Icons.videocam_rounded
                            : Icons.call_rounded,
                        size: 20,
                        color: iconColor,
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(_callDirectionIcon(), size: 15, color: leadingColor),
                      const SizedBox(width: 5),
                      Flexible(
                        child: Text(
                          _callMetaText(),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: Theme.of(context).textTheme.bodySmall
                              ?.copyWith(
                                color: fg.withValues(alpha: 0.82),
                                fontWeight: FontWeight.w500,
                              ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  IconData _callDirectionIcon() {
    final isSuccessLike =
        callEvent.result == CallRecordResult.completed ||
        callEvent.result == CallRecordResult.ongoing;
    if (callEvent.direction == CallRecordDirection.incoming) {
      return isSuccessLike
          ? Icons.call_received_rounded
          : Icons.call_received_rounded;
    }
    return Icons.call_made_rounded;
  }

  Color _callEventAccentColor() {
    return switch (callEvent.result) {
      CallRecordResult.completed ||
      CallRecordResult.ongoing => const Color(0xFF55C26A),
      CallRecordResult.failed => const Color(0xFFD9822B),
      CallRecordResult.missed ||
      CallRecordResult.declined ||
      CallRecordResult.busy ||
      CallRecordResult.canceled => const Color(0xFFE25555),
    };
  }

  String _callMetaText() {
    final base = _formatTime(timestampMs);
    if (callEvent.durationMs <= 0 ||
        callEvent.result != CallRecordResult.completed) {
      return base;
    }
    return '$base, ${_formatCallDurationMeta(callEvent.durationMs, isRu: isRu)}';
  }
}

String _formatCallDurationMeta(int durationMs, {required bool isRu}) {
  final totalSeconds = (durationMs / 1000).floor().clamp(0, 360000);
  final hours = totalSeconds ~/ 3600;
  final minutes = (totalSeconds % 3600) ~/ 60;
  final seconds = totalSeconds % 60;
  if (isRu) {
    if (hours > 0) {
      if (minutes > 0) {
        return '$hours ${_ruHours(hours)}, $minutes ${_ruMinutes(minutes)}';
      }
      return '$hours ${_ruHours(hours)}';
    }
    if (minutes > 0) return '$minutes ${_ruMinutes(minutes)}';
    return '$seconds ${_ruSeconds(seconds)}';
  }
  if (hours > 0) {
    if (minutes > 0) return '${hours}h ${minutes}m';
    return '${hours}h';
  }
  if (minutes > 0) return '${minutes}m';
  return '${seconds}s';
}

String _ruHours(int value) {
  final mod10 = value % 10;
  final mod100 = value % 100;
  if (mod10 == 1 && mod100 != 11) return 'час';
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) {
    return 'часа';
  }
  return 'часов';
}

String _ruMinutes(int value) {
  final mod10 = value % 10;
  final mod100 = value % 100;
  if (mod10 == 1 && mod100 != 11) return 'мин.';
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) {
    return 'мин.';
  }
  return 'мин.';
}

String _ruSeconds(int value) {
  final mod10 = value % 10;
  final mod100 = value % 100;
  if (mod10 == 1 && mod100 != 11) return 'сек.';
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) {
    return 'сек.';
  }
  return 'сек.';
}

