class _HeaderAvatar extends StatelessWidget {
  const _HeaderAvatar({
    required this.avatarPath,
    required this.title,
    required this.fallbackId,
    required this.isFavoritesChat,
    required this.favoritesAssetPath,
    required this.showOnlineDot,
    this.frameId,
  });

  final String? avatarPath;
  final String title;
  final String? fallbackId;
  final bool isFavoritesChat;
  final String favoritesAssetPath;
  final bool showOnlineDot;

  /// Peer's premium animated frame id (cosmetic). Null → plain avatar.
  final String? frameId;

  @override
  Widget build(BuildContext context) {
    if (isFavoritesChat) {
      final avatar = CircleAvatar(
        radius: 21,
        backgroundColor: const Color(0xFF0D5F38),
        child: Padding(
          padding: const EdgeInsets.all(8),
          child: SvgPicture.asset(
            favoritesAssetPath,
            fit: BoxFit.contain,
            colorFilter: const ColorFilter.mode(Colors.white, BlendMode.srcIn),
          ),
        ),
      );
      return _wrapTypingIndicator(context, avatar);
    }
    final hasAvatar = avatarPath != null && avatarPath!.isNotEmpty;
    final seed = (fallbackId ?? '').trim().isNotEmpty
        ? fallbackId!.trim()
        : title;
    final avatar = FramedAvatar(
      size: 42,
      frameId: frameId,
      avatarPath: hasAvatar ? avatarPath : null,
      fallbackSeed: seed,
      fallbackName: title,
      fallbackId: fallbackId,
      labelStyle: Theme.of(context).textTheme.titleMedium,
    );
    return _wrapTypingIndicator(context, avatar);
  }

  Widget _wrapTypingIndicator(BuildContext context, Widget avatar) {
    // Typing is no longer shown as an avatar badge — it is rendered as a
    // "Пишет" line under the name in the header. Only the online dot remains.
    if (!showOnlineDot) return avatar;
    final cs = Theme.of(context).colorScheme;
    return Stack(
      clipBehavior: Clip.none,
      children: [
        avatar,
        if (showOnlineDot)
          Positioned(
            right: -2,
            bottom: -2,
            child: DecoratedBox(
              decoration: BoxDecoration(
                color: cs.surface,
                shape: BoxShape.circle,
              ),
              child: const Padding(
                padding: EdgeInsets.all(2),
                child: _HeaderOnlineDot(),
              ),
            ),
          ),
      ],
    );
  }
}

/// Single-line text that, instead of an ellipsis, fades out at the right edge
/// when it overflows. Short strings render normally (the fade is past their
/// end). The shader only modulates alpha (`BlendMode.dstIn`), so the child
/// keeps its own (inherited) color — preserving the header's
/// white-when-expanded behaviour.
class _FadingText extends StatelessWidget {
  const _FadingText(this.text, {this.style});

  final String text;
  final TextStyle? style;

  @override
  Widget build(BuildContext context) {
    final child = Text(
      text,
      maxLines: 1,
      softWrap: false,
      overflow: TextOverflow.clip,
      style: style,
    );
    return LayoutBuilder(
      builder: (context, constraints) {
        // Only fade the trailing edge when the name actually OVERFLOWS the
        // available width. A short name that fits must stay fully visible —
        // previously the gradient mask was applied UNCONDITIONALLY, fading the
        // end of even short names into invisibility.
        if (!constraints.maxWidth.isFinite) return child;
        final effectiveStyle = DefaultTextStyle.of(context).style.merge(style);
        final tp = TextPainter(
          text: TextSpan(text: text, style: effectiveStyle),
          maxLines: 1,
          textDirection: Directionality.of(context),
          textScaler: MediaQuery.textScalerOf(context),
        )..layout();
        final overflows = tp.width > constraints.maxWidth + 0.5;
        if (!overflows) return child;
        return ShaderMask(
          blendMode: BlendMode.dstIn,
          shaderCallback: (rect) => const LinearGradient(
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
            colors: [Colors.white, Colors.white, Colors.transparent],
            stops: [0.0, 0.86, 1.0],
          ).createShader(rect),
          child: child,
        );
      },
    );
  }
}

/// Header status line shown beneath the conversation name when nobody is
/// typing: favorites note / room-call status / "Online" / last-seen. Extracted
/// verbatim from the inline header so the typing line can swap in cleanly.
class _HeaderStatusLine extends StatelessWidget {
  const _HeaderStatusLine({
    required this.controller,
    required this.convoId,
    required this.statusText,
    required this.isFavoritesChat,
    required this.isGroupChat,
    required this.isPeerOnline,
    required this.activeRoomCall,
    required this.formatGroupStatus,
    required this.formatLastSeen,
  });

  final AppController controller;
  final String convoId;
  final String statusText;
  final bool isFavoritesChat;
  final bool isGroupChat;
  final bool isPeerOnline;
  final CachedRoomCall? activeRoomCall;
  final String Function(BuildContext, CachedRoomCall?) formatGroupStatus;
  final String Function(BuildContext, int) formatLastSeen;

  @override
  Widget build(BuildContext context) {
    if (isFavoritesChat) {
      return Text(
        statusText,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: Theme.of(context).textTheme.labelSmall?.copyWith(
          color: Theme.of(
            context,
          ).colorScheme.onSurface.withValues(alpha: 0.75),
        ),
      );
    }
    if (isGroupChat) {
      final isActiveCall = activeRoomCall != null && activeRoomCall!.isActive;
      final base = Theme.of(context).textTheme.labelSmall?.copyWith(
        color: isActiveCall
            ? Theme.of(context).colorScheme.primary
            : Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.75),
        fontWeight: isActiveCall ? FontWeight.w600 : FontWeight.w500,
      );
      // A live call outranks everything — it is the one thing you may need to
      // act on. Below it, the room says who is typing, then who is here.
      if (isActiveCall) {
        return Text(
          formatGroupStatus(context, activeRoomCall),
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: base,
        );
      }
      return _RoomPresenceStatus(
        controller: controller,
        convoId: convoId,
        fallback: formatGroupStatus(context, activeRoomCall),
        style: base,
      );
    }
    if (isPeerOnline) {
      return Text(
        chatText(
          context,
          ru: 'Онлайн',
          en: 'Online',
          uk: 'Онлайн',
          es: 'En línea',
          pt: 'Online',
          fr: 'En ligne',
          de: 'Online',
        ),
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: Theme.of(context).textTheme.labelSmall?.copyWith(
          color: Theme.of(context).colorScheme.primary,
          fontWeight: FontWeight.w600,
        ),
      );
    }
    return FutureBuilder<int?>(
      future: controller.peerLastSeenMsForConversation(convoId),
      builder: (context, lastSeenSnapshot) {
        final lastSeenText = formatLastSeen(
          context,
          lastSeenSnapshot.data ?? 0,
        );
        return Text(
          lastSeenText.isEmpty ? statusText : lastSeenText,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: Theme.of(context).textTheme.labelSmall?.copyWith(
            color: Theme.of(
              context,
            ).colorScheme.onSurface.withValues(alpha: 0.75),
          ),
        );
      },
    );
  }
}

/// Header line shown while the peer (1:1) or a room member is typing:
/// animated [TypingDots] + an accent-tinted label. For rooms the label is
/// "name + Пишет"; for 1:1 it is just "Пишет".
class _HeaderTypingLine extends StatelessWidget {
  const _HeaderTypingLine({
    required this.controller,
    required this.convoId,
    required this.isRoom,
  });

  final AppController controller;
  final String convoId;
  final bool isRoom;

  @override
  Widget build(BuildContext context) {
    final accent = Theme.of(context).colorScheme.primary;
    final typingWord = chatText(
      context,
      ru: 'Пишет',
      en: 'typing',
      uk: 'Друкує',
      es: 'Escribiendo',
      pt: 'Digitando',
      fr: 'En train d\'écrire',
      de: 'Schreibt',
    );
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        TypingDots(color: accent),
        const SizedBox(width: 6),
        Flexible(
          child: FutureBuilder<String?>(
            future: isRoom
                ? controller.conversationTypingDisplayName(convoId)
                : Future<String?>.value(null),
            builder: (context, snap) {
              final name = (snap.data ?? '').trim();
              final label = (isRoom && name.isNotEmpty)
                  ? '$name $typingWord'
