class _PendingPhotoAlbumBubble extends StatelessWidget {
  const _PendingPhotoAlbumBubble({
    required this.id,
    required this.items,
    required this.createdAtMs,
    required this.sentBytes,
    required this.totalBytes,
    required this.speedBytesPerSec,
    required this.etaSeconds,
    required this.onCancel,
    required this.onCancelItem,
    this.viewportListenable,
  });

  final String id;
  final List<PendingPhotoUpload> items;
  final int createdAtMs;
  final int sentBytes;
  final int totalBytes;
  final double speedBytesPerSec;
  final int? etaSeconds;
  final VoidCallback onCancel;

  /// Cancel a SINGLE photo of the album (per-photo ✕). The rest keep uploading.
  final void Function(PendingPhotoUpload item) onCancelItem;
  final Listenable? viewportListenable;

  /// Per-cell upload overlay: size chip (top-left) + a radial progress ring with
  /// a ✕ (tap = cancel THIS photo only), or a ✓ once it finishes. This replaces
  /// the old single bottom "12% · 3.4 MB/s" status line — each photo now shows
  /// its own state, exactly like the outgoing-video indicator.
  Widget _cellOverlay(BuildContext context, PendingPhotoUpload item) {
    final total = item.totalBytes;
    final sent = item.sentBytes;
    final done = total > 0 && sent >= total;
    final progress = total > 0 ? (sent / total).clamp(0.0, 1.0) : null;
    return Stack(
      fit: StackFit.expand,
      children: [
        if (!done)
          DecoratedBox(
            decoration: BoxDecoration(
              color: Colors.black.withValues(alpha: 0.16),
            ),
          ),
        Positioned(
          left: 6,
          top: 6,
          child: IgnorePointer(
            child: done
                ? const _AlbumCellDoneBadge()
                : _UploadMbChip(label: _uploadMbLabel(context, sent, total)),
          ),
        ),
        if (!done)
          Center(
            child: _UploadProgressRing(
              progress: progress,
              onCancel: () => onCancelItem(item),
              size: 46,
            ),
          ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    // Only photos the user hasn't cancelled are shown (and the collage rebuilds
    // as items drop). The full [items] list stays intact in the model so the
    // upload worker's per-index cancel tokens stay aligned.
    final active = items.where((item) => !item.canceled).toList(growable: false);
    if (active.isEmpty) return const SizedBox.shrink();
    final attachments = active
        .map(
          (item) => _buildPendingAttachmentEvent(
            id: item.id,
            mime: item.mime,
            sizeBytes: item.totalBytes,
          ),
        )
        .toList(growable: false);
    final files = active
        .map((item) => File(item.filePath))
        .toList(growable: false);
    // PERF(keyboard): sizeOf, а НЕ MediaQuery.of. Второе подписывает на ВСЕ
    // изменения, включая viewInsets, которые меняются на каждом кадре анимации
    // клавиатуры — и каждый видимый пузырь с фото пересобирался ~20 раз за одно
    // её открытие. Отсюда были ощутимые подтормаживания в переписках с картинками.
    // Нужна отсюда только ширина, а размер экрана при клавиатуре не меняется:
    // Scaffold стоит с resizeToAvoidBottomInset: false. См. _KeyboardInsetAnchor —
    // он остаётся единственным листом, которому зависеть от вставок разрешено.
    final mediaSize = MediaQuery.sizeOf(context);
    // Bigger album (Telegram-style) — the old 236-262 cap looked cramped.
    final collageWidth = (mediaSize.width * 0.80)
        .clamp(300.0, 340.0)
        .toDouble();
    const maxVisibleTiles = 4;
    final visibleCount = attachments.length > maxVisibleTiles
        ? maxVisibleTiles
        : attachments.length;
    final hiddenCount = attachments.length - visibleCount;
    final fg = _chatBubbleForegroundColor(context, true);

    return _ChatMessageFrame(
      isMe: true,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: collageWidth + 2),
        child: _ChatBubbleSurface(
          isMe: true,
          showIncomingBorder: false,
          viewportListenable: viewportListenable,
          borderRadius: BorderRadius.circular(18),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(1, 1, 1, 4),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                _ImageGroupCollage(
                  attachments: attachments,
                  files: files,
                  visibleCount: visibleCount,
                  hiddenCount: hiddenCount,
                  collageWidth: collageWidth,
                  onImageTap: (_) {},
                  cellOverlayBuilder: (i) =>
                      i < active.length ? _cellOverlay(context, active[i]) : null,
                ),
                const SizedBox(height: 3),
                _BubbleMetaFooter(
                  timestampMs: createdAtMs,
                  status: _statusIcon(context, 'pending', fg, createdAtMs),
                  statusText: '',
                  color: fg,
                  reactionEventId: id,
                  reactions: const <MessageReaction>[],
                  selfProfileId: '',
                  reactionPlayTokens: const <String, int>{},
                  onToggleOwnReaction: (_) {},
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

