class _PendingPhotoBubble extends StatelessWidget {
  const _PendingPhotoBubble({
    required this.id,
    required this.filePath,
    required this.mime,
    required this.caption,
    required this.createdAtMs,
    required this.sentBytes,
    required this.totalBytes,
    required this.speedBytesPerSec,
    required this.etaSeconds,
    required this.onCancel,
    this.viewportListenable,
    this.filename,
    this.asFile = false,
  });

  final String id;
  final String filePath;
  final String mime;
  final String caption;
  final int createdAtMs;
  final int sentBytes;
  final int totalBytes;
  final double speedBytesPerSec;
  final int? etaSeconds;
  final VoidCallback onCancel;
  final Listenable? viewportListenable;
  final String? filename;
  final bool asFile;

  @override
  Widget build(BuildContext context) {
    final attachment = _buildPendingAttachmentEvent(
      id: id,
      mime: mime,
      sizeBytes: totalBytes,
      filename: filename,
    );
    final progress = totalBytes > 0
        ? (sentBytes / totalBytes).clamp(0.0, 1.0)
        : null;

    // A photo/video sent through the FILE path renders as a DOCUMENT row (never
    // an inline preview), matching how it will look once delivered.
    final renderAsDocument = asFile || !_isVisualMediaMime(mime);

    if (!renderAsDocument) {
      // PERF(keyboard): sizeOf, а НЕ MediaQuery.of. Второе подписывает на ВСЕ
      // изменения, включая viewInsets, которые меняются на каждом кадре анимации
      // клавиатуры — и каждый видимый пузырь с фото пересобирался ~20 раз за одно
      // её открытие. Отсюда были ощутимые подтормаживания в переписках с картинками.
      // Нужна отсюда только ширина, а размер экрана при клавиатуре не меняется:
      // Scaffold стоит с resizeToAvoidBottomInset: false. См. _KeyboardInsetAnchor —
      // он остаётся единственным листом, которому зависеть от вставок разрешено.
      final mediaSize = MediaQuery.sizeOf(context);
      final previewBubbleWidth = (mediaSize.width * 0.66)
          .clamp(220.0, 236.0)
          .toDouble();
      final previewMaxHeight = (mediaSize.height * 0.45)
          .clamp(300.0, 372.0)
          .toDouble();

      return _ChatMessageFrame(
        isMe: true,
        child: ConstrainedBox(
          constraints: BoxConstraints(maxWidth: previewBubbleWidth),
          child: _ChatBubbleSurface(
            isMe: true,
            showIncomingBorder: false,
            viewportListenable: viewportListenable,
            borderRadius: const BorderRadius.only(
              topLeft: Radius.circular(20),
              topRight: Radius.circular(20),
              bottomLeft: Radius.circular(20),
              bottomRight: Radius.circular(8),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(1, 1, 1, 0),
                  // Overlays live INSIDE the thumbnail's own Stack so the ring
                  // is centered ON THE IMAGE and the MB chip sits in its corner
                  // — not floating at the screen edge (the old Positioned.fill
                  // over the full row put them mid-screen for isMe bubbles).
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(19),
                    child: Stack(
                      children: [
                        _ChatFilledVisualPreview(
                          file: File(filePath),
                          mime: mime,
                          maxHeight: previewMaxHeight,
                          placeholderHeight: previewMaxHeight * 0.52,
                          // Uploading: the cancel ring IS the only center glyph
                          // — suppress the video play button so there is no
                          // duplicate play-under-spinner.
                          showPlayGlyph: false,
                        ),
                        Positioned.fill(
                          child: Center(
                            child: _UploadProgressRing(
                              progress: progress,
                              onCancel: onCancel,
                            ),
                          ),
                        ),
                        Positioned(
                          left: 8,
                          top: 8,
                          child: IgnorePointer(
                            child: _UploadMbChip(
                              label: _uploadMbLabel(
                                context,
                                sentBytes,
                                totalBytes,
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
                _AttachmentCaptionText(
                  caption: caption,
                  color: _chatBubbleForegroundColor(context, true),
                  padding: const EdgeInsets.fromLTRB(8, 6, 8, 0),
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(8, 4, 8, 6),
                  child: _BubbleMetaFooter(
                    timestampMs: createdAtMs,
                    status: _statusIcon(
                      context,
                      'pending',
                      _chatBubbleForegroundColor(context, true),
                      createdAtMs,
                    ),
                    statusText: '',
                    color: _chatBubbleForegroundColor(context, true),
                    reactionEventId: id,
                    reactions: const <MessageReaction>[],
                    selfProfileId: '',
                    reactionPlayTokens: const <String, int>{},
                    onToggleOwnReaction: (_) {},
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    // Document row: the file-type glyph IS the radial cancel ring; the MB
    // readout replaces the format/size subline while uploading.
    return _AttachmentBubble(
      attachment: attachment,
      timestampMs: createdAtMs,
      isMe: true,
      localState: 'pending',
      statusText: '',
      reactionEventId: id,
      reactions: const <MessageReaction>[],
      reactionPlayTokens: const <String, int>{},
      onToggleOwnReaction: (_) {},
      selfProfileId: '',
      onTap: null,
      viewportListenable: viewportListenable,
      uploadProgress: progress,
      onCancelUpload: onCancel,
    );
  }
}

