                        if (hasImage) ...[
                          const SizedBox(height: 8),
                          ClipRRect(
                            borderRadius: BorderRadius.circular(8),
                            child: AspectRatio(
                              aspectRatio: 16 / 9,
                              child: _linkPreviewImage(
                                bytes: imageBytes,
                                url: imageUrl,
                                errorBuilder: (_, __, ___) => Container(
                                  color: foregroundColor.withValues(
                                    alpha: 0.10,
                                  ),
                                  alignment: Alignment.center,
                                  child: Icon(
                                    Icons.link_rounded,
                                    color: foregroundColor.withValues(
                                      alpha: 0.72,
                                    ),
