  }
}

/// Wraps a sticker bubble whose pixels may need fetching first. Catalog stickers
/// ([event.hasInlineBlob] == false) render [fallback] immediately. USER stickers
/// (E2EE blob) are downloaded + decrypted via the controller on first build, and
/// [fallback] (a placeholder descriptor) shows until the cutout is ready.
class _UserStickerResolver extends StatefulWidget {
  const _UserStickerResolver({
    required this.event,
    required this.controller,
    required this.fallback,
    required this.builder,
  });

  final StickerEventV1 event;
  final AppController controller;
  final SecretlyStickerDescriptor fallback;
  final Widget Function(SecretlyStickerDescriptor sticker) builder;

  @override
  State<_UserStickerResolver> createState() => _UserStickerResolverState();
}

class _UserStickerResolverState extends State<_UserStickerResolver> {
  SecretlyStickerDescriptor? _resolved;

  @override
  void initState() {
    super.initState();
    _maybeResolve();
  }

  @override
  void didUpdateWidget(covariant _UserStickerResolver oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.event.stickerId != widget.event.stickerId ||
        oldWidget.event.blobId != widget.event.blobId) {
      _resolved = null;
      _maybeResolve();
    }
  }

  void _maybeResolve() {
    final event = widget.event;
    // Resolve blob carriers AND the user's own packs (which may have no blob in
    // self-chat) from the durable local cache.
    if (!event.hasInlineBlob && !event.packId.startsWith('user:')) return;
    widget.controller.ensureUserStickerCached(event).then((descriptor) {
      if (!mounted || descriptor == null) return;
      setState(() => _resolved = descriptor);
    });
  }

  @override
  Widget build(BuildContext context) =>
      widget.builder(_resolved ?? widget.fallback);
}

/// Bottom sheet shown when a sticker is tapped: the whole pack as a grid (tap a
/// tile to send it), plus an «Установить» button that — for a sticker a peer
/// sent us — pulls the rest of their pack over the e2ee WS and installs it.
/// Rebuilds on `controller.changed` so the grid fills in + the button advances
/// as chunks arrive.
class _StickerPackSheet extends StatelessWidget {
  const _StickerPackSheet({
    required this.controller,
    required this.event,
    required this.packId,
    required this.originPid,
    required this.isOwnPack,
    required this.tappedSticker,
    required this.onSendSticker,
  });

  final AppController controller;
  final StickerEventV1 event;
  final String packId;
  final String originPid;
  final bool isOwnPack;
  final SecretlyStickerDescriptor? tappedSticker;
  final Future<void> Function(SecretlyStickerDescriptor) onSendSticker;

  @override
  Widget build(BuildContext context) {
    final isRu = chatLocaleIsRussian(context);
    return StreamBuilder<void>(
      stream: controller.changed,
      builder: (context, _) {
        final localPack = SecretlyStickerCatalog.pickerPackById(packId);
        final installed = localPack != null;
        final stickers = <SecretlyStickerDescriptor>[
          if (localPack != null)
            ...localPack.stickers
          else if (tappedSticker != null)
            tappedSticker!,
        ];
        final title = (localPack != null && localPack.title.isNotEmpty)
            ? localPack.title
            : ((event.packTitle != null && event.packTitle!.isNotEmpty)
                  ? event.packTitle!
                  : (isRu ? 'Набор стикеров' : 'Sticker pack'));
        final total = installed
            ? localPack.stickers.length
            : (event.packStickerCount ?? stickers.length);
        final inFlight = controller.stickerPackFetchInFlight(packId);
        final (received, expected) = controller.stickerPackInstallProgress(
          packId,
        );
        final canFetch = !isOwnPack && !installed && originPid.isNotEmpty;
        final missing = installed ? 0 : (total - stickers.length).clamp(0, 16);

        return SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(16, 8, 16, 16),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 36,
                  height: 4,
                  decoration: BoxDecoration(
                    color: Colors.white.withValues(alpha: 0.22),
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
                const SizedBox(height: 14),
                Row(
                  children: [
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 17,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                          const SizedBox(height: 2),
                          Text(
                            isRu
                                ? '$total стикер${_stickerPluralRu(total)}'
                                : '$total sticker${total == 1 ? '' : 's'}',
                            style: TextStyle(
                              color: Colors.white.withValues(alpha: 0.55),
                              fontSize: 13,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 14),
                Flexible(
                  child: GridView.builder(
                    shrinkWrap: true,
                    physics: secretlyListPhysics(),
                    gridDelegate:
                        const SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 4,
                          mainAxisSpacing: 10,
                          crossAxisSpacing: 10,
                        ),
                    itemCount: stickers.length + missing,
                    itemBuilder: (context, i) {
                      if (i < stickers.length) {
                        final s = stickers[i];
                        return GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          onTap: () => unawaited(onSendSticker(s)),
                          child: SecretlyStickerAssetView(sticker: s, size: 68),
                        );
                      }
                      // Greyed slot for a not-yet-fetched sticker.
                      return DecoratedBox(
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.05),
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: Icon(
                          AppIcons.photo,
                          size: 22,
                          color: Colors.white.withValues(alpha: 0.18),
                        ),
                      );
                    },
                  ),
                ),
                // 🔴 ЧЕСТНО ПРО НЕПЕРЕДАННОЕ (08.08.2026). Ответ автора шлёт
                // пиксели инлайном, а `_buildInlineStickerB64` возвращает null
                // для анимированных, Lottie и слишком крупных — то есть такие
                // стикеры МОЛЧА выбрасываются. Человек, поделившийся набором
                // анимированных, не получал ничего и не узнавал почему, а
                // получатель считал набор таким и есть.
                //
                // Пока блоб-путь для ответа не построен, единственно честное —
                // сказать, что дошло не всё. Умолчание здесь хуже неполноты:
                // неполноту можно объяснить, а тишину человек объясняет
                // поломкой приложения.
                if (installed && missing > 0) ...[
                  const SizedBox(height: 10),
                  Row(
                    children: [
                      Icon(
                        Icons.info_outline_rounded,
                        size: 15,
                        color: Colors.white.withValues(alpha: 0.5),
                      ),
                      const SizedBox(width: 6),
                      Expanded(
                        child: Text(
                          isRu
                              ? 'Ещё $missing стикер${_stickerPluralRu(missing)} '
                                    'не передалось — возможно, у автора старая '
                                    'версия приложения'
                              : '$missing more sticker${missing == 1 ? '' : 's'} '
                                    "didn't transfer — the author may be on an "
                                    'older app version',
                          style: TextStyle(
                            color: Colors.white.withValues(alpha: 0.5),
                            fontSize: 12,
                            height: 1.25,
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
                const SizedBox(height: 14),
                SizedBox(
                  width: double.infinity,
                  child: _buildInstallButton(
                    isRu: isRu,
                    installed: installed || isOwnPack,
                    inFlight: inFlight,
                    canFetch: canFetch,
                    received: received,
                    expected: expected,
                    total: total,
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _buildInstallButton({
    required bool isRu,
    required bool installed,
    required bool inFlight,
    required bool canFetch,
    required int received,
    required int expected,
    required int total,
  }) {
    final shape = RoundedRectangleBorder(
      borderRadius: BorderRadius.circular(14),
    );
    if (installed) {
      return FilledButton(
        onPressed: null,
        style: FilledButton.styleFrom(shape: shape),
        child: Text(isRu ? 'Установлено' : 'Installed'),
      );
    }
    if (inFlight) {
      final label = expected > 0
          ? '${isRu ? 'Установка' : 'Installing'}… $received/$expected'
          : (isRu ? 'Установка…' : 'Installing…');
      return FilledButton(
        onPressed: null,
        style: FilledButton.styleFrom(shape: shape),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            const SizedBox(
              width: 16,
              height: 16,
              child: CircularProgressIndicator(strokeWidth: 2),
            ),
            const SizedBox(width: 10),
            Text(label),
          ],
        ),
      );
    }
    if (canFetch) {
      return FilledButton(
        onPressed: () => unawaited(
          controller.requestPeerStickerPack(
            packId: packId,
            originPid: originPid,
          ),
        ),
        style: FilledButton.styleFrom(shape: shape),
        // 🔴 С ЧИСЛОМ, как в Telegram: «Добавить 24 стикера». Человек решает,
        // стоит ли набор места, ещё до нажатия — а «Установить» без числа
        // заставляет его сначала нажать, потом смотреть.
        child: Text(
          total > 0
              ? (isRu
                    ? 'Добавить $total стикер${_stickerPluralRu(total)}'
                    : 'Add $total sticker${total == 1 ? '' : 's'}')
              : (isRu ? 'Добавить набор' : 'Add pack'),
        ),
      );
    }
    return const SizedBox.shrink();
  }

  /// Окончание для «стикер» по русским правилам.
  ///
  /// 🔴 Ради ощущения сделанного как следует. Без него получалось «1 стикеров» и
  /// «22 стикеров» — именно такие мелочи и выдают наспех собранное приложение,
  /// даже когда всё остальное работает. Форма та же, что у `_pluralRu` для
  /// участников комнаты.
  String _stickerPluralRu(int value) {
    final mod10 = value % 10;
    final mod100 = value % 100;
    if (mod10 == 1 && mod100 != 11) return '';
    if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return 'а';
    return 'ов';
  }
}

/// Заглушка на месте медиа, которое не удалось прочитать.
///
/// 🔴 ЗАЧЕМ ОНА ВООБЩЕ (09.08.2026, ТЗ по тактильности, Э-1). `Image.file` по
/// отсутствующему пути бросает исключение при КАЖДОЙ перерисовке, а Flutter его
/// гасит и рисует дальше — то есть каждое такое падение стоит кадра. В логах с
/// телефона это выглядело как поток «Another exception was thrown» дважды в
/// секунду, и именно так и появляется ощущение «подтормаживает».
///
/// Мёртвые пути у нас находились ДВАЖДЫ (фото профиля 13.07, стикеры 08.08), и
/// оба раза причина одна: абсолютный путь не переживает переустановку, потому что
/// на iOS каталог приложения меняет UUID. То есть у части людей часть медиа
/// заведомо лежит по устаревшим путям.
///
/// 🔴 ЗАГЛУШКА ВИДИМАЯ, А НЕ ПУСТАЯ. Молча спрятать ошибку значило бы превратить
/// «тормозит» в «часть фото пропала без следа» — а это хуже: человек не поймёт,
/// потерялось у него что-то или нет. Видимый кадр говорит «файла нет», и это
/// правда.
class _BrokenMediaBox extends StatelessWidget {
  const _BrokenMediaBox({this.iconSize = 22, this.rounded = false});

  final double iconSize;
  final bool rounded;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.06),
        shape: rounded ? BoxShape.circle : BoxShape.rectangle,
      ),
      child: Center(
        child: Icon(
          Icons.broken_image_outlined,
          size: iconSize,
          color: Colors.white.withValues(alpha: 0.35),
        ),
      ),
    );
  }
}

