                en: 'Invited by ${preview.inviterDisplayName}',
                uk: 'Запрошує: ${preview.inviterDisplayName}',
                es: 'Invita: ${preview.inviterDisplayName}',
                pt: 'Convidado por ${preview.inviterDisplayName}',
                ptBr: 'Convidado por ${preview.inviterDisplayName}',
                fr: 'Invite par ${preview.inviterDisplayName}',
                de: 'Eingeladen von ${preview.inviterDisplayName}',
