Color _chatBubbleForegroundColor(BuildContext context, bool isOutgoing) {
  final cs = Theme.of(context).colorScheme;
  return isOutgoing ? Colors.white : cs.onSurface;
}

/// Caption rendered INSIDE the same bubble as the media (Telegram-style).
/// Matches the chat's normal message text style; shown only when non-empty.
class _AttachmentCaptionText extends StatelessWidget {
  const _AttachmentCaptionText({
    required this.caption,
    required this.color,
    this.padding = const EdgeInsets.fromLTRB(8, 6, 8, 0),
  });

  final String? caption;
  final Color color;
  final EdgeInsetsGeometry padding;

  @override
  Widget build(BuildContext context) {
    final text = caption?.trim() ?? '';
    if (text.isEmpty) return const SizedBox.shrink();
    return Padding(
      padding: padding,
      child: Text(
        text,
        style: Theme.of(
          context,
        ).textTheme.bodyMedium?.copyWith(color: color, height: 1.3),
      ),
    );
  }
}

class _AttachmentBubble extends StatelessWidget {
  const _AttachmentBubble({
    required this.attachment,
    required this.timestampMs,
    required this.isMe,
    required this.localState,
    this.statusText,
    required this.reactionEventId,
    required this.reactions,
    required this.reactionPlayTokens,
    required this.onToggleOwnReaction,
    required this.selfProfileId,
    required this.onTap,
    this.isAudioPlaying = false,
    this.isAudioLoading = false,
    this.audioPosition = Duration.zero,
    this.audioDuration = Duration.zero,
    this.onSeek,
    this.replySnippet,
    this.showGroupAuthorHeader = false,
    this.showGroupAvatar = false,
    this.isFirstInSeries = false,
    this.groupAuthorName,
    this.groupAuthorAvatarPath,
    this.groupAuthorSeed,
    this.groupHeaderStatusText,
    this.onGroupAuthorTap,
    this.onReplySwipe,
    this.onReplyQuoteTap,
    this.viewportListenable,
    this.musicTitle,
    this.musicArtist,
    this.onMusicMenuRequested,
    this.onFileMenuRequested,
    this.voiceTranscriptionFooter,
    this.sideAffordance,
    this.isDownloading = false,
    this.loadThumbnailFile,
    this.uploadProgress,
    this.onCancelUpload,
  });

  final AttachmentEventV1? attachment;
  final int timestampMs;
  final bool isMe;
  final String localState;
  final String? statusText;
  final String reactionEventId;
  final List<MessageReaction> reactions;
  final Map<String, int> reactionPlayTokens;
  final void Function(String emoji) onToggleOwnReaction;
  final String selfProfileId;
  final VoidCallback? onTap;
  final bool isAudioPlaying;
  final bool isAudioLoading;
  final Duration audioPosition;
  final Duration audioDuration;
  final void Function(Duration)? onSeek;
  final _ReplySnippet? replySnippet;
  final bool showGroupAuthorHeader;
  final bool showGroupAvatar;
  final bool isFirstInSeries;
  final String? groupAuthorName;
  final String? groupAuthorAvatarPath;
  final String? groupAuthorSeed;
  final String? groupHeaderStatusText;
  final VoidCallback? onGroupAuthorTap;
  final VoidCallback? onReplySwipe;
  final VoidCallback? onReplyQuoteTap;
  final Listenable? viewportListenable;
  final String? musicTitle;
  final String? musicArtist;
  final Future<void> Function(Rect anchorRect)? onMusicMenuRequested;
  final Future<void> Function(Rect anchorRect)? onFileMenuRequested;
  final Widget? voiceTranscriptionFooter;

  /// Control rendered OUTSIDE the bubble by the frame (voice transcript
  /// trigger). Handed straight through — the bubble never draws it.
  final Widget? sideAffordance;

  /// True while this generic file is being downloaded on tap — shows a
  /// circular progress spinner in place of the file-type icon.
  final bool isDownloading;

  /// Loads (and caches) the image bytes for a previewable image-mime FILE so
  /// the document row can show a small rounded thumbnail instead of the generic
  /// file icon. Null for non-image files (keeps the icon).
  final Future<File?> Function(AttachmentEventV1 attachment)? loadThumbnailFile;

  /// When set, this document row is UPLOADING: the leading glyph becomes a
  /// Telegram-style radial ring with a ✕ (progress = 0..1, null = spinning),
  /// and [onCancelUpload] cancels it. Null for a normal (sent) file bubble.
  final double? uploadProgress;
  final VoidCallback? onCancelUpload;

  bool get _isUploading => onCancelUpload != null;

  @override
  Widget build(BuildContext context) {
    final l10n = context.l10n;
    final fg = _chatBubbleForegroundColor(context, isMe);
    final status = isMe
        ? _statusIcon(context, localState, fg, timestampMs)
        : null;
    final mime = (attachment?.mime ?? '').toLowerCase();
    final isAudio = mime.startsWith('audio/');

    if (isAudio) {
      // Voice recordings are AAC/m4a (mime `audio/mp4`), which the mime list
      // can't tell apart from a music m4a file — so we also treat any audio
      // attachment that carries a captured `waveform` as a voice message. That
      // envelope is only ever attached to in-app recordings, never to picked
      // music files, so this cleanly routes recordings to the waveform layout.
      final hasVoiceWaveform = attachment?.waveform?.isNotEmpty ?? false;
      final isVoice = _isVoiceMessageMime(mime) || hasVoiceWaveform;
      final audioAttachment = attachment!;
      final sizeLabel = _formatBytesHuman(audioAttachment.sizeBytes);
      final durationLabel = audioDuration > Duration.zero
          ? _fmtAudioDur(audioDuration)
          : '--:--';
      final progressFraction = audioDuration.inMilliseconds > 0
          ? (audioPosition.inMilliseconds / audioDuration.inMilliseconds).clamp(
              0.0,
              1.0,
            )
          : 0.0;

      final audioChild = !isVoice
          ? Builder(
              builder: (context) {
                final resolvedTitle = musicTitle?.trim();
                final resolvedArtist = musicArtist?.trim();
                final title = (resolvedTitle ?? '').isNotEmpty
                    ? resolvedTitle!
                    : l10n.music;
                final artist = (resolvedArtist ?? '').isNotEmpty
                    ? resolvedArtist!
                    : chatText(context, ru: 'Неизвестен', en: 'Unknown artist');
                final showProgressBar =
                    audioDuration > Duration.zero &&
                    (isAudioPlaying || audioPosition > Duration.zero);
                // One look for every audio bubble in BOTH directions: the same
                // accent circle the voice bubble uses, with a white glyph. The
                // outgoing card used to invert (white circle, blue glyph),
                // which read as a foreign element on the blue bubble.
                const playButtonColor = Color(0xFF5C9CEF);
                const playIconColor = Colors.white;
                final footerStyle =
                    Theme.of(context).textTheme.labelSmall?.copyWith(
                      color: Colors.white,
                      fontSize: 10.2,
                      fontWeight: FontWeight.w700,
                      height: 1,
                    ) ??
                    const TextStyle(
                      color: Colors.white,
                      fontSize: 10.2,
                      fontWeight: FontWeight.w700,
                      height: 1,
                    );

                return Padding(
                  padding: const EdgeInsets.fromLTRB(8, 7, 5, 5),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      if (isFirstInSeries && groupAuthorName != null)
                        _GroupAuthorInlineHeader(
                          onTap: onGroupAuthorTap,
                          name: groupAuthorName!,
                          seed: groupAuthorSeed ?? groupAuthorName!,
                          statusText: groupHeaderStatusText,
                          padding: const EdgeInsets.only(bottom: 4),
                        ),
                      if (replySnippet != null) ...[
                        _ReplyQuoteStrip(
                          snippet: replySnippet!,
                          color: Colors.white,
                          isMe: isMe,
                          onTap: onReplyQuoteTap,
                        ),
                        const SizedBox(height: 5),
                      ],
                      Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          GestureDetector(
                            onTap: onTap,
                            child: Container(
                              width: 42,
                              height: 42,
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color: playButtonColor,
                                boxShadow: [
                                  BoxShadow(
                                    color: Colors.black.withValues(
                                      alpha: isMe ? 0.16 : 0.12,
                                    ),
                                    blurRadius: isMe ? 10 : 8,
                                    offset: const Offset(0, 3),
                                  ),
                                ],
                              ),
                              child: Center(
                                child: Opacity(
                                  opacity: isAudioLoading ? 0.72 : 1,
                                  child: Icon(
                                    isAudioPlaying
                                        ? Icons.pause_rounded
                                        : Icons.play_arrow_rounded,
                                    size: isAudioPlaying ? 22 : 26,
                                    color: playIconColor,
                                  ),
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: GestureDetector(
                              onTap: onTap,
                              behavior: HitTestBehavior.opaque,
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Row(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Expanded(
                                        child: Text(
                                          title,
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: Theme.of(context)
                                              .textTheme
                                              .titleMedium
                                              ?.copyWith(
                                                color: Colors.white,
                                                fontSize: 13.2,
                                                fontWeight: FontWeight.w800,
                                                height: 1.06,
                                              ),
                                        ),
                                      ),
                                      if (onMusicMenuRequested != null)
                                        Builder(
                                          builder: (menuContext) => IconButton(
                                            visualDensity:
                                                VisualDensity.compact,
                                            padding: EdgeInsets.zero,
                                            constraints:
                                                const BoxConstraints.tightFor(
                                                  width: 20,
                                                  height: 20,
                                                ),
                                            onPressed: () {
                                              final box =
                                                  menuContext.findRenderObject()
                                                      as RenderBox?;
                                              if (box == null) return;
                                              final origin = box.localToGlobal(
                                                Offset.zero,
                                              );
                                              unawaited(
                                                onMusicMenuRequested!(
                                                  origin & box.size,
                                                ),
                                              );
                                            },
                                            icon: const Icon(
                                              Icons.more_vert_rounded,
                                              color: Colors.white,
                                              size: 18,
                                            ),
                                            tooltip: chatText(
                                              context,
                                              ru: 'Действия',
                                              en: 'Actions',
                                            ),
                                          ),
                                        )
                                      else
                                        const SizedBox(width: 20, height: 20),
                                    ],
                                  ),
                                  // The extra air (vs the old 1px/3px gaps)
                                  // brings the card to the SAME height as the
                                  // voice bubble — the two audio bubbles must
                                  // match.
                                  const SizedBox(height: 4),
                                  Text(
                                    artist,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: Theme.of(context)
                                        .textTheme
                                        .bodyMedium
                                        ?.copyWith(
                                          color: Colors.white,
                                          fontSize: 11.4,
                                          fontWeight: FontWeight.w600,
                                          height: 1.05,
                                        ),
                                  ),
                                  if (showProgressBar) ...[
                                    const SizedBox(height: 2),
                                    SizedBox(
                                      height: 12,
                                      child: Align(
                                        alignment: Alignment.centerLeft,
                                        child: _MusicProgressBar(
                                          progress: progressFraction,
                                          color: Colors.white,
                                          onSeek: onSeek,
                                          duration: audioDuration,
                                        ),
                                      ),
                                    ),
                                  ],
                                  const SizedBox(height: 10),
                                  Row(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.center,
                                    children: [
                                      Expanded(
                                        child: Text(
                                          '${_fmtAudioDur(audioPosition)} / $durationLabel',
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: footerStyle,
                                        ),
                                      ),
                                      if (statusText != null &&
                                          statusText!.isNotEmpty) ...[
                                        const SizedBox(width: 5),
                                        _buildBubbleStatusSlot(statusText!, footerStyle),
                                      ],
                                      const SizedBox(width: 5),
                                      Text(
                                        _formatTime(timestampMs),
                                        style: footerStyle,
                                      ),
                                      if (status != null) ...[
                                        const SizedBox(width: 4),
                                        status,
                                      ],
                                    ],
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ],
                      ),
                      // Always present so the bubble can GROW into its first
                      // reaction instead of snapping. See [_ReactionSlot].
                      _ReactionSlot(
                        alignment: Alignment.topRight,
                        child: reactions.isEmpty
                            ? const SizedBox.shrink()
                            : Padding(
                                padding: const EdgeInsets.only(top: 6),
                                child: Align(
                                  alignment: Alignment.centerRight,
                                  child: _ReactionPills(
                                    reactionEventId: reactionEventId,
                                    reactions: reactions,
                                    selfProfileId: selfProfileId,
                                    reactionPlayTokens: reactionPlayTokens,
                                    onToggleOwnReaction: onToggleOwnReaction,
                                  ),
                                ),
                              ),
                      ),
                    ],
                  ),
                );
              },
            )
          : Padding(
              padding: const EdgeInsets.fromLTRB(7, 7, 7, 5),
              child: Column(
                crossAxisAlignment: isMe
                    ? CrossAxisAlignment.end
                    : CrossAxisAlignment.start,
                children: [
                  if (isFirstInSeries && groupAuthorName != null)
                    _GroupAuthorInlineHeader(
                      onTap: onGroupAuthorTap,
                      name: groupAuthorName!,
                      seed: groupAuthorSeed ?? groupAuthorName!,
                      statusText: groupHeaderStatusText,
                      padding: const EdgeInsets.only(bottom: 4),
                    ),
                  if (replySnippet != null) ...[
                    _ReplyQuoteStrip(
                      snippet: replySnippet!,
                      color: fg,
                      isMe: isMe,
                      onTap: onReplyQuoteTap,
                    ),
                    const SizedBox(height: 5),
                  ],
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.center,
                    children: [
                      GestureDetector(
                        onTap: onTap,
                        child: Container(
                          // Same footprint and glyph sizing as the music card's
                          // play button — the two audio bubbles must read as
                          // one family.
                          width: 42,
                          height: 42,
                          decoration: const BoxDecoration(
                            shape: BoxShape.circle,
                            color: Color(0xFF5C9CEF),
                          ),
                          child: Center(
                            child: Opacity(
                              opacity: isAudioLoading ? 0.72 : 1,
                              child: Icon(
                                isAudioPlaying
                                    ? Icons.pause_rounded
                                    : Icons.play_arrow_rounded,
                                size: isAudioPlaying ? 22 : 26,
                                color: Colors.white,
                              ),
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 7),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            SeekableAudioWaveform(
                              progress: progressFraction,
                              seed: audioAttachment.blobId.hashCode,
                              amplitudes: audioAttachment.waveform,
                              height: 30,
                              barCount: 32,
                              barWidth: 2.1,
                              barSpacing: 1.3,
                              playedColor: Colors.white.withValues(alpha: 0.92),
                              unplayedColor: Colors.white.withValues(
                                alpha: 0.32,
                              ),
                              onSeek: onSeek != null
                                  ? (f) => onSeek!(
                                      Duration(
                                        milliseconds:
                                            (audioDuration.inMilliseconds * f)
                                                .round(),
                                      ),
                                    )
                                  : null,
                            ),
                            const SizedBox(height: 1),
                            Row(
                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                              children: [
                                Expanded(
                                  child: Text(
                                    // No "Voice message" label — the waveform
                                    // already says it; the words only bloated
                                    // the bubble.
                                    isAudioPlaying ||
                                            audioPosition > Duration.zero
                                        ? '${_fmtAudioDur(audioPosition)} • $sizeLabel'
                                        : sizeLabel,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      color: fg.withValues(alpha: 0.62),
                                      fontSize: 10,
                                      fontWeight: FontWeight.w500,
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 5),
                                Text(
                                  durationLabel,
                                  style: TextStyle(
                                    color: fg.withValues(alpha: 0.62),
                                    fontSize: 10,
                                    fontWeight: FontWeight.w500,
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  if (voiceTranscriptionFooter != null) ...[
                    const SizedBox(height: 2),
                    voiceTranscriptionFooter!,
                  ],
                  const SizedBox(height: 1),
                  _BubbleMetaFooter(
                    timestampMs: timestampMs,
                    status: status,
                    statusText: statusText,
                    color: fg,
                    reactionEventId: reactionEventId,
                    reactions: reactions,
                    selfProfileId: selfProfileId,
                    reactionPlayTokens: reactionPlayTokens,
                    onToggleOwnReaction: onToggleOwnReaction,
                  ),
                ],
              ),
            );

      return _ReplySwipeWrapper(
        enabled: onReplySwipe != null,
        onReplySwipe: onReplySwipe,
        child: _ChatMessageFrame(
          isMe: isMe,
          showGroupAuthorHeader: showGroupAuthorHeader,
          groupAuthorName: groupAuthorName,
          groupAuthorAvatarPath: groupAuthorAvatarPath,
          groupAuthorSeed: groupAuthorSeed,
          groupHeaderStatusText: groupHeaderStatusText,
          onGroupAuthorTap: onGroupAuthorTap,
          showGroupAvatar: showGroupAvatar,
          sideAffordance: sideAffordance,
          child: ConstrainedBox(
            constraints: BoxConstraints(
              minWidth: isVoice ? 168 : 176,
              maxWidth: isVoice ? 248 : 258,
            ),
            child: _ChatBubbleSurface(
              isMe: isMe,
              viewportListenable: viewportListenable,
              borderRadius: BorderRadius.only(
                topLeft: const Radius.circular(20),
                topRight: const Radius.circular(20),
                bottomLeft: Radius.circular(isMe ? 20 : 8),
                bottomRight: Radius.circular(isMe ? 8 : 20),
              ),
              child: audioChild,
            ),
          ),
        ),
      );
    }

    // ── Non-audio attachments (files, video, image fallback) ──────────────
    String label;
    IconData icon;
    String subline;
    final fileSizeLabel = attachment == null
        ? ''
        : _formatBytesHuman(attachment!.sizeBytes);

    // A photo SENT AS A FILE carries a filename — render it like a generic
    // file (real name + "FORMAT • SIZE"), with a small image thumbnail in the
    // leading slot. A filename-less image only reaches this bubble as a
    // fallback; keep the old "Photo / Tap to open" presentation for it.
    final hasFileName = (attachment?.filename?.trim().isNotEmpty ?? false);
    final isImageFile = mime.startsWith('image/') && hasFileName;
    final showPhotoThumbnail =
        isImageFile &&
        loadThumbnailFile != null &&
        _attachmentFileHasPhotoThumbnail(attachment);

    if (mime.startsWith('image/') && !hasFileName) {
      label = l10n.photo;
      icon = AppIcons.photo;
      subline = 'Tap to open';
    } else if (mime.startsWith('video/') && !hasFileName) {
      label = l10n.video;
      icon = AppIcons.playCircle;
      subline = 'HD • ${_fileExtFromMime(mime)}';
    } else {
      // Generic file (incl. photos sent as files) — Telegram-style: real file
      // name as the title, then "FORMAT • SIZE" as the subline (format from the
      // filename extension, falling back to the MIME subtype).
      label = _genericFileDisplayName(attachment, mime);
      icon = AppIcons.attach;
      subline = _genericFileFormatLabel(attachment, mime);
    }
    final String resolvedSubline;
    if (_isUploading) {
      // While uploading, the subline shows live MB progress: "FORMAT • 3.4/12 MB".
      final total = attachment?.sizeBytes ?? 0;
      final uploaded = ((uploadProgress ?? 0) * total).round();
      final mb = _uploadMbLabel(context, uploaded, total);
      resolvedSubline = subline.trim().isEmpty ? mb : '$subline • $mb';
    } else {
      resolvedSubline = fileSizeLabel.isEmpty
          ? subline
          : (subline.trim().isEmpty
                ? fileSizeLabel
                : '$subline • $fileSizeLabel');
    }

    // L1: the send time (and, for my own messages, the delivery checkmarks)
    // rides on the SAME row as "FORMAT • SIZE" — right-aligned — instead of a
    // separate footer line. Incoming bubbles show only the time (status is
    // null), which is what shrinks their height.
    Widget metaInline() {
      final metaStyle = Theme.of(context).textTheme.labelSmall?.copyWith(
        fontSize: 11,
        fontWeight: FontWeight.w600,
        height: 1,
        color: fg.withValues(alpha: 0.72),
      );
      return Row(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Text(_formatTime(timestampMs), style: metaStyle),
          if (statusText != null && statusText!.isNotEmpty) ...[
            const SizedBox(width: 6),
            _buildBubbleStatusSlot(statusText!, metaStyle),
          ],
          if (status != null) ...[const SizedBox(width: 5), status],
        ],
      );
    }

    // File name + the "FORMAT • SIZE  ⟵time✓✓" line. Shared by both the
    // compact (generic file) and the big-preview (photo file) layouts.
    Widget fileTextBlock({required int nameMaxLines}) => Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(
          label,
          maxLines: nameMaxLines,
          overflow: TextOverflow.ellipsis,
          style: TextStyle(color: fg, fontWeight: FontWeight.w600),
        ),
        const SizedBox(height: 2),
        Row(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Expanded(
              child: Text(
                resolvedSubline,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: Theme.of(context).textTheme.labelSmall?.copyWith(
                  color: fg.withValues(alpha: 0.8),
                ),
              ),
            ),
            const SizedBox(width: 8),
            metaInline(),
          ],
        ),
      ],
    );

    Widget menuButton() => Builder(
      builder: (menuContext) => IconButton(
        visualDensity: VisualDensity.compact,
        padding: EdgeInsets.zero,
        constraints: const BoxConstraints.tightFor(width: 28, height: 28),
        onPressed: () {
          final box = menuContext.findRenderObject() as RenderBox?;
          if (box == null) return;
          final origin = box.localToGlobal(Offset.zero);
          unawaited(onFileMenuRequested!(origin & box.size));
        },
        icon: Icon(
          Icons.more_vert_rounded,
          color: fg.withValues(alpha: 0.95),
          size: 20,
        ),
        tooltip: chatText(context, ru: 'Действия', en: 'Actions'),
      ),
    );

    Widget reactionsFooter() => _ReactionSlot(
      alignment: Alignment.topLeft,
      child: reactions.isEmpty
          ? const SizedBox.shrink()
          : Padding(
              padding: const EdgeInsets.only(top: 6),
              child: _ReactionPills(
                reactionEventId: reactionEventId,
                reactions: reactions,
                selfProfileId: selfProfileId,
                reactionPlayTokens: reactionPlayTokens,
                onToggleOwnReaction: onToggleOwnReaction,
              ),
            ),
    );

    Widget groupHeader() => _GroupAuthorInlineHeader(
      onTap: onGroupAuthorTap,
      name: groupAuthorName!,
      seed: groupAuthorSeed ?? groupAuthorName!,
      statusText: groupHeaderStatusText,
      padding: const EdgeInsets.only(bottom: 2),
    );

    // Compact document row for every file (incl. photos sent as files). A photo
    // file just gets a slightly LARGER leading thumbnail and tighter left/top/
    // bottom padding so it sits closer to the bubble edges — NOT a full-width
    // preview (that read as "huge" and left big gaps).
    final bool isPhotoFileRow = showPhotoThumbnail && !isDownloading;
    final double thumbSize = isPhotoFileRow ? 54 : 46;
    final child = Padding(
      padding: isPhotoFileRow
          ? const EdgeInsets.fromLTRB(8, 8, 12, 8)
          : const EdgeInsets.fromLTRB(12, 10, 12, 8),
      child: Column(
        crossAxisAlignment: isMe
            ? CrossAxisAlignment.end
            : CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          if (isFirstInSeries && groupAuthorName != null) groupHeader(),
          if (replySnippet != null) ...[
            _ReplyQuoteStrip(
              snippet: replySnippet!,
              color: fg,
              isMe: isMe,
              onTap: onReplyQuoteTap,
            ),
            const SizedBox(height: 8),
          ],
          Row(
            children: [
              if (_isUploading)
                // Uploading: the file-type glyph IS the radial cancel ring.
                _UploadProgressRing(
                  progress: uploadProgress,
                  onCancel: onCancelUpload!,
                  size: 46,
                )
              else if (isPhotoFileRow)
                _FileThumbnailLeading(
                  attachment: attachment!,
                  loadThumbnailFile: loadThumbnailFile!,
                  fallbackIcon: icon,
                  fg: fg,
                  size: thumbSize,
                )
              else
                Container(
                  width: 46,
                  height: 46,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: Colors.black.withValues(alpha: 0.25),
                  ),
                  child: isDownloading
                      ? Center(
                          child: SizedBox(
                            width: 22,
                            height: 22,
                            child: CircularProgressIndicator(
                              strokeWidth: 2.4,
                              valueColor: AlwaysStoppedAnimation<Color>(
                                fg.withValues(alpha: 0.95),
                              ),
                            ),
                          ),
                        )
                      : Icon(icon, size: 24, color: fg.withValues(alpha: 0.95)),
                ),
              const SizedBox(width: 10),
              Expanded(child: fileTextBlock(nameMaxLines: 2)),
              if (onFileMenuRequested != null) ...[
                const SizedBox(width: 6),
                menuButton(),
              ],
            ],
          ),
          _AttachmentCaptionText(
            caption: attachment?.caption,
            color: fg,
            padding: const EdgeInsets.only(top: 6),
          ),
          reactionsFooter(),
        ],
      ),
    );

    return _ReplySwipeWrapper(
      enabled: onReplySwipe != null,
      onReplySwipe: onReplySwipe,
      child: _ChatMessageFrame(
        isMe: isMe,
        showGroupAuthorHeader: showGroupAuthorHeader,
        groupAuthorName: groupAuthorName,
        groupAuthorAvatarPath: groupAuthorAvatarPath,
        groupAuthorSeed: groupAuthorSeed,
        groupHeaderStatusText: groupHeaderStatusText,
        onGroupAuthorTap: onGroupAuthorTap,
        showGroupAvatar: showGroupAvatar,
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 320),
          child: _ChatBubbleSurface(
            isMe: isMe,
            viewportListenable: viewportListenable,
            borderRadius: BorderRadius.only(
              topLeft: const Radius.circular(20),
              topRight: const Radius.circular(20),
              bottomLeft: Radius.circular(isMe ? 20 : 8),
              bottomRight: Radius.circular(isMe ? 8 : 20),
            ),
            child: Material(
              type: MaterialType.transparency,
              child: InkWell(
                onTap: onTap,
                borderRadius: BorderRadius.only(
                  topLeft: const Radius.circular(20),
                  topRight: const Radius.circular(20),
                  bottomLeft: Radius.circular(isMe ? 20 : 8),
                  bottomRight: Radius.circular(isMe ? 8 : 20),
                ),
                child: child,
              ),
            ),
          ),
        ),
      ),
    );
  }
}

/// Leading slot for an image-mime FILE in the document bubble: a small rounded
/// thumbnail of the image (loaded + cached via the same loader the image bubble
/// uses). Falls back to the generic file icon while loading or on failure.
class _FileThumbnailLeading extends StatelessWidget {
  const _FileThumbnailLeading({
    required this.attachment,
    required this.loadThumbnailFile,
    required this.fallbackIcon,
    required this.fg,
    this.size = 46,
  });

  final AttachmentEventV1 attachment;
  final Future<File?> Function(AttachmentEventV1 attachment) loadThumbnailFile;
  final IconData fallbackIcon;
  final Color fg;

  /// Box edge in logical px. Photos sent as files use a slightly larger box
  /// (54) so the thumbnail sits closer to the bubble edges; generic-file
  /// fallbacks keep 46.
  final double size;

  @override
  Widget build(BuildContext context) {
    Widget fallback() => Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: Colors.black.withValues(alpha: 0.25),
      ),
      child: Icon(
        fallbackIcon,
        size: size * 0.52,
        color: fg.withValues(alpha: 0.95),
      ),
    );

    return FutureBuilder<File?>(
      future: loadThumbnailFile(attachment),
      builder: (context, snapshot) {
        final file = snapshot.data;
        if (file == null) return fallback();
        // Decode to the thumbnail box (px = logical × DPR) instead of the full
        // source image — keeps the file-row thumb cheap in memory.
        final cacheDim = (size * MediaQuery.devicePixelRatioOf(context)).round();
        return ClipRRect(
          borderRadius: BorderRadius.circular(size >= 54 ? 12 : 9),
          child: Image.file(
            file,
            width: size,
            height: size,
            fit: BoxFit.cover,
            cacheWidth: cacheDim,
            cacheHeight: cacheDim,
            gaplessPlayback: true,
            errorBuilder: (context, error, stack) => fallback(),
          ),
        );
      },
    );
  }
}

class _ImageAttachmentBubble extends StatelessWidget {
  const _ImageAttachmentBubble({
    required this.attachment,
    required this.timestampMs,
    required this.isMe,
    required this.localState,
    this.statusText,
    required this.reactionEventId,
    required this.reactions,
    required this.reactionPlayTokens,
    required this.onToggleOwnReaction,
    required this.selfProfileId,
    required this.loadCachedFile,
    required this.onTap,
    this.bubbleless = false,
    this.replySnippet,
    this.showGroupAuthorHeader = false,
    this.showGroupAvatar = false,
    this.isFirstInSeries = false,
    this.groupAuthorName,
    this.groupAuthorAvatarPath,
    this.groupAuthorSeed,
    this.groupHeaderStatusText,
    this.onGroupAuthorTap,
    this.onReplySwipe,
    this.onReplyQuoteTap,
    this.viewportListenable,
  });

  final AttachmentEventV1 attachment;
  /// GIFs render like stickers — no bubble panel and no caption — so the
  /// animation floats on the wallpaper. Set true for `image/gif`.
  final bool bubbleless;
  final int timestampMs;
  final bool isMe;
  final String localState;
  final String? statusText;
  final String reactionEventId;
  final List<MessageReaction> reactions;
  final Map<String, int> reactionPlayTokens;
  final void Function(String emoji) onToggleOwnReaction;
  final String selfProfileId;
  final Future<File?> Function(AttachmentEventV1 attachment) loadCachedFile;
  final void Function(AttachmentEventV1 attachment) onTap;
  final _ReplySnippet? replySnippet;
  final bool showGroupAuthorHeader;
  final bool showGroupAvatar;
  final bool isFirstInSeries;
  final String? groupAuthorName;
  final String? groupAuthorAvatarPath;
  final String? groupAuthorSeed;
  final String? groupHeaderStatusText;
  final VoidCallback? onGroupAuthorTap;
  final VoidCallback? onReplySwipe;
  final VoidCallback? onReplyQuoteTap;
  final Listenable? viewportListenable;

  @override
  Widget build(BuildContext context) {
    // PERF(keyboard): sizeOf, а НЕ MediaQuery.of. Второе подписывает на ВСЕ
    // изменения, включая viewInsets, которые меняются на каждом кадре анимации
    // клавиатуры — и каждый видимый пузырь с фото пересобирался ~20 раз за одно
    // её открытие. Отсюда были ощутимые подтормаживания в переписках с картинками.
    // Нужна отсюда только ширина, а размер экрана при клавиатуре не меняется:
    // Scaffold стоит с resizeToAvoidBottomInset: false. См. _KeyboardInsetAnchor —
    // он остаётся единственным листом, которому зависеть от вставок разрешено.
    final mediaSize = MediaQuery.sizeOf(context);
    final previewBubbleWidth = (mediaSize.width * 0.66)
        .clamp(220.0, 236.0)
        .toDouble();
    final previewMaxHeight = (mediaSize.height * 0.45)
        .clamp(300.0, 372.0)
        .toDouble();
    final fg = _chatBubbleForegroundColor(context, isMe);
    final status = isMe
        ? _statusIcon(context, localState, fg, timestampMs)
        : null;

    final radius = BorderRadius.only(
      topLeft: const Radius.circular(20),
      topRight: const Radius.circular(20),
      bottomLeft: Radius.circular(isMe ? 20 : 8),
      bottomRight: Radius.circular(isMe ? 8 : 20),
    );

    final content = Material(
      type: MaterialType.transparency,
      child: InkWell(
        onTap: () => onTap(attachment),
        borderRadius: bubbleless ? BorderRadius.circular(19) : radius,
        child: Column(
          crossAxisAlignment: isMe
              ? CrossAxisAlignment.end
              : CrossAxisAlignment.start,
          children: [
            if (isFirstInSeries && groupAuthorName != null)
              _GroupAuthorInlineHeader(
                onTap: onGroupAuthorTap,
                name: groupAuthorName!,
                seed: groupAuthorSeed ?? groupAuthorName!,
                statusText: groupHeaderStatusText,
                padding: const EdgeInsets.fromLTRB(8, 8, 8, 2),
              ),
            if (replySnippet != null)
              Padding(
                padding: const EdgeInsets.fromLTRB(8, 8, 8, 4),
                child: _ReplyQuoteStrip(
                  snippet: replySnippet!,
                  color: fg,
                  isMe: isMe,
                  onTap: onReplyQuoteTap,
                ),
              ),
            Padding(
              padding: const EdgeInsets.fromLTRB(1, 1, 1, 0),
              // With a CAPTION the caption text (not the photo) can
              // drive the bubble width, leaving the preview narrower
              // than the plate with uneven rims. Force the preview to
              // FILL the bubble width then: the tight width makes the
              // aspect box adopt it and BoxFit.cover crops (never
              // stretches) any overflow — thin equal 1px rims on both
              // sides, for outgoing AND incoming alike.
              child: SizedBox(
                width: (!bubbleless &&
                        (attachment.caption ?? '').trim().isNotEmpty)
                    ? double.infinity
                    : null,
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(19),
                  // Sync-first: rows are disposed as they scroll away, so a
                  // plain FutureBuilder restarted the file resolve on every
                  // return — at least one frame of dark placeholder before the
                  // (already ImageCache-hot) picture, i.e. the blink while
                  // scrolling. Once a blob has resolved, later builds paint it
                  // synchronously and never blink again.
                  child: Builder(
                    builder: (context) {
                      final known = _chatMediaFilePeek(attachment.blobId);
                      final mime = (attachment.mime ?? '').toLowerCase();
                      // Reserve the EXACT media box height before the file
                      // resolves — from the sender-stamped pixel dims (or a
                      // previously-decoded aspect) — so the bubble never reflows
                      // its height mid-scroll. Null for older senders: the
                      // preview then falls back to its async decode.
                      final isVideo = _isVideoMediaMime(mime);
                      var knownAspect = _chatMediaAspectPeek(attachment.blobId);
                      if (knownAspect == null) {
                        final fromDims = _chatMediaAspectFromDims(
                          attachment.width,
                          attachment.height,
                          isVideo: isVideo,
                        );
                        if (fromDims != null) {
                          _chatMediaAspectRemember(attachment.blobId, fromDims);
                          knownAspect = fromDims;
                        }
                      }
                      // TZ E2: sender-stamped inline preview (blurred) fills
                      // the reserved box until the real file resolves.
                      final thumbBytes = _chatThumbBytesFor(
                        attachment.blobId,
                        attachment.thumbB64,
                      );
                      if (known != null) {
                        return _ChatFilledVisualPreview(
                          file: known,
                          mime: mime,
                          maxHeight: previewMaxHeight,
                          placeholderHeight: previewMaxHeight * 0.52,
                          knownAspect: knownAspect,
                          blobId: attachment.blobId,
                          thumbBytes: thumbBytes,
                        );
                      }
                      return FutureBuilder<File?>(
                        future: loadCachedFile(attachment).then((f) {
                          _chatMediaFileRemember(attachment.blobId, f);
                          return f;
                        }),
                        builder: (context, snapshot) {
                          return _ChatFilledVisualPreview(
                            file: snapshot.data,
                            mime: mime,
                            maxHeight: previewMaxHeight,
                            placeholderHeight: previewMaxHeight * 0.52,
                            knownAspect: knownAspect,
                            blobId: attachment.blobId,
                            thumbBytes: thumbBytes,
                          );
                        },
                      );
                    },
                  ),
                ),
              ),
            ),
            // GIFs float like stickers: no caption plate.
            if (!bubbleless)
              _AttachmentCaptionText(
                caption: attachment.caption,
                color: fg,
                padding: const EdgeInsets.fromLTRB(8, 6, 8, 0),
              ),
            Padding(
              padding: const EdgeInsets.fromLTRB(8, 4, 8, 6),
              child: _BubbleMetaFooter(
                timestampMs: timestampMs,
                status: status,
                statusText: statusText,
                color: fg,
                reactionEventId: reactionEventId,
                reactions: reactions,
                selfProfileId: selfProfileId,
                reactionPlayTokens: reactionPlayTokens,
                onToggleOwnReaction: onToggleOwnReaction,
              ),
            ),
          ],
        ),
      ),
    );

    return _ReplySwipeWrapper(
      enabled: onReplySwipe != null,
      onReplySwipe: onReplySwipe,
      child: _ChatMessageFrame(
        isMe: isMe,
        showGroupAuthorHeader: showGroupAuthorHeader,
        groupAuthorName: groupAuthorName,
        groupAuthorAvatarPath: groupAuthorAvatarPath,
        groupAuthorSeed: groupAuthorSeed,
        groupHeaderStatusText: groupHeaderStatusText,
        onGroupAuthorTap: onGroupAuthorTap,
        showGroupAvatar: showGroupAvatar,
        child: ConstrainedBox(
          constraints: BoxConstraints(maxWidth: previewBubbleWidth),
          // GIFs (bubbleless) skip the gradient panel so the animation floats
          // on the wallpaper exactly like a sticker; everything else keeps the
          // photo plate.
          child: bubbleless
              ? content
              : _ChatBubbleSurface(
                  isMe: isMe,
                  showIncomingBorder: false,
                  viewportListenable: viewportListenable,
                  borderRadius: radius,
                  child: content,
                ),
        ),
      ),
    );
  }
}

class _ImageGroupBubble extends StatelessWidget {
  const _ImageGroupBubble({
    required this.attachments,
    required this.timestampMs,
    required this.isMe,
    required this.localState,
    this.statusText,
    required this.reactionEventId,
    required this.reactions,
    required this.reactionPlayTokens,
    required this.onToggleOwnReaction,
    required this.selfProfileId,
    required this.loadCachedFiles,
    required this.onImageTap,
    this.replySnippet,
    this.showGroupAuthorHeader = false,
    this.showGroupAvatar = false,
    this.isFirstInSeries = false,
    this.groupAuthorName,
    this.groupAuthorAvatarPath,
    this.groupAuthorSeed,
    this.groupHeaderStatusText,
    this.onGroupAuthorTap,
    this.onReplySwipe,
    this.onReplyQuoteTap,
    this.viewportListenable,
  });

  final List<AttachmentEventV1> attachments;
  final int timestampMs;
  final bool isMe;
  final String localState;
  final String? statusText;
  final String reactionEventId;
  final List<MessageReaction> reactions;
  final Map<String, int> reactionPlayTokens;
  final void Function(String emoji) onToggleOwnReaction;
  final String selfProfileId;
  final Future<List<File?>> Function(List<AttachmentEventV1>) loadCachedFiles;
  final void Function(int index) onImageTap;
  final _ReplySnippet? replySnippet;
  final bool showGroupAuthorHeader;
  final bool showGroupAvatar;
  final bool isFirstInSeries;
  final String? groupAuthorName;
  final String? groupAuthorAvatarPath;
  final String? groupAuthorSeed;
  final String? groupHeaderStatusText;
  final VoidCallback? onGroupAuthorTap;
  final VoidCallback? onReplySwipe;
  final VoidCallback? onReplyQuoteTap;
  final Listenable? viewportListenable;

  @override
  Widget build(BuildContext context) {
    // PERF(keyboard): sizeOf, а НЕ MediaQuery.of. Второе подписывает на ВСЕ
    // изменения, включая viewInsets, которые меняются на каждом кадре анимации
    // клавиатуры — и каждый видимый пузырь с фото пересобирался ~20 раз за одно
    // её открытие. Отсюда были ощутимые подтормаживания в переписках с картинками.
    // Нужна отсюда только ширина, а размер экрана при клавиатуре не меняется:
    // Scaffold стоит с resizeToAvoidBottomInset: false. См. _KeyboardInsetAnchor —
    // он остаётся единственным листом, которому зависеть от вставок разрешено.
    final mediaSize = MediaQuery.sizeOf(context);
    // Bigger album (Telegram-style), matching the pending album bubble.
    final collageWidth = (mediaSize.width * 0.80)
        .clamp(300.0, 340.0)
        .toDouble();
    final fg = _chatBubbleForegroundColor(context, isMe);
    final status = isMe
        ? _statusIcon(context, localState, fg, timestampMs)
        : null;

    final bubbleContent = Padding(
      padding: const EdgeInsets.fromLTRB(1, 1, 1, 4),
      child: Column(
        crossAxisAlignment: isMe
            ? CrossAxisAlignment.end
            : CrossAxisAlignment.start,
        children: [
          if (isFirstInSeries && groupAuthorName != null)
            _GroupAuthorInlineHeader(
              onTap: onGroupAuthorTap,
              name: groupAuthorName!,
              seed: groupAuthorSeed ?? groupAuthorName!,
              statusText: groupHeaderStatusText,
              padding: const EdgeInsets.fromLTRB(4, 4, 4, 2),
            ),
          if (replySnippet != null) ...[
            Padding(
              padding: const EdgeInsets.fromLTRB(4, 2, 4, 8),
              child: _ReplyQuoteStrip(
                snippet: replySnippet!,
                color: fg,
                isMe: isMe,
                onTap: onReplyQuoteTap,
              ),
            ),
          ],
          FutureBuilder<List<File?>>(
            future: loadCachedFiles(attachments),
            builder: (context, snapshot) {
              final files = snapshot.data;
              const maxVisibleTiles = 10;
              final visibleCount = attachments.length > maxVisibleTiles
                  ? maxVisibleTiles
                  : attachments.length;
              final hiddenCount = attachments.length - visibleCount;
              return _ImageGroupCollage(
                attachments: attachments,
                files: files,
                visibleCount: visibleCount,
                hiddenCount: hiddenCount,
                collageWidth: collageWidth,
                onImageTap: onImageTap,
              );
            },
          ),
          // Album caption rides under the grid (carried on the first item).
          _AttachmentCaptionText(
            caption: attachments.isEmpty ? null : attachments.first.caption,
            color: fg,
            padding: const EdgeInsets.fromLTRB(4, 6, 4, 0),
          ),
          const SizedBox(height: 3),
          _BubbleMetaFooter(
            timestampMs: timestampMs,
            status: status,
            statusText: statusText,
            color: fg,
            reactionEventId: reactionEventId,
            reactions: reactions,
            selfProfileId: selfProfileId,
            reactionPlayTokens: reactionPlayTokens,
            onToggleOwnReaction: onToggleOwnReaction,
          ),
        ],
      ),
    );

    // Both directions use the SAME surface as normal message bubbles so an
    // album never reads as a stray "transparent" card: outgoing = the shared
    // green gradient, incoming = the Telegram-style frosted-wallpaper glass with
    // its 1px specular border (was a plain translucent _FrostedGlass plate).
    final bubbleShell = _ChatBubbleSurface(
      isMe: isMe,
      showIncomingBorder: !isMe,
      viewportListenable: viewportListenable,
      borderRadius: BorderRadius.circular(18),
      child: bubbleContent,
    );

    return _ReplySwipeWrapper(
      enabled: onReplySwipe != null,
      onReplySwipe: onReplySwipe,
      child: _ChatMessageFrame(
        isMe: isMe,
        showGroupAuthorHeader: showGroupAuthorHeader,
        groupAuthorName: groupAuthorName,
        groupAuthorAvatarPath: groupAuthorAvatarPath,
        groupAuthorSeed: groupAuthorSeed,
        groupHeaderStatusText: groupHeaderStatusText,
        onGroupAuthorTap: onGroupAuthorTap,
        showGroupAvatar: showGroupAvatar,
        child: ConstrainedBox(
          constraints: BoxConstraints(maxWidth: collageWidth + 2),
          child: bubbleShell,
        ),
      ),
    );
  }
}

bool _isVisualMediaMime(String mime) {
  final normalized = mime.trim().toLowerCase();
  return normalized.startsWith('image/') || normalized.startsWith('video/');
}

bool _isVideoMediaMime(String mime) {
  return mime.trim().toLowerCase().startsWith('video/');
}

Future<double> _resolveChatImageAspectRatio(File file) {
  return _chatImageAspectRatioCache.putIfAbsent(file.path, () async {
    try {
      final bytes = await file.readAsBytes();
      final decoded = await decodeImageFromList(bytes);
      try {
        final width = (decoded.width as num).toDouble();
        final height = (decoded.height as num).toDouble();
        if (width <= 0 || height <= 0) {
          return 0.62;
        }
        // Size the bubble box to the photo's real DECODED aspect within a wide
        // sane range so the box matches the image — `BoxFit.cover` then fills
        // with no distortion and no letterbox bars (height still capped by the
        // surrounding maxHeight). Wider/taller extremes (panoramas, very tall
        // portraits) clamp to the range edge and crop minimally.
        return (width / height).clamp(0.5, 1.9).toDouble();
      } finally {
        decoded.dispose();
      }
    } catch (_) {
      return 0.62;
    }
  });
}

Future<double> _resolveChatVideoAspectRatio(File file) {
  return _chatVideoAspectRatioCache.putIfAbsent(file.path, () async {
    VideoPlayerController? controller;
    try {
      controller = VideoPlayerController.file(file);
      await controller.initialize();
      final aspectRatio = controller.value.aspectRatio;
      if (!aspectRatio.isFinite || aspectRatio <= 0) {
        return 0.62;
      }
      return aspectRatio.clamp(0.56, 1.78).toDouble();
    } catch (_) {
      return 0.62;
    } finally {
      if (controller != null) {
        await controller.dispose();
      }
    }
  });
}

class _ChatFilledVisualPreview extends StatelessWidget {
  const _ChatFilledVisualPreview({
    required this.file,
    required this.mime,
    required this.maxHeight,
    required this.placeholderHeight,
    this.knownAspect,
    this.blobId,
    this.thumbBytes,
    this.showPlayGlyph = true,
  });

  final File? file;
  final String mime;
  final double maxHeight;
  final double placeholderHeight;

  /// TZ E2: sender-stamped inline micro-preview (decoded JPEG bytes). When the
  /// real file hasn't resolved yet, the placeholder shows this blurred instead
  /// of a flat tint — the bubble looks "loaded" instantly. Same box either way
  /// (zero reflow).
  final Uint8List? thumbBytes;

  /// Sender-stamped (or previously-decoded) aspect ratio, width / height. When
  /// non-null the bubble reserves the EXACT final box height up-front — both the
  /// placeholder AND the resolved frame share it — so the media never "jumps"
  /// its height when the file resolves. Null → the async decode of the local
  /// file drives the box (the pre-existing behavior, for older senders).
  final double? knownAspect;

  /// Blob id so a freshly-decoded aspect can be remembered for next time.
  final String? blobId;

  /// While a video is UPLOADING the bubble already draws the cancel ring, so the
  /// preview must NOT also draw its play glyph (that was the duplicate "play +
  /// spinner" the user saw). The real sent bubble shows the play glyph.
  final bool showPlayGlyph;

  @override
  Widget build(BuildContext context) {
    if (!_isVideoMediaMime(mime)) {
      return _ChatFilledImagePreview(
        file: file,
        maxHeight: maxHeight,
        placeholderHeight: placeholderHeight,
        knownAspect: knownAspect,
        blobId: blobId,
        thumbBytes: thumbBytes,
      );
    }

    final aspect = knownAspect;

    if (file == null) {
      final placeholder = _ChatMediaPlaceholderSurface(
        thumbBytes: thumbBytes,
        overlay: showPlayGlyph
            ? const Center(
                child: Icon(
                  AppIcons.playCircle,
                  color: Colors.white70,
                  size: 34,
                ),
              )
            : const SizedBox.shrink(),
      );
      // Known aspect → reserve the SAME box the resolved frame will fill (zero
      // reflow). Unknown → the legacy fixed placeholder height.
      if (aspect != null) {
        return ConstrainedBox(
          constraints: BoxConstraints(maxHeight: maxHeight),
          child: AspectRatio(aspectRatio: aspect, child: placeholder),
        );
      }
      return SizedBox(
        width: double.infinity,
        height: placeholderHeight,
        child: placeholder,
      );
    }

    // Sender told us the aspect → trust it and skip the heavy VideoPlayer
    // initialization we'd otherwise spin up just to measure. The box is stable
    // from the very first frame.
    if (aspect != null) {
      return ConstrainedBox(
        constraints: BoxConstraints(maxHeight: maxHeight),
        child: AspectRatio(
          aspectRatio: aspect,
          child: _ChatVideoPreviewSurface(
            file: file!,
            showPlayGlyph: showPlayGlyph,
          ),
        ),
      );
    }

    return FutureBuilder<double>(
      future: _resolveChatVideoAspectRatio(file!),
      builder: (context, snapshot) {
        final aspectRatio = snapshot.data ?? 0.62;
        if (snapshot.hasData && blobId != null) {
          _chatMediaAspectRemember(blobId!, aspectRatio);
        }
        return ConstrainedBox(
          constraints: BoxConstraints(maxHeight: maxHeight),
          child: AspectRatio(
            aspectRatio: aspectRatio,
            child: _ChatVideoPreviewSurface(
              file: file!,
              showPlayGlyph: showPlayGlyph,
            ),
          ),
        );
      },
    );
  }
}

/// TZ E2 (2026-07-18): the media placeholder surface — the sender-stamped
/// blurred micro-preview when available, the legacy flat tint otherwise. Kept
/// as one widget so every placeholder branch (image + video, known/unknown
/// aspect) renders identically and fills whatever box the caller reserved.
class _ChatMediaPlaceholderSurface extends StatelessWidget {
  const _ChatMediaPlaceholderSurface({
    required this.thumbBytes,
    required this.overlay,
  });

  final Uint8List? thumbBytes;
  final Widget overlay;

  @override
  Widget build(BuildContext context) {
    final bytes = thumbBytes;
    if (bytes == null) {
      return DecoratedBox(
        decoration: const BoxDecoration(color: Color(0x33000000)),
        child: overlay,
      );
    }
    return Stack(
      fit: StackFit.expand,
      children: [
        // Micro-JPEG (~32px) scaled up: a light blur hides the pixelation and
        // reads as a classic "photo loading" preview.
        ImageFiltered(
          imageFilter: ImageFilter.blur(sigmaX: 6, sigmaY: 6),
          child: Image.memory(
            bytes,
            fit: BoxFit.cover,
            gaplessPlayback: true,
            filterQuality: FilterQuality.low,
            errorBuilder: (_, _, _) =>
                const DecoratedBox(decoration: BoxDecoration(color: Color(0x33000000))),
          ),
        ),
        overlay,
      ],
    );
  }
}

class _ChatFilledImagePreview extends StatefulWidget {
  const _ChatFilledImagePreview({
    required this.file,
    required this.maxHeight,
    required this.placeholderHeight,
    this.knownAspect,
    this.blobId,
    this.thumbBytes,
  });

  final File? file;
  final double maxHeight;
  final double placeholderHeight;

  /// Sender-stamped / cached aspect (width / height). See
  /// [_ChatFilledVisualPreview.knownAspect].
  final double? knownAspect;
  final String? blobId;

  /// TZ E2: inline micro-preview bytes for the not-yet-resolved placeholder.
  final Uint8List? thumbBytes;

  @override
  State<_ChatFilledImagePreview> createState() =>
      _ChatFilledImagePreviewState();
}

class _ChatFilledImagePreviewState extends State<_ChatFilledImagePreview> {
  Future<double>? _aspectFuture;
  String? _resolvedPath;

  @override
  void initState() {
    super.initState();
    _ensureAspectFuture();
  }

  @override
  void didUpdateWidget(_ChatFilledImagePreview oldWidget) {
    super.didUpdateWidget(oldWidget);
    _ensureAspectFuture();
  }

  void _ensureAspectFuture() {
    // A known aspect needs no async decode at all — build() renders directly.
    if (widget.knownAspect != null) {
      _aspectFuture = null;
      _resolvedPath = null;
      return;
    }
    // Resolve the aspect ratio ONCE per file PATH. The pending-photo bubble
    // rebuilds on every upload-progress tick and hands us a brand-new File()
    // instance each time (File has no value equality), so keying off the path
    // is what keeps the future stable. Without this the FutureBuilder restarted
    // every tick, snapping the box to the 0.62 default for a frame and back —
    // the flicker/jerk that played the whole time a photo was uploading.
    final path = widget.file?.path;
    if (path == null) {
      _aspectFuture = null;
      _resolvedPath = null;
      return;
    }
    if (path != _resolvedPath) {
      _resolvedPath = path;
      final blobId = widget.blobId;
      // Remember the decoded aspect by blob id so the NEXT build (e.g. scrolling
      // back to this row) reserves the exact height with no async round-trip.
      _aspectFuture = _resolveChatImageAspectRatio(widget.file!).then((a) {
        if (blobId != null) _chatMediaAspectRemember(blobId, a);
        return a;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final file = widget.file;
    final knownAspect = widget.knownAspect;

    // No file yet → placeholder. Reserve the exact box when the aspect is
    // known; show the sender-stamped blurred micro-preview when we have one
    // (TZ E2) so the bubble reads as "loaded" instantly.
    if (file == null) {
      final placeholder = _ChatMediaPlaceholderSurface(
        thumbBytes: widget.thumbBytes,
        overlay: widget.thumbBytes == null
            ? const Center(
                child: Icon(AppIcons.photo, color: Colors.white70, size: 32),
              )
            : const SizedBox.shrink(),
      );
      if (knownAspect != null) {
        return ConstrainedBox(
          constraints: BoxConstraints(maxHeight: widget.maxHeight),
          child: AspectRatio(aspectRatio: knownAspect, child: placeholder),
        );
      }
      return SizedBox(
        width: double.infinity,
        height: widget.placeholderHeight,
        child: placeholder,
      );
    }

    // Aspect known up-front (sender dims / cache) → render directly. No
    // FutureBuilder, so no 1-frame default-aspect flash on parent rebuilds.
    if (knownAspect != null) {
      return _buildImageBox(context, knownAspect, file);
    }

    final aspectFuture = _aspectFuture;
    if (aspectFuture == null) {
      return SizedBox(
        width: double.infinity,
        height: widget.placeholderHeight,
        child: _ChatMediaPlaceholderSurface(
          thumbBytes: widget.thumbBytes,
          overlay: widget.thumbBytes == null
              ? const Center(
                  child: Icon(AppIcons.photo, color: Colors.white70, size: 32),
                )
              : const SizedBox.shrink(),
        ),
      );
    }

    return FutureBuilder<double>(
      future: aspectFuture,
      builder: (context, snapshot) {
        final aspectRatio = snapshot.data ?? 0.62;
        return _buildImageBox(context, aspectRatio, file);
      },
    );
  }

  Widget _buildImageBox(BuildContext context, double aspectRatio, File file) {
    final dpr = MediaQuery.devicePixelRatioOf(context);
    return ConstrainedBox(
      constraints: BoxConstraints(maxHeight: widget.maxHeight),
      child: AspectRatio(
        aspectRatio: aspectRatio,
        // Decode to the on-screen bubble-photo box (px = the larger laid-out
        // edge × DPR), not the full-res source. LayoutBuilder gives the real
        // box after AspectRatio resolves; larger edge keeps cover crisp.
        child: LayoutBuilder(
          builder: (context, constraints) {
            // Decode at the box WIDTH only and let Flutter derive the height
            // from the source aspect. Passing BOTH cacheWidth AND cacheHeight
            // the same value forced a SQUARE decode that stretched/squished
            // the photo (the bubble box was correct, the pixels inside were
            // not). The AspectRatio box already matches the image aspect, so
            // BoxFit.cover now fills with no distortion.
            final boxW = constraints.biggest.width;
            final cacheW = boxW.isFinite && boxW > 0
                ? (boxW * dpr).round()
                : null;
            return Image.file(
              file,
              fit: BoxFit.cover,
              alignment: Alignment.center,
              errorBuilder: (_, _, _) => const _BrokenMediaBox(),
              cacheWidth: cacheW,
              // Keep the already-decoded frame on rebuilds instead of
              // dropping to a blank box while the image re-resolves.
              gaplessPlayback: true,
            );
          },
        ),
      ),
    );
  }
}

class _ChatVideoPreviewSurface extends StatefulWidget {
  const _ChatVideoPreviewSurface({
    required this.file,
    this.showPlayGlyph = true,
  });

  final File file;

  /// Hidden while the video is uploading (the cancel ring is shown instead) so
  /// there is no duplicate play-button-under-spinner.
  final bool showPlayGlyph;

  @override
  State<_ChatVideoPreviewSurface> createState() =>
      _ChatVideoPreviewSurfaceState();
}

class _ChatVideoPreviewSurfaceState extends State<_ChatVideoPreviewSurface> {
  VideoPlayerController? _controller;
  bool _loadFailed = false;

  @override
  void initState() {
    super.initState();
    _openController();
  }

  @override
  void didUpdateWidget(covariant _ChatVideoPreviewSurface oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.file.path != widget.file.path) {
      _disposeController();
      _openController();
    }
  }

  void _openController() {
    _loadFailed = false;
    final controller = VideoPlayerController.file(widget.file);
    _controller = controller;
    controller
        .initialize()
        .then((_) async {
          if (!mounted || !identical(_controller, controller)) return;
          await controller.setVolume(0);
          await controller.pause();
          if (mounted) {
            setState(() {});
          }
        })
        .catchError((_) {
          if (!mounted || !identical(_controller, controller)) return;
          _loadFailed = true;
          setState(() {});
        });
  }

  void _disposeController() {
    final controller = _controller;
    _controller = null;
    if (controller != null) {
      unawaited(controller.dispose());
    }
  }

  @override
  void dispose() {
    _disposeController();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;
    final initialized = controller?.value.isInitialized == true;
    final videoSize = initialized ? controller!.value.size : const Size(1, 1);
    // Single play button — ONE thin white ring (2px, thinner than the old
    // play_circle glyph's fat stroke) + a plain triangle, with a faint dark
    // disc for contrast. No double-circle, no fat outline.
    final icon = Container(
      width: 50,
      height: 50,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: Colors.black.withValues(alpha: 0.18),
        border: Border.all(color: Colors.white, width: 2),
      ),
      child: const Icon(
        AppIcons.playFill,
        color: Colors.white,
        size: 20,
        shadows: [Shadow(color: Colors.black54, blurRadius: 6)],
      ),
    );

    return Stack(
      fit: StackFit.expand,
      children: [
        DecoratedBox(
          decoration: BoxDecoration(
            color: Colors.black.withValues(alpha: 0.24),
          ),
        ),
        if (initialized)
          ClipRect(
            child: FittedBox(
              fit: BoxFit.cover,
              clipBehavior: Clip.hardEdge,
              child: SizedBox(
                width: videoSize.width <= 0 ? 1 : videoSize.width,
                height: videoSize.height <= 0 ? 1 : videoSize.height,
                child: VideoPlayer(controller!),
              ),
            ),
          )
        else
          // While the player warms up, show the POSTER frame instead of a
          // black box — that box was the "black preview" blink every video
          // flashed when scrolled back into view. The poster comes from the
          // same disk cache the galleries use (attachment cache files are
          // named by blobId, so the basename addresses the same entry);
          // peek() serves revisits synchronously, the FutureBuilder covers
          // the first-ever encounter while ffmpeg extracts it.
          Builder(
            builder: (context) {
              if (_loadFailed) {
                return const Center(
                  child: Icon(
                    AppIcons.brokenImage,
                    color: Colors.white70,
                    size: 26,
                  ),
                );
              }
              final posterKey = p.basenameWithoutExtension(widget.file.path);
              final known = VideoThumbnailCache.peek(posterKey);
              if (known != null) {
                return Image.file(
                  known.file,
                  fit: BoxFit.cover,
                  errorBuilder: (_, _, _) => const _BrokenMediaBox(),
                );
              }
              return FutureBuilder<VideoThumbnail?>(
                future: VideoThumbnailCache.forVideo(
                  key: posterKey,
                  videoPath: widget.file.path,
                ),
                builder: (context, snap) {
                  final poster = snap.data;
                  if (poster != null) {
                    return Image.file(
                      poster.file,
                      fit: BoxFit.cover,
                      errorBuilder: (_, _, _) => const _BrokenMediaBox(),
                    );
                  }
                  return const Center(
                    child: SizedBox(
                      width: 22,
                      height: 22,
                      child: CircularProgressIndicator(strokeWidth: 2.2),
                    ),
                  );
                },
              );
            },
          ),
        DecoratedBox(
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [
                Colors.black.withValues(alpha: 0.08),
                Colors.black.withValues(alpha: 0.28),
              ],
            ),
          ),
        ),
        if (widget.showPlayGlyph) Center(child: IgnorePointer(child: icon)),
      ],
    );
  }
}

class _ChatGalleryMediaThumbnail extends StatelessWidget {
  const _ChatGalleryMediaThumbnail({
    required this.file,
    required this.mime,
    this.showPlayGlyph = true,
  });

  final File? file;
  final String mime;

  /// Suppressed on uploading album cells so a video's play button doesn't sit
  /// behind the per-photo upload ring (no play-under-spinner duplicate).
  final bool showPlayGlyph;

  @override
  Widget build(BuildContext context) {
    if (file == null) {
      return DecoratedBox(
        decoration: BoxDecoration(color: Colors.black.withValues(alpha: 0.22)),
        child: Center(
          child: Icon(
            _isVideoMediaMime(mime) && showPlayGlyph
                ? AppIcons.playCircle
                : AppIcons.photo,
            color: Colors.white70,
            size: 24,
          ),
        ),
      );
    }

    if (_isVideoMediaMime(mime)) {
      return _ChatVideoPreviewSurface(file: file!, showPlayGlyph: showPlayGlyph);
    }

    // Decode each collage tile to its on-screen footprint (px = the larger box
    // edge × DPR), not the full source image. The tile size varies by collage
    // layout, so read the real constraints from LayoutBuilder; sizing to the
    // larger edge keeps BoxFit.cover crisp on the cropped axis.
    final dpr = MediaQuery.devicePixelRatioOf(context);
    return LayoutBuilder(
      builder: (context, constraints) {
        final longestEdge = constraints.biggest.longestSide;
        final cacheDim = longestEdge.isFinite && longestEdge > 0
            ? (longestEdge * dpr).round()
            : null;
        // Decode with ONLY the width bound so the aspect ratio is preserved
        // (BoxFit.cover then crops the overflow). Setting BOTH cacheWidth and
        // cacheHeight to the same value decodes the image to a SQUARE, which
        // distorts non-square photos — that was the "squished" collage.
        return Image.file(
          file!,
          fit: BoxFit.cover,
          alignment: Alignment.center,
          errorBuilder: (_, _, _) => const _BrokenMediaBox(iconSize: 18),
          cacheWidth: cacheDim,
          // Как у одиночного превью: без этого плитка альбома моргает пустотой
          // на каждом пересоздании кадра, пока картинка декодируется заново.
          gaplessPlayback: true,
        );
      },
    );
  }
}

class _ImageGroupCollage extends StatelessWidget {
  const _ImageGroupCollage({
    required this.attachments,
    required this.files,
    required this.visibleCount,
    required this.hiddenCount,
    required this.collageWidth,
    required this.onImageTap,
    this.cellOverlayBuilder,
  });

  final List<AttachmentEventV1> attachments;
  final List<File?>? files;
  final int visibleCount;
  final int hiddenCount;
  final double collageWidth;
  final void Function(int index) onImageTap;

  /// Optional per-cell overlay (used by the pending-album bubble to paint a
  /// per-photo upload ring + ✕). Returns null for cells that need no overlay.
  final Widget? Function(int index)? cellOverlayBuilder;

  File? _fileAt(int index) {
    if (files == null || index >= files!.length) return null;
    return files![index];
  }

  Widget _tile(
    BuildContext context, {
    required int index,
    required BorderRadius borderRadius,
    int? overlayCount,
  }) {
    final attachment = attachments[index];
    final mime = (attachment.mime ?? '').toLowerCase();
    final file = _fileAt(index);
    final overlay = cellOverlayBuilder?.call(index);
    return GestureDetector(
      onTap: () => onImageTap(index),
      child: ClipRRect(
        borderRadius: borderRadius,
        child: Stack(
          fit: StackFit.expand,
          children: [
            DecoratedBox(
              decoration: BoxDecoration(
                color: Colors.black.withValues(alpha: 0.18),
              ),
              child: _ChatGalleryMediaThumbnail(
                file: file,
                mime: mime,
                // Uploading cells carry their own ring — hide the play button so
                // it doesn't peek out behind it (no duplicate play-under-ring).
                showPlayGlyph: overlay == null,
              ),
            ),
            if (overlayCount != null && overlayCount > 0)
              DecoratedBox(
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.52),
                ),
                child: Center(
                  child: Text(
                    '+$overlayCount',
                    style: Theme.of(context).textTheme.titleLarge?.copyWith(
                      color: Colors.white,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ),
            if (overlay != null) Positioned.fill(child: overlay),
          ],
        ),
      ),
    );
  }

  /// Telegram-style adaptive tile layout for 1..10 photos. Each entry is a row
  /// described by the number of tiles it holds; tiles are laid out evenly and
  /// the indices flow left-to-right, top-to-bottom.
  static List<int> _rowSizesFor(int n) {
    switch (n) {
      case 1:
        return const <int>[1];
      case 2:
        return const <int>[2];
      case 3:
        // handled specially (1 big + 2 stacked) in build()
        return const <int>[3];
      case 4:
        return const <int>[2, 2];
      case 5:
        return const <int>[2, 3];
      case 6:
        return const <int>[3, 3];
      case 7:
        return const <int>[3, 2, 2];
      case 8:
        return const <int>[3, 3, 2];
      case 9:
        return const <int>[3, 3, 3];
      case 10:
        return const <int>[3, 3, 4];
      default:
        return const <int>[1];
    }
  }

  @override
  Widget build(BuildContext context) {
    const gap = 1.0;
    final count = visibleCount.clamp(0, 10);
    // Index that should carry the "+N more" overlay (last visible tile).
    final overlayIndex = count - 1;
    int? overlayFor(int index) =>
        (hiddenCount > 0 && index == overlayIndex) ? hiddenCount : null;

    if (count <= 1) {
      final height = (collageWidth * 1.34).clamp(240.0, 336.0).toDouble();
      return SizedBox(
        width: collageWidth,
        height: height,
        child: _tile(
          context,
          index: 0,
          borderRadius: BorderRadius.circular(14),
          overlayCount: overlayFor(0),
        ),
      );
    }

    if (count == 2) {
      // Taller than square (Telegram-style portrait pair), not a short strip.
      final height = (collageWidth * 1.14).clamp(310.0, 356.0).toDouble();
      return SizedBox(
        width: collageWidth,
        height: height,
        child: Row(
          children: [
            Expanded(
              child: _tile(
                context,
                index: 0,
                borderRadius: const BorderRadius.only(
                  topLeft: Radius.circular(14),
                  bottomLeft: Radius.circular(14),
                  topRight: Radius.circular(6),
                  bottomRight: Radius.circular(6),
                ),
              ),
            ),
            const SizedBox(width: gap),
            Expanded(
              child: _tile(
                context,
                index: 1,
                borderRadius: const BorderRadius.only(
                  topLeft: Radius.circular(6),
                  bottomLeft: Radius.circular(6),
                  topRight: Radius.circular(14),
                  bottomRight: Radius.circular(14),
                ),
                overlayCount: overlayFor(1),
              ),
            ),
          ],
        ),
      );
    }

    if (count == 3) {
      final height = (collageWidth * 1.40).clamp(356.0, 400.0).toDouble();
      return SizedBox(
        width: collageWidth,
        height: height,
        child: Row(
          children: [
            Expanded(
              flex: 16,
              child: _tile(
                context,
                index: 0,
                borderRadius: const BorderRadius.only(
                  topLeft: Radius.circular(14),
                  bottomLeft: Radius.circular(14),
                  topRight: Radius.circular(6),
                  bottomRight: Radius.circular(6),
                ),
              ),
            ),
            const SizedBox(width: gap),
            Expanded(
              flex: 9,
              child: Column(
                children: [
                  Expanded(
                    child: _tile(
                      context,
                      index: 1,
                      borderRadius: const BorderRadius.only(
                        topLeft: Radius.circular(6),
                        bottomLeft: Radius.circular(6),
                        topRight: Radius.circular(14),
                        bottomRight: Radius.circular(6),
                      ),
                    ),
                  ),
                  const SizedBox(height: gap),
                  Expanded(
                    child: _tile(
                      context,
                      index: 2,
                      borderRadius: const BorderRadius.only(
                        topLeft: Radius.circular(6),
                        bottomLeft: Radius.circular(6),
                        topRight: Radius.circular(6),
                        bottomRight: Radius.circular(14),
                      ),
                      overlayCount: overlayFor(2),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      );
    }

    // ── 4..10 photos: generalized grid of rows (2×2, rows of 2-3, rows of 3) ──
    final rowSizes = _rowSizesFor(count);
    final rowCount = rowSizes.length;
    // Portrait-ish tiles (Telegram-style), not square — 1.4× taller per row so
    // the whole album bubble reads tall like the reference, never a flat strip.
    final tilesInWidestRow = rowSizes.fold<int>(1, (m, c) => c > m ? c : m);
    final approxTile = collageWidth / tilesInWidestRow;
    final height = (approxTile * rowCount * 1.40).clamp(240.0, 640.0).toDouble();

    // Outer corners of the whole collage are rounded; inner tile corners stay
    // square (clean Telegram-style tight grid). The whole thing is clipped.
    var runningIndex = 0;
    final rowWidgets = <Widget>[];
    for (var r = 0; r < rowCount; r++) {
      final tilesInRow = rowSizes[r];
      final tileWidgets = <Widget>[];
      for (var c = 0; c < tilesInRow; c++) {
        final index = runningIndex;
        runningIndex++;
        if (c > 0) tileWidgets.add(const SizedBox(width: gap));
        tileWidgets.add(
          Expanded(
            child: _tile(
              context,
              index: index,
              borderRadius: BorderRadius.zero,
              overlayCount: overlayFor(index),
            ),
          ),
        );
      }
      if (r > 0) rowWidgets.add(const SizedBox(height: gap));
      rowWidgets.add(Expanded(child: Row(children: tileWidgets)));
    }

    return SizedBox(
      width: collageWidth,
      height: height,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(14),
        child: Column(children: rowWidgets),
      ),
    );
  }
}

class _NowPlayingPanel extends StatelessWidget {
  const _NowPlayingPanel({
    required this.item,
    required this.isAudioPlaying,
    required this.audioPosition,
    required this.audioDuration,
    required this.onClose,
    required this.onPlayPause,
    required this.onOpen,
    this.merged = false,
  });

  /// This strip is a ROW inside a shared glass group: skip its own blur /
  /// highlight / outer shadow / rounding so the seam with the strip above it
  /// stays a single hairline instead of two stacked glass edges.
  final bool merged;

  final _NowPlayingItem item;
  final bool isAudioPlaying;
  final Duration audioPosition;
  final Duration audioDuration;
  final VoidCallback onClose;
  final VoidCallback onPlayPause;
  final VoidCallback onOpen;

  // Island geometry — a slim glass strip matching the chat-header islands.
  // Shares the pinned island's exact height/radius so the two stack as one
  // family (they used to differ: 18 vs 16 radius, fixed 48 vs content height).
  static const double _radius = _kChatIslandRadius;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final isAudio = item.kind == _NowPlayingKind.audio;
    final artistText = item.subtitle.trim();
    final progress = isAudio && audioDuration.inMilliseconds > 0
        ? (audioPosition.inMilliseconds / audioDuration.inMilliseconds).clamp(
            0.0,
            1.0,
          )
        : 0.0;
    final timeText = isAudio
        ? '${_fmtAudioDur(audioPosition)} / ${audioDuration > Duration.zero ? _fmtAudioDur(audioDuration) : '--:--'}'
        : item.subtitle;

    final accent = cs.primary;
    final onAccentBg = accent.withValues(alpha: isDark ? 0.22 : 0.14);

    final content = Padding(
      padding: const EdgeInsets.fromLTRB(6, 0, 4, 0),
      child: Row(
        children: [
          // ── Telegram-style round play/pause (filled icon, tinted disc) ──
          _RoundGlassButton(
            size: 32,
            background: onAccentBg,
            onTap: isAudio ? onPlayPause : onOpen,
            tooltip: isAudio ? (isAudioPlaying ? 'Pause' : 'Play') : 'Open',
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 160),
              transitionBuilder: (child, anim) =>
                  ScaleTransition(scale: anim, child: child),
              child: Icon(
                isAudio
                    ? (isAudioPlaying ? AppIcons.pauseFill : AppIcons.playFill)
                    : AppIcons.playFill,
                key: ValueKey(isAudio && isAudioPlaying),
                size: 14,
                color: accent,
              ),
            ),
          ),
          const SizedBox(width: 8),
          // ── Title • artist (single line, taps open the full player) ──
          Expanded(
            child: InkWell(
              onTap: onOpen,
              borderRadius: BorderRadius.circular(10),
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 6),
                child: Text.rich(
                  TextSpan(
                    children: [
                      TextSpan(
                        text: item.title,
                        style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                          fontWeight: FontWeight.w700,
                          letterSpacing: -0.1,
                        ),
                      ),
                      if (isAudio && artistText.isNotEmpty)
                        TextSpan(
                          text: '  •  $artistText',
                          style: Theme.of(context).textTheme.labelSmall
                              ?.copyWith(
                                color: cs.onSurface.withValues(alpha: 0.62),
                                fontWeight: FontWeight.w600,
                              ),
                        ),
                    ],
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            ),
          ),
          const SizedBox(width: 8),
          // ── Time, then a thin close — both pinned to the right edge ──
          Text(
            timeText,
            maxLines: 1,
            style: Theme.of(context).textTheme.labelSmall?.copyWith(
              color: cs.onSurface.withValues(alpha: 0.58),
              fontWeight: FontWeight.w600,
              fontFeatures: const [FontFeature.tabularFigures()],
            ),
          ),
          const SizedBox(width: 2),
          _RoundGlassButton(
            size: 28,
            background: Colors.transparent,
            onTap: onClose,
            tooltip: context.l10n.close,
            child: Icon(
              AppIcons.close,
              size: 15,
              color: cs.onSurface.withValues(alpha: 0.6),
            ),
          ),
        ],
      ),
    );

    // The strip's actual contents: the row, plus the playback rail flush to its
    // bottom edge. Shared by both the standalone and the merged form — only the
    // glass around it differs.
    final rowStack = Stack(
      children: [
        Positioned.fill(child: content),
        if (isAudio)
          // Playback rail sits FLUSH against the strip's bottom edge and runs
          // its full width — the clip around it (own island, or the group)
          // rounds its ends, so no inner pill clip is needed.
          Positioned(
            left: 0,
            right: 0,
            bottom: 0,
            child: SizedBox(
              height: 2,
              child: LinearProgressIndicator(
                value: progress,
                backgroundColor: cs.onSurface.withValues(alpha: 0.10),
                valueColor: AlwaysStoppedAnimation<Color>(
                  accent.withValues(alpha: 0.85),
                ),
              ),
            ),
          ),
      ],
    );

    // Merged: the group owns the blur/highlight/shadow/clip, so hand back the
    // bare row — otherwise the seam would show two stacked glass edges.
    if (merged) {
      return SizedBox(height: _kChatIslandHeight, child: rowStack);
    }

    // Glass island: matte backdrop blur + soft top→bottom white fill +
    // specular top-edge highlight (same recipe as the chat-header islands).
    final fillTop = isDark
        ? Colors.white.withValues(alpha: 0.06)
        : Colors.white.withValues(alpha: 0.65);
    final fillBottom = isDark
        ? Colors.white.withValues(alpha: 0.03)
        : Colors.white.withValues(alpha: 0.55);
    final br = BorderRadius.circular(_radius);

    return SizedBox(
      height: _kChatIslandHeight,
      child: CustomPaint(
        // Light-theme outer shadow (clipped to the ring) — lifts the player
        // island off the page like the chat-header / main islands.
        painter: isDark
            ? null
            : const IslandOuterShadowPainter(
                radius: _radius,
                color: Color(0x12000000),
              ),
        foregroundPainter: GlassHighlightBorderPainter(
          radius: _radius,
          strokeWidth: 1.2,
          color: isDark
              ? Colors.white.withValues(alpha: 0.22)
              : Colors.white.withValues(alpha: 0.40),
        ),
        child: ClipRRect(
          borderRadius: br,
          child: BackdropFilter(
            filter: ImageFilter.blur(sigmaX: 24, sigmaY: 24),
            child: DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [fillTop, fillBottom],
                ),
                borderRadius: br,
              ),
              child: rowStack,
            ),
          ),
        ),
      ),
    );
  }
}

/// Small circular tap target used inside the now-playing island. Keeps the
/// hit area generous while the visual disc stays compact and Telegram-like.
class _RoundGlassButton extends StatelessWidget {
  const _RoundGlassButton({
    required this.size,
    required this.background,
    required this.onTap,
    required this.child,
    this.tooltip,
  });

  final double size;
  final Color background;
  final VoidCallback onTap;
  final Widget child;
  final String? tooltip;

  @override
  Widget build(BuildContext context) {
    final btn = Material(
      color: background,
      shape: const CircleBorder(),
      clipBehavior: Clip.antiAlias,
      child: InkWell(
        onTap: onTap,
        customBorder: const CircleBorder(),
        child: SizedBox(
          width: size,
          height: size,
          child: Center(child: child),
        ),
      ),
    );
    return tooltip == null ? btn : Tooltip(message: tooltip!, child: btn);
  }
}

class _VideoPlayerDialog extends StatefulWidget {
  const _VideoPlayerDialog({required this.file, required this.title});

  final File file;
  final String title;

  @override
  State<_VideoPlayerDialog> createState() => _VideoPlayerDialogState();
}

class _VideoPlayerDialogState extends State<_VideoPlayerDialog> {
  late final VideoPlayerController _controller;
  StreamSubscription<void>? _tick;
  bool _ready = false;

  @override
  void initState() {
    super.initState();
    _controller = VideoPlayerController.file(widget.file);
    _controller.initialize().then((_) async {
      if (!mounted) return;
      setState(() => _ready = true);
      await _controller.play();
    });
    _tick = Stream<void>.periodic(const Duration(milliseconds: 200)).listen((
      _,
    ) {
      if (!mounted) return;
      setState(() {});
    });
  }

  @override
  void dispose() {
    _tick?.cancel();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final value = _controller.value;
    final duration = value.duration;
    final position = value.position;
    final maxMs = duration.inMilliseconds <= 0
        ? 1.0
        : duration.inMilliseconds.toDouble();
    final posMs = position.inMilliseconds.clamp(0, maxMs.toInt()).toDouble();

    return Scaffold(
      backgroundColor: Colors.black,
      body: SafeArea(
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(8, 6, 8, 4),
              child: Row(
                children: [
                  IconButton(
                    onPressed: () => Navigator.of(context).pop(),
                    icon: const Icon(AppIcons.arrowBack, color: Colors.white),
                  ),
                  Expanded(
                    child: Text(
                      widget.title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 22,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                ],
              ),
            ),
            Expanded(
              child: Center(
                child: !_ready
                    ? const CircularProgressIndicator(color: Colors.white)
                    : GestureDetector(
                        onTap: () async {
                          if (_controller.value.isPlaying) {
                            await _controller.pause();
                          } else {
                            await _controller.play();
                          }
                          setState(() {});
                        },
                        child: AspectRatio(
                          aspectRatio: _controller.value.aspectRatio,
                          child: VideoPlayer(_controller),
                        ),
                      ),
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 8, 14, 20),
              child: Column(
                children: [
                  Slider(
                    value: posMs,
                    min: 0,
                    max: maxMs,
                    onChanged: _ready
                        ? (v) => _controller.seekTo(
                            Duration(milliseconds: v.round()),
                          )
                        : null,
                  ),
                  Row(
                    children: [
                      Text(
                        _formatDurationLabel(position),
                        style: const TextStyle(color: Colors.white),
                      ),
                      const Spacer(),
                      Text(
                        _formatDurationLabel(duration),
                        style: const TextStyle(color: Colors.white),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
      floatingActionButton: _ready
          ? FloatingActionButton(
              onPressed: () async {
                if (_controller.value.isPlaying) {
                  await _controller.pause();
                } else {
                  await _controller.play();
                }
                setState(() {});
              },
              child: Icon(
                _controller.value.isPlaying ? AppIcons.pause : AppIcons.play,
              ),
            )
          : null,
    );
  }
}

class _ReplyQuoteStrip extends StatelessWidget {
  const _ReplyQuoteStrip({
    required this.snippet,
    required this.color,
    required this.isMe,
    this.onTap,
  });

  final _ReplySnippet snippet;
  final Color color;
  final bool isMe;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final seed = snippet.authorSeed;
    final accent = seed.isNotEmpty
        ? AvatarInitials.nicknameColor(seed: seed)
        : snippet.authorIsMe
        ? (Theme.of(
                context,
              ).extension<ChatVisualsThemeExtension>()?.outgoingNickname ??
              const Color(0xFF9AF4FF))
        : (Theme.of(
                context,
              ).extension<ChatVisualsThemeExtension>()?.incomingNickname ??
              Theme.of(context).colorScheme.primary);
    final panelBg = seed.isNotEmpty
        ? AvatarInitials.replyPanelColor(seed: seed, isMe: isMe)
        : isMe
        ? Colors.white.withValues(alpha: 0.12)
        : Theme.of(
            context,
          ).colorScheme.primaryContainer.withValues(alpha: 0.42);
    final strip = Container(
      padding: const EdgeInsets.fromLTRB(8, 6, 8, 6),
      decoration: BoxDecoration(
        color: panelBg,
        borderRadius: BorderRadius.circular(10),
      ),
      child: Row(
        // Shrink-wrap to the quoted content so the bubble sizes to the longer
        // of (message text, reply preview) instead of stretching full width.
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(
            width: 3,
            height: 28,
            decoration: BoxDecoration(
              color: accent,
              borderRadius: BorderRadius.circular(3),
            ),
          ),
          const SizedBox(width: 7),
          Flexible(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  snippet.authorName,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: Theme.of(context).textTheme.labelMedium?.copyWith(
                    color: accent,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                Text(
                  snippet.previewText,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: Theme.of(context).textTheme.bodySmall?.copyWith(
                    color: color.withValues(alpha: 0.9),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
    return onTap != null
        ? GestureDetector(
            onTap: onTap,
            behavior: HitTestBehavior.opaque,
            child: strip,
          )
        : strip;
  }
}

/// Telegram-style «Переслано от `name`» header rendered above the forwarded
/// message body. Shows the original author's avatar (or initials) to the left
/// of their name, and taps through to the source chat. Shrink-wraps to its
/// content so the bubble doesn't stretch.
class _ForwardedHeader extends StatelessWidget {
  const _ForwardedHeader({
    required this.name,
    required this.color,
    this.avatarPath,
    this.onTap,
  });

  final String name;
  final Color color;
  final String? avatarPath;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final accent = AvatarInitials.nicknameColor(seed: name);
    final labelStyle = Theme.of(context).textTheme.labelSmall?.copyWith(
      color: color.withValues(alpha: 0.65),
      fontWeight: FontWeight.w500,
      height: 1.1,
    );
    final path = avatarPath?.trim() ?? '';
    final hasPhoto = path.isNotEmpty && File(path).existsSync();
    final Widget avatar = hasPhoto
        ? CircleAvatar(radius: 14, backgroundImage: FileImage(File(path)))
        : AvatarInitials.fallbackBubble(
            context: context,
            radius: 14,
            seed: name,
            displayName: name,
            fallbackId: name,
            labelStyle: const TextStyle(fontWeight: FontWeight.w700),
          );
    final row = Row(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Padding(padding: const EdgeInsets.only(right: 8), child: avatar),
        Flexible(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                chatText(context, ru: 'Переслано от', en: 'Forwarded from'),
                style: labelStyle,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
              Text(
                name,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: Theme.of(context).textTheme.labelMedium?.copyWith(
                  color: accent,
                  fontWeight: FontWeight.w700,
                  height: 1.15,
                ),
              ),
            ],
          ),
        ),
      ],
    );
    if (onTap == null) return row;
    return GestureDetector(
      onTap: onTap,
      behavior: HitTestBehavior.opaque,
      child: row,
    );
  }
}

class _ChatBubbleSurface extends StatelessWidget {
  const _ChatBubbleSurface({
    required this.isMe,
    required this.borderRadius,
    required this.child,
    this.showIncomingBorder = true,
    this.viewportListenable,
  });

  final bool isMe;
  final BorderRadius borderRadius;
  final Widget child;
  final bool showIncomingBorder;
  final Listenable? viewportListenable;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final isDarkTheme = Theme.of(context).brightness == Brightness.dark;
    final visuals = Theme.of(context).extension<ChatVisualsThemeExtension>();
    final top =
        visuals?.bubbleTop ??
        (isDarkTheme ? const Color(0xFF0E5A3B) : const Color(0xFF1A6A48));
    final bottom =
        visuals?.bubbleBottom ??
        (isDarkTheme ? const Color(0xFF0D4B5A) : const Color(0xFF2A5F82));
    final mid = visuals?.bubbleMid;

    if (isMe) {
      return _SharedGradientBubbleSurface(
        borderRadius: borderRadius,
        gradientController: _ChatGradientController.shared(
          top: top,
          bottom: bottom,
          mid: mid,
          brightness: Theme.of(context).brightness,
        ),
        fallbackViewportSize: MediaQuery.sizeOf(context),
        viewportListenable: viewportListenable,
        child: child,
      );
    }

    // Incoming (собеседник) bubbles: «матовое стекло» как в Telegram iOS —
    // пузырь рисует участок ЗАРАНЕЕ размытых обоев по своей глобальной позиции
    // (никакого BackdropFilter на элемент списка — см. _FrostedWindowPainter),
    // поверх — полупрозрачный серый tint + фирменный 1px specular-кант.
    // Контроллер текстуры живёт в состоянии экрана чата; вне его (превью,
    // мок-контексты) — прежняя статичная матовая плита.
    // Runtime setting now, not a platform constant: a phone that runs hot has
    // to have a lever. Still off on Android, which never built the texture.
    final st = context.findAncestorStateOfType<_ChatScreenState>();
    final glassOn =
        kIncomingBubbleWallpaperGlass &&
        (st?.widget.controller.bubbleGlassEnabled ?? true);
    final blur = glassOn ? st?._wallpaperBlur : null;
    return _IncomingFrostedBubble(
      borderRadius: borderRadius,
      isDark: isDarkTheme,
      showBorder: showIncomingBorder,
      fill: cs.surfaceContainerHigh,
      borderColor: cs.outlineVariant.withValues(alpha: 0.2),
      blur: blur,
      viewportListenable: viewportListenable,
      fallbackViewportSize: MediaQuery.sizeOf(context),
      child: child,
    );
  }
}

/// Флаг «стеклянных» входящих пузырей (окно в размытые обои, Telegram iOS).
/// iOS/десктоп — стекло; Android ИСКЛЮЧЁН намеренно: там рисуется плоская
/// непрозрачная сероватая плашка, а живая пре-размытая текстура вообще не
/// строится — никакой нагрузки на GPU широкого парка Android-устройств.
/// (По просьбе: Android — простые/дешёвые, iOS — как сейчас.)
final bool kIncomingBubbleWallpaperGlass = !Platform.isAndroid;

/// Dense frosted-glass surface for INCOMING message bubbles.
///
/// Performance (the test device is a low/mid-range Xiaomi, many bubbles scroll
/// at once): this used to use a live [BackdropFilter] (gaussian blur), but a
/// BackdropFilter re-samples the moving wallpaper backdrop EVERY scroll frame —
/// a [RepaintBoundary] can't shield it because the sampled content keeps
/// changing — which was the dominant scroll-jank source on the test device.
/// It is now a STATIC frosted plate (no per-frame blur):
///   • a dense translucent vertical fill gradient (top→bottom) does the
///     "frosted" heavy lifting; opacity is tuned so the wallpaper reads exactly
///     as faint as it did through the old pre-blurred plate;
///   • the whole surface is wrapped in a [RepaintBoundary] so it never
///     invalidates its siblings while the list scrolls.
///
/// The "barely reflects the light" look comes from two cheap overlays painted
/// over the fill: a faint diagonal white→transparent sheen and a 1px specular
/// top/left highlight (the app's shared [GlassHighlightBorderPainter]).
// ── Warm timeline caches (top-level: survive the State being recreated) ──
// Keyed by convoId; a REOPENED chat paints its last known messages on the very
// first frame while the fresh DB query + decrypt pipeline runs in the
// background. Bounded to the last few conversations.
final Map<String, List<ChatEvent>> _warmEventsByConvo =
    <String, List<ChatEvent>>{};
final Map<String, List<_TimelineEntry>> _warmTimelineByConvo =
    <String, List<_TimelineEntry>>{};

/// Устройство → профиль его владельца для портретов авторов в комнатах.
///
/// Общее на всё приложение, а не на один чат: устройство принадлежит одному
/// профилю навсегда, и узнанная связь верна в любой комнате. Заполняется там,
/// где лента и так разрешает авторов (`_buildTimelineEntries`); размер — число
/// устройств собеседников, которые попадались на глаза.
final Map<String, String> _roomAuthorProfileIdByDevice = <String, String>{};

void _warmStore<T>(Map<String, T> cache, String convoId, T value) {
  if (!cache.containsKey(convoId) && cache.length >= 8) {
    cache.remove(cache.keys.first);
  }
  cache[convoId] = value;
}

class _IncomingFrostedBubble extends StatelessWidget {
  const _IncomingFrostedBubble({
    required this.borderRadius,
    required this.isDark,
    required this.showBorder,
    required this.fill,
    required this.borderColor,
    required this.child,
    this.blur,
    this.viewportListenable,
    this.fallbackViewportSize = Size.zero,
  });

  final BorderRadius borderRadius;
  final bool isDark;
  final bool showBorder;
  final Color fill;
  final Color borderColor;
  final Widget child;

  /// Контроллер размытой мини-текстуры обоев; null → легаси статичная плита.
  final WallpaperBlurController? blur;

  /// Скролл чата: repaint «окна» при прокрутке (только через Listenable у
  /// painter'а — никаких setState на кадр).
  final Listenable? viewportListenable;
  final Size fallbackViewportSize;

  @override
  Widget build(BuildContext context) {
    final blurController = blur;
    if (blurController != null) {
      // «Стеклянный» путь: окно в общую размытую текстуру обоев. Механика
      // привязки к вьюпорту 1:1 как у исходящих градиентных пузырей
      // (_SharedGradientBubbleSurface) — позиция резолвится в paint() без
      // layout thrashing, контент изолирован RepaintBoundary.
      RenderBox? bubbleRenderObjectProvider() {
        return context.findRenderObject() as RenderBox?;
      }

      RenderBox? viewportRenderObjectProvider() {
        final scrollable = Scrollable.maybeOf(context);
        final renderObject = scrollable?.context.findRenderObject();
        return renderObject is RenderBox ? renderObject : null;
      }

      final specular = Colors.white.withValues(alpha: isDark ? 0.14 : 0.30);
      return CustomPaint(
        isComplex: false,
        willChange: viewportListenable != null,
        painter: _FrostedWindowPainter(
          borderRadius: borderRadius,
          controller: blurController,
          resolver: _BubbleGradientResolver(
            fallbackViewportSize: fallbackViewportSize,
            bubbleRenderObjectProvider: bubbleRenderObjectProvider,
            viewportRenderObjectProvider: viewportRenderObjectProvider,
          ),
          tint: isDark
              ? blurController.config.darkTint
              : blurController.config.lightTint,
          fallbackTop: fill.withValues(alpha: isDark ? 0.95 : 0.98),
          fallbackBottom: fill.withValues(alpha: isDark ? 0.92 : 0.96),
          borderColor: showBorder ? borderColor : null,
          repaintTrigger: viewportListenable == null
              ? blurController
              : Listenable.merge(<Listenable?>[
                  blurController,
                  viewportListenable,
                ]),
        ),
        foregroundPainter: GlassHighlightBorderPainter(
          radius: borderRadius.topLeft.x,
          strokeWidth: 1.0,
          color: specular,
          bottomHighlight: false,
        ),
        child: ClipRRect(
          borderRadius: borderRadius,
          child: ColoredBox(
            color: Colors.transparent,
            child: RepaintBoundary(child: child),
          ),
        ),
      );
    }
    // Android: cheapest possible incoming bubble — a FLAT, opaque greyish plate
    // (no gradient, no diagonal sheen, no specular rim, no wallpaper texture).
    // The wallpaper glass is iOS/desktop-only; on Android this keeps scrolling
    // light on the wide hardware range. `fill` is the theme surfaceContainerHigh
    // (an opaque greyish surface) so it reads as a solid, monotone bubble.
    if (Platform.isAndroid) {
      return RepaintBoundary(
        child: ClipRRect(
          borderRadius: borderRadius,
          child: DecoratedBox(
            decoration: BoxDecoration(
              borderRadius: borderRadius,
              color: fill,
              border: showBorder ? Border.all(color: borderColor) : null,
            ),
            child: ColoredBox(color: Colors.transparent, child: child),
          ),
        ),
      );
    }
    // Dense, NOT see-through: the wallpaper shows through only faintly so text /
    // timestamps / reactions stay clearly readable over the dark chat
    // wallpapers. (The old solid fill was fully opaque; this keeps most of it.)
    //
    // PERF (P0-2): we used to wrap this in a live `BackdropFilter` (gaussian
    // blur sigma 14) so the wallpaper showed through pre-blurred. A
    // BackdropFilter re-samples the moving backdrop EVERY scroll frame (the
    // surrounding RepaintBoundary can't shield it because the sampled content
    // changes), which was the #1 scroll-jank source on the Xiaomi test device.
    // We drop the live blur entirely. To keep the plate visually identical, the
    // dense fill is nudged up a touch (the blur previously haze-lightened the
    // wallpaper behind the translucent fill; without it the wallpaper would read
    // very slightly sharper/darker through the plate, so a hair more opacity
    // restores the same perceived density). The gradient fill, diagonal sheen
    // and the shared specular top/left highlight already carry ~90% of the
    // frosted read with zero per-frame blur cost.
    // Nearly opaque matte plate — the wallpaper only just barely shows through
    // (a hair of translucency keeps the frosted feel without reading see-through).
    final fillTop = fill.withValues(alpha: isDark ? 0.95 : 0.98);
    final fillBottom = fill.withValues(alpha: isDark ? 0.92 : 0.96);
    // Matte: no diagonal gloss reflection.
    final sheen = Colors.white.withValues(alpha: 0.0);
    // 1px specular top/left highlight — same convex "lit-from-above" edge the
    // app's glass islands use.
    final specular = Colors.white.withValues(alpha: isDark ? 0.14 : 0.30);

    // Static frosted plate — same rounded shape, gradient fill, sheen and
    // border as before, just WITHOUT the live BackdropFilter (and its extra
    // saveLayer). ClipRRect keeps the child clipped to the rounded corners.
    Widget surface = ClipRRect(
      borderRadius: borderRadius,
      child: DecoratedBox(
        decoration: BoxDecoration(
          borderRadius: borderRadius,
          // Translucent vertical fill for density (lighter top → darker
          // bottom), then a faint diagonal sheen blended on top.
          gradient: LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[fillTop, fillBottom],
          ),
          border: showBorder ? Border.all(color: borderColor) : null,
        ),
        child: DecoratedBox(
          // Very subtle top-left → bottom-right white→transparent reflection.
          decoration: BoxDecoration(
            borderRadius: borderRadius,
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: <Color>[sheen, sheen.withValues(alpha: 0.0)],
              stops: const <double>[0.0, 0.6],
            ),
          ),
          child: ColoredBox(color: Colors.transparent, child: child),
        ),
      ),
    );

    // Specular rim (bright top edge + thin bottom rim light). Uses the shared
    // painter so it matches the header / paywall glass exactly. Radius is taken
    // from the top-left corner (all bubble corners share the same circular
    // radius except the tail corner, which is smaller — the rim still reads
    // correctly because the painter rounds to [radius]).
    surface = CustomPaint(
      foregroundPainter: GlassHighlightBorderPainter(
        radius: borderRadius.topLeft.x,
        strokeWidth: 1.0,
        color: specular,
        bottomHighlight: false, // matte — remove the bottom rim-light line
      ),
      child: surface,
    );

    // Isolate the plate so scrolling siblings don't force it to repaint.
    return RepaintBoundary(child: surface);
  }
}

/// Рисует под входящим пузырём участок ПРЕ-размытой текстуры обоев + серый
/// полупрозрачный tint (Telegram iOS).
///
/// Текстура (см. [WallpaperBlurController]) покрывает весь вьюпорт: dst-рект
/// для drawImageRect — это вьюпорт в координатах пузыря (тот же
/// [_BubbleGradientResolver], что двигает градиент исходящих пузырей), поэтому
/// при скролле «окно» само едет по текстуре — ничего не переразмывается и
/// saveLayer на пузырь не создаётся. Repaint — только через Listenable
/// (скролл + смена текстуры), без setState.
class _FrostedWindowPainter extends CustomPainter {
  _FrostedWindowPainter({
    required this.borderRadius,
    required this.controller,
    required this.resolver,
    required this.tint,
    required this.fallbackTop,
    required this.fallbackBottom,
    required this.borderColor,
    required Listenable repaintTrigger,
  }) : super(repaint: repaintTrigger);

  final BorderRadius borderRadius;
  final WallpaperBlurController controller;
  final _BubbleGradientResolver resolver;
  final Color tint;
  final Color fallbackTop;
  final Color fallbackBottom;
  final Color? borderColor;

  @override
  void paint(Canvas canvas, Size size) {
    final bounds = Offset.zero & size;
    final rrect = borderRadius.toRRect(bounds);
    final texture = controller.texture;
    if (texture == null) {
      // Текстура ещё готовится — прежняя матовая плита, без мигания.
      canvas.drawRRect(
        rrect,
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[fallbackTop, fallbackBottom],
          ).createShader(bounds),
      );
    } else {
      final resolution = resolver.resolve(size);
      canvas.save();
      canvas.clipRRect(rrect);
      // Окно в общую текстуру. Выборка БИКУБИЧЕСКАЯ (FilterQuality.high):
      // билинейная на ~16× апскейле превращала плавные градиенты в решётку
      // линейных «тентов» — на анимированных обоях она читалась как
      // сото-подобная сетка поверх пузыря. Текстура крошечная, разница в
      // стоимости не измерима.
      canvas.drawImageRect(
        texture,
        Rect.fromLTWH(
          0,
          0,
          texture.width.toDouble(),
          texture.height.toDouble(),
        ),
        resolution.viewportRectInBubble,
        Paint()..filterQuality = FilterQuality.high,
      );
      canvas.drawRect(bounds, Paint()..color = tint);
      canvas.restore();
    }
    final border = borderColor;
    if (border != null) {
      canvas.drawRRect(
        rrect.deflate(0.5),
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.0
          ..color = border,
      );
    }
  }

  @override
  bool shouldRepaint(covariant _FrostedWindowPainter oldDelegate) {
    return oldDelegate.borderRadius != borderRadius ||
        oldDelegate.controller != controller ||
        oldDelegate.tint != tint ||
        oldDelegate.fallbackTop != fallbackTop ||
        oldDelegate.fallbackBottom != fallbackBottom ||
        oldDelegate.borderColor != borderColor;
  }
}

class _ChatGradientController {
  _ChatGradientController({
    required this.top,
    required this.bottom,
    required this.brightness,
    this.mid,
  }) : shader = _GlobalGradientShader(
         top: top,
         bottom: bottom,
         mid: mid,
         brightness: brightness,
       );

  /// Общий контроллер для одинакового оформления.
  ///
  /// 🔴 ПОЧЕМУ ЭТО ГЛАВНОЕ (03.09.2026, аудит подтормаживания клавиатуры).
  /// Контроллер создавался прямо в `build()` КАЖДОГО пузыря. Значит у каждого
  /// был собственный кэш шейдера, и любая перестройка его обнуляла — кэш просто
  /// не доживал до второго обращения. Расширение кэша до нескольких мест без
  /// этой правки не дало бы ничего: словарь у каждого пузыря свой, и в нём
  /// всегда лежит ровно одна запись.
  ///
  /// Цвета берутся из темы и для всего экрана одинаковы, поэтому контроллеров
  /// нужно ровно столько, сколько различных сочетаний цветов, — обычно одно.
  /// Ключ включает все составляющие оформления, так что смена темы честно даёт
  /// другой контроллер, а не подсовывает старые цвета.
  factory _ChatGradientController.shared({
    required Color top,
    required Color bottom,
    required Brightness brightness,
    Color? mid,
  }) {
    final key = '${top.toARGB32()}|${bottom.toARGB32()}|'
        '${mid?.toARGB32() ?? 'none'}|${brightness.name}';
    final existing = _sharedControllers[key];
    if (existing != null) return existing;
    final created = _ChatGradientController(
      top: top,
      bottom: bottom,
      brightness: brightness,
      mid: mid,
    );
    // Сочетаний оформления единицы: тема, светлая и тёмная, свои обои чата.
    // Предел стоит не ради памяти, а чтобы опечатка в цвете не превратила
    // словарь в утечку.
    if (_sharedControllers.length >= 12) {
      _sharedControllers.remove(_sharedControllers.keys.first);
    }
    _sharedControllers[key] = created;
    return created;
  }

  static final Map<String, _ChatGradientController> _sharedControllers =
      <String, _ChatGradientController>{};



  final Color top;
  final Color bottom;
  final Color? mid;
  final Brightness brightness;
  final _GlobalGradientShader shader;

  @override
  bool operator ==(Object other) {
    return other is _ChatGradientController &&
        other.top == top &&
        other.bottom == bottom &&
        other.mid == mid &&
        other.brightness == brightness;
  }

  @override
  int get hashCode => Object.hash(top, bottom, mid, brightness);
}

class _GlobalGradientShader {
  _GlobalGradientShader({
    required Color top,
    required Color bottom,
    required Brightness brightness,
    Color? mid,
  }) : _gradient = LinearGradient(
         begin: Alignment.topLeft,
         end: Alignment.bottomRight,
         colors: _colors(top, bottom, mid, brightness),
         stops: const <double>[0.0, 0.22, 0.54, 0.82, 1.0],
       );

  final LinearGradient _gradient;

  /// Готовые шейдеры по прямоугольнику, свежие в конце.
  ///
  /// 🔴 БЫЛО ОДНО МЕСТО, И ЭТОГО ХВАТАЛО РОВНО НА ОДИН ПУЗЫРЬ (03.09.2026,
  /// аудит подтормаживания клавиатуры). Прямоугольник вычисляется от положения
  /// пузыря на экране, то есть у каждого он СВОЙ. Единственный слот вытеснялся
  /// следующим же пузырём, и попаданий не случалось никогда: замер на десяти
  /// пузырях дал ноль попаданий и десять созданий шейдера — на каждом кадре
  /// заново.
  ///
  /// Больнее всего это било не в саму анимацию, а в ПОКОЙ: когда клавиатура уже
  /// поднята, перерисовки продолжаются (курсор, подсказки, набор текста), и за
  /// тридцать кадров создавалось триста шейдеров там, где хватает десяти.
  ///
  /// Во время движения клавиатуры кэш помогает мало, и это ожидаемо: геометрия
  /// меняется на каждом кадре, попадать не во что. Стоимость самой анимации
  /// снимается тем, что из `paint` убраны обходы дерева, — см.
  /// `_BubbleGradientResolver`.
  ///
  /// Ёмкость с запасом: пузырей на экране редко больше десятка, а вытеснение
  /// давних не даёт словарю расти в неограниченный кэш на всю переписку.
  static const int _shaderCacheCapacity = 24;
  final Map<Rect, Shader> _shaderCache = <Rect, Shader>{};

  Shader createShader(Rect viewportRectInBubble) {
    final expandedRect = Rect.fromLTWH(
      viewportRectInBubble.left - viewportRectInBubble.width * 0.08,
      viewportRectInBubble.top,
      viewportRectInBubble.width * 1.16,
      viewportRectInBubble.height,
    );
    // `remove` + повторная вставка держат самые свежие в конце словаря: Dart
    // сохраняет порядок вставки, поэтому первый ключ — самый давний.
    final cached = _shaderCache.remove(expandedRect);
    if (cached != null) {
      _shaderCache[expandedRect] = cached;
      return cached;
    }
    final shader = _gradient.createShader(expandedRect);
    if (_shaderCache.length >= _shaderCacheCapacity) {
      _shaderCache.remove(_shaderCache.keys.first);
    }
    _shaderCache[expandedRect] = shader;
    return shader;
  }

  static List<Color> _colors(
    Color top,
    Color bottom,
    Color? mid,
    Brightness brightness,
  ) {
    final highlightBlend = brightness == Brightness.dark ? 0.10 : 0.18;
    final shadowBlend = brightness == Brightness.dark ? 0.14 : 0.04;
    final highlight = Color.lerp(top, Colors.white, highlightBlend) ?? top;
    final bridge = mid ?? (Color.lerp(top, bottom, 0.48) ?? top);
    final lowerBridge = mid != null
        ? (Color.lerp(mid, bottom, 0.55) ?? bottom)
        : (Color.lerp(top, bottom, 0.74) ?? bottom);
    final shadow = Color.lerp(bottom, Colors.black, shadowBlend) ?? bottom;
    return <Color>[highlight, top, bridge, lowerBridge, shadow];
  }
}

/// Положение окна прокрутки на экране, посчитанное ОДИН РАЗ ЗА КАДР.
///
/// 🔴 ЗАЧЕМ (03.09.2026, аудит подтормаживания клавиатуры). Каждая поверхность —
/// и градиентный пузырь, и матовое окно — звала в своей отрисовке
/// `localToGlobal` у окна прокрутки. Это обход дерева вверх до корня с
/// перемножением преобразований, а дерево здесь глубокое. Обход делался столько
/// раз, сколько поверхностей на экране, и так на каждом кадре подъёма
/// клавиатуры.
///
/// Положение окна на одном кадре одинаково для всех — считать его заново для
/// каждой поверхности незачем.
///
/// 🔴 КЛЮЧ — ОТМЕТКА ТЕКУЩЕГО КАДРА, а не время. Внутри кадра значение
/// переиспользуется, на новом считается заново. Поэтому цвет не может отстать
/// от геометрии: именно такое отставание чинили 01.08.2026, когда поднятые
/// клавиатурой пузыри сохраняли окраску прежнего положения.
class _ViewportOriginCache {
  const _ViewportOriginCache._();

  static Duration? _frame;
  static Offset? _origin;

  static Offset originGlobal(RenderBox? viewportRenderBox) {
    final frame = SchedulerBinding.instance.currentFrameTimeStamp;
    final cached = _origin;
    if (cached != null && _frame == frame) {
      return cached;
    }
    final origin = viewportRenderBox != null
        ? viewportRenderBox.localToGlobal(Offset.zero)
        : Offset.zero;
    _frame = frame;
    _origin = origin;
    return origin;
  }
}

class _BubbleGradientResolver {
  const _BubbleGradientResolver({
    required this.fallbackViewportSize,
    required this.bubbleRenderObjectProvider,
    required this.viewportRenderObjectProvider,
  });

  final Size fallbackViewportSize;
  final RenderBox? Function() bubbleRenderObjectProvider;
  final RenderBox? Function() viewportRenderObjectProvider;

  _BubbleGradientResolution resolve(Size bubbleSize) {
    final bubbleRenderBox = bubbleRenderObjectProvider();
    final viewportRenderBox = viewportRenderObjectProvider();
    final viewportSize = viewportRenderBox?.hasSize == true
        ? viewportRenderBox!.size
        : fallbackViewportSize;

    if (bubbleRenderBox == null || !bubbleRenderBox.hasSize) {
      return _BubbleGradientResolution(
        viewportRectInBubble: Rect.fromLTWH(
          -viewportSize.width * 0.68,
          0,
          viewportSize.width,
          viewportSize.height > bubbleSize.height
              ? viewportSize.height
              : bubbleSize.height,
        ),
      );
    }

    // Один обход дерева на кадр вместо одного на каждый пузырь — см.
    // `viewportOriginGlobalForFrame`.
    final viewportGlobalOrigin = _ViewportOriginCache.originGlobal(
      viewportRenderBox,
    );
    final viewportOriginInBubble = bubbleRenderBox.globalToLocal(
      viewportGlobalOrigin,
    );
    final gradientHeight = viewportSize.height > bubbleSize.height
        ? viewportSize.height
        : bubbleSize.height;
    return _BubbleGradientResolution(
      viewportRectInBubble: Rect.fromLTWH(
        viewportOriginInBubble.dx,
        viewportOriginInBubble.dy,
        viewportSize.width,
        gradientHeight,
      ),
    );
  }
}

class _BubbleGradientResolution {
  const _BubbleGradientResolution({required this.viewportRectInBubble});

  final Rect viewportRectInBubble;
}

class _SharedGradientBubbleSurface extends StatelessWidget {
  const _SharedGradientBubbleSurface({
    required this.borderRadius,
    required this.gradientController,
    required this.fallbackViewportSize,
    required this.child,
    this.viewportListenable,
  });

  final BorderRadius borderRadius;
  final _ChatGradientController gradientController;
  final Size fallbackViewportSize;
  final Listenable? viewportListenable;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    RenderBox? bubbleRenderObjectProvider() {
      return context.findRenderObject() as RenderBox?;
    }

    RenderBox? viewportRenderObjectProvider() {
      final scrollable = Scrollable.maybeOf(context);
      final renderObject = scrollable?.context.findRenderObject();
      return renderObject is RenderBox ? renderObject : null;
    }

    return CustomPaint(
      isComplex: false,
      willChange: viewportListenable != null,
      painter: _SharedGradientPainter(
        borderRadius: borderRadius,
        gradientController: gradientController,
        resolver: _BubbleGradientResolver(
          fallbackViewportSize: fallbackViewportSize,
          bubbleRenderObjectProvider: bubbleRenderObjectProvider,
          viewportRenderObjectProvider: viewportRenderObjectProvider,
        ),
        viewportListenable: viewportListenable,
      ),
      child: ClipRRect(
        borderRadius: borderRadius,
        child: ColoredBox(
          color: Colors.transparent,
          child: RepaintBoundary(child: child),
        ),
      ),
    );
  }
}

class _SharedGradientPainter extends CustomPainter {
  _SharedGradientPainter({
    required this.borderRadius,
    required this.gradientController,
    required this.resolver,
    required this.viewportListenable,
  }) : super(repaint: viewportListenable);

  final BorderRadius borderRadius;
  final _ChatGradientController gradientController;
  final _BubbleGradientResolver resolver;
  final Listenable? viewportListenable;

  @override
  void paint(Canvas canvas, Size size) {
    final bounds = Offset.zero & size;
    final rrect = borderRadius.toRRect(bounds);
    final resolution = resolver.resolve(size);
    final paint = Paint()
      ..shader = gradientController.shader.createShader(
        resolution.viewportRectInBubble,
      );
    canvas.drawRRect(rrect, paint);
  }

  @override
  bool shouldRepaint(covariant _SharedGradientPainter oldDelegate) {
    return oldDelegate.borderRadius != borderRadius ||
        oldDelegate.gradientController != gradientController ||
        oldDelegate.resolver.fallbackViewportSize !=
            resolver.fallbackViewportSize;
  }
}

/// The slot a bubble keeps for its reaction row, so the bubble GROWS into the
/// row instead of snapping to a new height.
///
/// 🔴 WHY (2026-08-01, request: "make the bubbles grow very smoothly when
/// someone adds a reaction"). The row used to be added and removed from the
/// tree outright, so the first reaction on a message changed the bubble's
/// height between two frames — a visible snap, and every row below it jumped
/// by the same amount in the same instant.
///
/// The slot is ALWAYS in the tree (empty when there are no reactions), which
/// is what gives [AnimatedSize] something to animate from. Note this animates
/// only CHANGES after the first layout — opening a chat lays the row out at
/// its final size with no animation at all, which is what we want: the growth
/// should read as "a reaction just landed", never as "the screen is still
/// assembling itself".
class _ReactionSlot extends StatelessWidget {
  const _ReactionSlot({required this.alignment, required this.child});

  final Alignment alignment;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    return AnimatedSize(
      // Long enough to read as a glide rather than a snap, short enough that a
      // burst of reactions never feels laggy.
      duration: const Duration(milliseconds: 260),
      curve: Curves.easeOutCubic,
      alignment: alignment,
      // 🔴 NO CLIPPING (2026-08-01, field: "the reaction is cut in half
      // horizontally until the growth finishes — it is a fraction of a second
      // but still infuriating").
      //
      // AnimatedSize animates BOTH axes and, by default, clips its child to the
      // box it is currently at. Growing from an empty slot means the width runs
      // 0 -> full as well as the height, so for the whole animation the chip was
      // being sliced down its middle. That is the horizontal cut.
      //
      // Clip.none lets the chip draw at its true size from the first frame while
      // the SPACE beneath it opens up. The bubble still grows smoothly — that is
      // the point of the slot — but nothing is ever sawn in half. The chip
      // briefly extends past the opening slot, so the anchor decides WHERE that
      // overflow lands: the two bubble footers anchor to the TOP, dropping it
      // into the gap below the bubble rather than across the text above it; the
      // inline meta row anchors to the RIGHT, away from the timestamp that
      // follows it.
      clipBehavior: Clip.none,
      child: child,
    );
  }
}

class _ReactionPills extends StatelessWidget {
  const _ReactionPills({
    required this.reactionEventId,
    required this.reactions,
    required this.selfProfileId,
    required this.reactionPlayTokens,
    required this.onToggleOwnReaction,
  });

  final String reactionEventId;
  final List<MessageReaction> reactions;
  final String selfProfileId;
  final Map<String, int> reactionPlayTokens;
  final void Function(String emoji) onToggleOwnReaction;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final grouped = <String, _GroupedReaction>{};
    for (final reaction in reactions) {
      grouped.update(
        reaction.emoji,
        (existing) => existing.copyWith(
          members: [...existing.members, reaction],
          isOwn: existing.isOwn || reaction.profileId == selfProfileId,
        ),
        ifAbsent: () => _GroupedReaction(
          emoji: reaction.emoji,
          members: [reaction],
          isOwn: reaction.profileId == selfProfileId,
        ),
      );
    }
    final chips = grouped.values.toList()
      ..sort((a, b) {
        final byCount = b.members.length.compareTo(a.members.length);
        if (byCount != 0) return byCount;
        return a.members.first.createdAtMs.compareTo(
          b.members.first.createdAtMs,
        );
      });

    return Wrap(
      spacing: 6,
      runSpacing: 6,
      children: [
        for (final reactionGroup in chips)
          Builder(
            builder: (context) {
              final isOwn = reactionGroup.isOwn;
              final members = reactionGroup.members;
              final showAvatars = members.length <= 5;
              final chip = Container(
                padding: const EdgeInsets.fromLTRB(7, 3, 7, 3),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(13),
                  // 🔴 THE INDICATOR COLOUR (2026-08-01, request: "make the
                  // background of the reaction oval the indicator colour").
                  //
                  // The "Цвета индикаторов" setting does not paint one widget —
                  // the chosen preset REPLACES `ColorScheme.primary` for the
                  // whole app (main.dart, `indicatorOverride`). So reading
                  // cs.primary here is what makes this pill follow the user's
                  // pick automatically, including the default "follow theme".
                  // Hard-coding any preset hue would freeze it on one choice.
                  //
                  // A reaction I took part in reads at full strength; one from
                  // other people is the same hue, softened, so my own reaction
                  // is still findable at a glance without inventing a colour.
                  color: isOwn
                      ? cs.primary
                      : cs.primary.withValues(alpha: 0.68),
                  border: Border.all(
                    color: isOwn
                        ? cs.primary
                        : cs.primary.withValues(alpha: 0.68),
                  ),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    _ReactionEmojiLottie(
                      emoji: reactionGroup.emoji,
                      size: 18,
                      playToken: members.fold<int?>(
                        null,
                        (current, reaction) =>
                            reactionPlayTokens['$reactionEventId|${reaction.profileId}|${reaction.emoji}'] ??
                            current,
                      ),
                    ),
                    if (showAvatars && members.isNotEmpty) ...[
                      const SizedBox(width: 5),
                      _ReactionAvatarStrip(reactions: members),
                    ],
                    if (members.length > 1) ...[
                      const SizedBox(width: 5),
                      Text(
                        '${members.length}',
                        style: Theme.of(context).textTheme.labelSmall?.copyWith(
                          fontSize: 11.5,
                          fontWeight: FontWeight.w800,
                          // The pill now carries the indicator colour, so the
                          // count MUST be the contrasting on-primary tone.
                          // Leaving it as cs.primary painted the number in the
                          // background's own colour — an invisible counter.
                          color: isOwn
                              ? cs.onPrimary
                              : cs.onPrimary.withValues(alpha: 0.92),
                          height: 1,
                        ),
                      ),
                    ],
                  ],
                ),
              );

              if (!isOwn) return chip;
              return GestureDetector(
                onTap: () => onToggleOwnReaction(reactionGroup.emoji),
                behavior: HitTestBehavior.opaque,
                child: chip,
              );
            },
          ),
      ],
    );
  }
}

class _GroupedReaction {
  const _GroupedReaction({
    required this.emoji,
    required this.members,
    required this.isOwn,
  });

  final String emoji;
  final List<MessageReaction> members;
  final bool isOwn;

  _GroupedReaction copyWith({
    String? emoji,
    List<MessageReaction>? members,
    bool? isOwn,
  }) {
    return _GroupedReaction(
      emoji: emoji ?? this.emoji,
      members: members ?? this.members,
      isOwn: isOwn ?? this.isOwn,
    );
  }
}

class _ReactionAvatarStrip extends StatelessWidget {
  const _ReactionAvatarStrip({required this.reactions});

  final List<MessageReaction> reactions;

  @override
  Widget build(BuildContext context) {
    final visible = reactions.take(3).toList();
    final width = 12 + (visible.length - 1) * 10;
    return SizedBox(
      width: width.toDouble(),
      height: 14,
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          for (var index = 0; index < visible.length; index++)
            Positioned(
              left: index * 10,
              child: _ReactionAvatar(
                avatarPath: visible[index].actorAvatarPath,
                actorName: visible[index].actorName,
                profileId: visible[index].profileId,
              ),
            ),
        ],
      ),
    );
  }
}

class _ReactionEmojiLottie extends StatefulWidget {
  const _ReactionEmojiLottie({
    required this.emoji,
    required this.size,
    this.playToken,
  });

  final String emoji;
  final double size;
  final int? playToken;

  @override
  State<_ReactionEmojiLottie> createState() => _ReactionEmojiLottieState();
}

class _ReactionEmojiLottieState extends State<_ReactionEmojiLottie>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  File? _file;
  int _loadGeneration = 0;
  int? _lastHandledToken;
  ({double min, double max}) _segment = (min: 0.0, max: 1.0);

  void _loadEmojiFile(String emoji) {
    final currentGeneration = ++_loadGeneration;
    final codepoint = _notoCodepoints[emoji];
    if (codepoint != null && _notoFileCache.containsKey(codepoint)) {
      _file = _notoFileCache[codepoint];
      return;
    }

    _file = null;
    _loadNotoLottieFile(emoji).then((file) {
      if (!mounted || currentGeneration != _loadGeneration) return;
      if (widget.emoji != emoji) return;
      setState(() {
        _file = file;
      });
    });
  }

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this)
      ..addStatusListener((status) {
        if (status == AnimationStatus.completed && mounted) {
          _controller.value = _segment.min;
        }
      });
    _loadEmojiFile(widget.emoji);
    // A chip can MOUNT with its play token already assigned (fresh chip for a
    // just-arrived reaction). didUpdateWidget never fires for the first build
    // and _onCompositionLoaded never fires for a non-catalog emoji (glyph
    // fallback) — so handle the initial token here or the pop is silently
    // skipped for exactly those chips.
    if (widget.playToken != null) {
      _lastHandledToken = widget.playToken;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _playOnce();
      });
    }
  }

  @override
  void didUpdateWidget(covariant _ReactionEmojiLottie oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.emoji != widget.emoji) {
      _lastHandledToken = null;
      _controller
        ..stop()
        ..value = 0.0;
      setState(() {
        _file = null;
      });
      _loadEmojiFile(widget.emoji);
      return;
    }
    if (widget.playToken != null && widget.playToken != _lastHandledToken) {
      _lastHandledToken = widget.playToken;
      _playOnce();
    }
  }

  void _onCompositionLoaded(LottieComposition composition) {
    _segment = (min: 0.0, max: 1.0);

    if (widget.playToken != null && widget.playToken != _lastHandledToken) {
      _lastHandledToken = widget.playToken;
      _playOnce();
    } else if (!_controller.isAnimating) {
      // Never reset a pop that is already in flight (started before the
      // composition finished loading) — that visibly killed the animation.
      _controller
        ..stop()
        ..value = _segment.min;
    }
  }

  void _playOnce() {
    _controller
      ..stop()
      ..value = _segment.min;
    final duration = Duration(
      milliseconds: (2833 * (_segment.max - _segment.min)).round().clamp(
        1500,
        3200,
      ),
    );
    unawaited(
      _controller.animateTo(
        _segment.max,
        duration: duration,
        curve: Curves.easeOutCubic,
      ),
    );
  }

  double _currentPopScale() {
    if (!_controller.isAnimating) {
      return 1.0;
    }
    final span = _segment.max - _segment.min;
    if (span <= 0.0001) {
      return 1.0;
    }
    final progress = ((_controller.value - _segment.min) / span).clamp(
      0.0,
      1.0,
    );
    if (progress <= 0.12) {
      final burst = Curves.easeOutBack.transform(
        (progress / 0.12).clamp(0.0, 1.0),
      );
      return lerpDouble(1.0, 2.75, burst) ?? 1.0;
    }
    if (progress <= 0.76) {
      final hold = Curves.easeInOut.transform(
        ((progress - 0.12) / 0.64).clamp(0.0, 1.0),
      );
      return lerpDouble(2.75, 2.25, hold) ?? 2.25;
    }
    final settle = Curves.easeOutCubic.transform(
      ((progress - 0.76) / 0.24).clamp(0.0, 1.0),
    );
    return lerpDouble(2.25, 1.0, settle) ?? 1.0;
  }

  double _currentPopLift() {
    if (!_controller.isAnimating) {
      return 0.0;
    }
    final span = _segment.max - _segment.min;
    if (span <= 0.0001) {
      return 0.0;
    }
    final progress = ((_controller.value - _segment.min) / span).clamp(
      0.0,
      1.0,
    );
    final maxLift = -widget.size * 0.62;
    if (progress <= 0.12) {
      final burst = Curves.easeOutBack.transform(
        (progress / 0.12).clamp(0.0, 1.0),
      );
      return lerpDouble(0.0, maxLift, burst) ?? 0.0;
    }
    if (progress <= 0.78) {
      final hover = Curves.easeInOut.transform(
        ((progress - 0.12) / 0.66).clamp(0.0, 1.0),
      );
      return lerpDouble(maxLift, maxLift * 0.82, hover) ?? (maxLift * 0.82);
    }
    final settle = Curves.easeOutCubic.transform(
      ((progress - 0.78) / 0.22).clamp(0.0, 1.0),
    );
    return lerpDouble(maxLift * 0.82, 0.0, settle) ?? 0.0;
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final file = _file;
    // Bundled cookie Lottie ONLY for the emoji that actually have one (the mood
    // reactions). For any other reaction (a custom emoji picked from the full
    // grid) DON'T fall back to the generic mood-selector — that made several
    // distinct custom reactions all render as the same smiley ("3 smileys").
    // Those show the real emoji glyph instead.
    final bundledAsset = _reactionAssetByEmoji[widget.emoji];
    final Widget? animated = file != null
        ? Lottie.file(
            file,
            controller: _controller,
            animate: false,
            repeat: false,
            fit: BoxFit.contain,
            onLoaded: _onCompositionLoaded,
            errorBuilder: (context, _, __) => _fallback(),
          )
        : (bundledAsset != null
              ? Lottie.asset(
                  bundledAsset,
                  controller: _controller,
                  animate: false,
                  repeat: false,
                  fit: BoxFit.contain,
                  onLoaded: _onCompositionLoaded,
                  errorBuilder: (context, _, __) => _fallback(),
                )
              : null);
    return SizedBox(
      width: widget.size,
      height: widget.size,
      child: AnimatedBuilder(
        animation: _controller,
        builder: (context, child) {
          // Static glyph base UNDER the Lottie: a handful of reaction
          // animations land on a transparent frame during the pop, which
          // made the reaction vanish once set. Shown only while the
          // controller is at rest (not actively animating) — during the
          // pop itself the Lottie is the sole visible layer, avoiding the
          // double-emoji look; once settled, the static glyph is the
          // safety net against a transparent resting frame.
          final Widget emojiWidget = animated == null
              ? _fallback()
              : (_controller.isAnimating
                    ? animated
                    : Stack(
                        alignment: Alignment.center,
                        children: [
                          Positioned.fill(child: Center(child: _fallback())),
                          animated,
                        ],
                      ));
          return Transform.translate(
            offset: Offset(0, _currentPopLift()),
            child: Transform.scale(
              scale: _currentPopScale(),
              alignment: Alignment.center,
              child: emojiWidget,
            ),
          );
        },
      ),
    );
  }

  Widget _fallback() => Text(
    widget.emoji,
    style: TextStyle(
      fontSize: widget.size * 0.8,
      // Missing-glyph codepoints fall back to the platform colour-emoji font
      // instead of a tofu cross (also used as the static base above).
      fontFamilyFallback: kEmojiFontFallback,
    ),
    textAlign: TextAlign.center,
  );
}

/// Animated emoji widget backed by the Noto Emoji Animation CDN.
/// Downloads the Lottie JSON once, caches it in the app's temp directory,
/// and plays it looped. Falls back to a plain emoji text while loading.
/// How a [_NotoEmojiLottie] animation should play.
enum _NotoLottieMode {
  /// Static first frame — emits no animation ticks (emoji picker grid).
  preview,

  /// Plays once on mount (or when the widget key changes); does not loop.
  once,

  /// Loops forever — used in the quick-reaction bar.
  looping,
}

// ─── GIF picker view ─────────────────────────────────────────────────────────

class _GifPickerView extends StatefulWidget {
  const _GifPickerView({
    required this.onPick,
    required this.controller,
    this.bottomInset = 0,
  });
  final ValueChanged<_GifItem> onPick;

  /// Нужен ради недавних: они лежат в шифрованной базе профиля.
  final AppController controller;
  final double bottomInset;

  @override
  State<_GifPickerView> createState() => _GifPickerViewState();
}

class _GifPickerViewState extends State<_GifPickerView> {
  final ScrollController _scroll = ScrollController();
  final TextEditingController _search = TextEditingController();

  List<_GifItem> _gifs = <_GifItem>[];
  List<RecentGif> _recents = const <RecentGif>[];

  /// Нажатая иконка категории, если нажата.
  int? _activeCategory;

  bool _loadingFirst = true;
  bool _loadingMore = false;
  bool _failed = false;
  bool _hasMore = false;

  /// Курсор GIPHY: сколько записей уже спросили.
  int _offset = 0;

  /// Слово и язык, которыми ДОБЫТА текущая выдача.
  ///
  /// 🔴 БЕЗ ЭТОГО ПОДГРУЗКА ЛОМАЕТСЯ. Человек ищет «кот», план превращает это в
  /// «cat» — и вторая страница обязана спрашивать «cat», а не «кот», иначе
  /// продолжение выдачи приезжает из другого поиска.
  String? _resolvedTerm;
  String _resolvedLang = 'en';

  /// Номер поколения запроса.
  ///
  /// Страница, приехавшая от старого запроса, не имеет права попасть в новую
  /// выдачу: человек набирает быстрее, чем отвечает сеть.
  int _seq = 0;

  Timer? _debounce;

  @override
  void initState() {
    super.initState();
    _scroll.addListener(_onScroll);
    unawaited(_loadFirst(null));
    unawaited(_loadRecents());
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _scroll.removeListener(_onScroll);
    _scroll.dispose();
    _search.dispose();
    super.dispose();
  }

  bool get _isSearching =>
      _activeCategory != null || _search.text.trim().isNotEmpty;

  Future<void> _loadRecents() async {
    final recents = await widget.controller.loadRecentGifs();
    if (!mounted) return;
    setState(() => _recents = recents);
  }

  void _onScroll() {
    if (_loadingFirst || _loadingMore || !_hasMore) return;
    if (!_scroll.hasClients) return;
    final pos = _scroll.position;
    if (pos.pixels < pos.maxScrollExtent - _gifPrefetchExtent) return;
    unawaited(_loadMore());
  }

  void _onQueryChanged(String value) {
    _debounce?.cancel();
    final q = value.trim();
    if (_activeCategory != null) {
      // Набранное слово важнее нажатой иконки: подсветка обязана уйти, иначе
      // человек видит выбранную категорию и результаты другого запроса.
      setState(() => _activeCategory = null);
    }
    _debounce = Timer(const Duration(milliseconds: 450), () {
      if (!mounted) return;
      unawaited(_loadFirst(q.isEmpty ? null : q));
    });
  }

  void _onCategoryTap(int index) {
    // Отклик на завершённое действие человека — по правилу Ш-3.
    HapticFeedback.selectionClick();
    _debounce?.cancel();
    final wasActive = _activeCategory == index;
    setState(() => _activeCategory = wasActive ? null : index);
    if (_search.text.isNotEmpty) {
      // Программная очистка не вызывает onChanged, так что подсветку она не
      // сбросит — это и нужно.
      _search.clear();
    }
    final category = wasActive ? null : kGifCategories[index];
    unawaited(_loadFirst(category?.query));
  }

  Future<void> _loadFirst(String? rawQuery) async {
    final seq = ++_seq;
    if (mounted) {
      setState(() {
        _loadingFirst = true;
        // Сбрасывается вместе с первой страницей: иначе застрявший признак от
        // отменённой подгрузки навсегда закрыл бы дорогу следующим страницам.
        _loadingMore = false;
        _failed = false;
        _gifs = <_GifItem>[];
        _hasMore = false;
        _offset = 0;
      });
    }

    final plan = gifQueryPlan(rawQuery ?? '');
    _GifPage page = _GifPage.empty;
    String? term;
    var lang = 'en';

    if (plan.isEmpty) {
      page = await _fetchGifPage(query: null, offset: 0);
      if (seq != _seq || !mounted) return;
    } else {
      for (final attempt in plan) {
        page = await _fetchGifPage(
          query: attempt.term,
          lang: attempt.lang,
          offset: 0,
        );
        if (seq != _seq || !mounted) return;
        term = attempt.term;
        lang = attempt.lang;
        // Нашлось — вторую попытку не делаем.
        if (page.items.isNotEmpty) break;
        // Нет связи — второй запрос тем же путём бессмыслен и только тратит
        // время человека.
        if (page.failed) break;
      }
    }

    setState(() {
      _gifs = page.items;
      _hasMore = page.hasMore && page.items.length < _gifMaxItems;
      _failed = page.failed;
      _loadingFirst = false;
      _offset = page.returned;
      _resolvedTerm = term;
      _resolvedLang = lang;
    });
  }

  Future<void> _loadMore() async {
    if (_loadingMore || !_hasMore) return;
    final seq = _seq;
    setState(() => _loadingMore = true);
    final page = await _fetchGifPage(
      query: _resolvedTerm,
      lang: _resolvedLang,
      offset: _offset,
    );
    if (seq != _seq || !mounted) return;
    setState(() {
      final before = _gifs.length;
      final merged = <_GifItem>[..._gifs];
      final seen = merged.map((g) => g.fullUrl).toSet();
      for (final item in page.items) {
        // GIPHY повторяет часть выдачи на границах страниц; без этого в сетке
        // появлялись бы одинаковые гифки.
        if (!seen.add(item.fullUrl)) continue;
        merged.add(item);
        if (merged.length >= _gifMaxItems) break;
      }
      _gifs = merged;
      _offset += page.returned;
      // Страница целиком из повторов значит, что полезное кончилось. Без этой
      // остановки список выглядел бы застрявшим и продолжал слать запросы на
      // каждое движение пальца у дна.
      final progressed = merged.length > before;
      _hasMore =
          page.hasMore &&
          !page.failed &&
          progressed &&
          merged.length < _gifMaxItems;
      _loadingMore = false;
    });
  }

  void _pick(_GifItem gif) {
    // Запоминаем в момент выбора, а не после отправки. Так недавние не зависят
    // от пути отправки сообщения — а его трогать нельзя.
    unawaited(
      widget.controller.rememberPickedGif(
        previewUrl: gif.previewUrl,
        fullUrl: gif.fullUrl,
      ),
    );
    widget.onPick(gif);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final cs = theme.colorScheme;
    return Column(
      children: [
        _buildCategoryStrip(cs),
        // Minimal, thin search (no filled background) under the category strip.
        Padding(
          padding: const EdgeInsets.fromLTRB(18, 2, 18, 6),
          child: TextField(
            controller: _search,
            autofocus: false,
            textInputAction: TextInputAction.search,
            decoration: InputDecoration(
              hintText: chatText(context, ru: 'Поиск GIF', en: 'Search GIFs'),
              hintStyle: TextStyle(
                color: cs.onSurfaceVariant.withValues(alpha: 0.7),
                fontSize: 14.5,
              ),
              prefixIcon: Icon(
                Icons.search_rounded,
                size: 17,
                color: cs.onSurfaceVariant.withValues(alpha: 0.7),
              ),
              prefixIconConstraints: const BoxConstraints(
                minWidth: 30,
                minHeight: 30,
              ),
              isDense: true,
              isCollapsed: true,
              contentPadding: const EdgeInsets.only(top: 4, bottom: 4),
              border: InputBorder.none,
              enabledBorder: InputBorder.none,
              focusedBorder: InputBorder.none,
              filled: false,
            ),
            onChanged: _onQueryChanged,
          ),
        ),
        Expanded(child: _buildBody(theme, cs)),
        // GIPHY ToS: visible attribution is required wherever GIFs are shown.
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 2, 16, 8),
          child: Text(
            'Powered by GIPHY',
            style: TextStyle(
              fontSize: 10.5,
              letterSpacing: 0.6,
              fontWeight: FontWeight.w600,
              color: cs.onSurfaceVariant.withValues(alpha: 0.62),
            ),
          ),
        ),
      ],
    );
  }

  /// Полоса эмодзи-категорий над поиском.
  ///
  /// Иконки нарисованы обычным текстом, а не анимированными Noto: восемнадцать
  /// анимаций в постоянно видимой полосе — это ровно та нагрузка, от которой
  /// просили избавиться.
  Widget _buildCategoryStrip(ColorScheme cs) {
    return SizedBox(
      height: 40,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        physics: secretlyListPhysics(),
        // Справа оставлено место под ✕ листа, чтобы иконки не уезжали под него.
        padding: const EdgeInsets.only(left: 12, right: 46),
        itemCount: kGifCategories.length,
        separatorBuilder: (_, _) => const SizedBox(width: 2),
        itemBuilder: (context, i) {
          final category = kGifCategories[i];
          final active = _activeCategory == i;
          return Semantics(
            button: true,
            selected: active,
            label: chatText(context, ru: category.ru, en: category.en),
            child: Material(
              color: Colors.transparent,
              child: InkWell(
                customBorder: const CircleBorder(),
                onTap: () => _onCategoryTap(i),
                child: Container(
                  width: 40,
                  height: 40,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: active
                        ? cs.primary.withValues(alpha: 0.16)
                        : Colors.transparent,
                  ),
                  child: Text(
                    category.emoji,
                    // Чуть больше ✕ справа (у того 20).
                    style: const TextStyle(fontSize: 23, height: 1.05),
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );
  }

  Widget _sectionHeader(ThemeData theme, ColorScheme cs, String label) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(18, 10, 18, 6),
      child: Text(
        label,
        style: theme.textTheme.labelMedium?.copyWith(
          color: cs.onSurfaceVariant,
          fontWeight: FontWeight.w700,
          letterSpacing: 0.3,
        ),
      ),
    );
  }

  Widget _buildBody(ThemeData theme, ColorScheme cs) {
    if (_loadingFirst && _gifs.isEmpty) {
      return const Center(child: CircularProgressIndicator());
    }

    final showRecents = _recents.isNotEmpty && !_isSearching;

    if (_gifs.isEmpty && !showRecents) {
      return Center(child: _emptyState(cs));
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        final crossAxisCount = constraints.maxWidth >= 520 ? 3 : 2;
        final grid = SliverGridDelegateWithFixedCrossAxisCount(
          crossAxisCount: crossAxisCount,
          crossAxisSpacing: 8,
          mainAxisSpacing: 8,
          childAspectRatio: 1.45,
        );
        return CustomScrollView(
          controller: _scroll,
          physics: secretlyListPhysics(),
          slivers: <Widget>[
            if (showRecents) ...<Widget>[
              SliverToBoxAdapter(
                child: _sectionHeader(
                  theme,
                  cs,
                  chatText(context, ru: 'Недавние', en: 'Recent'),
                ),
              ),
              SliverPadding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                sliver: SliverGrid(
                  gridDelegate: grid,
                  delegate: SliverChildBuilderDelegate(
                    (_, i) {
                      final recent = _recents[i];
                      return _gifTile(
                        cs,
                        _GifItem(
                          previewUrl: recent.previewUrl,
                          fullUrl: recent.fullUrl,
                        ),
                      );
                    },
                    childCount: _recents.length,
                    addAutomaticKeepAlives: false,
                  ),
                ),
              ),
            ],
            if (_gifs.isNotEmpty) ...<Widget>[
              if (showRecents)
                SliverToBoxAdapter(
                  child: _sectionHeader(
                    theme,
                    cs,
                    chatText(context, ru: 'Популярное', en: 'Trending'),
                  ),
                ),
              SliverPadding(
                padding: EdgeInsets.fromLTRB(16, showRecents ? 0 : 2, 16, 0),
                sliver: SliverGrid(
                  gridDelegate: grid,
                  delegate: SliverChildBuilderDelegate(
                    (_, i) => _gifTile(cs, _gifs[i]),
                    childCount: _gifs.length,
                    // Уехавшие вверх плитки не держим живыми: анимированная
                    // картинка, оставленная в дереве, продолжает стоить памяти.
                    addAutomaticKeepAlives: false,
                  ),
                ),
              ),
            ],
            if (_loadingMore)
              const SliverToBoxAdapter(
                child: Padding(
                  padding: EdgeInsets.symmetric(vertical: 14),
                  child: Center(
                    child: SizedBox(
                      width: 22,
                      height: 22,
                      child: CircularProgressIndicator(strokeWidth: 2.1),
                    ),
                  ),
                ),
              ),
            SliverToBoxAdapter(
              child: SizedBox(height: 16 + widget.bottomInset),
            ),
          ],
        );
      },
    );
  }

  /// Пустая выдача и обрыв связи выглядят по-разному — это разные причины.
  Widget _emptyState(ColorScheme cs) {
    final failed = _failed;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Icon(
          failed ? Icons.wifi_off_rounded : Icons.gif_box_outlined,
          size: 40,
          color: cs.outline,
        ),
        const SizedBox(height: 8),
        Text(
          failed
              ? chatText(context, ru: 'Нет связи', en: 'No connection')
              : chatText(context, ru: 'GIF не найдены', en: 'No GIFs found'),
          style: TextStyle(color: cs.outline),
        ),
        if (failed) ...<Widget>[
          const SizedBox(height: 6),
          TextButton(
            onPressed: () {
              final q = _search.text.trim();
              final category = _activeCategory == null
                  ? null
                  : kGifCategories[_activeCategory!].query;
              unawaited(_loadFirst(q.isNotEmpty ? q : category));
            },
            child: Text(chatText(context, ru: 'Повторить', en: 'Retry')),
          ),
        ],
      ],
    );
  }

  Widget _gifTile(ColorScheme cs, _GifItem gif) {
    return Material(
      color: Colors.transparent,
      child: InkWell(
        borderRadius: BorderRadius.circular(20),
        onTap: () => _pick(gif),
        child: Ink(
          decoration: BoxDecoration(
            color: cs.surface.withValues(alpha: 0.22),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(
              color: cs.outlineVariant.withValues(alpha: 0.18),
            ),
          ),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(20),
            child: Image.network(
              // Превьюшка GIPHY и так узкая (~200 px), поэтому cacheWidth здесь
              // не ставится: он бы не уменьшил, а РАСТЯНУЛ картинку до размера
              // плитки и съел памяти больше, а не меньше.
              gif.previewUrl,
              fit: BoxFit.cover,
              loadingBuilder: (_, child, progress) {
                if (progress == null) return child;
                return ColoredBox(
                  color: cs.surface.withValues(alpha: 0.28),
                  child: const Center(
                    child: CircularProgressIndicator(strokeWidth: 2),
                  ),
                );
              },
              errorBuilder: (_, _, _) => ColoredBox(
                color: cs.surface.withValues(alpha: 0.28),
                child: Icon(Icons.gif_box_outlined, color: cs.outline),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _NotoEmojiLottie extends StatefulWidget {
  const _NotoEmojiLottie({
    super.key,
    required this.emoji,
    this.size = 44.0,
    this.mode = _NotoLottieMode.looping,
    this.assetFallback,
  });

  final String emoji;
  final double size;
  final _NotoLottieMode mode;

  /// Optional BUNDLED Lottie asset shown while the Noto CDN file is loading or
  /// if it fails — so reaction emoji never fall back to a system-font glyph that
  /// can render as tofu (□). When null the fallback is plain emoji text (correct
  /// for arbitrary in-message emoji, which have no bundled asset).
  final String? assetFallback;

  @override
  State<_NotoEmojiLottie> createState() => _NotoEmojiLottieState();
}

/// Process-unique counter used to mint a stable, globally-unique key for each
/// looping [_NotoEmojiLottie]'s [VisibilityDetector]. (VisibilityDetector
/// requires a unique key per instance.)
int _notoLottieVisibilitySeq = 0;

class _NotoEmojiLottieState extends State<_NotoEmojiLottie>
    with SingleTickerProviderStateMixin {
  File? _file;
  AnimationController? _ctrl;
  int _loadGeneration = 0;

  /// INVISIBLE perf: for [_NotoLottieMode.looping] only — when the emoji is
  /// scrolled off-screen we set `animate: false`, which stops Lottie's internal
  /// looping AnimationController so no ticks fire off-screen. On-screen the
  /// render path is byte-identical to `Lottie.file(repeat: true)` (animate
  /// defaults to true). VisibilityDetector's 500 ms debounce means this never
  /// thrashes during a fling and never freezes an on-screen emoji.
  bool _onScreen = true;

  /// Stable unique key for the VisibilityDetector, minted once per state.
  late final Key _visibilityKey = ValueKey(
    'noto-emoji-vis-${_notoLottieVisibilitySeq++}',
  );

  void _onVisibilityChanged(VisibilityInfo info) {
    if (!mounted) return;
    final visible = info.visibleFraction > 0;
    if (visible != _onScreen) {
      setState(() => _onScreen = visible);
      // Looping: pause the controller off-screen (perf) and resume the
      // tail-trimmed loop on-screen.
      if (widget.mode == _NotoLottieMode.looping) {
        final c = _ctrl;
        if (c != null && c.duration != null) {
          if (visible) {
            _startNotoLoop(c);
          } else {
            c.stop();
          }
        }
      }
    }
  }

  /// Repeats [c] over `[0, 0.97]` so the transparent FINAL frame some Noto Lottie
  /// JSONs ship is never shown — that frame is what made the looping emoji blink
  /// out once per cycle. The shortened period keeps the original playback speed.
  void _startNotoLoop(AnimationController c) {
    final d = c.duration;
    if (d == null) return;
    // Loop over [0.01, 0.97]: trim BOTH the transparent final frame (0.97, the
    // original blink-per-cycle fix) AND the transparent FIRST frame (0.01) that
    // some Noto JSONs ship — landing on frame 0 at the loop wrap-around made a
    // handful of emoji blink out at the end of each cycle. Period scaled to the
    // 0.96-wide range so playback speed is unchanged.
    c.repeat(min: 0.01, max: 0.97, period: d * 0.96);
  }

  void _loadEmojiFile(String emoji) {
    final currentGeneration = ++_loadGeneration;
    final codepoint = _notoCodepoints[emoji];
    if (codepoint != null && _notoFileCache.containsKey(codepoint)) {
      _file = _notoFileCache[codepoint];
      return;
    }

    _file = null;
    _loadNotoLottieFile(emoji).then((f) {
      if (!mounted || currentGeneration != _loadGeneration) return;
      if (widget.emoji != emoji) return;
      setState(() => _file = f);
    });
  }

  @override
  void initState() {
    super.initState();
    if (widget.mode == _NotoLottieMode.once) {
      // Default 2 s duration — onLoaded will correct it to the real duration.
      _ctrl =
          AnimationController(vsync: this, duration: const Duration(seconds: 2))
            ..addStatusListener((status) {
              // Snap back near the first frame after the animation finishes.
              // Some Noto Lottie JSONs have a transparent last frame (reaching
              // 1.0 made the emoji disappear) AND a transparent first frame
              // (0.0) — so snap to 0.01, a frame that is visible for both
              // styles, instead of a possibly-blank frame 0.
              if (status == AnimationStatus.completed && mounted) {
                _ctrl!.value = 0.01;
              }
            });
    } else if (widget.mode == _NotoLottieMode.looping) {
      // Looping drives its own controller so it can loop a sub-range that
      // EXCLUDES the transparent final frame some Noto JSONs ship — otherwise
      // the emoji blinks out for one frame on every loop. Real duration is set
      // in onLoaded; the loop is (re)started by [_startNotoLoop].
      _ctrl = AnimationController(
        vsync: this,
        duration: const Duration(seconds: 2),
      );
    }
    _loadEmojiFile(widget.emoji);
  }

  @override
  void didUpdateWidget(covariant _NotoEmojiLottie oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.emoji != widget.emoji) {
      setState(() => _file = null);
      _ctrl?.reset();
      _loadEmojiFile(widget.emoji);
      return;
    }
    if (oldWidget.mode != widget.mode && widget.mode == _NotoLottieMode.once) {
      _ctrl?.reset();
    }
  }

  @override
  void dispose() {
    _ctrl?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final f = _file;
    if (f == null) return _fallback();
    switch (widget.mode) {
      case _NotoLottieMode.preview:
        return RepaintBoundary(
          child: SizedBox(
            width: widget.size,
            height: widget.size,
            child: Lottie.file(
              f,
              width: widget.size,
              height: widget.size,
              animate: false,
              fit: BoxFit.contain,
              errorBuilder: (_, __, ___) => _fallback(),
            ),
          ),
        );
      case _NotoLottieMode.once:
        final ctrl = _ctrl!;
        // No static glyph layered underneath (that duplicated the emoji —
        // visible statically AND animated at once — for the vast majority
        // of frames, which are opaque). Matches the desktop implementation
        // (noto_emoji_lottie.dart), which never had this overlay and has no
        // reported transparent-frame blink issue.
        return RepaintBoundary(
          child: SizedBox(
            width: widget.size,
            height: widget.size,
            child: Lottie.file(
              f,
              width: widget.size,
              height: widget.size,
              controller: ctrl,
              onLoaded: (comp) {
                ctrl.duration = comp.duration;
                if (ctrl.status == AnimationStatus.dismissed) {
                  ctrl.forward();
                }
              },
              fit: BoxFit.contain,
              errorBuilder: (_, __, ___) => _fallback(),
            ),
          ),
        );
      case _NotoLottieMode.looping:
        final ctrl = _ctrl!;
        // RepaintBoundary isolates this animation's repaints; VisibilityDetector
        // pauses the controller off-screen (perf). The controller loops
        // [0, 0.97] (see [_startNotoLoop]) so the transparent final frame is
        // never shown. No static glyph underneath — see the once-mode note.
        return RepaintBoundary(
          child: VisibilityDetector(
            key: _visibilityKey,
            onVisibilityChanged: _onVisibilityChanged,
            child: SizedBox(
              width: widget.size,
              height: widget.size,
              child: Lottie.file(
                f,
                width: widget.size,
                height: widget.size,
                controller: ctrl,
                onLoaded: (comp) {
                  ctrl.duration = comp.duration;
                  if (_onScreen && !ctrl.isAnimating) _startNotoLoop(ctrl);
                },
                fit: BoxFit.contain,
                errorBuilder: (_, __, ___) => _fallback(),
              ),
            ),
          ),
        );
    }
  }

  Widget _fallback() {
    final asset = widget.assetFallback;
    if (asset != null) {
      // Bundled Lottie (e.g. a reaction cookie) — always present, so the emoji
      // shows instantly and never as tofu while the Noto CDN file resolves.
      return SizedBox(
        width: widget.size,
        height: widget.size,
        child: Lottie.asset(
          asset,
          width: widget.size,
          height: widget.size,
          fit: BoxFit.contain,
          errorBuilder: (_, __, ___) => _textFallback(),
        ),
      );
    }
    return _textFallback();
  }

  Widget _textFallback() => SizedBox(
    width: widget.size,
    height: widget.size,
    child: Center(
      child: Text(
        widget.emoji,
        style: TextStyle(
          fontSize: widget.size * 0.72,
          // Route any glyph the active UI font lacks to the platform colour-
          // emoji font instead of a tofu box (.notdef / crossed rectangle).
          // Fixes emoji that rendered as a cross on ROMs whose system font
          // (e.g. MiSans on MIUI) does not carry the codepoint.
          fontFamilyFallback: kEmojiFontFallback,
        ),
        textAlign: TextAlign.center,
      ),
    ),
  );
}

/// Platform colour-emoji font fallback list. Used everywhere a raw emoji glyph
/// is rendered as text, so a codepoint missing from the active UI font falls
/// back to the OS emoji font (Apple Color Emoji on iOS, Noto Color Emoji on
/// Android) instead of showing a tofu box.
const List<String> kEmojiFontFallback = <String>[
  // 'Apple Color Emoji' is intentionally OMITTED. Listing it in
  // fontFamilyFallback made the SPACE (U+0020) resolve to the emoji font on
  // iOS/macOS, which has a very wide space advance → "huge spaces" in every
  // message bubble AND text field (iOS-only; Android used Noto and was fine).
  // Apple platforms render colour emoji via the system font cascade WITHOUT an
  // explicit fallback, so dropping it keeps emoji working and fixes the spaces.
  // This list is effectively a no-op on iOS now (these fonts don't exist there)
  // and still routes Android/Linux emoji to Noto.
  'Noto Color Emoji',
  'NotoColorEmoji',
];

class _ReactionAvatar extends StatelessWidget {
  const _ReactionAvatar({
    required this.avatarPath,
    required this.actorName,
    required this.profileId,
  });

  final String? avatarPath;
  final String? actorName;
  final String profileId;

  @override
  Widget build(BuildContext context) {
    final hasAvatar =
        avatarPath != null &&
        avatarPath!.isNotEmpty &&
        File(avatarPath!).existsSync();
    if (hasAvatar) {
      return CircleAvatar(
        radius: 7,
        backgroundImage: FileImage(File(avatarPath!)),
      );
    }
    final name = actorName?.trim() ?? '';
    final fallbackId = profileId.trim();
    // Ключ цвета — профиль, как у портрета человека в списке и в профиле:
    // по имени тот же человек выходил в реакции другого цвета (17.09.2026).
    final seed = fallbackId.isNotEmpty
        ? fallbackId
        : (name.isNotEmpty ? name : 'reaction');
    return AvatarInitials.fallbackBubble(
      context: context,
      radius: 7,
      seed: seed,
      displayName: name,
      fallbackId: fallbackId.isEmpty ? seed : fallbackId,
      labelStyle: Theme.of(context).textTheme.labelSmall?.copyWith(fontSize: 7),
    );
  }
}

