/// Telegram-style floating day chip shown while the timeline scrolls: it names
/// the day of the messages currently at the top of the viewport and fades out
/// once scrolling settles. Unlike the inline separator it DOES carry a soft
/// plate — it floats over the bubbles, so it needs to stay legible against
/// whatever scrolls beneath it.
class _ChatFloatingDayChip extends StatelessWidget {
  const _ChatFloatingDayChip({required this.timestampMs});

  final int timestampMs;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final label = _chatDayLabel(context, timestampMs);
    return ClipRRect(
      borderRadius: BorderRadius.circular(999),
      child: BackdropFilter(
