/// Day label shared by the inline separator and the floating chip, so a date
/// can never read one way in one place and another way in the other.
String _chatDayLabel(BuildContext context, int timestampMs) {
  final date = DateTime.fromMillisecondsSinceEpoch(timestampMs);
  final day = DateTime(date.year, date.month, date.day);
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);
  if (day == today) {
    return chatText(
      context,
      ru: 'Сегодня',
      en: 'Today',
      uk: 'Сьогодні',
      es: 'Hoy',
      pt: 'Hoje',
      fr: "Aujourd'hui",
      de: 'Heute',
    );
  }
  if (day == today.subtract(const Duration(days: 1))) {
    return chatText(
      context,
      ru: 'Вчера',
      en: 'Yesterday',
      uk: 'Учора',
      es: 'Ayer',
      pt: 'Ontem',
      fr: 'Hier',
      de: 'Gestern',
    );
  }
  // Locale-aware via MaterialLocalizations — no hand-rolled month tables to
  // keep in sync with the app's languages. The year only shows when it isn't
  // the current one, so the common case stays short.
  final base = MaterialLocalizations.of(context).formatMediumDate(day);
  return day.year == today.year ? base : '$base, ${day.year}';
}

/// Renders a bubble's status slot: a plain label, or — when the string carries
/// [_kReadReceiptMarker] — a small eye followed by the read count, with the word
/// dropped. The icon inherits the label's own colour, so every bubble type keeps
/// whatever tint it already passed.
Widget _buildBubbleStatusSlot(String statusText, TextStyle? style) {
  if (!statusText.startsWith(_kReadReceiptMarker)) {
    return Text(statusText, style: style);
  }
  final count = statusText.substring(_kReadReceiptMarker.length);
  return Row(
    mainAxisSize: MainAxisSize.min,
    children: [
      Icon(FluentIcons.eye_16_regular, size: 12, color: style?.color),
      const SizedBox(width: 3),
      Text(count, style: style),
    ],
  );
}

/// Quiet day marker between messages from different calendar days.
///
/// Deliberately plain: centred, silver-grey, no plate/pill/divider rules and no
/// display face — it is a structural marker, so it must recede against any
/// wallpaper instead of competing with the bubbles. Rendered as part of the
/// first row of each day (see the timeline itemBuilder) rather than as its own
/// list item, so row indices stay stable.
class _ChatDateSeparator extends StatelessWidget {
  const _ChatDateSeparator({required this.timestampMs});

  final int timestampMs;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    // "Silver": neutral, low-contrast grey that stays legible on both light and
    // dark wallpapers without reading as a bubble.
    final color = isDark
        ? const Color(0xFFC2C8D0).withValues(alpha: 0.80)
        : const Color(0xFF6B7280).withValues(alpha: 0.75);
    return Padding(
      padding: const EdgeInsets.only(top: 14, bottom: 8),
      child: Center(
        child: Text(
          _chatDayLabel(context, timestampMs),
          textAlign: TextAlign.center,
          style: TextStyle(
            fontSize: 12,
            height: 1.0,
            fontWeight: FontWeight.w500,
            letterSpacing: 0.3,
            color: color,
          ),
        ),
      ),
    );
  }
}

class _PinnedMessage {
  const _PinnedMessage({
    required this.eventId,
    required this.previewText,
    required this.pinnedAtMs,
  });

  final String eventId;
  final String previewText;
  final int pinnedAtMs;

  Map<String, Object> toJson() => <String, Object>{
    'eventId': eventId,
    'previewText': previewText,
    'pinnedAtMs': pinnedAtMs,
  };

  static _PinnedMessage? fromJson(Object? raw) {
    if (raw is! Map) return null;
    final eventId = (raw['eventId'] as String?)?.trim() ?? '';
    if (eventId.isEmpty) return null;
    final previewText = (raw['previewText'] as String?)?.trim() ?? '';
    final pinnedAtMs = raw['pinnedAtMs'] is int
        ? raw['pinnedAtMs'] as int
        : int.tryParse('${raw['pinnedAtMs']}') ?? 0;
    return _PinnedMessage(
      eventId: eventId,
      previewText: previewText,
      pinnedAtMs: pinnedAtMs,
    );
  }
}

