class _SelectableEventWrapper extends StatefulWidget {
  const _SelectableEventWrapper({
    required this.selectionMode,
    required this.selected,
    required this.onTap,
    required this.onDoubleTap,
    required this.onLongPress,
    required this.child,
  });

  final bool selectionMode;
  final bool selected;

  /// Single-tap handler. `null` means the *child* owns single-tap (e.g. a video
  /// note that enlarges + unmutes on tap) — the wrapper then forwards taps only
  /// while in selection mode (to toggle), and otherwise lets the gesture fall
  /// through to the child. Long-press / double-tap are unaffected.
  final ValueChanged<Offset?>? onTap;
  final VoidCallback onDoubleTap;
  final VoidCallback onLongPress;
  final Widget child;

  @override
  State<_SelectableEventWrapper> createState() =>
      _SelectableEventWrapperState();
}

class _SelectableEventWrapperState extends State<_SelectableEventWrapper> {
  Offset? _lastTapPosition;
  final GlobalKey _interactiveChildKey = GlobalKey();

  bool _isInteractiveChildHit(Offset? globalPosition) {
    if (widget.selectionMode) return true;
    if (globalPosition == null) return false;
    final renderObject = _interactiveChildKey.currentContext
        ?.findRenderObject();
    if (renderObject is! RenderBox || !renderObject.hasSize) return false;
    final localPosition = renderObject.globalToLocal(globalPosition);
    return renderObject.hitTest(BoxHitTestResult(), position: localPosition);
  }

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    // When the child owns single-tap (onTap == null) and we're NOT selecting,
    // don't register a competing onTap so the gesture reaches the child's own
    // GestureDetector (e.g. video-note tap-to-enlarge-with-sound). Long-press
    // (context menu) and double-tap (❤️) still go through this wrapper.
    final bool childOwnsTap = widget.onTap == null;
    final bool wrapperHandlesTap = !childOwnsTap || widget.selectionMode;
    return GestureDetector(
      behavior: HitTestBehavior.translucent,
      onTapDown: (details) {
        _lastTapPosition = details.globalPosition;
      },
      onDoubleTapDown: (details) {
        _lastTapPosition = details.globalPosition;
      },
      onTap: wrapperHandlesTap
          ? () {
              if (!_isInteractiveChildHit(_lastTapPosition)) {
                FocusManager.instance.primaryFocus?.unfocus();
                return;
              }
              final tap = widget.onTap;
              if (tap != null) {
                tap(_lastTapPosition);
              }
            }
          : null,
      onDoubleTap: () {
        if (!_isInteractiveChildHit(_lastTapPosition)) return;
        widget.onDoubleTap();
      },
      onLongPress: widget.onLongPress,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          AnimatedContainer(
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOut,
            width: widget.selectionMode ? 34 : 0,
            padding: EdgeInsets.only(
              left: widget.selectionMode ? 8 : 0,
              top: 14,
            ),
            child: AnimatedOpacity(
              duration: const Duration(milliseconds: 140),
              opacity: widget.selectionMode ? 1 : 0,
              child: AnimatedScale(
                duration: const Duration(milliseconds: 160),
                scale: widget.selectionMode ? 1 : 0.8,
                child: Container(
                  width: 20,
                  height: 20,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: widget.selected ? Colors.green : Colors.transparent,
                    border: Border.all(
                      color: widget.selected
                          ? Colors.green
                          : cs.outline.withValues(alpha: 0.55),
                      width: 2,
                    ),
                  ),
                  child: widget.selected
                      ? const Icon(
                          AppIcons.check,
                          size: 13,
                          color: Colors.white,
                        )
                      : null,
                ),
              ),
            ),
          ),
          Expanded(
            child: AbsorbPointer(
              absorbing: widget.selectionMode,
              child: KeyedSubtree(
                key: _interactiveChildKey,
                child: widget.child,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _ReplySwipeWrapperState extends State<_ReplySwipeWrapper>
    with SingleTickerProviderStateMixin {
  static const double _maxShift = 78;
  static const double _triggerShift = 48;
  // Light dead zone before the bubble starts following the finger (so a vertical
  // scroll's horizontal wobble doesn't open a reply), then move at half the
  // finger speed so the swipe is deliberate (2× slower than the finger).
  static const double _kReplyDeadZone = 12;
  static const double _kReplyDampFactor = 0.5;
  double _dx = 0;
  double _rawDx = 0;
  bool _armed = false;
  late final AnimationController _springCtrl;

  @override
  void initState() {
    super.initState();
    _springCtrl = AnimationController.unbounded(vsync: this)
      ..addListener(() {
        setState(() {
          _dx = _springCtrl.value;
        });
      });
  }

  @override
  void dispose() {
    _springCtrl.dispose();
    super.dispose();
  }

  void _springBack() {
    final sim = SpringSimulation(
      const SpringDescription(mass: 1, stiffness: 500, damping: 30),
      _dx,
      0,
      0,
    );
    _springCtrl.animateWith(sim);
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.enabled || widget.onReplySwipe == null) return widget.child;
    final reveal = (_dx.abs() / _maxShift).clamp(0.0, 1.0);

    return GestureDetector(
      behavior: HitTestBehavior.translucent,
      onHorizontalDragStart: (_) {
        _springCtrl.stop();
        _rawDx = 0;
        _armed = false;
      },
      onHorizontalDragUpdate: (details) {
        _springCtrl.stop();
        _rawDx += details.delta.dx;
        // Apply the dead zone, then move at half the finger distance (damped).
        final past = (_rawDx + _kReplyDeadZone).clamp(
          double.negativeInfinity,
          0.0,
        );
        final next = (past * _kReplyDampFactor).clamp(-_maxShift, 0.0);
        if (next == _dx) return;
        setState(() {
          _dx = next;
        });
        // Haptic the moment the reply threshold is reached (armed), once.
        final armed = _dx <= -_triggerShift;
        if (armed && !_armed) HapticFeedback.lightImpact();
        _armed = armed;
      },
      onHorizontalDragEnd: (details) {
        final velocity = details.primaryVelocity ?? 0;
        final shouldReply = _dx <= -_triggerShift || velocity < -220;
        if (shouldReply) {
          // Fast flick can trigger reply without crossing the threshold during
          // the drag — give the haptic then so it always fires once.
          if (!_armed) HapticFeedback.lightImpact();
          widget.onReplySwipe!.call();
        }
        _rawDx = 0;
        _armed = false;
        _springBack();
      },
      onHorizontalDragCancel: () {
        _rawDx = 0;
        _armed = false;
        if (_dx == 0) return;
        _springBack();
      },
      child: Stack(
        alignment: Alignment.centerRight,
        children: [
          Positioned(
            right: 18,
            child: AnimatedOpacity(
              duration: const Duration(milliseconds: 110),
              opacity: reveal,
              child: Transform.scale(
                scale: 0.9 + (0.1 * reveal),
                child: Icon(
                  AppIcons.reply,
                  size: 20,
                  color: Theme.of(
                    context,
                  ).colorScheme.primary.withValues(alpha: 0.85),
                ),
              ),
            ),
          ),
          Transform.translate(offset: Offset(_dx, 0), child: widget.child),
        ],
      ),
    );
  }
}

class _BubbleMetaFooter extends StatelessWidget {
  const _BubbleMetaFooter({
    required this.timestampMs,
    required this.status,
    required this.color,
    required this.reactionEventId,
    required this.reactions,
    required this.selfProfileId,
    required this.reactionPlayTokens,
    required this.onToggleOwnReaction,
    this.statusText,
    this.scheduledAtMs,
    this.scheduledHeldUntilMs,
  });

  final int timestampMs;
  final Widget? status;
  final Color color;
  final String reactionEventId;
  final List<MessageReaction> reactions;
  final String selfProfileId;
  final Map<String, int> reactionPlayTokens;
  final void Function(String emoji) onToggleOwnReaction;
  final String? statusText;

  /// When set (> 0) this is a `scheduled` ("send later") placeholder: instead
  /// of the sent-time + delivery status we show a single minimalist badge with
  /// the planned send time + date on the right. Null for ordinary messages.
  final int? scheduledAtMs;

  /// Planned release instant of an uploaded-but-still-HELD "send later"
  /// message (see _MessageBubble.scheduledHeldUntilMs). Keeps the badge up
  /// until the relay actually releases the message, then flips to time+tick.
  final int? scheduledHeldUntilMs;

  @override
  Widget build(BuildContext context) {
    final sched = scheduledAtMs;
    final heldUntil = scheduledHeldUntilMs;
    if (sched == null || sched <= 0) {
      if (heldUntil != null && heldUntil > 0) {
        // Uploaded "send later": badge while the relay still holds it, the
        // normal time+tick row once the release instant passes. A stateful
        // wrapper re-renders AT the release instant, so the badge does not
        // linger until some unrelated rebuild.
        return _wrapMeta(
          _ScheduledHoldMeta(
            heldUntilMs: heldUntil,
            badge: _ScheduledTimeBadge(scheduledAtMs: heldUntil, color: color),
            sentRow: _sentMetaRow(context),
          ),
        );
      }
    }
    final Widget metaRow = (sched != null && sched > 0)
        ? _ScheduledTimeBadge(scheduledAtMs: sched, color: color)
        : _sentMetaRow(context);
    return _wrapMeta(metaRow);
  }

  Widget _sentMetaRow(BuildContext context) => Row(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Text(
                _formatTime(timestampMs),
                style: Theme.of(context).textTheme.labelSmall?.copyWith(
                  fontSize: 11,
                  fontWeight: FontWeight.w600,
                  height: 1,
                  color: color.withValues(alpha: 0.72),
                ),
              ),
              if (statusText != null && statusText!.isNotEmpty) ...[
                const SizedBox(width: 6),
                _buildBubbleStatusSlot(
                  statusText!,
                  Theme.of(context).textTheme.labelSmall?.copyWith(
                    fontSize: 11,
                    fontWeight: FontWeight.w600,
                    height: 1,
                    color: color.withValues(alpha: 0.72),
                  ),
                ),
              ],
              if (status != null) ...[const SizedBox(width: 5), status!],
            ],
          );

  Widget _wrapMeta(Widget metaRow) {
    return Align(
      alignment: Alignment.centerRight,
      widthFactor: 1,
      child: Wrap(
        alignment: WrapAlignment.end,
        crossAxisAlignment: WrapCrossAlignment.center,
        spacing: 8,
        runSpacing: 4,
        children: [
          _ReactionSlot(
            alignment: Alignment.centerRight,
            child: reactions.isEmpty
                ? const SizedBox.shrink()
                : _ReactionPills(
                    reactionEventId: reactionEventId,
                    reactions: reactions,
                    selfProfileId: selfProfileId,
                    reactionPlayTokens: reactionPlayTokens,
                    onToggleOwnReaction: onToggleOwnReaction,
                  ),
          ),
          metaRow,
        ],
      ),
    );
  }
}

/// Keeps the scheduled badge on an uploaded "send later" bubble until the
/// relay's release instant, then swaps to the normal time+tick row.
///
/// Why stateful: the swap must happen AT the release instant. Nothing else is
/// guaranteed to rebuild the timeline right then (the delivered receipt only
/// arrives if the recipient is online), and without a timer the badge would
/// linger until some unrelated rebuild — reintroducing, in mirror image, the
/// bug this fixes (the badge vanishing seconds after send, while the message
/// was still parked on the server).
class _ScheduledHoldMeta extends StatefulWidget {
  const _ScheduledHoldMeta({
    required this.heldUntilMs,
    required this.badge,
    required this.sentRow,
  });

  final int heldUntilMs;
  final Widget badge;
  final Widget sentRow;

  @override
  State<_ScheduledHoldMeta> createState() => _ScheduledHoldMetaState();
}

class _ScheduledHoldMetaState extends State<_ScheduledHoldMeta> {
  Timer? _flip;

  bool get _held =>
      DateTime.now().millisecondsSinceEpoch < widget.heldUntilMs;

  @override
  void initState() {
    super.initState();
    _armFlip();
  }

  @override
  void didUpdateWidget(covariant _ScheduledHoldMeta oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.heldUntilMs != widget.heldUntilMs) _armFlip();
  }

  void _armFlip() {
    _flip?.cancel();
    _flip = null;
    final now = DateTime.now().millisecondsSinceEpoch;
    final waitMs = widget.heldUntilMs - now;
    if (waitMs <= 0) return; // already past — render the sent row directly
    // +1s of slack so the flip lands safely past the instant (timer drift).
    _flip = Timer(Duration(milliseconds: waitMs + 1000), () {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _flip?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => _held ? widget.badge : widget.sentRow;
}

