/// A small, muted "translate this message" affordance shown at the bottom-right
/// of an incoming text bubble (near the timestamp). Background is transparent;
/// while a translation is in flight it shows a tiny spinner instead of the
/// icon. Tapping toggles the inline translation. Fail-soft by design — the
/// parent supplies the (already error-swallowing) [onTap].
class _TranslateAffordance extends StatelessWidget {
  const _TranslateAffordance({
    required this.color,
    required this.inFlight,
    required this.active,
    this.onTap,
  });

  final Color color;
  final bool inFlight;
  final bool active;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    // Muted by default; a touch more present once a translation is shown.
    final iconColor = color.withValues(alpha: active ? 0.75 : 0.5);
    final Widget child = inFlight
        ? SizedBox(
            width: 14,
            height: 14,
            child: CircularProgressIndicator(
              strokeWidth: 1.6,
              valueColor: AlwaysStoppedAnimation<Color>(
                color.withValues(alpha: 0.6),
              ),
            ),
          )
        : Icon(Icons.translate_rounded, size: 16, color: iconColor);

    return Semantics(
      button: true,
      child: InkResponse(
        onTap: inFlight ? null : onTap,
        radius: 16,
        containedInkWell: false,
        child: Padding(padding: const EdgeInsets.all(2), child: child),
      ),
    );
  }
}

/// Strokes a rounded-rect (or circle) outline with a vertical gradient that is
/// bright at the top edge and fades to transparent toward the bottom — the
/// specular highlight that makes a glass island look convex / lit from above.
class _FrostedGlass extends StatelessWidget {
  const _FrostedGlass({
    required this.child,
    this.borderRadius,
    this.backgroundColor,
    this.sigmaX = 18,
    this.sigmaY = 18,
  });

  final Widget child;
  final BorderRadius? borderRadius;
  final Color? backgroundColor;
  final double sigmaX;
  final double sigmaY;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final bg =
        backgroundColor ?? cs.surfaceContainerHighest.withValues(alpha: 0.5);
    final br = borderRadius ?? BorderRadius.circular(20);
    return ClipRRect(
      borderRadius: br,
      child: BackdropFilter(
        filter: ImageFilter.blur(sigmaX: sigmaX, sigmaY: sigmaY),
        child: DecoratedBox(
          decoration: BoxDecoration(
            color: bg,
            borderRadius: br,
            border: Border.all(color: Colors.white.withValues(alpha: 0.18)),
          ),
          child: child,
        ),
      ),
    );
  }
}

String? _guessMime(String pathOrName) =>
    // 🔴 ОДНА ТАБЛИЦА ТИПОВ НА ПРИЛОЖЕНИЕ (14.08.2026). Здесь лежал свой список
    // из ~26 расширений — он знал pdf и zip, но НЕ знал apk, docx, xlsx, rar.
    // Поэтому apk уходил с сервера как `application/octet-stream`, то есть
    // портился в самом источнике, у отправителя. Таких списков было ТРИ, с
    // разным содержимым.
    //
    // Возврат `null` для незнакомого типа СОХРАНЁН намеренно: вызывающие пишут
    // `_guessMime(p) ?? выбранныйСистемойТип`, и «не знаю» вместо `null` затёрло
    // бы настоящий тип.
    attachmentMimeForOrNull(pathOrName);

AttachmentEventV1 _buildPendingAttachmentEvent({
  required String id,
  required String mime,
  required int sizeBytes,
  String? filename,
  List<int>? waveform,
}) {
  return AttachmentEventV1(
    eventId: 'pending:$id',
    blobId: 'pending:$id',
    fileKeyB64: '',
    sizeBytes: sizeBytes,
    mime: mime,
    filename: filename,
    waveform: (waveform == null || waveform.isEmpty) ? null : waveform,
  );
}

/// Compact "3.4 / 12 MB" upload label (megabytes, one decimal below 100 MB) —
/// the minimalist size readout shown at the top corner of an uploading bubble.
String _uploadMbLabel(BuildContext context, int sentBytes, int totalBytes) {
  String mb(int b) {
    final v = b / (1024 * 1024);
    if (v >= 100) return v.toStringAsFixed(0);
    return v.toStringAsFixed(1);
  }

  final unit = wave1Text(context, ru: 'МБ', en: 'MB');
  return '${mb(sentBytes)} / ${mb(totalBytes)} $unit';
}

/// Telegram-style radial upload indicator: dim scrim disc, faint track ring, a
/// determinate white progress arc (from the top, clockwise), and a centered ✕ —
/// tapping anywhere on it cancels the upload. While progress is still unknown
/// (encrypting / connecting) it spins as an indeterminate arc.
class _UploadProgressRing extends StatefulWidget {
  const _UploadProgressRing({
    required this.progress,
    required this.onCancel,
    this.size = 54,
  });

  final double? progress;
  final VoidCallback onCancel;
  final double size;

  @override
  State<_UploadProgressRing> createState() => _UploadProgressRingState();
}

class _UploadProgressRingState extends State<_UploadProgressRing>
    with SingleTickerProviderStateMixin {
  late final AnimationController _spin = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1100),
  );

  @override
  void initState() {
    super.initState();
    if (widget.progress == null) _spin.repeat();
  }

  @override
  void didUpdateWidget(covariant _UploadProgressRing oldWidget) {
    super.didUpdateWidget(oldWidget);
    final indeterminate = widget.progress == null;
    if (indeterminate && !_spin.isAnimating) {
      _spin.repeat();
    } else if (!indeterminate && _spin.isAnimating) {
      _spin.stop();
    }
  }

  @override
  void dispose() {
    _spin.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: widget.onCancel,
      child: SizedBox(
        width: widget.size,
        height: widget.size,
        child: AnimatedBuilder(
          animation: _spin,
          builder: (context, child) => CustomPaint(
            painter: _UploadRingPainter(
              progress: widget.progress,
              rotation: _spin.value,
            ),
            child: child,
          ),
          child: Center(
            child: Icon(
              AppIcons.close,
              size: widget.size * 0.34,
              color: Colors.white,
            ),
          ),
        ),
      ),
    );
  }
}

class _UploadRingPainter extends CustomPainter {
  _UploadRingPainter({required this.progress, required this.rotation});

  final double? progress;
  final double rotation;

  @override
  void paint(Canvas canvas, Size size) {
    final center = size.center(Offset.zero);
    final radius = size.width / 2;
    canvas.drawCircle(
      center,
      radius,
      Paint()..color = Colors.black.withValues(alpha: 0.45),
    );
    final ringRadius = radius - 4;
    final rect = Rect.fromCircle(center: center, radius: ringRadius);
    canvas.drawCircle(
      center,
      ringRadius,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3
        ..color = Colors.white.withValues(alpha: 0.26),
    );
    final arcPaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 3
      ..strokeCap = StrokeCap.round
      ..color = Colors.white;
    final p = progress;
    if (p == null) {
      final start = rotation * 2 * pi - pi / 2;
      canvas.drawArc(rect, start, pi * 0.6, false, arcPaint);
    } else {
      final sweep = p.clamp(0.0, 1.0) * 2 * pi;
      canvas.drawArc(rect, -pi / 2, sweep, false, arcPaint);
    }
  }

  @override
  bool shouldRepaint(covariant _UploadRingPainter oldDelegate) =>
      oldDelegate.progress != progress || oldDelegate.rotation != rotation;
}

