String _fileExtFromMime(String mime) {
  if (mime.isEmpty) return 'file';
  final slash = mime.indexOf('/');
  if (slash < 0 || slash >= mime.length - 1) return mime;
  return mime.substring(slash + 1).toUpperCase();
}

/// Real display name for a generic-file bubble: the original [filename] when
/// present, otherwise a friendly fallback derived from the MIME subtype.
String _genericFileDisplayName(AttachmentEventV1? attachment, String mime) {
  final name = attachment?.filename?.trim() ?? '';
  if (name.isNotEmpty) return name;
  final ext = _fileExtFromMime(mime);
  return ext.isEmpty || ext == 'file' ? 'File' : 'File.${ext.toLowerCase()}';
}

/// Uppercased FORMAT label for a generic file — derived from the filename's
/// extension when available (e.g. "PDF"), else from the MIME subtype.
String _genericFileFormatLabel(AttachmentEventV1? attachment, String mime) {
  final name = attachment?.filename?.trim() ?? '';
  if (name.isNotEmpty) {
    final ext = p.extension(name).replaceFirst('.', '').trim();
    if (ext.isNotEmpty) return ext.toUpperCase();
  }
  return _fileExtFromMime(mime);
}

/// True when [attachment] should RENDER as a photo — i.e. image/video bubble
/// or album tile — rather than a document row.
///
/// Telegram parity: a photo SENT AS A FILE carries a non-empty [filename] and
/// must show as a DOCUMENT row (small thumbnail + name + "FORMAT • SIZE"),
/// full-quality and each in its own bubble — never grouped into an album. Only
/// a normal photo (photo/gallery tab → "send to chat"), which has NO filename,
/// renders as a compressed image / album.
bool _attachmentRendersAsPhoto(AttachmentEventV1 attachment) {
  // Video notes (квадратики) have their OWN bubble (VideoNoteBubble) and must
  // never be treated as a photo/album tile — even though they are video-mime
  // with no filename — otherwise the image branch renders them as a plain
  // video before the dedicated video-note branch is ever reached.
  if (attachment.videoNote) return false;
  if (!_isVisualMediaMime(attachment.mime ?? '')) return false;
  final name = attachment.filename?.trim() ?? '';
  return name.isEmpty;
}

/// True when an image-mime FILE can show a real image THUMBNAIL in its document
/// row (previewable raster format). Non-previewable formats (raw/tiff/etc.)
/// keep the generic file icon.
const Set<String> _kThumbnailablePhotoExtensions = <String>{
  'jpg',
  'jpeg',
  'png',
  'webp',
  'heic',
  'heif',
  'gif',
};

bool _attachmentFileHasPhotoThumbnail(AttachmentEventV1? attachment) {
  if (attachment == null) return false;
  final name = attachment.filename?.trim() ?? '';
  if (name.isEmpty) return false;
  final mime = (attachment.mime ?? '').trim().toLowerCase();
  if (!mime.startsWith('image/')) return false;
  final mimeSub = mime.substring('image/'.length);
  if (_kThumbnailablePhotoExtensions.contains(mimeSub) || mimeSub == 'jpeg') {
    return true;
  }
  final ext = p.extension(name).replaceFirst('.', '').trim().toLowerCase();
  return _kThumbnailablePhotoExtensions.contains(ext);
}

/// True for voice-recorder MIME types (ogg/opus/webm/amr/3gpp).
bool _isVoiceMessageMime(String mime) => isVoiceAttachmentMime(mime);

/// Robust voice-vs-music for an attachment. In-app voice notes are recorded as
/// AAC/m4a → mime `audio/mp4`, which is INDISTINGUISHABLE from a real music
/// file by mime alone, so the mime-only check ([_isVoiceMessageMime]) misses
/// them and they get mislabelled «Музыка» in the mini-player / queue. Voice
/// notes always ship the captured waveform; shared music files don't — so the
/// waveform is the reliable discriminator. Use THIS anywhere the result drives
/// a "Voice message" vs "Музыка" label. Mirrors the bubble's own isVoice rule.
bool _isVoiceMessageAttachment(AttachmentEventV1 a) =>
    _isVoiceMessageMime((a.mime ?? '').toLowerCase()) ||
    (a.waveform?.isNotEmpty ?? false);

/// blobId → resolved cache file, readable SYNCHRONOUSLY at build time.
///
/// Media rows are disposed as they scroll out and rebuilt as they scroll back,
/// and each rebuild used to restart the async file resolve — one-plus frames of
/// dark placeholder before a picture whose pixels were already hot in the
/// ImageCache. That's the black blink the timeline had while scrolling. The
/// map is process-wide on purpose (survives leaving/reopening the chat) and
/// capped so a media-heavy account can't grow it without bound.
final LinkedHashMap<String, File> _chatMediaFileMemoByBlobId =
    LinkedHashMap<String, File>();
const int _chatMediaFileMemoCap = 768;

File? _chatMediaFilePeek(String blobId) => _chatMediaFileMemoByBlobId[blobId];

void _chatMediaFileRemember(String blobId, File? file) {
  if (file == null || blobId.isEmpty) return;
  _chatMediaFileMemoByBlobId.remove(blobId); // refresh LRU position
  _chatMediaFileMemoByBlobId[blobId] = file;
  while (_chatMediaFileMemoByBlobId.length > _chatMediaFileMemoCap) {
    _chatMediaFileMemoByBlobId.remove(_chatMediaFileMemoByBlobId.keys.first);
  }
}

/// Compact duration label:  "0:07"  "1:24"  "1:02:15"
String _fmtAudioDur(Duration d) {
  if (d.inHours > 0) {
    final m = d.inMinutes.remainder(60).toString().padLeft(2, '0');
    final s = d.inSeconds.remainder(60).toString().padLeft(2, '0');
    return '${d.inHours}:$m:$s';
  }
  final m = d.inMinutes.remainder(60);
  final s = d.inSeconds.remainder(60).toString().padLeft(2, '0');
  return '$m:$s';
}

String _formatDurationLabel(Duration d) {
  final totalSeconds = d.inSeconds;
  final minutes = (totalSeconds ~/ 60).toString().padLeft(2, '0');
  final seconds = (totalSeconds % 60).toString().padLeft(2, '0');
  return '$minutes:$seconds';
}

String _formatBytesHuman(int bytes) => formatAttachmentBytes(bytes);

String _formatSpeedHuman(double bytesPerSec) {
  if (bytesPerSec <= 0) return '0 KB/s';
  return '${_formatBytesHuman(bytesPerSec.round())}/s';
}

String _formatEta(int seconds) {
  if (seconds <= 0) return '0s';
  if (seconds < 60) return '${seconds}s';
  final m = seconds ~/ 60;
  final s = seconds % 60;
  if (m < 60) return s == 0 ? '${m}m' : '${m}m ${s}s';
  final h = m ~/ 60;
  final mm = m % 60;
  return mm == 0 ? '${h}h' : '${h}h ${mm}m';
}

/// Ступень индикатора доставки: насколько ярко рисовать галочку и сколько их.
///
/// Три ступени, заданные владельцем продукта 02.09.2026:
///
///   отправлено  → ОДНА приглушённая галочка — ушло на релей, получатель ещё
///                 не подтвердил, что конверт до него дошёл;
///   доставлено  → ОДНА яркая галочка — устройство получателя приняло конверт
///                 и прислало квитанцию;
///   прочитано   → ДВЕ яркие галочки — собеседник открыл чат и увидел.
///
/// До этого «отправлено» и «доставлено» рисовались ОДИНАКОВО, и разница между
/// «ушло на сервер» и «дошло до человека» на экране не читалась вовсе.
///
/// 🔴 ЯРКОСТЬЮ, А НЕ ЦВЕТОМ. Галочки живут только на СВОИХ пузырях, где текст
/// всегда белый в обеих темах (`_chatBubbleForegroundColor`). Поэтому ступени
/// заданы прозрачностью поверх цвета пузыря, а не жёстким `Colors.white`:
/// глухой белый совпал бы с нынешним видом, но перестал бы попадать в тему,
/// если фон своих пузырей когда-нибудь посветлеет. Приглушённая ступень взята
/// 0.55 — ниже она сливается с фоном на светлых обоях чата, выше перестаёт
/// отличаться от яркой.
///
/// Возвращает `null` для состояний, которые галочками не рисуются вовсе —
/// отправка в процессе (часы), провал (красная галочка), отложенная отправка.
@visibleForTesting
({double alpha, bool doubled})? chatDeliveryTickStyle(String localState) {
  return switch (MessageLocalState.normalize(localState)) {
    MessageLocalState.sent => (alpha: 0.55, doubled: false),
    MessageLocalState.delivered => (alpha: 1.0, doubled: false),
    MessageLocalState.read => (alpha: 1.0, doubled: true),
    _ => null,
  };
}

Widget? _statusIcon(
  BuildContext context,
  String localState,
  Color color,
  int timestampMs,
) {
  final state = MessageLocalState.normalize(localState);
  final c = color.withValues(alpha: 0.75);
  final tickStyle = chatDeliveryTickStyle(state);

  return switch (state) {
    // Queued / actively sending / retrying / permanently failed — all mean
    // "not delivered to the relay" from the user's point of view. While
    // ONLINE this is a sub-second red flash before it flips to one tick; while
    // OFFLINE it stays red, which is exactly the "не отправлено" signal.
    MessageLocalState.pending ||
    MessageLocalState.sending ||
    MessageLocalState.retry => _SendingClockStatusIcon(color: c),
    MessageLocalState.failed => const _TickMarks(color: _kUnsentTickColor),
    MessageLocalState.sent ||
    MessageLocalState.delivered ||
    MessageLocalState.read => _TickMarks(
      color: color.withValues(alpha: tickStyle!.alpha),
      doubled: tickStyle.doubled,
    ),
    // A scheduled send is intentionally deferred — NOT an error — so it keeps
    // its own clock glyph rather than the red "unsent" tick.
    MessageLocalState.scheduled => const _ScheduledStatusIcon(),
    _ => null,
  };
}

/// One red tick for a message that permanently failed to send.
const Color _kUnsentTickColor = Color(0xFFE53935);

/// Animated clock for a message still in the send pipeline (queued / sending /
/// retrying) — the "процесс отправки" indicator.
class _SendingClockStatusIcon extends StatefulWidget {
  const _SendingClockStatusIcon({required this.color});

  final Color color;

  @override
  State<_SendingClockStatusIcon> createState() =>
      _SendingClockStatusIconState();
}

class _SendingClockStatusIconState extends State<_SendingClockStatusIcon>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1200),
    )..repeat();
  }

  @override
