class _SendingClockStatusPainter extends CustomPainter {
  const _SendingClockStatusPainter({
    required this.progress,
    required this.color,
  });

  final double progress;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final center = size.center(Offset.zero);
    final radius = (size.shortestSide / 2) - 1.2;
    final ringPaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.4
      ..strokeCap = StrokeCap.round
      ..color = color.withValues(alpha: 0.82);
    final handPaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.6
      ..strokeCap = StrokeCap.round
      ..color = color;
    final centerPaint = Paint()..color = color;

    canvas.drawCircle(center, radius, ringPaint);

    final hourAngle = (-pi / 2) + (progress * pi);
    final minuteAngle = (-pi / 2) + (progress * 2 * pi);
    final hourHand = Offset(
      cos(hourAngle) * radius * 0.42,
      sin(hourAngle) * radius * 0.42,
    );
    final minuteHand = Offset(
      cos(minuteAngle) * radius * 0.68,
      sin(minuteAngle) * radius * 0.68,
    );

    canvas.drawLine(center, center + hourHand, handPaint);
    canvas.drawLine(center, center + minuteHand, handPaint);
    canvas.drawCircle(center, 1.2, centerPaint);
  }

  @override
  bool shouldRepaint(covariant _SendingClockStatusPainter oldDelegate) {
    return oldDelegate.progress != progress || oldDelegate.color != color;
  }
}

