/// Delivery ticks drawn as crisp strokes (so they read «bolder» than the font
/// glyph) in the bubble's own colour. [doubled] draws the read-receipt ✓✓.
class _TickMarks extends StatelessWidget {
  const _TickMarks({required this.color, this.doubled = false});

  final Color color;
  final bool doubled;

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: doubled ? 17 : 12,
      height: 11,
      child: CustomPaint(
        painter: _TickPainter(color: color, doubled: doubled, strokeWidth: 1.7),
      ),
    );
  }
}

class _TickPainter extends CustomPainter {
  const _TickPainter({
    required this.color,
    required this.doubled,
    required this.strokeWidth,
  });

  final Color color;
  final bool doubled;
  final double strokeWidth;

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = strokeWidth
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..isAntiAlias = true;
    final h = size.height;
    void tick(double dx) {
      final path = Path()
        ..moveTo(dx + 0.5, h * 0.55)
        ..lineTo(dx + 3.0, h * 0.86)
        ..lineTo(dx + 8.5, h * 0.16);
      canvas.drawPath(path, paint);
    }

    tick(0);
    if (doubled) tick(4.6);
  }

  @override
  bool shouldRepaint(_TickPainter old) =>
      old.color != color ||
      old.doubled != doubled ||
      old.strokeWidth != strokeWidth;
}

