class _QuietHoursHourPickerSheetState
    extends State<_QuietHoursHourPickerSheet> {
  late int _selectedHour;
  late final FixedExtentScrollController _hourCtrl;

  @override
  void initState() {
    super.initState();
    _selectedHour = widget.initialHour.clamp(0, 23);
