// ---------------------------------------------------------------------------
// Schedule date/time picker bottom sheet (Telegram-style 3-wheel picker)
// ---------------------------------------------------------------------------
class _ScheduleDateTimePicker extends StatefulWidget {
  const _ScheduleDateTimePicker();

  @override
  State<_ScheduleDateTimePicker> createState() =>
      _ScheduleDateTimePickerState();
}

class _ScheduleDateTimePickerState extends State<_ScheduleDateTimePicker> {
  static const int _dayCount = 366; // today + 365 future days

  late List<DateTime> _days;
  late int _dayIndex;
  late int _hour;
  late int _minute;

  late final FixedExtentScrollController _dayCtrl;
  late final FixedExtentScrollController _hourCtrl;
  late final FixedExtentScrollController _minCtrl;

  @override
  void initState() {
    super.initState();
    final now = DateTime.now();
    _days = List.generate(
      _dayCount,
      (i) => DateTime(now.year, now.month, now.day).add(Duration(days: i)),
    );
    _dayIndex = 0;
    _hour = now.hour;
    _minute = (now.minute + 5).clamp(0, 59);
    _dayCtrl = FixedExtentScrollController(initialItem: _dayIndex);
    _hourCtrl = FixedExtentScrollController(initialItem: _hour);
    _minCtrl = FixedExtentScrollController(initialItem: _minute);
  }

  @override
  void dispose() {
    _dayCtrl.dispose();
    _hourCtrl.dispose();
    _minCtrl.dispose();
    super.dispose();
  }

  DateTime get _selectedDateTime {
    final d = _days[_dayIndex];
    return DateTime(d.year, d.month, d.day, _hour, _minute);
  }

  List<String> _monthLabels(BuildContext context) {
    return switch (chatLocaleTagFromContext(context)) {
      'ru' => const [
        'янв',
        'фев',
        'мар',
        'апр',
        'май',
        'июн',
        'июл',
        'авг',
        'сен',
        'окт',
        'ноя',
        'дек',
      ],
      'uk' => const [
        'січ',
        'лют',
        'бер',
        'кві',
        'тра',
        'чер',
        'лип',
        'сер',
        'вер',
        'жов',
        'лис',
        'гру',
      ],
      'es' => const [
        'ene',
        'feb',
        'mar',
        'abr',
        'may',
        'jun',
        'jul',
        'ago',
        'sep',
        'oct',
        'nov',
        'dic',
      ],
      'pt' || 'pt_BR' => const [
        'jan',
        'fev',
        'mar',
        'abr',
        'mai',
        'jun',
        'jul',
        'ago',
        'set',
        'out',
        'nov',
        'dez',
      ],
      'fr' => const [
        'janv.',
        'févr.',
        'mars',
        'avr.',
        'mai',
        'juin',
        'juil.',
        'août',
        'sept.',
        'oct.',
        'nov.',
        'déc.',
      ],
      'de' => const [
        'Jan',
        'Feb',
        'Mär',
        'Apr',
        'Mai',
        'Jun',
        'Jul',
        'Aug',
        'Sep',
        'Okt',
        'Nov',
        'Dez',
      ],
      _ => const [
        'Jan',
        'Feb',
        'Mar',
        'Apr',
        'May',
        'Jun',
        'Jul',
        'Aug',
        'Sep',
        'Oct',
        'Nov',
        'Dec',
      ],
    };
  }

  String _formatScheduledDate(
    BuildContext context,
    DateTime date,
    AppLocalizations l10n, {
    required bool includeYear,
  }) {
    final months = _monthLabels(context);
    final yearSuffix = includeYear ? ' ${date.year}' : '';
    return '${date.day} ${months[date.month - 1]}$yearSuffix';
  }

  String _dayLabel(BuildContext context, DateTime d, AppLocalizations l10n) {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    if (d == today) {
      return chatText(context, ru: 'Сегодня', en: 'Today');
    }
    if (d == today.add(const Duration(days: 1))) {
      return chatText(context, ru: 'Завтра', en: 'Tomorrow');
    }
    return _formatScheduledDate(
      context,
      d,
      l10n,
      includeYear: d.year != today.year,
    );
  }

  String _confirmLabel(BuildContext context, AppLocalizations l10n) {
    final dt = _selectedDateTime;
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final timeStr =
        '${_hour.toString().padLeft(2, '0')}:${_minute.toString().padLeft(2, '0')}';
    if (_days[_dayIndex] == today) {
      return l10n.scheduledSendToday(timeStr);
    }
    final dateStr = _formatScheduledDate(
      context,
      dt,
      l10n,
      includeYear: dt.year != today.year,
    );
    return l10n.scheduledSendOn(dateStr, timeStr);
  }

  @override
  Widget build(BuildContext context) {
    final l10n = context.l10n;
    final cs = Theme.of(context).colorScheme;
    final media = MediaQuery.of(context);

    return Container(
      decoration: BoxDecoration(
        color: cs.surface,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
      ),
      padding: EdgeInsets.only(bottom: media.padding.bottom + 8),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Handle bar
          Padding(
            padding: const EdgeInsets.only(top: 12, bottom: 8),
            child: Container(
              width: 40,
              height: 4,
              decoration: BoxDecoration(
                color: cs.onSurface.withValues(alpha: 0.25),
                borderRadius: BorderRadius.circular(2),
              ),
            ),
          ),
          // Title
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 4),
            child: Text(
              l10n.sendLater,
              style: Theme.of(
                context,
              ).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w600),
            ),
          ),
          const SizedBox(height: 8),
          // 3-wheel picker row
          SizedBox(
            height: 200,
            child: Stack(
              alignment: Alignment.center,
              children: [
                // Selection highlight
                IgnorePointer(
                  child: Align(
                    alignment: Alignment.center,
                    child: Container(
                      height: 40,
                      margin: const EdgeInsets.symmetric(horizontal: 12),
                      decoration: BoxDecoration(
                        color: cs.primary.withValues(alpha: 0.10),
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                  ),
                ),
                Row(
                  children: [
                    // Day wheel
                    Expanded(
                      flex: 5,
                      child: ListWheelScrollView.useDelegate(
                        controller: _dayCtrl,
                        itemExtent: 40,
                        perspective: 0.003,
                        diameterRatio: 2.0,
                        physics: const FixedExtentScrollPhysics(),
                        onSelectedItemChanged: (i) =>
                            setState(() => _dayIndex = i),
                        childDelegate: ListWheelChildBuilderDelegate(
                          childCount: _dayCount,
                          builder: (_, i) => Center(
                            child: Text(
                              _dayLabel(context, _days[i], l10n),
                              style: Theme.of(context).textTheme.bodyLarge
                                  ?.copyWith(
                                    fontWeight: i == _dayIndex
                                        ? FontWeight.w600
                                        : FontWeight.normal,
                                    color: i == _dayIndex
                                        ? cs.onSurface
                                        : cs.onSurface.withValues(alpha: 0.45),
                                  ),
                            ),
                          ),
                        ),
                      ),
                    ),
                    // Hour wheel
                    Expanded(
                      flex: 3,
                      child: ListWheelScrollView.useDelegate(
                        controller: _hourCtrl,
                        itemExtent: 40,
                        perspective: 0.003,
                        diameterRatio: 2.0,
                        physics: const FixedExtentScrollPhysics(),
                        onSelectedItemChanged: (i) => setState(() => _hour = i),
                        childDelegate: ListWheelChildBuilderDelegate(
                          childCount: 24,
                          builder: (_, i) => Center(
                            child: Text(
                              i.toString().padLeft(2, '0'),
                              style: Theme.of(context).textTheme.bodyLarge
                                  ?.copyWith(
                                    fontWeight: i == _hour
                                        ? FontWeight.w600
                                        : FontWeight.normal,
                                    color: i == _hour
                                        ? cs.onSurface
                                        : cs.onSurface.withValues(alpha: 0.45),
                                  ),
                            ),
                          ),
                        ),
                      ),
                    ),
                    // Colon separator
                    Text(
                      ':',
                      style: Theme.of(context).textTheme.titleLarge?.copyWith(
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    // Minute wheel
                    Expanded(
                      flex: 3,
                      child: ListWheelScrollView.useDelegate(
                        controller: _minCtrl,
                        itemExtent: 40,
                        perspective: 0.003,
                        diameterRatio: 2.0,
                        physics: const FixedExtentScrollPhysics(),
                        onSelectedItemChanged: (i) =>
                            setState(() => _minute = i),
                        childDelegate: ListWheelChildBuilderDelegate(
                          childCount: 60,
                          builder: (_, i) => Center(
                            child: Text(
                              i.toString().padLeft(2, '0'),
                              style: Theme.of(context).textTheme.bodyLarge
                                  ?.copyWith(
                                    fontWeight: i == _minute
                                        ? FontWeight.w600
                                        : FontWeight.normal,
                                    color: i == _minute
                                        ? cs.onSurface
                                        : cs.onSurface.withValues(alpha: 0.45),
                                  ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
          // "Repeat: Never" locked chip
          Padding(
            padding: const EdgeInsets.only(top: 8),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(
                  AppIcons.lock,
                  size: 14,
                  color: cs.onSurface.withValues(alpha: 0.40),
                ),
                const SizedBox(width: 6),
                Text(
                  '${l10n.repeat}: ${l10n.repeatNever}',
                  style: Theme.of(context).textTheme.bodySmall?.copyWith(
                    color: cs.onSurface.withValues(alpha: 0.40),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 12),
          // Confirm button
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: SizedBox(
              width: double.infinity,
              child: FilledButton(
                onPressed: () => Navigator.of(context).pop(_selectedDateTime),
                child: Text(_confirmLabel(context, l10n)),
              ),
            ),
          ),
          const SizedBox(height: 8),
        ],
      ),
    );
  }
}

String _formatTime(int ms) {
  final dt = DateTime.fromMillisecondsSinceEpoch(ms);
  return '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}';
}

// ---------------------------------------------------------------------------
// In-chat search bottom bar (replaces the composer while search is open).
// Frosted "island" that hosts: a calendar button (P3 stub), the match counter,
// up/down navigation arrows, and a "List" button (P2 stub).
// ---------------------------------------------------------------------------
class _ChatSearchBottomBar extends StatelessWidget {
  const _ChatSearchBottomBar({
    required this.islandBuilder,
    required this.total,
    required this.currentIndex,
    required this.inProgress,
    required this.onPrev,
    required this.onNext,
    required this.onCalendar,
    required this.onOpenList,
  });

  /// Wraps the bar content in the app's frosted island (passed from the State so
  /// it reuses `_frostedHeaderIsland` and stays visually identical to the
  /// composer plate).
  final Widget Function(Widget child) islandBuilder;
  final int total;
  final int currentIndex;
  final bool inProgress;
  final VoidCallback? onPrev;
  final VoidCallback? onNext;
  final VoidCallback onCalendar;
  final VoidCallback onOpenList;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final fg = cs.onSurface;
    final hasHits = total > 0 && currentIndex >= 0;

    final String countLabel;
    if (inProgress && total == 0) {
      countLabel = wave1Text(
        context,
        ru: 'Поиск…',
        en: 'Searching…',
        uk: 'Пошук…',
        es: 'Buscando…',
        pt: 'A procurar…',
        ptBr: 'Procurando…',
        fr: 'Recherche…',
        de: 'Suche…',
      );
    } else if (!hasHits) {
      countLabel = wave1Text(
        context,
        ru: 'Нет совпадений',
        en: 'No matches',
        uk: 'Немає збігів',
        es: 'Sin coincidencias',
        pt: 'Sem correspondências',
        ptBr: 'Sem correspondências',
        fr: 'Aucun résultat',
        de: 'Keine Treffer',
      );
    } else {
      final pos = currentIndex + 1;
      // "{pos} of {total}" — localized connector word.
      final of = wave1Text(
        context,
        ru: 'из',
        en: 'of',
        uk: 'з',
        es: 'de',
        pt: 'de',
        ptBr: 'de',
        fr: 'sur',
        de: 'von',
      );
      countLabel = '$pos $of $total';
    }

    final listLabel = wave1Text(
      context,
      ru: 'Список',
      en: 'List',
      uk: 'Список',
      es: 'Lista',
      pt: 'Lista',
      ptBr: 'Lista',
      fr: 'Liste',
      de: 'Liste',
    );

    return islandBuilder(
      Padding(
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
        child: Row(
          children: [
            IconButton(
              icon: Icon(AppIcons.calendar, size: 22, color: fg),
              onPressed: onCalendar,
              tooltip: wave1Text(
                context,
                ru: 'По дате',
                en: 'By date',
                uk: 'За датою',
                es: 'Por fecha',
                pt: 'Por data',
                ptBr: 'Por data',
                fr: 'Par date',
                de: 'Nach Datum',
              ),
            ),
            Expanded(
              child: Center(
                child: Text(
                  countLabel,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    color: hasHits ? fg : fg.withValues(alpha: 0.6),
                    fontSize: 14,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
            ),
            IconButton(
              icon: Icon(
                AppIcons.searchUp,
                size: 22,
                color: onPrev == null ? fg.withValues(alpha: 0.3) : fg,
              ),
              onPressed: onPrev,
              tooltip: wave1Text(
                context,
                ru: 'Предыдущее',
                en: 'Previous',
                uk: 'Попереднє',
                es: 'Anterior',
                pt: 'Anterior',
                ptBr: 'Anterior',
                fr: 'Précédent',
                de: 'Vorheriges',
              ),
            ),
            IconButton(
              icon: Icon(
                AppIcons.searchDown,
                size: 22,
                color: onNext == null ? fg.withValues(alpha: 0.3) : fg,
              ),
              onPressed: onNext,
              tooltip: wave1Text(
                context,
                ru: 'Следующее',
                en: 'Next',
                uk: 'Наступне',
                es: 'Siguiente',
                pt: 'Próximo',
                ptBr: 'Próximo',
                fr: 'Suivant',
                de: 'Nächstes',
              ),
            ),
            TextButton(
              onPressed: onOpenList,
              child: Text(
                listLabel,
                style: TextStyle(
                  color: cs.primary,
                  fontSize: 14,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
// Row highlight wrapper (scroll-to-reply flash effect)
