class _HighlightWrapper extends StatelessWidget {
  const _HighlightWrapper({
    super.key,
    required this.highlighted,
    required this.child,
  });

  final bool highlighted;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    return AnimatedContainer(
      duration: const Duration(milliseconds: 550),
      curve: Curves.easeOutCubic,
      color: highlighted
          ? Theme.of(context).colorScheme.primary.withValues(alpha: 0.20)
          : Colors.transparent,
      child: child,
    );
  }
}

// ---------------------------------------------------------------------------
// Slide-up entrance animation for new messages
// ---------------------------------------------------------------------------
class _SlideUpEntrance extends StatefulWidget {
  const _SlideUpEntrance({
    required this.child,
    this.animate = true,
    this.isOutgoing = false,
  });
  final Widget child;
  final bool animate;
  final bool isOutgoing;

  @override
  State<_SlideUpEntrance> createState() => _SlideUpEntranceState();
}

class _SlideUpEntranceState extends State<_SlideUpEntrance>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;
  late final Animation<Offset> _slide;

  @override
  void initState() {
    super.initState();
    final duration = widget.isOutgoing
        ? const Duration(milliseconds: 360)
        : const Duration(milliseconds: 280);
    _ctrl = AnimationController(vsync: this, duration: duration);
    final curve = CurvedAnimation(
      parent: _ctrl,
      curve: widget.isOutgoing
          ? const Cubic(0.16, 1.0, 0.3, 1.0)
          : Curves.easeOutQuart,
    );
    _slide = Tween<Offset>(
      begin: widget.isOutgoing ? const Offset(0, 0.24) : const Offset(0, 0.32),
      end: Offset.zero,
    ).animate(curve);
    if (widget.animate) {
      _ctrl.forward();
    } else {
      _ctrl.value = 1;
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ClipRect(
      child: SlideTransition(position: _slide, child: widget.child),
    );
  }
}

class _VoiceLockArrowClipper extends CustomClipper<Path> {
  @override
  Path getClip(Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(size.width / 2, size.height);
    path.lineTo(size.width, 0);
    path.close();
    return path;
  }

  @override
  bool shouldReclip(_VoiceLockArrowClipper oldClipper) => false;
}

